INSERT INTO content_unit (slug, bucket, title, kind, sort_order) VALUES ('spiritual-ethos', 'Islamic', 'Spiritual Ethos', 'book', 0) ON CONFLICT(slug) DO UPDATE SET bucket = excluded.bucket, title = excluded.title;
INSERT INTO unit_detail (slug, title_arabic, title_language, study_track, blurb_html, edition_note, cover_key, pdf_key, published_at, source_commit) VALUES ('spiritual-ethos', 'الخلق الروحاني', 'ar', 'theology', '<p>This is a work of scholarship, and at its close a work of translation. Reza Shah-Kazemi published it in 2006, reading the Shii and Sufi traditions of Islam together and drawing on sources that reach back to the seventh century. Its subject is the spirituality of Ali ibn Abi Talib — cousin and son-in-law of the Prophet Muhammad, fourth caliph, and first of the Shii Imams — and its argument is that in this one figure the inward substance of the Islamic tradition finds an integral expression.</p>', NULL, 'spiritual-ethos/cover.png', 'spiritual-ethos/book.pdf', '2026-08-29T20:17:47Z', '46129cd6f0dc8a11ac4bdab0739b9368abc93429');
