INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('spiritual-ethos', 'justice and the tyrant''s pride', 'pp. 22-83', '["Justice Versus Tyranny", "Human virtue and ultimate reality"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('spiritual-ethos', 'conscience, compassion, and the ordering of society', 'pp. 25-25', '["Moral Conscience And Spiritual Consciousness", "The compassion of justice", "State and society"]');
