INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('spiritual-ethos', 'dhikr: the polish of the heart', 'pp. 116-292', '["Dhikru''Llah As A Polish For Hearts", "After this verse come the following two", "How can it be conceived that something veils Him, since He is the one who manifests everything?", "How can it be conceived that something veils Him, since He is the one who is manifest through everything?", "How can it be conceived that something veils Him, since He is the one who is manifest in everything?", "How can it be conceived that something veils Him, since He is the Manifest to everything?", "How can it be conceived that something veils Him, since He was the Manifest before the existence of everything?", "How can it be conceived that something veils Him, since He is more manifest than anything?"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('spiritual-ethos', 'remembrance as the quintessence of worship', 'pp. 229-294', '["Remembrance As The Quintessence Of Worship"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('spiritual-ethos', 'extinction and the name: the death of the saint', 'pp. 246-251', '["He said, ''I am wielding the sword for God''s sake, I am the servant of God, I am not under the command of the body.", "I have removed the baggage of self out of the way, I have deemed (what is) other than God to be non-existence.", "I am a shadow, the Sun is my lord; I am the chamberlain, I am not the curtain (which prevents approach) to Him."]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('spiritual-ethos', 'the first sermon of the nahj al-balagha', 'pp. 206-251', '["The First Sermon of Nahj al-Balagha"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('spiritual-ethos', 'the letter to malik al-ashtar', 'pp. 211-324', '["The Letter of Ali (ع) to Malik al-Ashtar", "In the Name of God, the Compassionate, the Merciful.", "And peace be upon the Messenger of God—God bless him and his good and pure progeny."]');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'blurb', NULL, 'Spiritual Ethos', 0, NULL, 'This is a work of scholarship, and at its close a work of translation. Reza Shah-Kazemi published it in 2006, reading the Shii and Sufi traditions of Islam together and drawing on sources that reach back to the seventh century. Its subject is the spirituality of Ali ibn Abi Talib — cousin and son-in-law of the Prophet Muhammad, fourth caliph, and first of the Shii Imams — and its argument is that in this one figure the inward substance of the Islamic tradition finds an integral expression.', '', NULL, NULL, NULL, NULL, 'spiritual ethos', 'this is a work of scholarship and at its close a work of translation reza shah kazemi published it in 2006 reading the shii and sufi traditions of islam together and drawing on sources that reach back to the seventh century its subject is the spirituality of ali ibn abi talib cousin and son in law of the prophet muhammad fourth caliph and first of the shii imams and its argument is that in this one figure the inward substance of the islamic tradition finds an integral expression', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'introduction to the book', 'Introduction to the Book', 0, NULL, 'This is a work of scholarship, and at its close a work of translation. Reza Shah-Kazemi published it in 2006, reading the Shii and Sufi traditions of Islam together and drawing on sources that reach back to the seventh century. Its subject is the spirituality of Ali ibn Abi Talib — cousin and son-in-law of the Prophet Muhammad, fourth caliph, and first of the Shii Imams — and its argument is that in this one figure the inward substance of the Islamic tradition finds an integral expression.', '', NULL, NULL, NULL, NULL, 'spiritual ethos introduction to the book', 'this is a work of scholarship and at its close a work of translation reza shah kazemi published it in 2006 reading the shii and sufi traditions of islam together and drawing on sources that reach back to the seventh century its subject is the spirituality of ali ibn abi talib cousin and son in law of the prophet muhammad fourth caliph and first of the shii imams and its argument is that in this one figure the inward substance of the islamic tradition finds an integral expression', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'introduction to the book', 'Introduction to the Book', 1, NULL, 'The book moves inward. It opens with Ali''s nearness to the Prophet and the household around him, then turns to what he understood by intellect as distinct from mere reason, and to the certainty that intellect yields. From there it follows his conception of justice — sacred rather than merely legal — through the ordering of society, the claims of the poor, and the sincerity that must underlie every act of rule. Its final movement is devotional: prayer, the remembrance of God, and the extinction of the self in the divine Name.', '', NULL, NULL, NULL, NULL, 'spiritual ethos introduction to the book', 'the book moves inward it opens with alis nearness to the prophet and the household around him then turns to what he understood by intellect as distinct from mere reason and to the certainty that intellect yields from there it follows his conception of justice sacred rather than merely legal through the ordering of society the claims of the poor and the sincerity that must underlie every act of rule its final movement is devotional prayer the remembrance of god and the extinction of the self in the divine name', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'introduction to the book', 'Introduction to the Book', 2, NULL, 'The closing chapters set commentary aside and let Ali speak for himself. The first sermon of the Nahj al-Balagha and his letter to the governor Malik al-Ashtar are given in full translation, so that the reader may weigh the man against his own words.', '', NULL, NULL, NULL, NULL, 'spiritual ethos introduction to the book', 'the closing chapters set commentary aside and let ali speak for himself the first sermon of the nahj al balagha and his letter to the governor malik al ashtar are given in full translation so that the reader may weigh the man against his own words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 0, NULL, 'In relation to the Prophet, Ali (عَلَيْهِ السَّلَامُ) was both a living presence and a promise. The epigraph names it: "I am the city of knowledge and Ali is its gate; so whoever desires knowledge, let him enter the gate" (أَنَا مَدِينَةُ الْعِلْمِ وَعَلِيٌّ بَابُهَا، فَمَنْ أَرَادَ الْعِلْمَ فَلْيَأْتِ الْبَابَ).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'in relation to the prophet ali عليه السلام was both a living presence and a promise the epigraph names it i am the city of knowledge and ali is its gate so whoever desires knowledge let him enter the gate انا مدينه العلم وعلي بابها فمن اراد العلم فليات الباب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 1, NULL, 'To speak of Ali ibn Abi Talib — cousin and son-in-law of the Prophet Muhammad, fourth caliph of Islam, and first in the line of Shii Imams — is to speak of the very heart of Islamic spiritual life. In this central figure of Islam''s earliest days, both of its two great sources come together: the revelation of the Quran and the inspired Sunna of the Prophet. Sunna here does not mean simply copying the Prophet''s outward actions — a narrow view that is all too common today — but rather the inner spiritual substance of prophetic perfection, the perfection to which the Quran itself points:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'to speak of ali ibn abi talib cousin and son in law of the prophet muhammad fourth caliph of islam and first in the line of shii imams is to speak of the very heart of islamic spiritual life in this central figure of islams earliest days both of its two great sources come together the revelation of the quran and the inspired sunna of the prophet sunna here does not mean simply copying the prophets outward actions a narrow view that is all too common today but rather the inner spiritual substance of prophetic perfection the perfection to which the quran itself points', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 2, NULL, 'Al-Qalam: 4وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍۢ"Verily, thou art of a tremendous nature" (Al-Qalam: 4).', '', NULL, 'Al-Qalam: 4', NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'al qalam 4وانك لعلي خلق عظيم verily thou art of a tremendous nature al qalam 4', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 3, NULL, 'The Prophet''s words and deeds give voice to that spiritual substance, yet they do not exhaust it. To take this substance inwardly into oneself, rather than merely copy its outward forms, is the aim of every Muslim drawn to the spiritual life. Between the believer''s soul and the prophetic nature there is a deep kinship, a mysterious closeness that reaches across time and space, as the following verse expresses:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'the prophets words and deeds give voice to that spiritual substance yet they do not exhaust it to take this substance inwardly into oneself rather than merely copy its outward forms is the aim of every muslim drawn to the spiritual life between the believers soul and the prophetic nature there is a deep kinship a mysterious closeness that reaches across time and space as the following verse expresses', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 4, NULL, 'Al-Ahzab: 6ٱلنَّبِىُّ أَوْلَىٰ بِٱلْمُؤْمِنِينَ مِنْ أَنفُسِهِمْ ۖ وَأَزْوَجُهُۥٓ أُمَّهَتُهُمْ ۗ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍۢ فِى كِتَبِ ٱللَّهِ مِنَ ٱلْمُؤْمِنِينَ وَٱلْمُهَجِرِينَ إِلَّآ أَن تَفْعَلُوٓا۟ إِلَىٰٓ أَوْلِيَآئِكُم مَّعْرُوفًۭا ۚ كَانَ ذَلِكَ فِى ٱلْكِتَبِ مَسْطُورًۭا"The Prophet is closer to the believers than they are to themselves, and his wives are their mothers; and by the ordinance of God, blood relatives are more entitled to one another than other believers and emigrants, unless you would show kindness to your close associates. This is decreed in the Record" (Al-Ahzab: 6).', '', NULL, 'Al-Ahzab: 6', NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'al ahzab 6النبي اولي بالمومنين من انفسهم وازوجه امهتهم واولوا الارحام بعضهم اولي ببعض في كتب الله من المومنين والمهجرين الا ان تفعلوا الي اوليايكم معروفا كان ذلك في الكتب مسطورا the prophet is closer to the believers than they are to themselves and his wives are their mothers and by the ordinance of god blood relatives are more entitled to one another than other believers and emigrants unless you would show kindness to your close associates this is decreed in the record al ahzab 6', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 5, NULL, 'The Prophet thus shows outwardly the very perfection that the spiritually sensitive believer senses, in some measure, at the core of his or her own soul.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'the prophet thus shows outwardly the very perfection that the spiritually sensitive believer senses in some measure at the core of his or her own soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 6, NULL, 'It is no surprise, then, to find the Prophet saying that Ali "is as my own soul":', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'it is no surprise then to find the prophet saying that ali is as my own soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 7, NULL, 'Sayingعليٌّ مِنِّي بِمَنْزِلَةِ نَفْسِي', '', 'عليٌّ مِنِّي بِمَنْزِلَةِ نَفْسِي', 'Saying', NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'sayingعلي مني بمنزله نفسي', 'علي مني بمنزله نفسي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 8, NULL, 'This confirms not only the extraordinarily close bond between Ali and the Prophet, but also the kinship — and in the end the oneness — between every sanctified soul and the prophetic nature. More mysterious still, the Prophet said to Ali, "You are from me, and I am from you":', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'this confirms not only the extraordinarily close bond between ali and the prophet but also the kinship and in the end the oneness between every sanctified soul and the prophetic nature more mysterious still the prophet said to ali you are from me and i am from you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 9, NULL, 'Sayingأنْتَ مِنِّی وَ أَنَا مِنْکَ', '', 'أنْتَ مِنِّی وَ أَنَا مِنْکَ', 'Saying', NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'sayingانت مني و انا منك', 'انت مني و انا منك');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 10, NULL, 'As for how fully Ali took into himself the substance (مَوَادّ) of the Quran, there is this saying of the Prophet:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'as for how fully ali took into himself the substance مواد of the quran there is this saying of the prophet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 11, NULL, 'Sayingإِنَّ عَلِيًّا مَعَ الْقُرْآنِ وَالْقُرْآنُ مَعَ عَلِيٍّ، لَنْ يَفْتَرِقَا حَتَّى يَرِدَا عَلَيَّ الْحَوْضَ"Ali is with the Quran and the Quran is with Ali. They will not separate from each other until they return to me at the [paradisal] pool (al-hawd)."', '', NULL, 'Saying', NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'sayingان عليا مع القران والقران مع علي لن يفترقا حتي يردا علي الحوض ali is with the quran and the quran is with ali they will not separate from each other until they return to me at the paradisal pool al hawd', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 12, NULL, 'Ali thus took fully within himself both the spirit of the Quran and the soul of the Prophet; and it is exactly this taking-within of the two sources of the Islamic revelation that forms the spiritual path of Islam.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'ali thus took fully within himself both the spirit of the quran and the soul of the prophet and it is exactly this taking within of the two sources of the islamic revelation that forms the spiritual path of islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 13, NULL, 'The chief way to study and reflect upon the spirituality of Ali is to engage with the body of teachings handed down under his name. Not every one of the thousands of sayings attributed to him can be assigned to him with confidence; yet the sheer size of this body of work shows that he must have given voice to a great many profound teachings. No other companion of the Prophet left anything close to it. The same holds for the sciences. His founding role in a whole range of them may be open to debate — among them jurisprudence (فِقْهٌ), theology (كَلَامٌ), Quranic exegesis (تَفْسِيرٌ), rhetoric (بَلَاغَةٌ), grammar (نَحْوٌ), and calligraphy (خَطٌّ), the mystical knowledge of Sufism, and such hidden sciences as numerology (جَفْرٌ) and alchemy (اَلْكِيمِيَاءُ) — but the later masters in every one of these fields look back to him as the first impulse behind their discipline, which itself testifies to how far and how deep the influence of both his formal teaching and his personal radiance reached.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'the chief way to study and reflect upon the spirituality of ali is to engage with the body of teachings handed down under his name not every one of the thousands of sayings attributed to him can be assigned to him with confidence yet the sheer size of this body of work shows that he must have given voice to a great many profound teachings no other companion of the prophet left anything close to it the same holds for the sciences his founding role in a whole range of them may be open to debate among them jurisprudence فقه theology كلام quranic exegesis تفسير rhetoric بلاغه grammar نحو and calligraphy خط the mystical knowledge of sufism and such hidden sciences as numerology جفر and alchemy الكيمياء but the later masters in every one of these fields look back to him as the first impulse behind their discipline which itself testifies to how far and how deep the influence of both his formal teaching and his personal radiance reached', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 14, NULL, 'Because the Islamic intellectual sciences as a whole are so closely bound to Ali, the Prophet''s description of him as the "gate" to prophetic wisdom, quoted in the epigraph, reads in two ways at once: as an account of what Ali was to the Prophet in their own lifetime, and as a prophecy of the part he would play as those sciences later unfolded. Each of these sciences is understood as one more outward, formal expression of the inward, essential spirit of the Islamic revelation — a spirit that Ali drew together within himself and faithfully passed on. The main historical outlines of his life come first.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'because the islamic intellectual sciences as a whole are so closely bound to ali the prophets description of him as the gate to prophetic wisdom quoted in the epigraph reads in two ways at once as an account of what ali was to the prophet in their own lifetime and as a prophecy of the part he would play as those sciences later unfolded each of these sciences is understood as one more outward formal expression of the inward essential spirit of the islamic revelation a spirit that ali drew together within himself and faithfully passed on the main historical outlines of his life come first', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 15, NULL, 'Ali was a "follower" of the Prophet in the deepest sense of that word. He lived at the Prophet''s side, in his very shadow, and took in spiritually all that shone out from him. The closeness between them is caught in the words of one of the Imam''s own sermons:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'ali was a follower of the prophet in the deepest sense of that word he lived at the prophets side in his very shadow and took in spiritually all that shone out from him the closeness between them is caught in the words of one of the imams own sermons', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 16, NULL, 'Sayingلَمَّا كُنْتُ وَلِيدًا ضَمَّنِي إِلَى صَدْرِهِ، فَكُنْتُ أتَّبِعُهُ اتّبَاعَ الفَصِيلِ أُمَّهُ"When I was but a child he took me under his wing. I would follow him as a baby camel follows its mother."', '', NULL, 'Saying', NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'sayingلما كنت وليدا ضمني الي صدره فكنت اتبعه اتباع الفصيل امه when i was but a child he took me under his wing i would follow him as a baby camel follows its mother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 17, NULL, 'Sayingيَرْفَعُ لِي فِي كُلِّ يَوْمٍ عَلَمًا مِنْ أَخْلاقِهِ الْكَرِيمَةِ وَيَأمُرُنِي بِالاِقْتِدَاءِ بِهِ"Every day he would hold up for me a sign of his noble character and command me to follow it."', '', NULL, 'Saying', NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'sayingيرفع لي في كل يوم علما من اخلاقه الكريمه ويامرني بالاقتداء به every day he would hold up for me a sign of his noble character and command me to follow it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 18, NULL, 'Sayingوَكَانَ يَتَعَاهَدُ غَارَ حِرَاءٍ فِي كُلِّ سَنَةٍ، فَأَرَاهُ وَلَا يَرَاهُ غَيْرِي"Each year he would go into seclusion at the mountain of Hira. I saw him there, and no one else did."', '', NULL, 'Saying', NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'sayingوكان يتعاهد غار حراء في كل سنه فاراه ولا يراه غيري each year he would go into seclusion at the mountain of hira i saw him there and no one else did', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 19, NULL, 'Sayingوَلَمْ يَجْمَعْ بَيْتٌ وَاحِدٌ يَوْمَئِذٍ فِي الإِسْلامِ غَيْرَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَخَدِيجَةَ وَأَنَا ثَالِثُهُمَا"At that time no single household was gathered together in the religion of Islam, save that of the Messenger of God, Khadija, and myself as the third among them."', '', NULL, 'Saying', NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'sayingولم يجمع بيت واحد يوميذ في الاسلام غير رسول الله صلي الله عليه وسلم وخديجه وانا ثالثهما at that time no single household was gathered together in the religion of islam save that of the messenger of god khadija and myself as the third among them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 20, NULL, 'Sayingأَرَى نُورَ الْوَحْيِ وَالرِّسَالَةِ، وَأَشُمُّ رِيحَ النُّبُوَّةِ"I saw the light of the revelation and the message, and I smelt the fragrance of prophecy..."', '', NULL, 'Saying', NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'sayingاري نور الوحي والرساله واشم ريح النبوه i saw the light of the revelation and the message and i smelt the fragrance of prophecy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 21, NULL, 'This sketch concerns Ali as the faithful follower who carried on the prophetic pattern. Its focus is the early period of his life, from his birth (c. 599 CE) to the death of the Prophet (11/632). Two later periods fall outside it: the second, from the Prophet''s death to Ali''s own accession to the caliphate (35/656); and the third, his brief caliphate, torn by tragic civil wars and ended by his assassination in 40/661. These periods raise questions tangled in historical and source-critical difficulty, and to enter those disputes would pull away from the main aim of this book — to present the spiritual ethos of this extraordinary figure in a way that shows how widely it speaks, both within Islam and beyond it. That ethos rises above the boundaries of formal religion, just as it rises above the political quarrels underlying the outward Shii-Sunni divergence — quarrels that only draw attention away from the essential spiritual message of Ali.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'this sketch concerns ali as the faithful follower who carried on the prophetic pattern its focus is the early period of his life from his birth c 599 ce to the death of the prophet 11 632 two later periods fall outside it the second from the prophets death to alis own accession to the caliphate 35 656 and the third his brief caliphate torn by tragic civil wars and ended by his assassination in 40 661 these periods raise questions tangled in historical and source critical difficulty and to enter those disputes would pull away from the main aim of this book to present the spiritual ethos of this extraordinary figure in a way that shows how widely it speaks both within islam and beyond it that ethos rises above the boundaries of formal religion just as it rises above the political quarrels underlying the outward shii sunni divergence quarrels that only draw attention away from the essential spiritual message of ali', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 22, NULL, 'What this book brings forward instead is the uniting power of his spiritual teachings — teachings whose great importance and depth Muslims of every school affirm alike. What follows is a brief survey of that earlier period of Ali''s life spent with the Prophet, along with the ways the Prophet described him in well-attested sayings; this is the necessary background for understanding his role as the gate to prophetic wisdom. The second part of this opening chapter then takes up some key principles of his spiritual ethos, with special attention to the place of the intellect within it.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'what this book brings forward instead is the uniting power of his spiritual teachings teachings whose great importance and depth muslims of every school affirm alike what follows is a brief survey of that earlier period of alis life spent with the prophet along with the ways the prophet described him in well attested sayings this is the necessary background for understanding his role as the gate to prophetic wisdom the second part of this opening chapter then takes up some key principles of his spiritual ethos with special attention to the place of the intellect within it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 23, NULL, 'By the account of all Shii authorities and of several Sunni sources, Ali held the singular distinction of being born inside the Kaba in Mecca. His mother was Fatima bt. Asad; his father, Abu Talib, son of Abd al-Muttalib, was a leading member of the Hashimite clan. Abu Talib had raised the young orphan Muhammad, son of his brother Abd Allah, and would later become his chief protector once Islam was preached openly in Mecca. Some years before the mission began, in a time of drought, Muhammad lightened Abu Talib''s burden by taking his young son Ali — then about five years old — into his own household. From that time on, Ali was like a son to him, and the two were seldom apart.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'by the account of all shii authorities and of several sunni sources ali held the singular distinction of being born inside the kaba in mecca his mother was fatima bt asad his father abu talib son of abd al muttalib was a leading member of the hashimite clan abu talib had raised the young orphan muhammad son of his brother abd allah and would later become his chief protector once islam was preached openly in mecca some years before the mission began in a time of drought muhammad lightened abu talibs burden by taking his young son ali then about five years old into his own household from that time on ali was like a son to him and the two were seldom apart', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 24, NULL, 'Ali is held to be the first male to embrace Islam, though he was only nine or ten at the time. Abu Bakr was the first grown man to enter the new religion, and Khadija, the Prophet''s wife, was the first woman. That the young boy answered the prophetic message at once, and held to it without wavering ever after, carries great weight. About three years later, when revelation instructed the Prophet to "warn thy nearest kin":', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'ali is held to be the first male to embrace islam though he was only nine or ten at the time abu bakr was the first grown man to enter the new religion and khadija the prophets wife was the first woman that the young boy answered the prophetic message at once and held to it without wavering ever after carries great weight about three years later when revelation instructed the prophet to warn thy nearest kin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'verse', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 25, NULL, 'Ash-Shu''ara: 214وَأَنذِرْ عَشِيرَتَكَ ٱلْأَقْرَبِينَ', '', 'وَأَنذِرْ عَشِيرَتَكَ ٱلْأَقْرَبِينَ', 'Ash-Shu''ara: 214', 26, 214, 'spiritual ethos 1 in the prophets shadow', 'ash shuara 214وانذر عشيرتك الاقربين', 'وانذر عشيرتك الاقربين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 26, NULL, '(Ash-Shuara: 214), he invited the leading members of his clan to a feast and then addressed them: "O sons of Abd al-Muttalib, I know of no Arab who hath come to his people with a nobler message than mine. I bring you the best of this world and the next. God hath commanded me to call you unto Him. Which of you, then, will help me in this, and be my brother, mine executor and my successor among you?" All remained silent, except for the youthful Ali, who spoke up: "O Prophet of God, I will be thy helper in this." The Prophet then placed his hand on Alis neck and said, "This is my brother, mine executor and my successor among you. Hearken unto him and obey him." Though the clan''s leaders met this with mockery at the time, the declaration was taken far more seriously as the years passed and the extraordinary character, nobility, and intelligence of the Prophet''s young cousin grew ever more dazzlingly plain.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'ash shuara 214 he invited the leading members of his clan to a feast and then addressed them o sons of abd al muttalib i know of no arab who hath come to his people with a nobler message than mine i bring you the best of this world and the next god hath commanded me to call you unto him which of you then will help me in this and be my brother mine executor and my successor among you all remained silent except for the youthful ali who spoke up o prophet of god i will be thy helper in this the prophet then placed his hand on alis neck and said this is my brother mine executor and my successor among you hearken unto him and obey him though the clans leaders met this with mockery at the time the declaration was taken far more seriously as the years passed and the extraordinary character nobility and intelligence of the prophets young cousin grew ever more dazzlingly plain', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 27, NULL, 'This early period also holds the part Ali played in the migration (هِجْرَة) from Mecca to Medina (622 CE), the event that marks the start of the Muslim calendar. The Prophet''s enemies had plotted to kill him; knowing this, Ali risked his own life by taking the Prophet''s place, sleeping in his bed on the night he left. Once in Medina, the Prophet took Ali as his "brother" in the pact of brotherhood he made between the "emigrants" (الْمُهَاجِرُونَ) — the Muslims who had come with him on the hijra from Mecca — and the "helpers" (الْأَنْصَارُ), the Medinan tribes who had embraced the new faith.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'this early period also holds the part ali played in the migration هجره from mecca to medina 622 ce the event that marks the start of the muslim calendar the prophets enemies had plotted to kill him knowing this ali risked his own life by taking the prophets place sleeping in his bed on the night he left once in medina the prophet took ali as his brother in the pact of brotherhood he made between the emigrants المهاجرون the muslims who had come with him on the hijra from mecca and the helpers الانصار the medinan tribes who had embraced the new faith', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'in the prophet''s shadow', '1. In the Prophet''s Shadow', 28, NULL, 'During the Medinan years, Ali made his mark on the battlefield, as a scribe of the Quranic revelation as it came down, and as a leading companion of the Prophet. In the battles against the overwhelming forces of the Meccan Quraysh and their allies, his courage and heroism were second to none. He stood in the front rank of nearly every major engagement fought under the Prophet''s banner and was often made standard-bearer. He was never beaten in the single-combat duel with which battles customarily opened; indeed, he was never beaten in any battle he fought at all. Both his unbreakable courage and his matchless skill as a warrior became legendary. It is said that at the battle of Uhud a heavenly voice was heard to proclaim, "There is no chivalric knight but Ali, no sword but Dhul-Faqar (لَا فَتَى إِلَّا عَلِيّ، وَلَا سَيْفَ إِلَّا ذُو الْفَقَارِ)," the last being the name of the sword the Prophet had given him. The battle that did most to fix Alis name as the foremost — indeed the unconquerable — warrior of Islam was Khaybar, in 7/629. The Muslims had been able to make no headway against the heavily fortified defenses of their foes, which seemed impossible to breach. The Prophet then declared that he would hand the army''s banner to one who "loves God and His Messenger and is loved by God and His Messenger," and that through him victory would be granted. He sent for Ali, who was away on account of an ailment of the eyes. The Prophet healed him by placing saliva on his eyes, and Ali went on to lead the Muslims to victory. In the thick of the fighting, having lost his own shield, he is said to have torn a gate from its hinges and used it as a shield — a gate that, after the battle, eight men could barely lift.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 1 in the prophets shadow', 'during the medinan years ali made his mark on the battlefield as a scribe of the quranic revelation as it came down and as a leading companion of the prophet in the battles against the overwhelming forces of the meccan quraysh and their allies his courage and heroism were second to none he stood in the front rank of nearly every major engagement fought under the prophets banner and was often made standard bearer he was never beaten in the single combat duel with which battles customarily opened indeed he was never beaten in any battle he fought at all both his unbreakable courage and his matchless skill as a warrior became legendary it is said that at the battle of uhud a heavenly voice was heard to proclaim there is no chivalric knight but ali no sword but dhul faqar لا فتي الا علي ولا سيف الا ذو الفقار the last being the name of the sword the prophet had given him the battle that did most to fix alis name as the foremost indeed the unconquerable warrior of islam was khaybar in 7 629 the muslims had been able to make no headway against the heavily fortified defenses of their foes which seemed impossible to breach the prophet then declared that he would hand the armys banner to one who loves god and his messenger and is loved by god and his messenger and that through him victory would be granted he sent for ali who was away on account of an ailment of the eyes the prophet healed him by placing saliva on his eyes and ali went on to lead the muslims to victory in the thick of the fighting having lost his own shield he is said to have torn a gate from its hinges and used it as a shield a gate that after the battle eight men could barely lift', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 0, NULL, 'Ali (ع)s standing as a warrior is only one of many things that explain his unique place in the Islamic tradition. Far more important is how close he was, in every respect, to the Prophet, and the wisdom and sanctity that flowed from that closeness. Ali received the immense honor of marrying the Prophet''s daughter Fatima. She and her mother Khadija, the Prophet''s first wife, are regarded as the most saintly women in Islam. One of the epithets the tradition bestows on Fatima is Majma al-Nurayn, Confluence of the Two Lights'', the two lights of nubuwwa (prophecy) and وَلَايَة (sanctity). After the Prophet himself, Ali was thus the head of what became known as the Ahl al-Bayt, the People of the House, that is, the Prophet''s family.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'ali ع s standing as a warrior is only one of many things that explain his unique place in the islamic tradition far more important is how close he was in every respect to the prophet and the wisdom and sanctity that flowed from that closeness ali received the immense honor of marrying the prophets daughter fatima she and her mother khadija the prophets first wife are regarded as the most saintly women in islam one of the epithets the tradition bestows on fatima is majma al nurayn confluence of the two lights the two lights of nubuwwa prophecy and ولايه sanctity after the prophet himself ali was thus the head of what became known as the ahl al bayt the people of the house that is the prophets family', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 1, NULL, 'The Ahl al-Bayt are addressed in an important Quranic verse as having been purified of all defilement:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'the ahl al bayt are addressed in an important quranic verse as having been purified of all defilement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'verse', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 2, NULL, 'Al-Ahzab: 33وَقَرْنَ فِى بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ ٱلْجَهِلِيَّةِ ٱلْأُولَىٰۖ وَأَقِمْنَ ٱلصَّلَوٰةَ وَآتِينَ ٱلزَّكَوٰةَ وَأَطِعْنَ ٱللَّهَ وَرَسُولَهُۚۥٓ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذْهِبَ عَنكُمُ ٱلرِّجْسَ أَهْلَ ٱلْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًۭاGod only wisheth to remove from you all impurity, O People of the House, and to purify you with a complete purification (Al-Ahzab: 33).', '', 'وَقَرْنَ فِى بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ ٱلْجَهِلِيَّةِ ٱلْأُولَىٰۖ وَأَقِمْنَ ٱلصَّلَوٰةَ وَآتِينَ ٱلزَّكَوٰةَ وَأَطِعْنَ ٱللَّهَ وَرَسُولَهُۚۥٓ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذْهِبَ عَنكُمُ ٱلرِّجْسَ أَهْلَ ٱلْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًۭا', 'Al-Ahzab: 33', 33, 33, 'spiritual ethos 2 the people of the house and the prophets witness', 'al ahzab 33وقرن في بيوتكن ولا تبرجن تبرج الجهليه الاولي واقمن الصلوه واتين الزكوه واطعن الله ورسوله انما يريد الله ليذهب عنكم الرجس اهل البيت ويطهركم تطهيراgod only wisheth to remove from you all impurity o people of the house and to purify you with a complete purification al ahzab 33', 'وقرن في بيوتكن ولا تبرجن تبرج الجهليه الاولي واقمن الصلوه واتين الزكوه واطعن الله ورسوله انما يريد الله ليذهب عنكم الرجس اهل البيت ويطهركم تطهيرا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 3, NULL, 'According to several of the most authoritative early sources, the Prophet called for Fatima, Ali, and their two sons Hasan and Husayn, and declared, This is my Ahl al-Bayt. On one well-attested occasion the Prophet gathered these members of his family beneath his cloak and recited the words of this verse. This happened when a Christian delegation from Najran was engaged in religious debate with the Prophet, and a revelation came calling for a challenge of mutual imprecation (مُبَاهَلَة) against the Christians. The Prophet brought forward the four persons named above for this مُبَاهَلَة, but the Christians declined the challenge.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'according to several of the most authoritative early sources the prophet called for fatima ali and their two sons hasan and husayn and declared this is my ahl al bayt on one well attested occasion the prophet gathered these members of his family beneath his cloak and recited the words of this verse this happened when a christian delegation from najran was engaged in religious debate with the prophet and a revelation came calling for a challenge of mutual imprecation مباهله against the christians the prophet brought forward the four persons named above for this مباهله but the christians declined the challenge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 4, NULL, 'The importance of the Ahl al-Bayt is further expressed in a verse in which the Prophet is instructed:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'the importance of the ahl al bayt is further expressed in a verse in which the prophet is instructed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'verse', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 5, NULL, 'Ash-Shura: 23ذَلِكَ ٱلَّذِى يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ آمَنُوا۟ وَعَمِلُوا۟ ٱلصَّلِحَتِ ۗ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِلَّا ٱلْمَوَدَّةَ فِى ٱلْقُرْبَىٰ ۗ وَمَن يَقْتَرِفْ حَسَنَةًۭ نَّزِدْ لَهُۥ فِيهَا حُسْنًا ۚ إِنَّ ٱللَّهَ غَفُورٌۭ شَكُورٌSay: I ask you for no reward, save love of the near of kin (Ash-Shura: 23).', '', 'ذَلِكَ ٱلَّذِى يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ آمَنُوا۟ وَعَمِلُوا۟ ٱلصَّلِحَتِ ۗ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِلَّا ٱلْمَوَدَّةَ فِى ٱلْقُرْبَىٰ ۗ وَمَن يَقْتَرِفْ حَسَنَةًۭ نَّزِدْ لَهُۥ فِيهَا حُسْنًا ۚ إِنَّ ٱللَّهَ غَفُورٌۭ شَكُورٌ', 'Ash-Shura: 23', 42, 23, 'spiritual ethos 2 the people of the house and the prophets witness', 'ash shura 23ذلك الذي يبشر الله عباده الذين امنوا وعملوا الصلحت قل لا اسلكم عليه اجرا الا الموده في القربي ومن يقترف حسنه نزد له فيها حسنا ان الله غفور شكورsay i ask you for no reward save love of the near of kin ash shura 23', 'ذلك الذي يبشر الله عباده الذين امنوا وعملوا الصلحت قل لا اسلكم عليه اجرا الا الموده في القربي ومن يقترف حسنه نزد له فيها حسنا ان الله غفور شكور');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 6, NULL, 'Several of the most significant Quranic commentators identify the near of kin in this verse as the Prophet''s Ahl al-Bayt. The revelation thus explicitly demands love of the Prophet''s family. This does not exclude the verse''s wider meaning, which takes in love for all those bound to a person by close kinship. How deeply all Muslims are to revere the Prophet''s family is shown further by another practice: blessings are to be called down upon his al, or progeny, as part of the blessings called down upon him. The Quran instructs the believers:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'several of the most significant quranic commentators identify the near of kin in this verse as the prophets ahl al bayt the revelation thus explicitly demands love of the prophets family this does not exclude the verses wider meaning which takes in love for all those bound to a person by close kinship how deeply all muslims are to revere the prophets family is shown further by another practice blessings are to be called down upon his al or progeny as part of the blessings called down upon him the quran instructs the believers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 7, NULL, 'Al-Ahzab: 56إِنَّ ٱللَّهَ وَمَلَٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِىِّۚ يَٓأَيُّهَا ٱلَّذِينَ آمَنُوا۟ صَلُّوا۟ عَلَيْهِ وَسَلِّمُوا۟ تَسْلِيمًاTruly, God and His angels bless the Prophet. O ye who believe, bless him and greet him with peace (Al-Ahzab: 56).', '', NULL, 'Al-Ahzab: 56', NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'al ahzab 56ان الله ومليكته يصلون علي النبي يايها الذين امنوا صلوا عليه وسلموا تسليماtruly god and his angels bless the prophet o ye who believe bless him and greet him with peace al ahzab 56', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 8, NULL, 'When this verse was revealed, the Prophet was asked how one should perform this blessing, and he replied that blessings were to be invoked upon him and his al as follows: O God, bless Muhammad and the progeny of Muhammad, as Thou hast blessed Abraham and the progeny of Abraham. Truly, Thou art the Praised, the Glorious ... This blessing is recited during the canonical prayer. Its importance, together with the obligation to love the Prophet''s family, is beautifully expressed in the following lines by Imam al-Shafii, founder of one of the four schools of Sunni jurisprudence:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'when this verse was revealed the prophet was asked how one should perform this blessing and he replied that blessings were to be invoked upon him and his al as follows o god bless muhammad and the progeny of muhammad as thou hast blessed abraham and the progeny of abraham truly thou art the praised the glorious this blessing is recited during the canonical prayer its importance together with the obligation to love the prophets family is beautifully expressed in the following lines by imam al shafii founder of one of the four schools of sunni jurisprudence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 9, NULL, 'Loving you, O family of the household of the Prophet of God, is an obligation (فَرْضٌ) from God in the Quran which He revealed; Sufficient to show the grandeur of your dignity is that one who blesses you not, no prayer has he.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'loving you o family of the household of the prophet of god is an obligation فرض from god in the quran which he revealed sufficient to show the grandeur of your dignity is that one who blesses you not no prayer has he', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 10, NULL, 'There is also a prophetic saying that underscores the spiritual significance of the Ahl al-Bayt:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'there is also a prophetic saying that underscores the spiritual significance of the ahl al bayt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 11, NULL, 'Truly, I am leaving behind among you the two weighty things (اَلثَّقَلَيْنِ): the Book of God and my Ahl al-Bayt. They will not be parted from each other until they return to me at the [paradisal pool] الْحَوْضَ.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'truly i am leaving behind among you the two weighty things الثقلين the book of god and my ahl al bayt they will not be parted from each other until they return to me at the paradisal pool الحوض', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 12, NULL, 'Beyond these sayings, which concern Ali as the most important member of the Prophet''s Ahl al-Bayt, there are sayings of the Prophet that concern Ali specifically, and these deserve to be cited in full. Only on the basis of these sayings can one begin to appreciate the immensely important role of Ali in the spiritual dimension of the Islamic faith. These traditions (ahadith, sing. hadith) are presented here as a list with minimal commentary, following the manner in which they appear in most standard hadith collections. Anyone who takes prophetic guidance seriously cannot but take Ali seriously, and it is largely for this reason that countless Muslims across the centuries have meditated on these sayings, drawing from them diverse interpretations and incalculable inspiration. In a certain sense, these sayings form the prism through which the tradition views Ali, and they deepen one''s spiritual receptivity to his teachings. The crucial importance of Ali in the spiritual firmament of nascent Islam emerges more clearly in the light of these prophetic descriptions. They should therefore be regarded as a significant part of the prophetic background to Ali s seminal contribution to Islamic spiritual and intellectual life, whether in a Shii, Sunni, or Sufi context.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'beyond these sayings which concern ali as the most important member of the prophets ahl al bayt there are sayings of the prophet that concern ali specifically and these deserve to be cited in full only on the basis of these sayings can one begin to appreciate the immensely important role of ali in the spiritual dimension of the islamic faith these traditions ahadith sing hadith are presented here as a list with minimal commentary following the manner in which they appear in most standard hadith collections anyone who takes prophetic guidance seriously cannot but take ali seriously and it is largely for this reason that countless muslims across the centuries have meditated on these sayings drawing from them diverse interpretations and incalculable inspiration in a certain sense these sayings form the prism through which the tradition views ali and they deepen ones spiritual receptivity to his teachings the crucial importance of ali in the spiritual firmament of nascent islam emerges more clearly in the light of these prophetic descriptions they should therefore be regarded as a significant part of the prophetic background to ali s seminal contribution to islamic spiritual and intellectual life whether in a shii sunni or sufi context', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 13, NULL, 'The traditions given below can be found in any standard Shii hadith collection. To show that they — together with their implications and the devotion they have inspired — are not confined to Shii Islam, they are cited here from two of the most authoritative Sunni traditionists. The first is Ahmad al-Nasai, author of the Sunan, one of the six collections deemed canonical in the Sunni corpus (اَلْكُتُبُ السِّتَّةُ). The second is al-Hakim al-Nisaburi, author of al-Mustadrak alal-sahihayn (Supplement to the Two Sound Collections). This work gathers those prophetic traditions that meet the exacting criteria of authenticity established by Bukhari and Muslim, authors of the sahihayn, but were not included in their own collections. These sayings speak of Ali s distinctions, virtues, and merits, all conveyed by the Arabic word fadail (sing. fadila). They explain why Ahmad b. Hanbal, another leading Sunni traditionist and founder of one of the four Sunni schools of law, made the following statement: No companion of the Prophet has had such fadail ascribed to him as those which have been ascribed to Ali ibn Abi Talib.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'the traditions given below can be found in any standard shii hadith collection to show that they together with their implications and the devotion they have inspired are not confined to shii islam they are cited here from two of the most authoritative sunni traditionists the first is ahmad al nasai author of the sunan one of the six collections deemed canonical in the sunni corpus الكتب السته the second is al hakim al nisaburi author of al mustadrak alal sahihayn supplement to the two sound collections this work gathers those prophetic traditions that meet the exacting criteria of authenticity established by bukhari and muslim authors of the sahihayn but were not included in their own collections these sayings speak of ali s distinctions virtues and merits all conveyed by the arabic word fadail sing fadila they explain why ahmad b hanbal another leading sunni traditionist and founder of one of the four sunni schools of law made the following statement no companion of the prophet has had such fadail ascribed to him as those which have been ascribed to ali ibn abi talib', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 14, NULL, 'The sayings are these:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'the sayings are these', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 15, NULL, 'Truly, Ali is from me and I am from him (إِنَّ عَلِيًّا مِنِّي وَأَنَا مِنْهُ), and he is the wali (patron/spiritual master) of every believer after me.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'truly ali is from me and i am from him ان عليا مني وانا منه and he is the wali patron spiritual master of every believer after me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 16, NULL, 'Ali is with the Quran and the Quran is with Ali, إِنَّ عَلِيًّا مَعَ الْقُرْآنِ وَالْقُرْآنُ مَعَ عَلِيٍّ، لَنْ يَفْتَرِقَا حَتَّى يَرِدَا عَلَيَّ الْحَوْضَ. They will not separate from each other until they return to me at the [paradisal pool] (الْحَوْضَ).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'ali is with the quran and the quran is with ali ان عليا مع القران والقران مع علي لن يفترقا حتي يردا علي الحوض they will not separate from each other until they return to me at the paradisal pool الحوض', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 17, NULL, 'Three things were revealed to me regarding Ali: he is the leader of the Muslims, the guide of the pious, and chief of the radiantly devout (سَيِّدُ الْمُسْلِمِينَ، إِمَامُ الْمُتَّقِينَ، وَقَائِدُ الْغُرِّ الْمُحَجَّلِينَ).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'three things were revealed to me regarding ali he is the leader of the muslims the guide of the pious and chief of the radiantly devout سيد المسلمين امام المتقين وقايد الغر المحجلين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 18, NULL, 'Gazing upon Ali is an act of worship (النَّظَرُ إِلَى عَلِيٍّ عِبَادَةٌ).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'gazing upon ali is an act of worship النظر الي علي عباده', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 19, NULL, 'May God have mercy on Ali. O God, make the truth revolve around Ali wherever he turns (أَدِرِ الْحَقَّ مَعَهُ حَيْثُ دَارَ).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'may god have mercy on ali o god make the truth revolve around ali wherever he turns ادر الحق معه حيث دار', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 20, NULL, 'I am the city of knowledge and Ali is its gate; so whoever desires knowledge, let him enter the gate.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'i am the city of knowledge and ali is its gate so whoever desires knowledge let him enter the gate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 21, NULL, 'O Ali, you are a leader (سَيِّدٌ) in this world and the Hereafter. Your beloved is my beloved, and my beloved is the beloved of God; your enemy is my enemy, and my enemy is the enemy of God. Woe to those who hate you after me [after I have passed away].', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'o ali you are a leader سيد in this world and the hereafter your beloved is my beloved and my beloved is the beloved of god your enemy is my enemy and my enemy is the enemy of god woe to those who hate you after me after i have passed away', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 22, NULL, 'Whoever desires to live my life and to die my death and to take his rest in the eternal Garden my Lord has promised me, let him orient himself toward Ali ibn Abi Talib, for truly he will never lead you away from right guidance, nor lead you into error.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'whoever desires to live my life and to die my death and to take his rest in the eternal garden my lord has promised me let him orient himself toward ali ibn abi talib for truly he will never lead you away from right guidance nor lead you into error', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 23, NULL, 'The Prophet said that Ali was as my own soul (عليٌّ مِنِّي بِمَنْزِلَةِ نَفْسِي).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'the prophet said that ali was as my own soul علي مني بمنزله نفسي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 24, NULL, 'He said to Ali, You are from me and I am from you, أنْتَ مِنِّی وَ أِنَا مِنْکَ.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'he said to ali you are from me and i am from you انت مني و انا منك', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 25, NULL, '... whoever obeys Ali obeys me, and whoever disobeys him disobeys me.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'whoever obeys ali obeys me and whoever disobeys him disobeys me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 26, NULL, 'You will clarify for my community that over which they will differ after me (أَنْتَ تُبَيِّنُ لِأُمَّتِي مَا اخْتَلَفُوا فِيهِ مِنْ بَعْدِي).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'you will clarify for my community that over which they will differ after me انت تبين لامتي ما اختلفوا فيه من بعدي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 27, NULL, 'There is one among you who will fight for the تَأْوِيل [spiritual interpretation] of the Quran as I have fought for its tanzil [literal revelation], عَلِیٌّ یُقَاتِلُ عَلیٰ تَاوِیلِہِ کَما قَاتَلْتُ عَلیٰ تَنزِیلِہِ. Abu Bakr asked, Is it I? The Prophet said, No. Umar asked, Is it I? The Prophet said, No, it is the one who is mending the sandal. The Prophet had given Ali his sandal to mend.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'there is one among you who will fight for the تاويل spiritual interpretation of the quran as i have fought for its tanzil literal revelation علي يقاتل علي تاويله كما قاتلت علي تنزيله abu bakr asked is it i the prophet said no umar asked is it i the prophet said no it is the one who is mending the sandal the prophet had given ali his sandal to mend', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 28, NULL, 'O Ali, there is in you something akin to Jesus, on whom be peace and blessings. The Jews hated him so intensely that they slandered his mother; and the Christians loved him so intensely that they ascribed to him a rank he did not possess. O Ali, whoever separates himself from me separates himself from God, and whoever separates himself from you, O Ali, separates himself from me.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'o ali there is in you something akin to jesus on whom be peace and blessings the jews hated him so intensely that they slandered his mother and the christians loved him so intensely that they ascribed to him a rank he did not possess o ali whoever separates himself from me separates himself from god and whoever separates himself from you o ali separates himself from me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 29, NULL, 'Whoever curses Ali curses me, and whoever curses me curses God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'whoever curses ali curses me and whoever curses me curses god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 30, NULL, 'The Prophet said to his wife Aisha, Call unto me the leader (سَيِّدٌ) of the Arabs. She asked, O Prophet of God, are you not the leader of the Arabs? He said, I am the leader of the children of Adam, and Ali is the leader of the Arabs.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'the prophet said to his wife aisha call unto me the leader سيد of the arabs she asked o prophet of god are you not the leader of the arabs he said i am the leader of the children of adam and ali is the leader of the arabs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 31, NULL, 'When Fatima was asked by some women why the Prophet had given her in marriage to a man as poor as Ali, she related this to the Prophet. He said: Are you not pleased that God, exalted and glorified be He, surveyed the people of the world and chose two men from among them: one is your father, and the other your husband?', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'when fatima was asked by some women why the prophet had given her in marriage to a man as poor as ali she related this to the prophet he said are you not pleased that god exalted and glorified be he surveyed the people of the world and chose two men from among them one is your father and the other your husband', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 32, NULL, 'The first of you to reach the [paradisal] pool (الْحَوْضَ) is the first of you who entered Islam, Ali ibn Abi Talib.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'the first of you to reach the paradisal pool الحوض is the first of you who entered islam ali ibn abi talib', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 33, NULL, 'Ali is from me and I am from him (عَلِيٌّ مِنِّي وَأَنَا مِنْهُ), and nobody can fulfill my duty but myself and Ali.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'ali is from me and i am from him علي مني وانا منه and nobody can fulfill my duty but myself and ali', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 34, NULL, 'Ali himself relates that the Prophet told him that none but a believer will love him, and none but a hypocrite will hate him.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'ali himself relates that the prophet told him that none but a believer will love him and none but a hypocrite will hate him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 35, NULL, 'When the Prophet was about to depart on an expedition to Tabuk, he left Ali as his deputy in Medina. Ali was saddened not to be going with him. The Prophet said, Are you not content to stand in relation to me as Aaron stood in relation to Moses, except that there is no prophet after me?', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'when the prophet was about to depart on an expedition to tabuk he left ali as his deputy in medina ali was saddened not to be going with him the prophet said are you not content to stand in relation to me as aaron stood in relation to moses except that there is no prophet after me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 36, NULL, 'The Prophet prayed to God to bring the most beloved of Thy creatures'' to share with him a meal of fowl. Only when Ali arrived did the Prophet invite him to join him.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'the prophet prayed to god to bring the most beloved of thy creatures to share with him a meal of fowl only when ali arrived did the prophet invite him to join him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 37, NULL, 'Among the several Quranic verses on which the Prophet commented with reference to Ali is 13:7: Verily thou art a warner, and for every people there is a guide. The Prophet said, I am the warner... you are the guide, O Ali. After me, the rightly-guided shall be guided by you.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'among the several quranic verses on which the prophet commented with reference to ali is 13 7 verily thou art a warner and for every people there is a guide the prophet said i am the warner you are the guide o ali after me the rightly guided shall be guided by you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 38, NULL, 'Verse 55 of Sura 5 (al-Maida (اَلْمَائِدَةُ)) reads, Verily your wali is only God and His Messenger and those who believe, establish the prayer and give alms while bowing in prayer. The commentators tie its revelation to the occasion when Ali, while bowing in prayer, extended his ring to a beggar who had asked for alms. On being told of the incident, the Prophet recited this verse, and then added what are perhaps the most celebrated words ever spoken about Ali: For whomever I am the mawla [guardian, master, close friend], Ali is his mawla (مَنْ كُنْتُ مَوْلَاهُ فَعَلِيٌّ مَوْلَاهُ).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'verse 55 of sura 5 al maida المايده reads verily your wali is only god and his messenger and those who believe establish the prayer and give alms while bowing in prayer the commentators tie its revelation to the occasion when ali while bowing in prayer extended his ring to a beggar who had asked for alms on being told of the incident the prophet recited this verse and then added what are perhaps the most celebrated words ever spoken about ali for whomever i am the mawla guardian master close friend ali is his mawla من كنت مولاه فعلي مولاه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 39, NULL, 'This last saying was expressed on a number of occasions, the most famous of which came after the Prophet''s final pilgrimage to Mecca, in the year 10/632, at a pool midway between Mecca and Medina known as Ghadir Khumm. The Prophet assembled all the pilgrims, had a pulpit erected, and delivered an address to the thousands gathered there. The address culminated in the declaration: For whomever I am the mawla, Ali is his mawla. For Shiis, this is an unambiguous designation (نَصّ) of Ali as the Prophet''s successor; for Sunnis it marks the special closeness of Ali to the Prophet, but not his nomination as successor in the political domain. That the reference to Ali as mawla — in some versions as wali — carries the highest spiritual significance is, however, not seriously disputed. Umar is reported to have approached Ali and said, Bakh bakh, an expression of congratulation, you have become my mawla and the mawla of every Muslim. The heated debate that has occupied countless minds throughout history, and continues to this day, turns on the political implications of Ali s spiritual authority, his وَلَايَة.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'this last saying was expressed on a number of occasions the most famous of which came after the prophets final pilgrimage to mecca in the year 10 632 at a pool midway between mecca and medina known as ghadir khumm the prophet assembled all the pilgrims had a pulpit erected and delivered an address to the thousands gathered there the address culminated in the declaration for whomever i am the mawla ali is his mawla for shiis this is an unambiguous designation نص of ali as the prophets successor for sunnis it marks the special closeness of ali to the prophet but not his nomination as successor in the political domain that the reference to ali as mawla in some versions as wali carries the highest spiritual significance is however not seriously disputed umar is reported to have approached ali and said bakh bakh an expression of congratulation you have become my mawla and the mawla of every muslim the heated debate that has occupied countless minds throughout history and continues to this day turns on the political implications of ali s spiritual authority his ولايه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 40, NULL, 'Although the place of Ali within Shii Islam is not the subject here, his charisma was such that, even during the Prophet''s own lifetime, a group came to be known as the shia, or partisans, of Ali. Al-Tabari, author of the first great commentary on the Quran, reports that the Prophet interpreted the verse:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'although the place of ali within shii islam is not the subject here his charisma was such that even during the prophets own lifetime a group came to be known as the shia or partisans of ali al tabari author of the first great commentary on the quran reports that the prophet interpreted the verse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 41, NULL, 'Al-Bayyinah: 7إِنَّ ٱلَّذِينَ آمَنُوا۟ وَعَمِلُوا۟ ٱلصَّلِحَتِ أُو۟لَٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِThose who have faith and do righteous deeds, they are the best of created beings'' (Al-Bayyinah: 7)', '', NULL, 'Al-Bayyinah: 7', NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'al bayyinah 7ان الذين امنوا وعملوا الصلحت اوليك هم خير البريهthose who have faith and do righteous deeds they are the best of created beings al bayyinah 7', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 42, NULL, 'He interpreted it as referring to Ali and his shia.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'he interpreted it as referring to ali and his shia', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the people of the house and the prophet''s witness', '2. The People of the House and the Prophet''s Witness', 43, NULL, 'Four individuals in particular were renowned for their devotion to Ali during the Prophet''s lifetime and are regarded as the prototypes of early Shiism: Salman al-Farisi, Abu Dharr al-Ghifari, Ammar b. Yasir, and Miqdad b. Amr. This early love for Ali should not be equated with the theological doctrines later elaborated in the Shii branch of Islam in the generations that followed. It is nonetheless worth emphasizing that, at the core of Shiism in all its different expressions, lies the notion of fidelity to Ali. This fidelity, loyalty, or love is one aspect of وَلَايَة; the other, complementary aspect is the spiritual authority or sanctity of Ali. It is equally important to stress that neither devotion to Ali nor the spiritual orientation toward the وَلَايَة he embodies belongs to Shiism alone. Rather, it extends across the whole of the Islamic faith, for devotion to Ali as head of the Prophet''s Ahl al-Bayt is found throughout the Muslim world and is especially deep wherever Sufism flourishes. Ali is regarded as the first spiritual pole (قُطْبٌ) of Sufism after the Prophet himself, and he stands at the summit of all the spiritual chains (salasil, sing. silsila) through which the Sufi orders trace their lineage back to the Prophet. To speak of Ali is to speak not of exclusivist sectarianism but of universal spirituality.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 2 the people of the house and the prophets witness', 'four individuals in particular were renowned for their devotion to ali during the prophets lifetime and are regarded as the prototypes of early shiism salman al farisi abu dharr al ghifari ammar b yasir and miqdad b amr this early love for ali should not be equated with the theological doctrines later elaborated in the shii branch of islam in the generations that followed it is nonetheless worth emphasizing that at the core of shiism in all its different expressions lies the notion of fidelity to ali this fidelity loyalty or love is one aspect of ولايه the other complementary aspect is the spiritual authority or sanctity of ali it is equally important to stress that neither devotion to ali nor the spiritual orientation toward the ولايه he embodies belongs to shiism alone rather it extends across the whole of the islamic faith for devotion to ali as head of the prophets ahl al bayt is found throughout the muslim world and is especially deep wherever sufism flourishes ali is regarded as the first spiritual pole قطب of sufism after the prophet himself and he stands at the summit of all the spiritual chains salasil sing silsila through which the sufi orders trace their lineage back to the prophet to speak of ali is to speak not of exclusivist sectarianism but of universal spirituality', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 0, NULL, 'The spiritual ethos of Ali (ع) has an intellectual heart. The intellect (الْعَقْل) plays a central part in how his spiritual teachings are worked out and taken in. Sketching the key features of that ethos, with special attention to its intellectual side, gives firmer ground to the explorations that follow. One aim is to bring out something of the spirit of the intellect, الرُّوحُ الْعَقْلُ — the phrase coined for the bond between the intellect and the spirit as it appears in the Imam''s worldview. This spirit surpasses the workings of the rational mind even as it contains them, and it reaches into areas not usually tied to the intellect today, such as moral conduct and a sense of beauty. This spiritual understanding of the intellect is directly connected to the Quranic idea of the spirit (الرُّوح), and much of what follows examines what comes of engaging deeply with this unifying spirit that belongs to the intellect.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'the spiritual ethos of ali ع has an intellectual heart the intellect العقل plays a central part in how his spiritual teachings are worked out and taken in sketching the key features of that ethos with special attention to its intellectual side gives firmer ground to the explorations that follow one aim is to bring out something of the spirit of the intellect الروح العقل the phrase coined for the bond between the intellect and the spirit as it appears in the imams worldview this spirit surpasses the workings of the rational mind even as it contains them and it reaches into areas not usually tied to the intellect today such as moral conduct and a sense of beauty this spiritual understanding of the intellect is directly connected to the quranic idea of the spirit الروح and much of what follows examines what comes of engaging deeply with this unifying spirit that belongs to the intellect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 1, NULL, 'It helps at the outset to explain why the English word intellect is preferred over reason to render aql. The word is meant to call up the original sense of intellectus in Latin Christendom, a sense almost identical to that of nous in the Greek of the Church Fathers. Intellectus means understanding, and it holds within it the idea of standing under a thing: to understand something is to stand beneath a perception of reality and let that perception overshadow and govern one''s actions, for a person always acts in the shadow of how things are perceived. Intellectus, or nous, is therefore the faculty able to see transcendent realities directly, in contemplation — the very realities of which the Quran speaks but which are hidden from the senses. Reason, which renders the Latin ratio and the Greek dianoia, is by contrast indirect and step by step; it works through logic and reaches only mental concepts of those realities. The root of ratio means a relation or comparison between two numbers, and this catches how reason proceeds: by comparison, by a binary logic of affirming and denying, weighing one thing against another until it has defined what it examines. Reason so understood is the instrument the intellect uses, but it can carry a person only as far as the outward form of a thing, only as far as the mental concept or image of a reality. With the intellect one can contemplate, or see, the Absolute; with reason one can only think about it. To know about a reality is one thing; to contemplate and experience it directly is quite another, and it is the intellect, not reason, that is capable of that experience — even though it is through reason that the intellect is brought to it.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'it helps at the outset to explain why the english word intellect is preferred over reason to render aql the word is meant to call up the original sense of intellectus in latin christendom a sense almost identical to that of nous in the greek of the church fathers intellectus means understanding and it holds within it the idea of standing under a thing to understand something is to stand beneath a perception of reality and let that perception overshadow and govern ones actions for a person always acts in the shadow of how things are perceived intellectus or nous is therefore the faculty able to see transcendent realities directly in contemplation the very realities of which the quran speaks but which are hidden from the senses reason which renders the latin ratio and the greek dianoia is by contrast indirect and step by step it works through logic and reaches only mental concepts of those realities the root of ratio means a relation or comparison between two numbers and this catches how reason proceeds by comparison by a binary logic of affirming and denying weighing one thing against another until it has defined what it examines reason so understood is the instrument the intellect uses but it can carry a person only as far as the outward form of a thing only as far as the mental concept or image of a reality with the intellect one can contemplate or see the absolute with reason one can only think about it to know about a reality is one thing to contemplate and experience it directly is quite another and it is the intellect not reason that is capable of that experience even though it is through reason that the intellect is brought to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 2, NULL, 'These opening reflections on the spirit of the intellect in the Imam''s ethos turn chiefly on a short discourse of the greatest importance in the Nahj al-balagha: the one the Imam gave to Kumayl, among his closest disciples. The method here is that of an interpretive commentary on the Imam''s words, drawing not only on his other sayings on the same theme but also on Quranic verses that agree with them and, at times, on traditions of the Prophet that either help clarify the Imam''s saying at hand or are themselves clarified by it. Three factors belonging to the spirit of this intellectual outlook must be stressed first: the centrality of revelation; the harmony between revelation and the intellect; and the distinction between the intellect, understood as the principle by which consciousness is articulated, and reason, understood as one expression of that principle.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'these opening reflections on the spirit of the intellect in the imams ethos turn chiefly on a short discourse of the greatest importance in the nahj al balagha the one the imam gave to kumayl among his closest disciples the method here is that of an interpretive commentary on the imams words drawing not only on his other sayings on the same theme but also on quranic verses that agree with them and at times on traditions of the prophet that either help clarify the imams saying at hand or are themselves clarified by it three factors belonging to the spirit of this intellectual outlook must be stressed first the centrality of revelation the harmony between revelation and the intellect and the distinction between the intellect understood as the principle by which consciousness is articulated and reason understood as one expression of that principle', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 3, NULL, 'To begin with the first: everything in the Imam''s life and teachings is centered on the Quranic revelation and on its embodiment in the Prophet''s conduct. The Quran is the center around which the intellect must turn, for the intellect needs a center, principles, and definitions to hold fast to if it is to be rightly guided. Both the thought and the life of the Imam can be read as a kind of spiritual commentary, a تَأْوِيل, on the sacred text. On the doctrinal plane, it can be said with confidence that Ali had an inborn gift for the work of تَأْوِيل. On the plane of his own life as well, his path — from his birth in the most holy shrine of the Kaba to his martyrdom in the mosque of Kufa — reads as a dramatic unfolding of the inner meaning of the revealed text. Ali s refusal to stop at the surface of things, whether religious, ethical, or political, showed an unflinching fidelity to the sacred substance of the religion, a fidelity that called for inward intellectual penetration and outward armed resistance alike. The saying of the Prophet cited earlier bears closely on this: Ali would fight for the تَأْوِيل of the Quran just as he, the Prophet, had fought for its tanzil, عَلِیُّ یُقَاتِلُ عَلیٰ تَاوِیلِہ کَما قَتَلُ عَلیَ تَنزِیلِہِ. Ali s short caliphate was dominated by bloody civil wars, and a strong case can be made that all three — the wars of the Camel (اَلْجَمَلُ), of Nahrawan, and of Siffin — were fought for the sake of interpreting and applying the Quran rightly, for the clarification of its central message of تَوْحِيد, and for the realization of that oneness on every level, spiritual and social alike. These were not political battles or mere struggles for power; they were waged to clarify and uphold the oneness of God according to the principles of the Quran — in thought, in speech, and in action. The Imam''s response to a bedouin brings this vividly home. Just as the battle of the Camel (اَلْجَمَلُ) was about to begin, the man approached him and said, O Commander of the Faithful (یَا أَمِیرَ الْمُوْمِنِینَ)! Do you say that God is one? Those present rebuked the bedouin, telling him this was neither the time nor the place for such questions. The Imam, however, intervened: Leave him, for surely what the bedouin wishes is what we wish for the people.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'to begin with the first everything in the imams life and teachings is centered on the quranic revelation and on its embodiment in the prophets conduct the quran is the center around which the intellect must turn for the intellect needs a center principles and definitions to hold fast to if it is to be rightly guided both the thought and the life of the imam can be read as a kind of spiritual commentary a تاويل on the sacred text on the doctrinal plane it can be said with confidence that ali had an inborn gift for the work of تاويل on the plane of his own life as well his path from his birth in the most holy shrine of the kaba to his martyrdom in the mosque of kufa reads as a dramatic unfolding of the inner meaning of the revealed text ali s refusal to stop at the surface of things whether religious ethical or political showed an unflinching fidelity to the sacred substance of the religion a fidelity that called for inward intellectual penetration and outward armed resistance alike the saying of the prophet cited earlier bears closely on this ali would fight for the تاويل of the quran just as he the prophet had fought for its tanzil علي يقاتل علي تاويله كما قتل علي تنزيله ali s short caliphate was dominated by bloody civil wars and a strong case can be made that all three the wars of the camel الجمل of nahrawan and of siffin were fought for the sake of interpreting and applying the quran rightly for the clarification of its central message of توحيد and for the realization of that oneness on every level spiritual and social alike these were not political battles or mere struggles for power they were waged to clarify and uphold the oneness of god according to the principles of the quran in thought in speech and in action the imams response to a bedouin brings this vividly home just as the battle of the camel الجمل was about to begin the man approached him and said o commander of the faithful يا امير المومنين do you say that god is one those present rebuked the bedouin telling him this was neither the time nor the place for such questions the imam however intervened leave him for surely what the bedouin wishes is what we wish for the people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 4, NULL, 'This response bears directly on the principle that right intention comes before outward action, whatever that action may be. Had the Imam been guided by reason alone, he would have sided with those who rebuked the bedouin and told him to find a fitter time and place; but he saw with the intellect that stands above reason. For the Imam, the deepest intention behind every action, whether religious in the ordinary sense or military as here, is knowledge of the true nature of ultimate reality. What the Imam wishes for the people, then, is precisely this knowledge, and it must lie at the very heart of all concerns, motives, and actions, whether on the battlefield or the prayer-rug. There is therefore no time or place where the question What do you mean by saying God is one? is beside the point. It was for the sake of true knowledge of the divine, and of all that flows from it in society, that the Imam was fighting, in fulfillment of the prophetic saying just mentioned. On the very field of battle, then, the Imam gives a discourse on the meaning of divine oneness. The first part of his reply holds a key to his whole spiritual ethos. He rejects any notion that God''s oneness is numerical, a matter of counting. He tells the bedouin that one may not say one while holding any numerical idea in mind, for that which has no second does not enter into the category of numbers''. The moment a thing can be counted as one, it at once admits the possibility of two, three, four; a oneness understood in this numerical sense is thus undone by the very number that would affirm it.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'this response bears directly on the principle that right intention comes before outward action whatever that action may be had the imam been guided by reason alone he would have sided with those who rebuked the bedouin and told him to find a fitter time and place but he saw with the intellect that stands above reason for the imam the deepest intention behind every action whether religious in the ordinary sense or military as here is knowledge of the true nature of ultimate reality what the imam wishes for the people then is precisely this knowledge and it must lie at the very heart of all concerns motives and actions whether on the battlefield or the prayer rug there is therefore no time or place where the question what do you mean by saying god is one is beside the point it was for the sake of true knowledge of the divine and of all that flows from it in society that the imam was fighting in fulfillment of the prophetic saying just mentioned on the very field of battle then the imam gives a discourse on the meaning of divine oneness the first part of his reply holds a key to his whole spiritual ethos he rejects any notion that gods oneness is numerical a matter of counting he tells the bedouin that one may not say one while holding any numerical idea in mind for that which has no second does not enter into the category of numbers the moment a thing can be counted as one it at once admits the possibility of two three four a oneness understood in this numerical sense is thus undone by the very number that would affirm it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 5, NULL, 'That which has no second is not merely a divinity to which no partner can be ascribed, as a theologian might put it, but that reality which has no otherness'' — the Real, اَلْحَقّ, at once transcendent and immanent, beyond all things'' and yet made manifest by all things'', at once out of reach and inseparable from all that is. To say that God has no otherness is not to say that things exist which might have been His partners but which believers simply choose not to associate with Him; it is to affirm that nothing in all of existence bears His likeness, nothing that could be set beside Him. In these few words the Imam works, for those who have ears to hear, a shift of awareness: from the doctrinal notion of one God against many gods to the mystical grasp of the one and only Reality, before which everything else is mere appearance. All things come to be seen as outward appearances waiting to be read, as signs (آیات) pointing beyond themselves to That of which they are the manifestations, for an aya is precisely a meaningful token that points beyond itself to another. Tracing these appearances back to their source and origin is the literal meaning of تَأْوِيل: a return to the awwal, the First (عَوْدَۃٌ اِلَی الْاَوَّلِ). On the one hand, the Real is described as the beginning and end of all things, the apparent and the hidden; there is nothing in being but this one Reality: He is the First and the Last, the Outward and the Inward (Al-Hadid: 3).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'that which has no second is not merely a divinity to which no partner can be ascribed as a theologian might put it but that reality which has no otherness the real الحق at once transcendent and immanent beyond all things and yet made manifest by all things at once out of reach and inseparable from all that is to say that god has no otherness is not to say that things exist which might have been his partners but which believers simply choose not to associate with him it is to affirm that nothing in all of existence bears his likeness nothing that could be set beside him in these few words the imam works for those who have ears to hear a shift of awareness from the doctrinal notion of one god against many gods to the mystical grasp of the one and only reality before which everything else is mere appearance all things come to be seen as outward appearances waiting to be read as signs ايات pointing beyond themselves to that of which they are the manifestations for an aya is precisely a meaningful token that points beyond itself to another tracing these appearances back to their source and origin is the literal meaning of تاويل a return to the awwal the first عوده الي الاول on the one hand the real is described as the beginning and end of all things the apparent and the hidden there is nothing in being but this one reality he is the first and the last the outward and the inward al hadid 3', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'verse', 'intellect, not reason', '3. Intellect, Not Reason', 6, NULL, 'Al-Hadid: 3هُوَ ٱلْأَوَّلُ وَٱلْآخِرُ وَٱلظَّهِرُ وَٱلْبَاطِنُ ۖ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', '', 'هُوَ ٱلْأَوَّلُ وَٱلْآخِرُ وَٱلظَّهِرُ وَٱلْبَاطِنُ ۖ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'Al-Hadid: 3', 57, 3, 'spiritual ethos 3 intellect not reason', 'al hadid 3هو الاول والاخر والظهر والباطن وهو بكل شيء عليم', 'هو الاول والاخر والظهر والباطن وهو بكل شيء عليم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 7, NULL, 'On the other hand, apparent multiplicity is to be brought back to real oneness: We shall show them Our signs (سَنُرِيهِمْ آيَتِنَا) on the horizons and in their own souls, so that it be clear to them that He is the Real (Fussilat: 53).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'on the other hand apparent multiplicity is to be brought back to real oneness we shall show them our signs سنريهم ايتنا on the horizons and in their own souls so that it be clear to them that he is the real fussilat 53', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'verse', 'intellect, not reason', '3. Intellect, Not Reason', 8, NULL, 'Fussilat: 53سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ', '', 'سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ', 'Fussilat: 53', 41, 53, 'spiritual ethos 3 intellect not reason', 'fussilat 53سنريهم ايتنا في الافاق وفي انفسهم حتي يتبين لهم انه الحق', 'سنريهم ايتنا في الافاق وفي انفسهم حتي يتبين لهم انه الحق');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 9, NULL, 'In one saying attributed to Ali, the Prophet is described as the first whom God taught the science of تَأْوِيل, and who in turn taught it to Ali. According to the Prophet, Truly, Ali is with the Quran, and the Quran is with Ali, أَنَّ عَلِیٌّ مَعَ الْقُرْآنِ، وَ قُرْآنٌ مَعَ الْعَلِیِّ. In another famous saying, often quoted by Sufi commentators, Ali claimed that he could load seventy camels with the pages of commentary he could give on the Fatiha alone, the opening chapter of the Quran. Ali s cousin Ibn Abbas, often called the first commentator, likewise claimed to have learned the science of interpretation from Ali.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'in one saying attributed to ali the prophet is described as the first whom god taught the science of تاويل and who in turn taught it to ali according to the prophet truly ali is with the quran and the quran is with ali ان علي مع القران و قران مع العلي in another famous saying often quoted by sufi commentators ali claimed that he could load seventy camels with the pages of commentary he could give on the fatiha alone the opening chapter of the quran ali s cousin ibn abbas often called the first commentator likewise claimed to have learned the science of interpretation from ali', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 10, NULL, 'Closely related is a saying of the Imam of the first importance, which helps explain why he is held in the highest esteem within the discipline of Quranic exegesis, tafsir: The Quran consists of a book inscribed, between two covers; it speaks not with a tongue, it cannot do without an interpreter (لَا بُدَّ لَهُ مِنْ تُرْجُمَانٍ). The mutual dependence of revelation and the intellect is underlined again in the saying, The prophet of a man is the interpreter of his intellect (رَسُولُ الرَّجُلِ تَرْجُمَانُ عَقْلِهِ). Elsewhere the intellect is set in plain correspondence with the inner messenger: the intellect is the messenger of the Real.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'closely related is a saying of the imam of the first importance which helps explain why he is held in the highest esteem within the discipline of quranic exegesis tafsir the quran consists of a book inscribed between two covers it speaks not with a tongue it cannot do without an interpreter لا بد له من ترجمان the mutual dependence of revelation and the intellect is underlined again in the saying the prophet of a man is the interpreter of his intellect رسول الرجل ترجمان عقله elsewhere the intellect is set in plain correspondence with the inner messenger the intellect is the messenger of the real', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 11, NULL, 'The Imam''s teachings, which give voice to his spiritual ethos, should therefore be read above all as creative interpretations of the Quranic revelation. They set in motion a movement from the letter of the revelation to its spirit, and from the spirit of the revelation to the spirit of the Revealer — a work of retracing, of returning to the source, the origin, the beginning, al-awwal, achieved to the degree that the spirit of the intellect is brought to life within the interpreter. Yet the Revealer stays of necessity hidden even as He is revealed through the revelation, hidden because the essence of what is revealed, the divine Reality in itself, cannot be uttered or put into words; only the forms of its manifestations can be revealed. This play between form and the formless, the evident and the hidden, the revealed and the concealed — such pairs of opposites lie at the root of the paradoxical manner of expression for which the Imam is renowned, and which recurs throughout this book. The relationship that especially concerns the present discussion is the second of the three factors named above: that between revelation and intellection, by which is meant the creative use of the intellect. This relationship matters all the more in a setting so largely defined by fidelity to revelation. Where strict rationalists hold intellect and revelation to be mutually exclusive, here they are seen as fully harmonious, standing in creative reciprocity, each needing the other for its completeness, its wholeness, for the making one that is the very essence of تَوْحِيد.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'the imams teachings which give voice to his spiritual ethos should therefore be read above all as creative interpretations of the quranic revelation they set in motion a movement from the letter of the revelation to its spirit and from the spirit of the revelation to the spirit of the revealer a work of retracing of returning to the source the origin the beginning al awwal achieved to the degree that the spirit of the intellect is brought to life within the interpreter yet the revealer stays of necessity hidden even as he is revealed through the revelation hidden because the essence of what is revealed the divine reality in itself cannot be uttered or put into words only the forms of its manifestations can be revealed this play between form and the formless the evident and the hidden the revealed and the concealed such pairs of opposites lie at the root of the paradoxical manner of expression for which the imam is renowned and which recurs throughout this book the relationship that especially concerns the present discussion is the second of the three factors named above that between revelation and intellection by which is meant the creative use of the intellect this relationship matters all the more in a setting so largely defined by fidelity to revelation where strict rationalists hold intellect and revelation to be mutually exclusive here they are seen as fully harmonious standing in creative reciprocity each needing the other for its completeness its wholeness for the making one that is the very essence of توحيد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 12, NULL, 'Indeed, one of the most striking features of the Imam''s outlook is the way it lays bare the emptiness of many false or overdrawn oppositions that later came to mark, or were forced upon, Islamic thought. This owes much to the deeply synthetic quality of the Imam''s discourses, seen as pre-philosophical by some scholars and as supra-philosophical — inspired and evocative — by those within the Islamic spiritual tradition. The seemingly unbridgeable split between intellect and revelation shows up in several opposed forms: reason versus faith, convention (سنۃ) versus nature (طَبِيعَة), imitation (تَقْلِيد) versus verification (تَحْقِيق), piety versus inquiry, and so on. In Ali s ethos, however, intellect and revelation are not mutually exclusive but complementary, and at the highest level inseparable, since truth is one. The human intellect plainly cannot be equated with divine revelation, yet the spirit that animates the intellect is not, in the end, bound by human limits. It is this spirit that perceives and grasps the divine character of revelation.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'indeed one of the most striking features of the imams outlook is the way it lays bare the emptiness of many false or overdrawn oppositions that later came to mark or were forced upon islamic thought this owes much to the deeply synthetic quality of the imams discourses seen as pre philosophical by some scholars and as supra philosophical inspired and evocative by those within the islamic spiritual tradition the seemingly unbridgeable split between intellect and revelation shows up in several opposed forms reason versus faith convention سنه versus nature طبيعه imitation تقليد versus verification تحقيق piety versus inquiry and so on in ali s ethos however intellect and revelation are not mutually exclusive but complementary and at the highest level inseparable since truth is one the human intellect plainly cannot be equated with divine revelation yet the spirit that animates the intellect is not in the end bound by human limits it is this spirit that perceives and grasps the divine character of revelation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 13, NULL, 'The divine spirit that shapes the form of revelation and fills its content must be fathomable, to some degree, by human awareness; without this, revelation would amount to no more than a set of rules and regulations for the will, rather than a source of creative inspiration for the intelligence. It cannot be stressed too strongly that divine revelation, far from curbing the workings of reason and imposing some unintelligible command, on the contrary asks for a creative engagement with all the resources of the intelligence — above all those acts of reflection and meditation for which the Imam himself is renowned, and which the Quran calls for again and again. It is the very opposite of a decree imposed from outside: the Quran constantly demands fikr, deep and sustained reflection, and such reflection does not shut the meaning of the text within its literal surface but opens it out, unfolding the inner horizons of meaning folded within the letter.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'the divine spirit that shapes the form of revelation and fills its content must be fathomable to some degree by human awareness without this revelation would amount to no more than a set of rules and regulations for the will rather than a source of creative inspiration for the intelligence it cannot be stressed too strongly that divine revelation far from curbing the workings of reason and imposing some unintelligible command on the contrary asks for a creative engagement with all the resources of the intelligence above all those acts of reflection and meditation for which the imam himself is renowned and which the quran calls for again and again it is the very opposite of a decree imposed from outside the quran constantly demands fikr deep and sustained reflection and such reflection does not shut the meaning of the text within its literal surface but opens it out unfolding the inner horizons of meaning folded within the letter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 14, NULL, 'For the revealed text is itself silent; it speaks only through its interpreter, the intellect. This understanding of the bond between intellect and revelation shuts out all literalism and shallowness, every attempt to pen meaning within a flat, one-sided reading. How deeply the text''s meaning is sounded depends on the depth and penetration of the interpreter''s own intellect, for the text carries many levels of meaning at once. At its most profound, this prophetic intellect rejoins the very source of revelation itself; for it is this inner prophet, the innermost degree of consciousness, that is the ultimate ground on which a person can confirm the verses of the outer revelation as true — to validate them through lived experience, and not merely to affirm them as dogma. It is in this sense that the Imam says, in the first sermon of the Nahj, that one of the purposes for which God sent forth prophets to mankind was to unearth for them the buried treasures of the intellects'' (دَفَائِنُ الْعُقُولِ).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'for the revealed text is itself silent it speaks only through its interpreter the intellect this understanding of the bond between intellect and revelation shuts out all literalism and shallowness every attempt to pen meaning within a flat one sided reading how deeply the texts meaning is sounded depends on the depth and penetration of the interpreters own intellect for the text carries many levels of meaning at once at its most profound this prophetic intellect rejoins the very source of revelation itself for it is this inner prophet the innermost degree of consciousness that is the ultimate ground on which a person can confirm the verses of the outer revelation as true to validate them through lived experience and not merely to affirm them as dogma it is in this sense that the imam says in the first sermon of the nahj that one of the purposes for which god sent forth prophets to mankind was to unearth for them the buried treasures of the intellects دفاين العقول', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 15, NULL, 'This saying is one of the keys to the spiritual ethos under consideration, and it returns again and again throughout these essays. The intellect is not stifled by revelation; it is brought to life by it. Revelation is a clarion call to the spiritual depths of the intellect, cultivating the seeds of consciousness — the seeds of توحید — that God has planted there and that lie buried within us, and bringing them to fruition. For the spirit of one''s intellect already carries the initial imprint of its Creator: in the world of the spirit it witnessed its Lord and testified to His lordship, and revelation, the ذکر, does no more than remind it of that primordial testimony. A reminder, after all, is never a new piece of information; it is knowledge one already possesses but has forgotten, for one can only be reminded of what one already knows. We were created in this world in a kind of amnesia. Just as a physician tells the family of a man who has lost his memory to surround him with familiar things, with signs (آیات) out of his past, to jog his memory, so God has set His reminders in the horizons and the souls (آفَاق وَ أَنْفُس). The spirit of one''s intellect, then, cannot be alien to what descends as revelation from on high; on the contrary, it must be fundamentally akin to it, and it is precisely for this reason that one can be absolutely certain that the revelation truly comes from the Absolute. The point is not to set up a dichotomy between intellect and revelation, but to see the intellect as revelation, or at least as one mode of revelation: the God-given means by which the individual comes to discern, affirm, and plumb the divine revelations'' outside himself, both those of scripture and those constituted by the signs'' (آیات) of the natural world. If the human intellect can perceive and recognize revelation, it is because both are rooted in one and the same ultimate source; we came from a spiritual realm, and so did revelation, sent to remind us of what we once witnessed and have since forgotten. Prophetic revelation awakens and quickens the depths of the human intellect; it does not replace or displace it. The messengers do for these buried seeds what the farmer does when he waters what lies hidden beneath the soil, what the miner does when he digs into the mountain for its gold and silver, and what the diver does when he descends to the sea-bed to bring up its buried treasures. From this perspective the revealed text is not some extraneous source set against the intelligence, but the objective, outward expression of the very principles that the intellect itself yields up to the inner prophet — the intellect serving as the inner messenger whom the outer messenger awakens and nourishes. By intellect is meant not simply the faculty of reasoning but the source of consciousness that articulates the human spirit.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'this saying is one of the keys to the spiritual ethos under consideration and it returns again and again throughout these essays the intellect is not stifled by revelation it is brought to life by it revelation is a clarion call to the spiritual depths of the intellect cultivating the seeds of consciousness the seeds of توحيد that god has planted there and that lie buried within us and bringing them to fruition for the spirit of ones intellect already carries the initial imprint of its creator in the world of the spirit it witnessed its lord and testified to his lordship and revelation the ذكر does no more than remind it of that primordial testimony a reminder after all is never a new piece of information it is knowledge one already possesses but has forgotten for one can only be reminded of what one already knows we were created in this world in a kind of amnesia just as a physician tells the family of a man who has lost his memory to surround him with familiar things with signs ايات out of his past to jog his memory so god has set his reminders in the horizons and the souls افاق و انفس the spirit of ones intellect then cannot be alien to what descends as revelation from on high on the contrary it must be fundamentally akin to it and it is precisely for this reason that one can be absolutely certain that the revelation truly comes from the absolute the point is not to set up a dichotomy between intellect and revelation but to see the intellect as revelation or at least as one mode of revelation the god given means by which the individual comes to discern affirm and plumb the divine revelations outside himself both those of scripture and those constituted by the signs ايات of the natural world if the human intellect can perceive and recognize revelation it is because both are rooted in one and the same ultimate source we came from a spiritual realm and so did revelation sent to remind us of what we once witnessed and have since forgotten prophetic revelation awakens and quickens the depths of the human intellect it does not replace or displace it the messengers do for these buried seeds what the farmer does when he waters what lies hidden beneath the soil what the miner does when he digs into the mountain for its gold and silver and what the diver does when he descends to the sea bed to bring up its buried treasures from this perspective the revealed text is not some extraneous source set against the intelligence but the objective outward expression of the very principles that the intellect itself yields up to the inner prophet the intellect serving as the inner messenger whom the outer messenger awakens and nourishes by intellect is meant not simply the faculty of reasoning but the source of consciousness that articulates the human spirit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 16, NULL, 'The intellect holds unsuspected depths, buried treasures, and is far from being exhausted by its surface operations — the cognitions and reasonings proper to its purely mental dimension. A third matter now follows: the relationship between intellect and reason. Just as there can be no contradiction whatsoever between revelation and intellection, so too a false dichotomy between reason and intellect must be avoided. Reason should rather be seen as one of the modes of the intellect; reason no more contradicts intellect than intellect contradicts revelation. Reason is a mode of the intellect, but it is not to be equated with it wholesale, just as one cannot reduce the universal objectivity of revelation to the subjective specificities of any one individual''s intellection, to his or her own private revelation. To equate reason with intellect would amount to denying the very existence of the buried treasures'' of the intellect — those supra-rational dimensions that are, at first, buried beneath, and thus hidden from, the rational surface of the intellect. The revelation constituted by the intellect is embedded within the creation of the human being, the intellect being that which most critically defines the human being as such. Far from pitting the intellect against revelation, each is to be seen in the light of the other: the substance of revelation cannot be engaged except through the intellect, on the one hand, and the buried treasures'' of the intellect cannot be disclosed except through revelation, on the other — a genuine co-dependency of the two.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'the intellect holds unsuspected depths buried treasures and is far from being exhausted by its surface operations the cognitions and reasonings proper to its purely mental dimension a third matter now follows the relationship between intellect and reason just as there can be no contradiction whatsoever between revelation and intellection so too a false dichotomy between reason and intellect must be avoided reason should rather be seen as one of the modes of the intellect reason no more contradicts intellect than intellect contradicts revelation reason is a mode of the intellect but it is not to be equated with it wholesale just as one cannot reduce the universal objectivity of revelation to the subjective specificities of any one individuals intellection to his or her own private revelation to equate reason with intellect would amount to denying the very existence of the buried treasures of the intellect those supra rational dimensions that are at first buried beneath and thus hidden from the rational surface of the intellect the revelation constituted by the intellect is embedded within the creation of the human being the intellect being that which most critically defines the human being as such far from pitting the intellect against revelation each is to be seen in the light of the other the substance of revelation cannot be engaged except through the intellect on the one hand and the buried treasures of the intellect cannot be disclosed except through revelation on the other a genuine co dependency of the two', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 17, NULL, 'This understanding of the intellect stands close to what the Imam refers to as the heart (قَلْب), that innermost mode of perception capable of seeing God. It is the heart that can see God — not with eyesight, not with بصارۃ, but with insight, with بصیرۃ, that spiritual insight generated by the verities of faith (حَقَائِقُ الْإِيمَان / حَقَائِقُ الْاِیمَانِ). As the Imam puts it, in response to the questioner asking whether he had seen his Lord: Eyes see Him not through sight''s observation, but hearts see Him through the verities of faith.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'this understanding of the intellect stands close to what the imam refers to as the heart قلب that innermost mode of perception capable of seeing god it is the heart that can see god not with eyesight not with بصاره but with insight with بصيره that spiritual insight generated by the verities of faith حقايق الايمان حقايق الايمان as the imam puts it in response to the questioner asking whether he had seen his lord eyes see him not through sights observation but hearts see him through the verities of faith', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 18, NULL, 'Between the spiritual depths of the intellect and its rational surface there is both continuity and discontinuity. The continuity shows in an evident fact: all thinking begins with concepts that convey intelligible meaning. Thought sets out from ideas that are rationally discernible, and these must bear some relation to the realities they express, or they collapse into ideas that lead nowhere. But there is discontinuity too between the spiritual and rational aspects of the intellect, in that reason stops short at the ideas it has de-fined. The Arabic word for definition, hadd (حَدّ), expresses — like its English equivalent — both senses at once: that of a conceptual definition and that of a limitation, a boundary, the very boundary that reason draws around an idea by weighing its pros and cons until the idea is fixed and defined. To go beyond the limits imposed by this rational act of definition, something more than reason is needed; and it is this something more that makes the ethos under consideration a spiritual one, and not a rationalistic one. It is certainly rational, in the sense that the form of the ethos is indeed open to rational scrutiny; but it is not rationalistic, inasmuch as its essence is not predicated on reason alone.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'between the spiritual depths of the intellect and its rational surface there is both continuity and discontinuity the continuity shows in an evident fact all thinking begins with concepts that convey intelligible meaning thought sets out from ideas that are rationally discernible and these must bear some relation to the realities they express or they collapse into ideas that lead nowhere but there is discontinuity too between the spiritual and rational aspects of the intellect in that reason stops short at the ideas it has de fined the arabic word for definition hadd حد expresses like its english equivalent both senses at once that of a conceptual definition and that of a limitation a boundary the very boundary that reason draws around an idea by weighing its pros and cons until the idea is fixed and defined to go beyond the limits imposed by this rational act of definition something more than reason is needed and it is this something more that makes the ethos under consideration a spiritual one and not a rationalistic one it is certainly rational in the sense that the form of the ethos is indeed open to rational scrutiny but it is not rationalistic inasmuch as its essence is not predicated on reason alone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 19, NULL, 'Now Ali frequently hints, in highly allusive terms, at the mysteries and marvels — the unearthed treasures of the intellect — that he has directly witnessed by the eye of his purified heart. He also alludes to this supra-rational mode of awareness indirectly, through a bewildering use of apophatic discourse and paradoxical utterance, of which the corpus attributed to him is full. In this ethos it seems that the higher the truth, the deeper the paradox: the sheer lack of any common measure between reality as it is in itself and the human conceptions formed of it is effectively evoked by this creative use of paradox. In modern parlance, each human conception of reality needs to be deconstructed. But then, unlike a modern deconstructionism so radically destructive that it has nothing left to reconstruct, the Imam''s apophasis feeds directly into modes of spiritual intuition, contemplation, and realization of that which reason, on its own, cannot attain. It is this intuition and contemplation which re-members'' — or reconstructs'', if one likes — the spiritual realities that transcend the categories of reason. The value of the paradoxes, the antinomies, the apophasis, and the negation is entirely predicated on the eminently positive realities which the intellect can plumb, thereby becoming aware of its own hidden depths. The resulting consciousness does not so much negate reason as situate it, revealing the limits of reason''s proper sphere of operation: it reveals that reason alone cannot comprehend the higher realities, nor express them fully, however indispensable reason may be in initiating the cognitive movement toward those realities.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'now ali frequently hints in highly allusive terms at the mysteries and marvels the unearthed treasures of the intellect that he has directly witnessed by the eye of his purified heart he also alludes to this supra rational mode of awareness indirectly through a bewildering use of apophatic discourse and paradoxical utterance of which the corpus attributed to him is full in this ethos it seems that the higher the truth the deeper the paradox the sheer lack of any common measure between reality as it is in itself and the human conceptions formed of it is effectively evoked by this creative use of paradox in modern parlance each human conception of reality needs to be deconstructed but then unlike a modern deconstructionism so radically destructive that it has nothing left to reconstruct the imams apophasis feeds directly into modes of spiritual intuition contemplation and realization of that which reason on its own cannot attain it is this intuition and contemplation which re members or reconstructs if one likes the spiritual realities that transcend the categories of reason the value of the paradoxes the antinomies the apophasis and the negation is entirely predicated on the eminently positive realities which the intellect can plumb thereby becoming aware of its own hidden depths the resulting consciousness does not so much negate reason as situate it revealing the limits of reasons proper sphere of operation it reveals that reason alone cannot comprehend the higher realities nor express them fully however indispensable reason may be in initiating the cognitive movement toward those realities', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 20, NULL, 'Thus, when the Imam negates, as he does so often, the possibility of human conceptions encompassing the divine Reality, what is being negated is the limitation that is the inescapable consequence of all such conceptions — not the positive content, the mana or spiritual meaning, of the conception itself. For this conception is a necessary starting point for a process of assimilation that engages a deeper level of awareness than that de-fined by the mind, and which therefore extends far beyond the domain of speculative thought. In this light, the negation of the limitations of human conception should be seen as the prelude to an absolute affirmation: the affirmation of the Absolute, which has no limitation. The spiritual negation of conceptual limitation is of an upward, constructive order, not a nihilistic, deconstructive one. Nowhere is this style of discourse more apparent than in the famous opening lines of the first sermon of the Nahj al-balagha:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'thus when the imam negates as he does so often the possibility of human conceptions encompassing the divine reality what is being negated is the limitation that is the inescapable consequence of all such conceptions not the positive content the mana or spiritual meaning of the conception itself for this conception is a necessary starting point for a process of assimilation that engages a deeper level of awareness than that de fined by the mind and which therefore extends far beyond the domain of speculative thought in this light the negation of the limitations of human conception should be seen as the prelude to an absolute affirmation the affirmation of the absolute which has no limitation the spiritual negation of conceptual limitation is of an upward constructive order not a nihilistic deconstructive one nowhere is this style of discourse more apparent than in the famous opening lines of the first sermon of the nahj al balagha', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 21, NULL, 'Praise be to God, whose laudation those who speak cannot deliver, whose graces those who count cannot number, whose rightful due those who strive cannot render; He who cannot be grasped by far-reaching aspirations, nor fathomed by profound intuitions; He whose attribute has no binding limitation, no existing description, no time appointed, no term extended.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'praise be to god whose laudation those who speak cannot deliver whose graces those who count cannot number whose rightful due those who strive cannot render he who cannot be grasped by far reaching aspirations nor fathomed by profound intuitions he whose attribute has no binding limitation no existing description no time appointed no term extended', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 22, NULL, 'The divine attribute (الصِّفَة) has no limit in terms of which it can be defined — laysa li-sifatih hadd mahdud — and yet it is affirmed as real. It has no existing description, and yet in some sense it is described (مَوْصُوف), by the very words of the Quranic revelation; for in the Quran God is described as having such attributes as mercy, compassion, and power. He is the Merciful, the Compassionate, the Almighty, and yet the Imam affirms that these very attributes cannot be defined, bounded, or described. The paradox sharpens still further when the Imam speaks of the perfection of إِخْلَاص — the rendering sincere, the purification of one''s devotion to God and of one''s conception of Him: this perfection, he says, is to divest (نفی) God of all attributes. On the one hand the attributes are affirmed; on the other they are to be negated. The rational mind can only think of God in terms of the attributes given verbal expression in the Quran; and yet here the Imam appears to negate these same attributes, thereby depriving the mind of any convenient conceptual handle by which to grasp the nature of the divine Reality. The simultaneous affirmation and negation of the attributes raises an apparently irresolvable contradiction, and in doing so enhances receptivity to a deeper mode of knowing. This style of discourse appears designed to awaken in the listener some latent awareness inscribed in the heart or the depths of the intellect, and to invite the seeker to dive into those depths, into the knowledge buried in the intellect. The very shock of the apparent contradiction in this apophasis seems intended to precipitate a leap of consciousness, from the formal activity of reason to the supra-rational contemplation of the spirit.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'the divine attribute الصفه has no limit in terms of which it can be defined laysa li sifatih hadd mahdud and yet it is affirmed as real it has no existing description and yet in some sense it is described موصوف by the very words of the quranic revelation for in the quran god is described as having such attributes as mercy compassion and power he is the merciful the compassionate the almighty and yet the imam affirms that these very attributes cannot be defined bounded or described the paradox sharpens still further when the imam speaks of the perfection of اخلاص the rendering sincere the purification of ones devotion to god and of ones conception of him this perfection he says is to divest نفي god of all attributes on the one hand the attributes are affirmed on the other they are to be negated the rational mind can only think of god in terms of the attributes given verbal expression in the quran and yet here the imam appears to negate these same attributes thereby depriving the mind of any convenient conceptual handle by which to grasp the nature of the divine reality the simultaneous affirmation and negation of the attributes raises an apparently irresolvable contradiction and in doing so enhances receptivity to a deeper mode of knowing this style of discourse appears designed to awaken in the listener some latent awareness inscribed in the heart or the depths of the intellect and to invite the seeker to dive into those depths into the knowledge buried in the intellect the very shock of the apparent contradiction in this apophasis seems intended to precipitate a leap of consciousness from the formal activity of reason to the supra rational contemplation of the spirit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 23, NULL, 'The words spoken by the Imam immediately after affirming that his heart had indeed witnessed God — not by means of outward vision but through the verities of faith — run:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'the words spoken by the imam immediately after affirming that his heart had indeed witnessed god not by means of outward vision but through the verities of faith run', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 24, NULL, 'My Lord is not described in terms of dimension (بُعْدٌ), nor motion (حَرَكَة), nor rest (سُكُونٌ) ... nor through coming or going: He is subtle in subtlety but not described by subtlety, magnificent in magnificence but not described by magnificence, great in greatness but not described by greatness ...', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'my lord is not described in terms of dimension بعد nor motion حركه nor rest سكون nor through coming or going he is subtle in subtlety but not described by subtlety magnificent in magnificence but not described by magnificence great in greatness but not described by greatness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 25, NULL, 'The attributes are again affirmed and denied. God possesses these attributes but is not reducible to them. The mind can begin to think of God in terms of these categories, but He is not reducible to such conceptions. The attributes afford the mind something by which the divine nature can be understood, but this understanding is fragmentary, never exhaustive, and it needs to be negated as the prelude to a fuller apprehension. The initial conceptual orientation to the divine Reality needs to be both negated and sublimated: negated as a mental conception, while the positive content of the conception needs to be sublimated through spiritual intuition. Only then can the two-dimensional portrait defined by reason be given a third dimension — that of depth. But this third dimension emerges only after the insufficiency of the rational depiction is understood; whence the need for that cognitive shock which paradox produces, a shock intended to reveal the pretension of reason in its effort to disclose the nature of the Absolute, the transcendent source of reason''s own activities.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'the attributes are again affirmed and denied god possesses these attributes but is not reducible to them the mind can begin to think of god in terms of these categories but he is not reducible to such conceptions the attributes afford the mind something by which the divine nature can be understood but this understanding is fragmentary never exhaustive and it needs to be negated as the prelude to a fuller apprehension the initial conceptual orientation to the divine reality needs to be both negated and sublimated negated as a mental conception while the positive content of the conception needs to be sublimated through spiritual intuition only then can the two dimensional portrait defined by reason be given a third dimension that of depth but this third dimension emerges only after the insufficiency of the rational depiction is understood whence the need for that cognitive shock which paradox produces a shock intended to reveal the pretension of reason in its effort to disclose the nature of the absolute the transcendent source of reasons own activities', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 26, NULL, 'The Imam''s discourses show a repeated combination of affirmation and denial, which mirrors the negation and affirmation found in the first testimony of Islam: la ilaha, no god, being the negation (نفی); then illaLlah, except God, coming as the affirmation (اِثْبَات). This helps to show that the negation of the attributes which the Imam names as the perfection of إِخْلَاص is in fact an affirmation of the infinitude of the divine Reality. Each of the attributes is to be negated, but only insofar as it is conceived by the mind. Such negation is necessary because, at the mental level, each attribute excludes other attributes, and also excludes the object of attribution itself — that is, the divine Essence — such exclusion following inescapably from the very possibility of conceptually distinguishing between the attribute and the object of attribution, between the divine quality and the divine Essence. For any conception to take place in the mind, defined ideas are necessary; and where there are definitions, there are limits and thus exclusions. The reality of the attribute, however, is unlimited, by virtue of its absolute identity with the Essence. The attribute that has been negated is paradoxically affirmed — not in itself, but inasmuch as it is nothing but God: illaLlah. Thus one can place each of the negated attributes in the position of the nafy of the first testimony and arrive at such formulations as la rahmana illaLlah, There is no All-Compassionate except God; la rahima illaLlah, No All-Merciful except God, and so on. The apparent negation of the attributes becomes, in fact, an affirmation of their true identity, shorn of any restrictive association with the poverty of mental conceptions. The attributes are not superadded to the Essence but are absolutely one with it, differentiable from it only conceptually, not ontologically. The Essence does indeed comprise all the attributes mentioned — greatness, subtlety, and so on — but it is also infinitely more than these attributes; and, for their part, the attributes are infinite only within and as the Essence. The Imam''s apophasis here can be seen as a commentary on the Quranic refrain, Glorified be God above what they describe (Al-Muminun: 91). The infinitude of God strictly requires, on the human plane, the negation of all that the mind can conceive through reason — but not of all that the heart can see through spiritual vision. This very negation on the plane of reason calls out to something deeper, and this in turn can only be understood in the light of spiritual praxis, which is always assumed as the reflective, devotional, or contemplative context for the hearers of the Imam''s sermons and discourses. The heart, symbolic seat of the contemplative intelligence, calls out to be polished, and this is precisely what the remembrance of God does — this dhikr (ذِکْر) Allah being, according to the Imam, the most excellent form of worship. Even at this level of praxis there is a further paradox: the reality of the remembrance is not attained until you forget yourself in your remembrance.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'the imams discourses show a repeated combination of affirmation and denial which mirrors the negation and affirmation found in the first testimony of islam la ilaha no god being the negation نفي then illallah except god coming as the affirmation اثبات this helps to show that the negation of the attributes which the imam names as the perfection of اخلاص is in fact an affirmation of the infinitude of the divine reality each of the attributes is to be negated but only insofar as it is conceived by the mind such negation is necessary because at the mental level each attribute excludes other attributes and also excludes the object of attribution itself that is the divine essence such exclusion following inescapably from the very possibility of conceptually distinguishing between the attribute and the object of attribution between the divine quality and the divine essence for any conception to take place in the mind defined ideas are necessary and where there are definitions there are limits and thus exclusions the reality of the attribute however is unlimited by virtue of its absolute identity with the essence the attribute that has been negated is paradoxically affirmed not in itself but inasmuch as it is nothing but god illallah thus one can place each of the negated attributes in the position of the nafy of the first testimony and arrive at such formulations as la rahmana illallah there is no all compassionate except god la rahima illallah no all merciful except god and so on the apparent negation of the attributes becomes in fact an affirmation of their true identity shorn of any restrictive association with the poverty of mental conceptions the attributes are not superadded to the essence but are absolutely one with it differentiable from it only conceptually not ontologically the essence does indeed comprise all the attributes mentioned greatness subtlety and so on but it is also infinitely more than these attributes and for their part the attributes are infinite only within and as the essence the imams apophasis here can be seen as a commentary on the quranic refrain glorified be god above what they describe al muminun 91 the infinitude of god strictly requires on the human plane the negation of all that the mind can conceive through reason but not of all that the heart can see through spiritual vision this very negation on the plane of reason calls out to something deeper and this in turn can only be understood in the light of spiritual praxis which is always assumed as the reflective devotional or contemplative context for the hearers of the imams sermons and discourses the heart symbolic seat of the contemplative intelligence calls out to be polished and this is precisely what the remembrance of god does this dhikr ذكر allah being according to the imam the most excellent form of worship even at this level of praxis there is a further paradox the reality of the remembrance is not attained until you forget yourself in your remembrance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 27, NULL, 'It is not just the rational mind and the determinate conceptions proportioned to it that are to be negated or deconstructed, but the individual soul itself, as the locus of all cognition, rational or supra-rational. This final denouement, or فَنَاء, is the ultimate form of apophasis.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'it is not just the rational mind and the determinate conceptions proportioned to it that are to be negated or deconstructed but the individual soul itself as the locus of all cognition rational or supra rational this final denouement or فناء is the ultimate form of apophasis', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 28, NULL, 'These considerations show the extent to which the spirit of the intellect, in Ali s perspective, transcends the rational faculty. The intellect must be seen, first and foremost, as a spiritual faculty; and the spirit, in turn, must be appreciated as the source of the intellect, as well as the source of life. Without the intellect the spirit is reduced to unconscious existence; conversely, without the spirit, the intellect tends toward lifeless thought. These aspects of the spirit are clearly expressed in the first sermon of the Nahj, which can be read as a commentary upon the Quranic verses describing the creation of man in terms of God''s breathing of His spirit into man: He began the creation of man with clay... He fashioned him and breathed into him of His spirit (ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِ).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'these considerations show the extent to which the spirit of the intellect in ali s perspective transcends the rational faculty the intellect must be seen first and foremost as a spiritual faculty and the spirit in turn must be appreciated as the source of the intellect as well as the source of life without the intellect the spirit is reduced to unconscious existence conversely without the spirit the intellect tends toward lifeless thought these aspects of the spirit are clearly expressed in the first sermon of the nahj which can be read as a commentary upon the quranic verses describing the creation of man in terms of gods breathing of his spirit into man he began the creation of man with clay he fashioned him and breathed into him of his spirit ثم سواه ونفخ فيه من روحه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 29, NULL, 'The following lines, from the first sermon, form one of the many passages in which this infusion of the divine spirit into man is commented upon by Ali:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'the following lines from the first sermon form one of the many passages in which this infusion of the divine spirit into man is commented upon by ali', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 30, NULL, 'Sayingثُمَّ جَمَعَ سُبْحَانَهُ مِنْ حَزْنِ الاْرْضِ وَسَهْلِهَا، وَعَذْبِهَا وَسَبَخِهَا۔ تُرْبَةً سَنَّهَا بالمَاءِ حَتَّى خَلَصَتْ۔ وَلاَطَهَا بِالبَلَّةِ حَتَّى لَزَبَتْ۔ فَجَبَلَ مِنْها صُورَةً ذَاتَ أَحْنَاءَ وَوُصُولَ، وَأَعْضَاءَ وَفُصُول۔ أَجْمَدَهَا حَتَّى اسْتَمْسَكَتْ، وَأَصْلَدَهَا حَتَّى صَلْصَلَتْ۔ لِوَقْت مَعْدُود، وَأجَل مَعْلُوم۔ ثُمَّ نَفَخَ فِيها مِنْ رُوحِهِ فَمَثُلَتْ إِنْساناً ذَا أَذْهَانُ يُجيلُهَا، وَفِكَر يَتَصَرَّفُ بِهَا، وَجَوَارِحَ يَخْتَدِمُهَا، وَأَدَوَات يُقَلِّبُهَا، وَمَعْرِفَة يَفْرُقُ بِهَا بَيْنَ الحَقِّ وَالبَاطِلِ۔', '', 'ثُمَّ جَمَعَ سُبْحَانَهُ مِنْ حَزْنِ الاْرْضِ وَسَهْلِهَا، وَعَذْبِهَا وَسَبَخِهَا۔ تُرْبَةً سَنَّهَا بالمَاءِ حَتَّى خَلَصَتْ۔ وَلاَطَهَا بِالبَلَّةِ حَتَّى لَزَبَتْ۔ فَجَبَلَ مِنْها صُورَةً ذَاتَ أَحْنَاءَ وَوُصُولَ، وَأَعْضَاءَ وَفُصُول۔ أَجْمَدَهَا حَتَّى اسْتَمْسَكَتْ، وَأَصْلَدَهَا حَتَّى صَلْصَلَتْ۔ لِوَقْت مَعْدُود، وَأجَل مَعْلُوم۔ ثُمَّ نَفَخَ فِيها مِنْ رُوحِهِ فَمَثُلَتْ إِنْساناً ذَا أَذْهَانُ يُجيلُهَا، وَفِكَر يَتَصَرَّفُ بِهَا، وَجَوَارِحَ يَخْتَدِمُهَا، وَأَدَوَات يُقَلِّبُهَا، وَمَعْرِفَة يَفْرُقُ بِهَا بَيْنَ الحَقِّ وَالبَاطِلِ۔', 'Saying', NULL, NULL, 'spiritual ethos 3 intellect not reason', 'sayingثم جمع سبحانه من حزن الارض وسهلها وعذبها وسبخها تربه سنها بالماء حتي خلصت ولاطها بالبله حتي لزبت فجبل منها صوره ذات احناء ووصول واعضاء وفصول اجمدها حتي استمسكت واصلدها حتي صلصلت لوقت معدود واجل معلوم ثم نفخ فيها من روحه فمثلت انسانا ذا اذهان يجيلها وفكر يتصرف بها وجوارح يختدمها وادوات يقلبها ومعرفه يفرق بها بين الحق والباطل', 'ثم جمع سبحانه من حزن الارض وسهلها وعذبها وسبخها تربه سنها بالماء حتي خلصت ولاطها بالبله حتي لزبت فجبل منها صوره ذات احناء ووصول واعضاء وفصول اجمدها حتي استمسكت واصلدها حتي صلصلت لوقت معدود واجل معلوم ثم نفخ فيها من روحه فمثلت انسانا ذا اذهان يجيلها وفكر يتصرف بها وجوارح يختدمها وادوات يقلبها ومعرفه يفرق بها بين الحق والباطل');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 31, NULL, 'Then He, glorified be He, gathered up a quantity of dust, from some hard earth and some soft, some sweet earth and some salty, and poured water onto it until it was pure, then kneaded into it some moisture until it stuck together; then He fashioned from this a form with curves and joints, limbs and parts. He compacted it until it held tightly together, solidified it until it became as sounding clay, assigning to it a measured duration and a known consummation. Then He breathed into it of His spirit, and it stood up as a human being, endowed with intellectual powers with which to reflect, thoughts by which to conduct himself, limbs to put to service, instruments at his disposal, and knowledge with which to discern between the true and the false ...', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'then he glorified be he gathered up a quantity of dust from some hard earth and some soft some sweet earth and some salty and poured water onto it until it was pure then kneaded into it some moisture until it stuck together then he fashioned from this a form with curves and joints limbs and parts he compacted it until it held tightly together solidified it until it became as sounding clay assigning to it a measured duration and a known consummation then he breathed into it of his spirit and it stood up as a human being endowed with intellectual powers with which to reflect thoughts by which to conduct himself limbs to put to service instruments at his disposal and knowledge with which to discern between the true and the false', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 32, NULL, 'The body had been fashioned entire — its eyes, its ears, the organ of thought all in place — and yet it could neither hear nor see nor reflect until God breathed His spirit into it; only then did it stand up as a human being. It is this in-spiration — literally, the in-breathing and the insertion of the spirit, of God''s breath — that produces consciousness and life. Death, by contrast, is the ex-piration, the departure of the spirit. Life in the absence of aspiration — the intention to be true to one''s spirit — is a kind of death. It is through the spirit that inanimate, unconscious matter is brought to life and to awareness of itself: it generates not only knowledge but self-knowledge as well. This intimate intertwining between the gift of life and the capacity to know — existence that is conscious, and knowledge that is existential — is one of the foundations of any truly spiritual perspective. The question is not one of setting the spirit against the body, but of recognizing that the infusion of the spirit into the body is precisely what brings the body to life; and it is for this reason that knowledge vivifies, in the very measure that it is spiritual: O ye who believe, respond to God and His Messenger when they call you to that which vivifies you (Al-Anfal: 24). According to the Imam, one of the most important aspects of this call from God to human beings is to remind them of the buried treasures of the intellect.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'the body had been fashioned entire its eyes its ears the organ of thought all in place and yet it could neither hear nor see nor reflect until god breathed his spirit into it only then did it stand up as a human being it is this in spiration literally the in breathing and the insertion of the spirit of gods breath that produces consciousness and life death by contrast is the ex piration the departure of the spirit life in the absence of aspiration the intention to be true to ones spirit is a kind of death it is through the spirit that inanimate unconscious matter is brought to life and to awareness of itself it generates not only knowledge but self knowledge as well this intimate intertwining between the gift of life and the capacity to know existence that is conscious and knowledge that is existential is one of the foundations of any truly spiritual perspective the question is not one of setting the spirit against the body but of recognizing that the infusion of the spirit into the body is precisely what brings the body to life and it is for this reason that knowledge vivifies in the very measure that it is spiritual o ye who believe respond to god and his messenger when they call you to that which vivifies you al anfal 24 according to the imam one of the most important aspects of this call from god to human beings is to remind them of the buried treasures of the intellect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 33, NULL, 'Existentiation is the bestowal of the spirit, which is consciousness. The aql, or intellect, is the principle of articulation for the spirit, and so it is not merely a mental faculty but is itself constitutive of our true life. The intellect is that of which the mental faculty is one formal expression, one mode of its operation — but by no means the only one. The aql is many-faceted, comprising aspects that in our times are rarely associated with intelligence. To be true to one''s intellect — to the treasures buried deep within it, and not merely to the rational functions operative on its surface — amounts to being spiritual.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'existentiation is the bestowal of the spirit which is consciousness the aql or intellect is the principle of articulation for the spirit and so it is not merely a mental faculty but is itself constitutive of our true life the intellect is that of which the mental faculty is one formal expression one mode of its operation but by no means the only one the aql is many faceted comprising aspects that in our times are rarely associated with intelligence to be true to ones intellect to the treasures buried deep within it and not merely to the rational functions operative on its surface amounts to being spiritual', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 34, NULL, 'For Ali, the true intellectual — al-aqil — is one who not only thinks correctly but also acts ethically, and, at the deepest level, one who seeks to realize the ultimate Reality. The intellectual is defined as one who puts all things in their proper place (العاقل من وضع شئی حق محلہ), one who aligns his acts with the intentions of his Creator. This same alignment is the very definition of justice (عَدْل); only the true intellectual can therefore be fully just (عَادِل), for only one who sees things as they truly are is able to put them in their right place.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'for ali the true intellectual al aqil is one who not only thinks correctly but also acts ethically and at the deepest level one who seeks to realize the ultimate reality the intellectual is defined as one who puts all things in their proper place العاقل من وضع شيي حق محله one who aligns his acts with the intentions of his creator this same alignment is the very definition of justice عدل only the true intellectual can therefore be fully just عادل for only one who sees things as they truly are is able to put them in their right place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'intellect, not reason', '3. Intellect, Not Reason', 35, NULL, 'Thought, action, and realization are all the concern of the true intellectual, the الْعَاقِل. Correct thinking, impeccable virtue, and authentic being are inextricably bound up with the intellect in the spiritual ethos considered here. These aspects of the ethos come into sharper focus in the light of the Imam''s discourse to Kumayl.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 3 intellect not reason', 'thought action and realization are all the concern of the true intellectual the العاقل correct thinking impeccable virtue and authentic being are inextricably bound up with the intellect in the spiritual ethos considered here these aspects of the ethos come into sharper focus in the light of the imams discourse to kumayl', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 0, NULL, 'The discourse the Imam delivered to Kumayl brings these aspects of the ethos into sharper focus. Its importance lies above all in how deeply esoteric it is. The Imam took his disciple Kumayl by the hand and led him out of Kufa to a graveyard; once the city lay behind them, he drew a deep breath and gave him the following private counsel.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'the discourse the imam delivered to kumayl brings these aspects of the ethos into sharper focus its importance lies above all in how deeply esoteric it is the imam took his disciple kumayl by the hand and led him out of kufa to a graveyard once the city lay behind them he drew a deep breath and gave him the following private counsel', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 1, NULL, 'Sayingيَا كُمَيْل بْن زِيَادٍ، إِنَّ هذهِ الْقُلُوبَ أَوْعِيَةٌ فَخَيْرُهَا أَوْعَاهَا فَاحْفَظْ عَنِّي مَا أَقُولُ لَكَ۔ النَّاسُ ثَلاَثَةٌ- فَعَالِمٌ رَبَّانِيٌّ وَمُتَعَلِّمٌ عَلَى سَبِيلِ نَجَاةٍ، وَهَمَجٌ رَعَاعٌ أَتْبَاعُ كُلِّ نَاعِقٍ يَمِيلُونَ مَعَ كُلِّ رِيحٍ، لَمْ يَسْتَضِيئُوا بِنُورِ الْعِلْمِ، وَلَمْ يَلْجَؤُوا إِلَى رُكْنٍ وَثِيقٍ', '', 'يَا كُمَيْل بْن زِيَادٍ، إِنَّ هذهِ الْقُلُوبَ أَوْعِيَةٌ فَخَيْرُهَا أَوْعَاهَا فَاحْفَظْ عَنِّي مَا أَقُولُ لَكَ۔ النَّاسُ ثَلاَثَةٌ- فَعَالِمٌ رَبَّانِيٌّ وَمُتَعَلِّمٌ عَلَى سَبِيلِ نَجَاةٍ، وَهَمَجٌ رَعَاعٌ أَتْبَاعُ كُلِّ نَاعِقٍ يَمِيلُونَ مَعَ كُلِّ رِيحٍ، لَمْ يَسْتَضِيئُوا بِنُورِ الْعِلْمِ، وَلَمْ يَلْجَؤُوا إِلَى رُكْنٍ وَثِيقٍ', 'Saying', NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'sayingيا كميل بن زياد ان هذه القلوب اوعيه فخيرها اوعاها فاحفظ عني ما اقول لك الناس ثلاثه فعالم رباني ومتعلم علي سبيل نجاه وهمج رعاع اتباع كل ناعق يميلون مع كل ريح لم يستضييوا بنور العلم ولم يلجووا الي ركن وثيق', 'يا كميل بن زياد ان هذه القلوب اوعيه فخيرها اوعاها فاحفظ عني ما اقول لك الناس ثلاثه فعالم رباني ومتعلم علي سبيل نجاه وهمج رعاع اتباع كل ناعق يميلون مع كل ريح لم يستضييوا بنور العلم ولم يلجووا الي ركن وثيق');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 2, NULL, 'O Kumayl ibn Ziyad, truly these hearts are vessels, containers for knowledge and wisdom, and the best of them are those which hold the most. So retain from me that which I say to you. People are divided into three types: a lordly knower (عَالِمٌ رَبَّانِيٌّ); one who seeks knowledge (مُتَعَلِّمٌ) for the sake of deliverance; and the common folk (هَمَجٌ رَعَاعٌ), the word naming the moth that hurls itself at any flame, following just anyone, swaying with every current, neither desiring to be illumined by the light of knowledge nor seeking refuge in any strong support.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'o kumayl ibn ziyad truly these hearts are vessels containers for knowledge and wisdom and the best of them are those which hold the most so retain from me that which i say to you people are divided into three types a lordly knower عالم رباني one who seeks knowledge متعلم for the sake of deliverance and the common folk همج رعاع the word naming the moth that hurls itself at any flame following just anyone swaying with every current neither desiring to be illumined by the light of knowledge nor seeking refuge in any strong support', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 3, NULL, 'O Kumayl, knowledge is better than wealth, for knowledge guards you, while you must guard your wealth; and wealth diminishes as it is spent, while knowledge only increases as it is disbursed, replenishing itself the more it is given away; the fruits of wealth vanish when the wealth itself is gone, the friends bought with money and the comforts it purchased all falling away with it, while no one can take a man''s knowledge from him. O Kumayl, the wise apprehension of knowledge (مَعْرِفَةُ الْعِلْمِ) is a religion by which God is worshipped, for din, religion, is kin to dayn, a debt, and it is by acquiring knowledge that a man repays the debt his own intellect has incurred to its Maker. Through it man acquires obedience in his life and a good name after his death. And knowledge is a judge, while wealth is judged: knowledge is active and wealth passive, for the one who knows takes command of what he owns, his knowledge directing him how to handle it, whereas wealth is forever something ruled upon by its possessor.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'o kumayl knowledge is better than wealth for knowledge guards you while you must guard your wealth and wealth diminishes as it is spent while knowledge only increases as it is disbursed replenishing itself the more it is given away the fruits of wealth vanish when the wealth itself is gone the friends bought with money and the comforts it purchased all falling away with it while no one can take a mans knowledge from him o kumayl the wise apprehension of knowledge معرفه العلم is a religion by which god is worshipped for din religion is kin to dayn a debt and it is by acquiring knowledge that a man repays the debt his own intellect has incurred to its maker through it man acquires obedience in his life and a good name after his death and knowledge is a judge while wealth is judged knowledge is active and wealth passive for the one who knows takes command of what he owns his knowledge directing him how to handle it whereas wealth is forever something ruled upon by its possessor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 4, NULL, 'O Kumayl, those who hoard wealth perish even while they live, but the knowers endure for as long as time subsists; their material forms are absent, but their images in the hearts of men are present. Ah, what abundant knowledge is here (and he pointed to his breast), would that I could find one to bear it. Yes, I found one who was quick to understand, but he could not be trusted with it, exploiting the tools of religion for the sake of worldly gain, empowering himself with the graces of God against His slaves and with His proofs against His friends; for when the vessel of the heart is corrupt, this knowledge, pure and precious as it is, becomes a weapon turned against the very friends of God. Then there was another, obedient to the bearers of truth but lacking heartfelt insight, in whom, at the first appearance of obscurity, doubt was kindled in the heart. So alas, neither this one nor that! Nor one who is greedy for pleasure and submissive to passion, nor one obsessed with acquisition and accumulation, neither of them a guardian of religion in any respect. They resemble nothing so much as grazing cattle. Thus does knowledge die with the death of its bearers, when its trust falls to the worthless and the self-serving.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'o kumayl those who hoard wealth perish even while they live but the knowers endure for as long as time subsists their material forms are absent but their images in the hearts of men are present ah what abundant knowledge is here and he pointed to his breast would that i could find one to bear it yes i found one who was quick to understand but he could not be trusted with it exploiting the tools of religion for the sake of worldly gain empowering himself with the graces of god against his slaves and with his proofs against his friends for when the vessel of the heart is corrupt this knowledge pure and precious as it is becomes a weapon turned against the very friends of god then there was another obedient to the bearers of truth but lacking heartfelt insight in whom at the first appearance of obscurity doubt was kindled in the heart so alas neither this one nor that nor one who is greedy for pleasure and submissive to passion nor one obsessed with acquisition and accumulation neither of them a guardian of religion in any respect they resemble nothing so much as grazing cattle thus does knowledge die with the death of its bearers when its trust falls to the worthless and the self serving', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 5, NULL, 'But indeed, O my God, the earth will never be empty of one who establishes the proof of God, whether overtly and in the open or fearfully and in obscurity, lest God''s proofs and elucidations come to naught. Yet how many are such as these, and where are they? By God, they may be the smallest in number, but with God they are the greatest in rank, for here authority is not the possession of the many, and truth is not settled by the count of those who hold it; the guardians of the proof are few, and it is they who stand highest in the sight of God. Through them God preserves His proofs and elucidations, so that they may entrust them to their compeers and sow them in the hearts of those who resemble them. Through them, knowledge penetrates the reality of insight; they take hold of the very spirit of certainty; they make easy what the extravagant find harsh, and they befriend that by which the ignorant are estranged; with their bodies they keep company with the world, while their spirits are bound to the transcendent realm. They are the vicegerents of God upon His earth, the summoners to His religion. Ah, how I long to see them! Go now, Kumayl, as you will.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'but indeed o my god the earth will never be empty of one who establishes the proof of god whether overtly and in the open or fearfully and in obscurity lest gods proofs and elucidations come to naught yet how many are such as these and where are they by god they may be the smallest in number but with god they are the greatest in rank for here authority is not the possession of the many and truth is not settled by the count of those who hold it the guardians of the proof are few and it is they who stand highest in the sight of god through them god preserves his proofs and elucidations so that they may entrust them to their compeers and sow them in the hearts of those who resemble them through them knowledge penetrates the reality of insight they take hold of the very spirit of certainty they make easy what the extravagant find harsh and they befriend that by which the ignorant are estranged with their bodies they keep company with the world while their spirits are bound to the transcendent realm they are the vicegerents of god upon his earth the summoners to his religion ah how i long to see them go now kumayl as you will', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 6, NULL, 'The four sentences of the penultimate paragraph describe those who bear the title of lordly knower (عَالِمٌ رَبَّانِيٌّ): the fewest in number, yet the greatest in the sight of God, and the ones through whom His religion is sustained. By His religion is meant the divine reality of religion — the pure and unchanging essence of the faith, perfect and constant — as against religion in the ordinary sense, whose outward institutions are subject to the changes of human history. From Adam to the Seal of the prophets those outward institutions have shifted with the conditions of men, but the essence, the message, and the purpose have never altered: the salvation of the soul through willing submission to God, as the Quran declares: إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلْإِسْلَمُ, "Truly, religion in the sight of God is submission" (Ali Imran: 19). It is through the knowledge of the true knowers that religion stays true to itself, and only through such sages that religion truly lives in the world.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'the four sentences of the penultimate paragraph describe those who bear the title of lordly knower عالم رباني the fewest in number yet the greatest in the sight of god and the ones through whom his religion is sustained by his religion is meant the divine reality of religion the pure and unchanging essence of the faith perfect and constant as against religion in the ordinary sense whose outward institutions are subject to the changes of human history from adam to the seal of the prophets those outward institutions have shifted with the conditions of men but the essence the message and the purpose have never altered the salvation of the soul through willing submission to god as the quran declares ان الدين عند الله الاسلم truly religion in the sight of god is submission ali imran 19 it is through the knowledge of the true knowers that religion stays true to itself and only through such sages that religion truly lives in the world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 7, NULL, '"Through them, knowledge penetrates the reality of insight." The Imam does not say that their knowledge penetrates it, but that through them knowledge penetrates the reality of insight. Knowledge can remain merely abstract, far removed from that reality. There is the outward, surface knowledge of a thing — its zahir — and the inner, hidden knowledge of the same thing — its batin. Yet knowledge holds a potential that calls out to be realized. It needs to be brought to life so that it may reach something deeper than the words and concepts that give shape to its own outward form, the meaning that lies ready on the surface. A man may have a surface knowledge of a verse of the Quran, of a saying, of why he prays and fasts and how many cycles each prayer requires; but when he presses past that surface and asks what the bowing and the prostration truly represent, a world of knowledge opens that is wholly unlike the bare information he began with. Degrees of knowledge are plainly implied here, and with them the rejection of all literalism and superficiality, of the easy mistake of taking factual information for real knowledge, let alone for wisdom. The shift of consciousness this penetration requires is shown vividly by the Imam''s gesture toward his breast: it is not the chest but the heart hidden behind it that holds knowledge. The chest is the outward form, the zahir that conceals the heart within its batin, and to reach the heart one must first penetrate the chest.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'through them knowledge penetrates the reality of insight the imam does not say that their knowledge penetrates it but that through them knowledge penetrates the reality of insight knowledge can remain merely abstract far removed from that reality there is the outward surface knowledge of a thing its zahir and the inner hidden knowledge of the same thing its batin yet knowledge holds a potential that calls out to be realized it needs to be brought to life so that it may reach something deeper than the words and concepts that give shape to its own outward form the meaning that lies ready on the surface a man may have a surface knowledge of a verse of the quran of a saying of why he prays and fasts and how many cycles each prayer requires but when he presses past that surface and asks what the bowing and the prostration truly represent a world of knowledge opens that is wholly unlike the bare information he began with degrees of knowledge are plainly implied here and with them the rejection of all literalism and superficiality of the easy mistake of taking factual information for real knowledge let alone for wisdom the shift of consciousness this penetration requires is shown vividly by the imams gesture toward his breast it is not the chest but the heart hidden behind it that holds knowledge the chest is the outward form the zahir that conceals the heart within its batin and to reach the heart one must first penetrate the chest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 8, NULL, 'The word chosen to translate hajama is "penetrate," but the primary sense of the verb is to assault, to take by storm, to charge. In the warfare of that age the battle lines were drawn as a right wing, a left wing, and a center — the heart of the army (قَلْبُ الْعَسْكَرِ), where the king or commander stood. The aim of the assault was to break through the wings and reach that heart, for once the king was taken the battle was won, and the victor took command of everything the defeated had held: the kingdom, its treasury, its army, its people. The chessboard preserves the same rule. So the word helps to show that conceptual knowledge holds a latent force — one might almost call it an explosive power — deriving from the reality of knowledge, its haqiqa or spiritual essence. It is this that calls out to be made real through tahaqquq, realization in depth rather than mere verification on the surface; and the striving by which one storms the outer wall of words to reach the heart of their meaning is تَحْقِيق, investigation. This haqiqa can be pointed to, but never captured, by the words and concepts that make up its formal, communicable aspect — just as the chest can only be opened in order to reach the heart. By means of this inner force, which its outer conceptual form at once hides and evokes, knowledge can effect a shift of consciousness from one degree of knowledge to another: a man begins to see the very realities of this world differently from those who rest in the surface play of cause and effect, so that the same act which is a burden to one is a delight to another. An indirect, mental conception of reality thus prepares the way for a penetrating, existential perception of reality. This is the difference between mere sight and true insight: sight reaches only the outward, superficial reality, whereas the reality of insight opens the intelligence to reality as such — ordinary insight, like abstract knowledge, remaining only at the surface level of understanding. The same idea appears in a saying of Ali (ع) concerning the true understanding that comes to plumb, and so truly to know, the buried treasures of knowledge: "He who understands knows the depth of knowledge (مَنْ فَهِمَ عَلِمَ غَوْرَ اَلْعِلْمِ)." And the effort that true knowledge demands, as against the mere piling up of facts, is likewise indicated: "Through learning and assimilating knowledge, until it becomes deeply rooted in one''s consciousness, is knowledge attained (بِالتَّعَلُّمِ يُنَالُ الْعِلْمُ)."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'the word chosen to translate hajama is penetrate but the primary sense of the verb is to assault to take by storm to charge in the warfare of that age the battle lines were drawn as a right wing a left wing and a center the heart of the army قلب العسكر where the king or commander stood the aim of the assault was to break through the wings and reach that heart for once the king was taken the battle was won and the victor took command of everything the defeated had held the kingdom its treasury its army its people the chessboard preserves the same rule so the word helps to show that conceptual knowledge holds a latent force one might almost call it an explosive power deriving from the reality of knowledge its haqiqa or spiritual essence it is this that calls out to be made real through tahaqquq realization in depth rather than mere verification on the surface and the striving by which one storms the outer wall of words to reach the heart of their meaning is تحقيق investigation this haqiqa can be pointed to but never captured by the words and concepts that make up its formal communicable aspect just as the chest can only be opened in order to reach the heart by means of this inner force which its outer conceptual form at once hides and evokes knowledge can effect a shift of consciousness from one degree of knowledge to another a man begins to see the very realities of this world differently from those who rest in the surface play of cause and effect so that the same act which is a burden to one is a delight to another an indirect mental conception of reality thus prepares the way for a penetrating existential perception of reality this is the difference between mere sight and true insight sight reaches only the outward superficial reality whereas the reality of insight opens the intelligence to reality as such ordinary insight like abstract knowledge remaining only at the surface level of understanding the same idea appears in a saying of ali ع concerning the true understanding that comes to plumb and so truly to know the buried treasures of knowledge he who understands knows the depth of knowledge من فهم علم غور العلم and the effort that true knowledge demands as against the mere piling up of facts is likewise indicated through learning and assimilating knowledge until it becomes deeply rooted in ones consciousness is knowledge attained بالتعلم ينال العلم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 9, NULL, 'The urgency of realizing this immanent power within knowledge — of moving from the abstract to the concrete, the potential to the actual, the static to the dynamic, the formal to the essential — is powerfully evoked by hajama, a word bound up with battle. It warns against taking the first understanding of an idea for its full comprehension, and full intellectual comprehension for the idea''s living interiorization in the spirit. For when knowledge at last storms the surface of religion and takes the heart, a transformation begins from within: the heart, now illumined by the realities it has seized, takes command of the limbs and the actions, which are the soul''s own resources, exactly as the victor takes command of the kingdom he has won. This interiorization is a process of endless unfolding within, not the mere registering of some fact from without. It requires the effective integration of knowledge within being: knowledge from without must be transformed into being from within, woven into the deepest texture of one''s existence. Knowledge thus demands not merely the attention of the mind but the total orientation of the soul.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'the urgency of realizing this immanent power within knowledge of moving from the abstract to the concrete the potential to the actual the static to the dynamic the formal to the essential is powerfully evoked by hajama a word bound up with battle it warns against taking the first understanding of an idea for its full comprehension and full intellectual comprehension for the ideas living interiorization in the spirit for when knowledge at last storms the surface of religion and takes the heart a transformation begins from within the heart now illumined by the realities it has seized takes command of the limbs and the actions which are the souls own resources exactly as the victor takes command of the kingdom he has won this interiorization is a process of endless unfolding within not the mere registering of some fact from without it requires the effective integration of knowledge within being knowledge from without must be transformed into being from within woven into the deepest texture of ones existence knowledge thus demands not merely the attention of the mind but the total orientation of the soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 10, NULL, 'In this ethos, then, the effective integration (تَوْحِيد) of knowledge within being cannot be reached without the participation of the whole soul; and this in turn requires the elimination of all the vices that flow from self-centeredness. Thus the الْعَاقِل, the true intellectual, is described by the Imam as one constantly engaged in struggle against his own soul — against the lower inclinations, the passionate whims, and the distracting caprices of the ego. These vices are not confined to the plane of morality; they encroach upon the domain of knowledge as well, and this becomes clear in the very measure that knowledge is grasped as a concrete vision of things rather than a merely notional or conceptual grasp of them. The vices are then seen as so many clouds obscuring the vision proper to the reality of insight. According to the Quran, evil actions become a rust that covers over the heart: "Nay, their hearts have become rusted by that which they have done" (Al-Mutaffifin: 14). The aqil, then, is engaged in a constant inner struggle against the tendencies that not only sully the soul but blind the heart. As a virtuous man he opposes vice on the moral plane, because it runs contrary to virtue; but vice is opposed for a further reason, one that lies on the higher plane of spiritual reality: it contradicts the nature of the Real, it obscures the reality of insight, and it blinds the eye of the heart which alone can see God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'in this ethos then the effective integration توحيد of knowledge within being cannot be reached without the participation of the whole soul and this in turn requires the elimination of all the vices that flow from self centeredness thus the العاقل the true intellectual is described by the imam as one constantly engaged in struggle against his own soul against the lower inclinations the passionate whims and the distracting caprices of the ego these vices are not confined to the plane of morality they encroach upon the domain of knowledge as well and this becomes clear in the very measure that knowledge is grasped as a concrete vision of things rather than a merely notional or conceptual grasp of them the vices are then seen as so many clouds obscuring the vision proper to the reality of insight according to the quran evil actions become a rust that covers over the heart nay their hearts have become rusted by that which they have done al mutaffifin 14 the aqil then is engaged in a constant inner struggle against the tendencies that not only sully the soul but blind the heart as a virtuous man he opposes vice on the moral plane because it runs contrary to virtue but vice is opposed for a further reason one that lies on the higher plane of spiritual reality it contradicts the nature of the real it obscures the reality of insight and it blinds the eye of the heart which alone can see god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 11, NULL, 'This does not deny the validity of the moral perspective; the stress falls rather on the deeper motive that drives the الْعَاقِل toward virtue, a motive that rises above the moral plane while including it. Morality appears here as the fruit or effect, and spirituality as the seed or cause. By drawing attention to the intellectual side of the aqil''s motive for shedding the vices, the Imam shows more clearly how immorality is rooted in ignorance; and to uproot that ignorance, for the true intellectual, is to dissolve the very substance of the vices. This uprooting demands great effort, a relentless battle within — indeed the most formidable of all battles, al-jihad al-akbar, the greatest struggle, as the Prophet defined it.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'this does not deny the validity of the moral perspective the stress falls rather on the deeper motive that drives the العاقل toward virtue a motive that rises above the moral plane while including it morality appears here as the fruit or effect and spirituality as the seed or cause by drawing attention to the intellectual side of the aqils motive for shedding the vices the imam shows more clearly how immorality is rooted in ignorance and to uproot that ignorance for the true intellectual is to dissolve the very substance of the vices this uprooting demands great effort a relentless battle within indeed the most formidable of all battles al jihad al akbar the greatest struggle as the prophet defined it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 12, NULL, 'The following sayings of Ali bear on the importance of this inner struggle:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'the following sayings of ali bear on the importance of this inner struggle', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 13, NULL, '"Struggling against the soul through knowledge, such is the mark of the intellect."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'struggling against the soul through knowledge such is the mark of the intellect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 14, NULL, '"The strongest of people are those who are strongest against their own souls."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'the strongest of people are those who are strongest against their own souls', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 15, NULL, '"Truly, one who fights his own soul in obedience to God, and does not sin against Him, has the rank of the righteous martyr in the sight of God."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'truly one who fights his own soul in obedience to god and does not sin against him has the rank of the righteous martyr in the sight of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 16, NULL, '"The ultimate battle is that of a man against his own soul."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'the ultimate battle is that of a man against his own soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 17, NULL, '"He who knows his soul fights it."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'he who knows his soul fights it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 18, NULL, '"No jihad is more excellent than the jihad of the soul."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'no jihad is more excellent than the jihad of the soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 19, NULL, 'In another saying the Imam clarifies what the Prophet meant by naming the greatest jihad the jihad of the soul (النَّفْس). It is not so much a matter of fighting against the soul as of the battle for the soul itself. This emerges from the metaphor by which the Imam defines the struggle: الْعَقْل, the intellect, leads the forces of al-Rahman, the Compassionate; al-hawa — whim, caprice, desire — commands the forces of al-shaytan, the devil; and النَّفْس, the soul, wavers between them, drawn by both (مُتَجَاذِبَةٌ بَيْنَهُمَا), falling under the sway of whichever of the two prevails.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'in another saying the imam clarifies what the prophet meant by naming the greatest jihad the jihad of the soul النفس it is not so much a matter of fighting against the soul as of the battle for the soul itself this emerges from the metaphor by which the imam defines the struggle العقل the intellect leads the forces of al rahman the compassionate al hawa whim caprice desire commands the forces of al shaytan the devil and النفس the soul wavers between them drawn by both متجاذبه بينهما falling under the sway of whichever of the two prevails', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 20, NULL, 'These sayings make clear that for the true intellectual the soul in its entirety must be "conquered" and enlisted on the side of the intellect. The aim is not to destroy the lower soul but to free it from the destructive influence of its caprice, its egoistic whims, its subjectivism, its individualism — all of which are gathered up in the word هَوَى. The Prophet, the Quran tells us, does not speak from هَوَى; rather: "It is naught but a revelation revealed" (An-Najm: 3-4). The divine objectivity of revelation is here set against the human subjectivity of passionate whim. In the setting of the holy war within, the Imam''s sayings bring a parallel opposition into focus: the objectivity of the intellect must prevail over the subjectivity of individual caprice and egotistic desire. It is the intellect that represents — in the sense of "makes present" — the divine power of al-Rahman, and that combats the forces of al-shaytan as embodied in al-hawa.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'these sayings make clear that for the true intellectual the soul in its entirety must be conquered and enlisted on the side of the intellect the aim is not to destroy the lower soul but to free it from the destructive influence of its caprice its egoistic whims its subjectivism its individualism all of which are gathered up in the word هوي the prophet the quran tells us does not speak from هوي rather it is naught but a revelation revealed an najm 3 4 the divine objectivity of revelation is here set against the human subjectivity of passionate whim in the setting of the holy war within the imams sayings bring a parallel opposition into focus the objectivity of the intellect must prevail over the subjectivity of individual caprice and egotistic desire it is the intellect that represents in the sense of makes present the divine power of al rahman and that combats the forces of al shaytan as embodied in al hawa', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 21, NULL, 'The word هَوَى is used further in the Quran to denote desires that spring from the ego, by which the ego becomes a kind of false god: "Hast thou seen him who maketh his desire his god?" (25: 43; almost identical at 45: 23). This is the subtle or hidden idolatry (الشِّرْكُ الْخَفِيُّ) that the Prophet described as more hidden than a black ant crawling on a dark stone in a moonless night. To root out this idolatry of the ego, a force higher than the ego itself must be brought to bear, since the ego can never be controlled by anything that belongs to it; and that higher force is the divine Reality, access to which is opened through the power of the intellect and the graces of faith. This complementarity between the effort to overcome the egoism of هَوَى and the inflow of divine grace is well expressed in the following Quranic verse: "As for he who fears the station of his Lord, and restraineth his soul from whim (هَوَى), verily, Paradise will be his abode" (An-Naziat: 40-41).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'the word هوي is used further in the quran to denote desires that spring from the ego by which the ego becomes a kind of false god hast thou seen him who maketh his desire his god 25 43 almost identical at 45 23 this is the subtle or hidden idolatry الشرك الخفي that the prophet described as more hidden than a black ant crawling on a dark stone in a moonless night to root out this idolatry of the ego a force higher than the ego itself must be brought to bear since the ego can never be controlled by anything that belongs to it and that higher force is the divine reality access to which is opened through the power of the intellect and the graces of faith this complementarity between the effort to overcome the egoism of هوي and the inflow of divine grace is well expressed in the following quranic verse as for he who fears the station of his lord and restraineth his soul from whim هوي verily paradise will be his abode an naziat 40 41', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 22, NULL, 'The soul''s fundamental energy is not to be destroyed but converted and redirected — away from the fleeting objects of individualistic desire and the impulses of al-shaytan, and toward the one true object named by al-Rahman. This "conquest" of the soul is far more than the arrival at some mental conception. It is not only the mind, the will, and the character that must be transformed; the soul''s very deepest disposition must be integrated into the truth perceived by the intellect, if a man is to perceive that truth in all its dimensions and ramifications across the different planes of being.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'the souls fundamental energy is not to be destroyed but converted and redirected away from the fleeting objects of individualistic desire and the impulses of al shaytan and toward the one true object named by al rahman this conquest of the soul is far more than the arrival at some mental conception it is not only the mind the will and the character that must be transformed the souls very deepest disposition must be integrated into the truth perceived by the intellect if a man is to perceive that truth in all its dimensions and ramifications across the different planes of being', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 23, NULL, 'For the Imam the need to win the soul over in its totality follows naturally from his understanding of تَوْحِيد, the most fundamental principle of Islam. تَوْحِيد is a verbal noun, and to translate it as mere oneness or unity fails to capture its full force. Literally it means "affirming one" — the affirmation of and belief in God''s oneness, which is the outward, theological meaning — or "realizing one," the realization that there is but one reality, which is the inner, spiritual meaning. In the Imam''s view, then, the absolutely Real is perceived not only as being one but also as making one, as integrating. The Real is not only unique; it is also unifying. تَوْحِيد thus comes to mean not merely affirming the oneness of God, but being one oneself so as to reflect the One perfectly: to know God is to be "integrated." Here one may see a link with the etymology of aql, whose primary meaning is "to bind." Yet whereas the later mystical tradition tends to stress the limiting aspect of this word — the intellect as that which defines and encloses meaning, over against the heart, which intuits and discloses spiritual truth — here the intellect is that which "binds together" the scattered elements of the soul into an organic unity. This principle is expressed in the first of the following sayings of the Imam, each of which merits deep reflection:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'for the imam the need to win the soul over in its totality follows naturally from his understanding of توحيد the most fundamental principle of islam توحيد is a verbal noun and to translate it as mere oneness or unity fails to capture its full force literally it means affirming one the affirmation of and belief in gods oneness which is the outward theological meaning or realizing one the realization that there is but one reality which is the inner spiritual meaning in the imams view then the absolutely real is perceived not only as being one but also as making one as integrating the real is not only unique it is also unifying توحيد thus comes to mean not merely affirming the oneness of god but being one oneself so as to reflect the one perfectly to know god is to be integrated here one may see a link with the etymology of aql whose primary meaning is to bind yet whereas the later mystical tradition tends to stress the limiting aspect of this word the intellect as that which defines and encloses meaning over against the heart which intuits and discloses spiritual truth here the intellect is that which binds together the scattered elements of the soul into an organic unity this principle is expressed in the first of the following sayings of the imam each of which merits deep reflection', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 24, NULL, '"He who knows God integrates himself (مَنْ عَرَفَ اللهَ تَوَحَّدَ)."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'he who knows god integrates himself من عرف الله توحد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 25, NULL, '"He who knows his soul disengages himself (مَنْ عَرَفَ نَفْسَهُ تَجَرَّدَ)."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'he who knows his soul disengages himself من عرف نفسه تجرد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 26, NULL, '"He who knows people isolates himself (مَنْ عَرَفَ النَّاسَ تَفَرَّدَ)."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'he who knows people isolates himself من عرف الناس تفرد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 27, NULL, '"He who knows the world withholds himself (مَنْ عَرَفَ الدُّنْيَا تَزَهَّدَ)."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'he who knows the world withholds himself من عرف الدنيا تزهد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 28, NULL, 'Elsewhere this total adherence to the Real is described by the Imam as "sincerity" — sidq or إِخْلَاص — terms that mean far more than simple truthfulness, as the root of إِخْلَاص already shows. The verb khalusa means to be utterly pure, true to one''s essence, unmixed with any foreign element. This side of the meaning comes through clearly in the following saying of the Imam: "Make purely for God (أَخْلِصْ لِلَّهِ) your action and your knowledge, your love and your hatred, your taking and your leaving, your speech and your silence."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'elsewhere this total adherence to the real is described by the imam as sincerity sidq or اخلاص terms that mean far more than simple truthfulness as the root of اخلاص already shows the verb khalusa means to be utterly pure true to ones essence unmixed with any foreign element this side of the meaning comes through clearly in the following saying of the imam make purely for god اخلص لله your action and your knowledge your love and your hatred your taking and your leaving your speech and your silence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 29, NULL, 'To be totally sincere, then, means to make oneself "purely" for God — to carry no "stain" of impurity, understood here as whatever is other than God, in one''s devotion, action, intention, or even sentiment. One must love and hate only in relation to one''s bond with God. Of all the tendencies that work their way into one''s motives and intentions, the most destructive is egotism. إِخْلَاص, pure sincerity, is the active effort to be, think, and act purely for God — that is, with selflessness — which is why the Imam lays such stress on the holy war within the soul as the "ultimate battle." One who wins this battle attains the rank of the "righteous martyr," for the victor here is a martyr in the truest sense: he has sacrificed his lower life for the sake of God, with whom is the real life — the life witnessed by the intellect, the only element within human consciousness able to look upon the soul as "the other" with genuine objectivity.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'to be totally sincere then means to make oneself purely for god to carry no stain of impurity understood here as whatever is other than god in ones devotion action intention or even sentiment one must love and hate only in relation to ones bond with god of all the tendencies that work their way into ones motives and intentions the most destructive is egotism اخلاص pure sincerity is the active effort to be think and act purely for god that is with selflessness which is why the imam lays such stress on the holy war within the soul as the ultimate battle one who wins this battle attains the rank of the righteous martyr for the victor here is a martyr in the truest sense he has sacrificed his lower life for the sake of god with whom is the real life the life witnessed by the intellect the only element within human consciousness able to look upon the soul as the other with genuine objectivity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 30, NULL, 'As the saying holds, "struggling against the soul through knowledge, such is the mark of the intellect." The intellectual engaged in this battle is also one who bears "witness" (al-shahid, meaning both martyr and witness, as in the original Greek sense of the word). He bears witness to God through the intellect''s sacrifice of whatever opposes the truth of God, and the chief opponent is his own egotism, his own "false life." To possess perfect إِخْلَاص, then, is to be rid of all hypocritical self-preoccupation and to put in its place a sincere theocentricity — a mode of being centered upon God rather than oneself. إِخْلَاص, therefore, means being for God, or belonging to God, in the sense pointed to by the Quranic verse: "Say: Truly my worship and my sacrifice, and my living and my dying, are for God, Lord of the universes" (Al-Anam: 162).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'as the saying holds struggling against the soul through knowledge such is the mark of the intellect the intellectual engaged in this battle is also one who bears witness al shahid meaning both martyr and witness as in the original greek sense of the word he bears witness to god through the intellects sacrifice of whatever opposes the truth of god and the chief opponent is his own egotism his own false life to possess perfect اخلاص then is to be rid of all hypocritical self preoccupation and to put in its place a sincere theocentricity a mode of being centered upon god rather than oneself اخلاص therefore means being for god or belonging to god in the sense pointed to by the quranic verse say truly my worship and my sacrifice and my living and my dying are for god lord of the universes al anam 162', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 31, NULL, 'That worship is the first thing named in this verse is of particular significance for understanding Ali s spiritual ethos, and the indispensable role of worship and devotion must be emphasized in setting that ethos out. The second chapter takes up this role in the context of the quest for the fundamental virtue of justice. The ultimate fruits of worship and devotion — of which the quintessence is the remembrance of God — are the subject of the third chapter. One of the defining features of the Imam''s spiritual ethos is indeed the emphasis he places on prayer, taking that term in its widest sense to include all the means — from formal worship and supplication to meditation and reflection, remembrance and contemplation — by which the individual is oriented and attuned to the Real, اَلْحَقّ.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'that worship is the first thing named in this verse is of particular significance for understanding ali s spiritual ethos and the indispensable role of worship and devotion must be emphasized in setting that ethos out the second chapter takes up this role in the context of the quest for the fundamental virtue of justice the ultimate fruits of worship and devotion of which the quintessence is the remembrance of god are the subject of the third chapter one of the defining features of the imams spiritual ethos is indeed the emphasis he places on prayer taking that term in its widest sense to include all the means from formal worship and supplication to meditation and reflection remembrance and contemplation by which the individual is oriented and attuned to the real الحق', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 32, NULL, 'Worship is therefore an integral aspect of إِخْلَاص, precisely because it answers to and sustains a fundamental dimension of the human soul. That within the soul which yearns to worship, and is nourished by worship alone, must be given its due. In a spiritual context, if worship is pushed to the margins, one''s sincerity is compromised: one is no longer being sincere with God, no longer being "just" to God, no longer rendering God His due. And the spiritual logic of the Imam holds that if one is not just with God, one cannot be just to His creatures. "Whoso establishes well-being between himself and God," he says, "God establishes well-being between him and mankind."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'worship is therefore an integral aspect of اخلاص precisely because it answers to and sustains a fundamental dimension of the human soul that within the soul which yearns to worship and is nourished by worship alone must be given its due in a spiritual context if worship is pushed to the margins ones sincerity is compromised one is no longer being sincere with god no longer being just to god no longer rendering god his due and the spiritual logic of the imam holds that if one is not just with god one cannot be just to his creatures whoso establishes well being between himself and god he says god establishes well being between him and mankind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 33, NULL, 'One might also cite here the Quranic verse: "Worship thy Lord until certainty cometh to thee" (Al-Hijr: 99). The quest for knowledge demands total dedication if it is to yield its inner riches, and that dedication includes the near-alchemical transformation of consciousness worked by total concentration on the divine Reality — prayer in one of its deepest modes. In this form of prayer, the intensity of dedication is such that nothing else can occupy one''s consciousness alongside its object: the "remembrance" (ذِکْر) of God strictly implies the forgetting of everything else, and above all of oneself. The spiritual reality of the dhikr can only be reached when "you forget your soul in your remembrance." Concentration upon the divine Reality as the supreme object of knowledge, made present through the Name or Names of God, is thus a mode of prayer — one which, to be effective, requires both presence of mind and a genuine engagement of the will. To pray absent-mindedly or mechanically is far from enough. On this the Imam says, "He who prays without exertion is like one who shoots [arrows] without a bow." In the same way, there is nothing passive or easy about acquiring knowledge: "Knowledge calls out for action; if it is answered [it is of avail], otherwise it departs."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'one might also cite here the quranic verse worship thy lord until certainty cometh to thee al hijr 99 the quest for knowledge demands total dedication if it is to yield its inner riches and that dedication includes the near alchemical transformation of consciousness worked by total concentration on the divine reality prayer in one of its deepest modes in this form of prayer the intensity of dedication is such that nothing else can occupy ones consciousness alongside its object the remembrance ذكر of god strictly implies the forgetting of everything else and above all of oneself the spiritual reality of the dhikr can only be reached when you forget your soul in your remembrance concentration upon the divine reality as the supreme object of knowledge made present through the name or names of god is thus a mode of prayer one which to be effective requires both presence of mind and a genuine engagement of the will to pray absent mindedly or mechanically is far from enough on this the imam says he who prays without exertion is like one who shoots arrows without a bow in the same way there is nothing passive or easy about acquiring knowledge knowledge calls out for action if it is answered it is of avail otherwise it departs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the discourse to kumayl', '4. The Discourse to Kumayl', 34, NULL, 'The same idea is expressed more forcefully in this saying of the Imam: "When you hear knowledge [being imparted] cleave to it, do not mix it up with jest, lest hearts spew it forth." Knowledge that is not taken seriously will be of no avail; it remains "undigested" and cannot be assimilated by the "heart" — that innermost faculty which has access to the "reality of insight" and which can thus "see" God. For it is the heart that sees Allah, not by eyesight, not by بصارۃ, but through the spiritual insight, the بصیرۃ, generated by the true principles of faith, the حَقَائِقُ الْاِیمَانِ. Indeed, it is not the individual who "assimilates" knowledge to himself; it is knowledge — or rather the reality of being expressed through true knowledge — that assimilates the individual to itself: "Acquire knowledge, and [true] life will acquire you." The relationship between life and consciousness, so central to the intrinsic function of the spirit, is again at the heart of this maxim. At first the individual seeks knowledge and cultivates consciousness; then life "seeks" the individual, as being makes itself more fully real within him. Put differently, the individual first makes an active effort to integrate knowledge within his being; but at a certain point this activity turns into passive receptivity: being — "true life" — integrates the individual within itself. To return to the Imam''s guidance to Kumayl: "Through them knowledge penetrates the reality of insight." It is not the knowers who penetrate; it is knowledge that penetrates to the reality of insight, doing so through them, and this in the very measure of their effacement within knowledge — an effacement that is the shadow cast by their effective integration within the life that "acquires" them.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 4 the discourse to kumayl', 'the same idea is expressed more forcefully in this saying of the imam when you hear knowledge being imparted cleave to it do not mix it up with jest lest hearts spew it forth knowledge that is not taken seriously will be of no avail it remains undigested and cannot be assimilated by the heart that innermost faculty which has access to the reality of insight and which can thus see god for it is the heart that sees allah not by eyesight not by بصاره but through the spiritual insight the بصيره generated by the true principles of faith the حقايق الايمان indeed it is not the individual who assimilates knowledge to himself it is knowledge or rather the reality of being expressed through true knowledge that assimilates the individual to itself acquire knowledge and true life will acquire you the relationship between life and consciousness so central to the intrinsic function of the spirit is again at the heart of this maxim at first the individual seeks knowledge and cultivates consciousness then life seeks the individual as being makes itself more fully real within him put differently the individual first makes an active effort to integrate knowledge within his being but at a certain point this activity turns into passive receptivity being true life integrates the individual within itself to return to the imams guidance to kumayl through them knowledge penetrates the reality of insight it is not the knowers who penetrate it is knowledge that penetrates to the reality of insight doing so through them and this in the very measure of their effacement within knowledge an effacement that is the shadow cast by their effective integration within the life that acquires them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 0, NULL, 'The discourse to Kumayl continues: "They rejoice in their intimacy with the spirit of certainty." This sentence speaks directly to the sheer happiness that flows from the life of the spirit. In the Arabic phrase wa basharu ruh al-yaqin, the word bashara means first of all to have intimate experience of something, to come into direct physical contact with it. In this form the verb also carries a sense of joy, so that "to rejoice in intimate contact" conveys better what the single word holds. To touch the spirit of certainty is not to reach some cold logical fact at the end of a purely mental process. It means entering deeply into the very object of one''s certainty — and that object, in the end, is nothing less than the divine itself. This reality is infinitely more blessed than any bliss of Paradise one could imagine, for the Quran affirms that the divine رِضْوَان, its beatitude and contentment, is "greater" than Paradise. It cannot, then, but bestow joy upon the soul that truly opens itself to it:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'the discourse to kumayl continues they rejoice in their intimacy with the spirit of certainty this sentence speaks directly to the sheer happiness that flows from the life of the spirit in the arabic phrase wa basharu ruh al yaqin the word bashara means first of all to have intimate experience of something to come into direct physical contact with it in this form the verb also carries a sense of joy so that to rejoice in intimate contact conveys better what the single word holds to touch the spirit of certainty is not to reach some cold logical fact at the end of a purely mental process it means entering deeply into the very object of ones certainty and that object in the end is nothing less than the divine itself this reality is infinitely more blessed than any bliss of paradise one could imagine for the quran affirms that the divine رضوان its beatitude and contentment is greater than paradise it cannot then but bestow joy upon the soul that truly opens itself to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 1, NULL, 'At-Tawbah: 72وَعَدَ ٱللَّهُ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَتِ جَنَّتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَرُ خَلِدِينَ فِيهَا وَمَسَكِنَ طَيِّبَةًۭ فِى جَنَّتِ عَدْنٍۢ ۚ وَرِضْوَنٌۭ مِّنَ ٱللَّهِ أَكْبَرُ ۚ ذَلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ"God has promised the believers, men and women, gardens beneath which rivers flow, wherein they abide, and goodly dwellings in gardens of Eden. And beatitude from God is greater. That is the supreme triumph" (At-Tawbah: 72).', '', NULL, 'At-Tawbah: 72', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'at tawbah 72وعد الله المومنين والمومنت جنت تجري من تحتها الانهر خلدين فيها ومسكن طيبه في جنت عدن ورضون من الله اكبر ذلك هو الفوز العظيم god has promised the believers men and women gardens beneath which rivers flow wherein they abide and goodly dwellings in gardens of eden and beatitude from god is greater that is the supreme triumph at tawbah 72', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 2, NULL, 'In the words of Ali (ع), "Learning and reflecting upon knowledge is the delight of the knowers."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'in the words of ali ع learning and reflecting upon knowledge is the delight of the knowers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 3, NULL, 'This might be called a way of knowing steeped in joy, for "the most joyous of mankind is the intellectual (الْعَاقِل)." Such a view stands in sharp contrast to the modern conception, modeled on science, that treats knowledge as dry, cold, and abstract. It deserves careful thought, for it opens up a crucial dimension of the spiritual knowledge proper to the Imam''s perspective, and indeed to every spiritual tradition worthy of the name. To engage with truths ought to bring happiness, and it does so to the degree that those truths are fundamental to one''s own being, or to Being as such. In the end these two are one and the same, given the uniqueness — the "one-and-onliness" — of Being. What has no second, no other, cannot be counted; Being is indivisible. So the being of the individual cannot finally differ from Being as such, however vast the difference in existence between the individual and God — a difference, indeed, past all common measure. True knowledge is knowledge of Being, and so it cannot help but be a form of self-discovery, even though knowledge of the Absolute is impossible without absolute self-abandonment. The highest discovery calls for the deepest self-effacement.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'this might be called a way of knowing steeped in joy for the most joyous of mankind is the intellectual العاقل such a view stands in sharp contrast to the modern conception modeled on science that treats knowledge as dry cold and abstract it deserves careful thought for it opens up a crucial dimension of the spiritual knowledge proper to the imams perspective and indeed to every spiritual tradition worthy of the name to engage with truths ought to bring happiness and it does so to the degree that those truths are fundamental to ones own being or to being as such in the end these two are one and the same given the uniqueness the one and onliness of being what has no second no other cannot be counted being is indivisible so the being of the individual cannot finally differ from being as such however vast the difference in existence between the individual and god a difference indeed past all common measure true knowledge is knowledge of being and so it cannot help but be a form of self discovery even though knowledge of the absolute is impossible without absolute self abandonment the highest discovery calls for the deepest self effacement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 4, NULL, 'In the early stages, though, the true knowledge the intellectual gains is a self-discovery that brings the happiness of a homecoming — a return from the exile of ignorance. This is so because "the most intellectual of people" is "the one who is closest to God" and "the one who is most alive." To be close to God is to be fully alive, and this true life gives a deep joy, the joie de vivre, the sheer joy of living. It is a joy that belongs to existence itself, independent of any particular experience, pleasant or not.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'in the early stages though the true knowledge the intellectual gains is a self discovery that brings the happiness of a homecoming a return from the exile of ignorance this is so because the most intellectual of people is the one who is closest to god and the one who is most alive to be close to god is to be fully alive and this true life gives a deep joy the joie de vivre the sheer joy of living it is a joy that belongs to existence itself independent of any particular experience pleasant or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 5, NULL, 'Here the crucial bond between life and consciousness comes into view — between the fruits of the in-spiration of God''s spirit on one side, and this life of spiritual awareness and joy on the other. Those who are true to the spirit of God within them truly possess joy. It is likewise from their intimate and unshakeable certainty of God''s goodness and compassion that the Imam defines the true فَقِيهٌ — not so much "the jurist" as "one who truly understands" — as "he who does not make people despair of the mercy of God, and does not make them lose hope in the gracious spirit of God (rawh Allah)." So deeply is the sage immersed in the joyous certainty of God''s mercy that no room is left for despair. To despair of this mercy is itself a mark of unbelief:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'here the crucial bond between life and consciousness comes into view between the fruits of the in spiration of gods spirit on one side and this life of spiritual awareness and joy on the other those who are true to the spirit of god within them truly possess joy it is likewise from their intimate and unshakeable certainty of gods goodness and compassion that the imam defines the true فقيه not so much the jurist as one who truly understands as he who does not make people despair of the mercy of god and does not make them lose hope in the gracious spirit of god rawh allah so deeply is the sage immersed in the joyous certainty of gods mercy that no room is left for despair to despair of this mercy is itself a mark of unbelief', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 6, NULL, 'Al-Hijr: 56قَالَ وَمَن يَقْنَطُ مِن رَّحْمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ"And who despaireth of the mercy of his Lord except those who stray in error?" (Al-Hijr: 56).', '', NULL, 'Al-Hijr: 56', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'al hijr 56قال ومن يقنط من رحمه ربه الا الضالون and who despaireth of the mercy of his lord except those who stray in error al hijr 56', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 7, NULL, 'The Quran''s assurances of mercy come fully alive in souls that possess a deep knowledge of the blessed nature of the divine Reality — a knowledge lived, not merely thought:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'the qurans assurances of mercy come fully alive in souls that possess a deep knowledge of the blessed nature of the divine reality a knowledge lived not merely thought', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'verse', 'the fruits of certainty', '5. The Fruits of Certainty', 8, NULL, 'Al-A''raf: 156وَٱكْتُبْ لَنَا فِى هَذِهِ ٱلدُّنْيَا حَسَنَةًۭ وَفِى ٱلْآخِرَةِ إِنَّا هُدْنَآ إِلَيْكَ ۚ قَالَ عَذَابِىٓ أُصِيبُ بِهِۦ مَنْ أَشَآءُ ۖ وَرَحْمَتِى وَسِعَتْ كُلَّ شَىْءٍۢ ۚ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَتِنَا يُؤْمِنُونَ"My mercy encompasseth all things" (Al-Araf: 156)', '', 'وَٱكْتُبْ لَنَا فِى هَذِهِ ٱلدُّنْيَا حَسَنَةًۭ وَفِى ٱلْآخِرَةِ إِنَّا هُدْنَآ إِلَيْكَ ۚ قَالَ عَذَابِىٓ أُصِيبُ بِهِۦ مَنْ أَشَآءُ ۖ وَرَحْمَتِى وَسِعَتْ كُلَّ شَىْءٍۢ ۚ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَتِنَا يُؤْمِنُونَ', 'Al-A''raf: 156', 7, 156, 'spiritual ethos 5 the fruits of certainty', 'al araf 156واكتب لنا في هذه الدنيا حسنه وفي الاخره انا هدنا اليك قال عذابي اصيب به من اشاء ورحمتي وسعت كل شيء فساكتبها للذين يتقون ويوتون الزكوه والذين هم بايتنا يومنون my mercy encompasseth all things al araf 156', 'واكتب لنا في هذه الدنيا حسنه وفي الاخره انا هدنا اليك قال عذابي اصيب به من اشاء ورحمتي وسعت كل شيء فساكتبها للذين يتقون ويوتون الزكوه والذين هم بايتنا يومنون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 9, NULL, 'and', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'and', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'verse', 'the fruits of certainty', '5. The Fruits of Certainty', 10, NULL, 'Al-An''am: 54وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤْمِنُونَ بِـَٔايَتِنَا فَقُلْ سَلَمٌ عَلَيْكُمْ ۖ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۖ أَنَّهُۥ مَنْ عَمِلَ مِنكُمْ سُوٓءًۢا بِجَهَلَةٍۢ ثُمَّ تَابَ مِنۢ بَعْدِهِۦ وَأَصْلَحَ فَأَنَّهُۥ غَفُورٌۭ رَّحِيمٌۭ"thy Lord has prescribed for Himself mercy" (Al-Anam: 54).', '', 'وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤْمِنُونَ بِـَٔايَتِنَا فَقُلْ سَلَمٌ عَلَيْكُمْ ۖ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۖ أَنَّهُۥ مَنْ عَمِلَ مِنكُمْ سُوٓءًۢا بِجَهَلَةٍۢ ثُمَّ تَابَ مِنۢ بَعْدِهِۦ وَأَصْلَحَ فَأَنَّهُۥ غَفُورٌۭ رَّحِيمٌۭ', 'Al-An''am: 54', 6, 54, 'spiritual ethos 5 the fruits of certainty', 'al anam 54واذا جاءك الذين يومنون بايتنا فقل سلم عليكم كتب ربكم علي نفسه الرحمه انه من عمل منكم سوءا بجهله ثم تاب من بعده واصلح فانه غفور رحيم thy lord has prescribed for himself mercy al anam 54', 'واذا جاءك الذين يومنون بايتنا فقل سلم عليكم كتب ربكم علي نفسه الرحمه انه من عمل منكم سوءا بجهله ثم تاب من بعده واصلح فانه غفور رحيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 11, NULL, 'These are the ones who truly understand, the true فُقَهَاءُ.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'these are the ones who truly understand the true فقهاء', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 12, NULL, 'This opening to joy through intimate knowledge of God''s mercy cannot be separated from beauty, and in the Imam''s view the perception of beauty is another unexpected companion of the intellect. The love of beauty is not merely a matter of private taste; it belongs objectively to the intellect''s own working. Beauty also leads straight to the heart of morality. The Arabic احسان is often translated simply as "virtue" or "excellence," yet one of its plain, literal meanings is "making beautiful," since حَسَنَ means "beauty." Virtue, احسان, can thus be understood as what makes the soul beautiful. Seen this way, the bond among intellect, morality, and beauty grows far clearer. "The excellence of the intellect," says Ali, "is in the beauty of things outward and inward (جَمَالُ الظَّوَاهِرِ وَالْبَوَاطِنِ)." The outward beauty of forms and actions must be matched by inward beauty — beauty of soul, or virtue in its fullest and deepest sense. All of this follows naturally from two sayings attributed to the Prophet: "Truly God is beautiful and He loves beauty," and "Assume the character traits of God."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'this opening to joy through intimate knowledge of gods mercy cannot be separated from beauty and in the imams view the perception of beauty is another unexpected companion of the intellect the love of beauty is not merely a matter of private taste it belongs objectively to the intellects own working beauty also leads straight to the heart of morality the arabic احسان is often translated simply as virtue or excellence yet one of its plain literal meanings is making beautiful since حسن means beauty virtue احسان can thus be understood as what makes the soul beautiful seen this way the bond among intellect morality and beauty grows far clearer the excellence of the intellect says ali is in the beauty of things outward and inward جمال الظواهر والبواطن the outward beauty of forms and actions must be matched by inward beauty beauty of soul or virtue in its fullest and deepest sense all of this follows naturally from two sayings attributed to the prophet truly god is beautiful and he loves beauty and assume the character traits of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 13, NULL, 'To cultivate beautiful traits within oneself makes one lovable to God, since He loves beauty. And making oneself lovable to God cannot be separated from imitating the virtues brought to perfection in the soul of the Prophet:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'to cultivate beautiful traits within oneself makes one lovable to god since he loves beauty and making oneself lovable to god cannot be separated from imitating the virtues brought to perfection in the soul of the prophet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 14, NULL, 'Ali ''Imran: 31قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ۗ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ"Say: O ye who believe, if ye love God, follow me, the Prophet; God will love you" (Ali Imran: 31).', '', NULL, 'Ali ''Imran: 31', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'ali imran 31قل ان كنتم تحبون الله فاتبعوني يحببكم الله ويغفر لكم ذنوبكم والله غفور رحيم say o ye who believe if ye love god follow me the prophet god will love you ali imran 31', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 15, NULL, 'Another saying of the Imam points to this drawing-down of God''s love through making oneself beautiful in the fullest sense: "The foundation of the intellect is the assimilation of love (أَوَّلُ الْعَقْلِ التَّوَدُّدُ)." Instead of speaking of love as such (wudd/mawadda), the Imam chooses the form تَوَدُّد to draw attention to the need to make oneself lovable to God. The word points to a twofold work: taking the principle of love into oneself and making it real there, and at the same time letting the love felt within shine outward — for love is at once an outward radiance and an inward attraction.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'another saying of the imam points to this drawing down of gods love through making oneself beautiful in the fullest sense the foundation of the intellect is the assimilation of love اول العقل التودد instead of speaking of love as such wudd mawadda the imam chooses the form تودد to draw attention to the need to make oneself lovable to god the word points to a twofold work taking the principle of love into oneself and making it real there and at the same time letting the love felt within shine outward for love is at once an outward radiance and an inward attraction', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 16, NULL, 'To follow the Prophet, and so make oneself open to the inflowing of divine love, means among other things cultivating the prophetic virtues. These virtues are called prophetic not because they belong to the Prophet alone, but because he is held to have realized virtue in all its fullness and is therefore the exemplar, par excellence, of virtue itself. Beauty and love are not the only qualities that give shape to the intellect''s openness to the divine Reality. Kindness and contentment, courtesy, generosity and modesty, and wise forbearance (حِلْم) matter just as much. Not one of these moral qualities is missing from the soul of the true intellectual. There can be no wisdom or intellect in the fullest sense in a soul that lacks them. It is exactly the presence of these virtues that lets the intellect grow in depth and in breadth. Without them it stays trapped on the flat, horizontal plane of its own operations, held to the work of reason alone. Such reason, until faith touches it and grace deepens it, does not know what lies beneath the surface of its own field. It stays blind to the hidden treasures of the intellect, and blind to the need to gather the whole soul within the mold of that integral, or unifying, virtue which gives intelligence its integrity. This making-one, this integration, lies at the very root of تَوْحِيد, now understood as a living process of spiritual unification demanded by the very idea of God''s oneness. Truth must plainly inspire the soul; but just as necessary, in the other direction, is that virtue should aerate the intelligence — the leaven that lets it rise to its full dimensions.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'to follow the prophet and so make oneself open to the inflowing of divine love means among other things cultivating the prophetic virtues these virtues are called prophetic not because they belong to the prophet alone but because he is held to have realized virtue in all its fullness and is therefore the exemplar par excellence of virtue itself beauty and love are not the only qualities that give shape to the intellects openness to the divine reality kindness and contentment courtesy generosity and modesty and wise forbearance حلم matter just as much not one of these moral qualities is missing from the soul of the true intellectual there can be no wisdom or intellect in the fullest sense in a soul that lacks them it is exactly the presence of these virtues that lets the intellect grow in depth and in breadth without them it stays trapped on the flat horizontal plane of its own operations held to the work of reason alone such reason until faith touches it and grace deepens it does not know what lies beneath the surface of its own field it stays blind to the hidden treasures of the intellect and blind to the need to gather the whole soul within the mold of that integral or unifying virtue which gives intelligence its integrity this making one this integration lies at the very root of توحيد now understood as a living process of spiritual unification demanded by the very idea of gods oneness truth must plainly inspire the soul but just as necessary in the other direction is that virtue should aerate the intelligence the leaven that lets it rise to its full dimensions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 17, NULL, 'In this perspective, sinful and immoral qualities are seen not only as vices but as so many blind spots, so many failures of the intellect. Vice sickens the heart; it blinds the heart''s eye and so leaves it unable to see the Real. As the Quran says:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'in this perspective sinful and immoral qualities are seen not only as vices but as so many blind spots so many failures of the intellect vice sickens the heart it blinds the hearts eye and so leaves it unable to see the real as the quran says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 18, NULL, 'Al-Baqarah: 10فِى قُلُوبِهِم مَّرَضٌۭ فَزَادَهُمُ ٱللَّهُ مَرَضًۭا ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْذِبُونَ"In their hearts is a disease and God increased them in disease" (Al-Baqarah: 10)', '', NULL, 'Al-Baqarah: 10', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'al baqarah 10في قلوبهم مرض فزادهم الله مرضا ولهم عذاب اليم بما كانوا يكذبون in their hearts is a disease and god increased them in disease al baqarah 10', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 19, NULL, 'and', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'and', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'verse', 'the fruits of certainty', '5. The Fruits of Certainty', 20, NULL, 'Al-Hajj: 46أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌۭ يَعْقِلُونَ بِهَآ أَوْ آذَانٌۭ يَسْمَعُونَ بِهَا ۖ فَإِنَّهَا لَا تَعْمَى ٱلْأَبْصَرُ وَلَكِن تَعْمَى ٱلْقُلُوبُ ٱلَّتِى فِى ٱلصُّدُورِ"It is not the sights that are blind, but blind are the hearts" (Al-Hajj: 46).', '', 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌۭ يَعْقِلُونَ بِهَآ أَوْ آذَانٌۭ يَسْمَعُونَ بِهَا ۖ فَإِنَّهَا لَا تَعْمَى ٱلْأَبْصَرُ وَلَكِن تَعْمَى ٱلْقُلُوبُ ٱلَّتِى فِى ٱلصُّدُورِ', 'Al-Hajj: 46', 22, 46, 'spiritual ethos 5 the fruits of certainty', 'al hajj 46افلم يسيروا في الارض فتكون لهم قلوب يعقلون بها او اذان يسمعون بها فانها لا تعمي الابصر ولكن تعمي القلوب التي في الصدور it is not the sights that are blind but blind are the hearts al hajj 46', 'افلم يسيروا في الارض فتكون لهم قلوب يعقلون بها او اذان يسمعون بها فانها لا تعمي الابصر ولكن تعمي القلوب التي في الصدور');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 21, NULL, 'All the vices are contained within egotism, which in turn is often called simply caprice (هَوَى). In one saying the Imam treats the conquest of caprice as the same as salvation: "He attains deliverance whose intellect dominates his caprice." Deliverance, فَلَاحٌ, which carries the sense both of salvation and of blessedness, is thus within reach to some degree here and now; it is not a grace granted only after death. Such deliverance means tasting the joy that flows from certainty, from intimate contact with the spirit of that certainty. As for how to cultivate an openness to this spirit of certainty: beyond obedience to the rules and regulations of the revealed Law, what is required is that union of pure intention and sincere devotion that the word إِخْلَاص expresses. Without this sincerity, this purity, obedience to formal rules is nothing but hypocrisy (نِفَاقٌ) and pretension (رِيَاء) — which the Imam in turn calls the gravest of all sins, شِرْك, the setting-up of partners to God: "Know that the slightest pretension (رِيَاء) is polytheism." This saying can be read as a commentary on one of the Quran''s weightiest condemnations of hypocrisy. The verses speak of those who deny the essence of faith while outwardly keeping to it:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'all the vices are contained within egotism which in turn is often called simply caprice هوي in one saying the imam treats the conquest of caprice as the same as salvation he attains deliverance whose intellect dominates his caprice deliverance فلاح which carries the sense both of salvation and of blessedness is thus within reach to some degree here and now it is not a grace granted only after death such deliverance means tasting the joy that flows from certainty from intimate contact with the spirit of that certainty as for how to cultivate an openness to this spirit of certainty beyond obedience to the rules and regulations of the revealed law what is required is that union of pure intention and sincere devotion that the word اخلاص expresses without this sincerity this purity obedience to formal rules is nothing but hypocrisy نفاق and pretension رياء which the imam in turn calls the gravest of all sins شرك the setting up of partners to god know that the slightest pretension رياء is polytheism this saying can be read as a commentary on one of the qurans weightiest condemnations of hypocrisy the verses speak of those who deny the essence of faith while outwardly keeping to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 22, NULL, '"Hast thou seen the one who belieth religion? He is the one who repelleth the orphan and urgeth not the feeding of the poor. So woe be to those who pray, those who are heedless of their prayer, who want only to be seen, and withhold small kindnesses" (Al-Maun: 1-7).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'hast thou seen the one who belieth religion he is the one who repelleth the orphan and urgeth not the feeding of the poor so woe be to those who pray those who are heedless of their prayer who want only to be seen and withhold small kindnesses al maun 1 7', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 23, NULL, 'This short sura makes plain that formal acts of devotion have no value at all unless they are woven into a life of virtue and performed with the right intention — that is, with إِخْلَاص. It also helps explain why the Imam''s ethos is called here not merely religious but spiritual: it carries the ideals of religion to their deepest application. To be spiritual in this sense is precisely to be true to one''s intellect, true to the treasures buried deep within it, and not merely to the reasoning that works on its surface. Without this depth, religion is empty. "There is no religion for one who has no intellect," says the Imam. And likewise: "Action without knowledge is error." What counts is the intention behind the action, for "action, all action, is dust, except what is purified within it." This turning away from the action in itself, toward an inner state of being from which good actions must flow, clearly reflects the Quranic teaching:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'this short sura makes plain that formal acts of devotion have no value at all unless they are woven into a life of virtue and performed with the right intention that is with اخلاص it also helps explain why the imams ethos is called here not merely religious but spiritual it carries the ideals of religion to their deepest application to be spiritual in this sense is precisely to be true to ones intellect true to the treasures buried deep within it and not merely to the reasoning that works on its surface without this depth religion is empty there is no religion for one who has no intellect says the imam and likewise action without knowledge is error what counts is the intention behind the action for action all action is dust except what is purified within it this turning away from the action in itself toward an inner state of being from which good actions must flow clearly reflects the quranic teaching', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 24, NULL, 'Al-Hajj: 37لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَكِن يَنَالُهُ ٱلتَّقْوَىٰ مِنكُمْ ۚ كَذَلِكَ سَخَّرَهَا لَكُمْ لِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ ۗ وَبَشِّرِ ٱلْمُحْسِنِينَ"It is not their sacrificed flesh nor their blood that reacheth God, but it is piety from you that reacheth Him" (Al-Hajj: 37).', '', NULL, 'Al-Hajj: 37', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'al hajj 37لن ينال الله لحومها ولا دماوها ولكن يناله التقوي منكم كذلك سخرها لكم لتكبروا الله علي ما هداكم وبشر المحسنين it is not their sacrificed flesh nor their blood that reacheth god but it is piety from you that reacheth him al hajj 37', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 25, NULL, '"There is no religion for one who has no intellect." Perhaps no group shows the truth of this saying better than the Kharijites. Among those who rebelled against the Imam were many readers (قُرَّاء, sing. qari) of the Quran — men who enjoyed considerable religious prestige for their Quranic knowledge and their intense worship. Their piety, though, was more apparent than real; it was in fact a zeal born of bitterness, a caricature of true piety. When his supporters spoke of the long night vigils kept by members of this group, the Imam answered sharply: "Sleeping with certainty is better than praying with doubt." Certainty brings peace and joy. So for one immersed in what the Imam calls the spirit of certainty, sleep is a rest of the body that only deepens the happiness flowing from a good conscience and from spiritual certitude — a certitude that is itself a kind of unbroken wakefulness, an awakeness to higher realities. Sleep of the body, then, does not contradict wakefulness of the spirit. As the hadith of the Prophet has it: "My eyes sleep, but my heart sleeps not."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'there is no religion for one who has no intellect perhaps no group shows the truth of this saying better than the kharijites among those who rebelled against the imam were many readers قراء sing qari of the quran men who enjoyed considerable religious prestige for their quranic knowledge and their intense worship their piety though was more apparent than real it was in fact a zeal born of bitterness a caricature of true piety when his supporters spoke of the long night vigils kept by members of this group the imam answered sharply sleeping with certainty is better than praying with doubt certainty brings peace and joy so for one immersed in what the imam calls the spirit of certainty sleep is a rest of the body that only deepens the happiness flowing from a good conscience and from spiritual certitude a certitude that is itself a kind of unbroken wakefulness an awakeness to higher realities sleep of the body then does not contradict wakefulness of the spirit as the hadith of the prophet has it my eyes sleep but my heart sleeps not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 26, NULL, 'When it comes to formal worship, the true intellectual, the الْعَاقِل — whom the Imam defines as the one who puts each thing in its proper place (العاقل من وضع شئی حق محلہ) — is one who obeys the divine command to pray. Yet he does not pray by rote, supposing that the act alone is enough. He knows that such obedience is necessary but not sufficient for opening himself to grace. There must be awareness of what one is doing and why; and it is this awareness, together with virtue, inward beauty, that draws divine acceptance. "The most worthy knowledge for you," says the Imam, "is that by virtue of whose presence action is accepted by God."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'when it comes to formal worship the true intellectual the العاقل whom the imam defines as the one who puts each thing in its proper place العاقل من وضع شيي حق محله is one who obeys the divine command to pray yet he does not pray by rote supposing that the act alone is enough he knows that such obedience is necessary but not sufficient for opening himself to grace there must be awareness of what one is doing and why and it is this awareness together with virtue inward beauty that draws divine acceptance the most worthy knowledge for you says the imam is that by virtue of whose presence action is accepted by god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 27, NULL, '"They make easy what the extravagant find harsh; they befriend that by which the ignorant are estranged." This sentence bears, among other things, on how the remembrance of death — its certainty, and the renunciation of this world that certainty demands — works upon the souls of the true sages. To begin with, what the extravagant, the greedy, worldly sort find harsh is outward hardship, difficulty, and loss. The Quran views all such circumstances as the trials that must accompany life in this world:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'they make easy what the extravagant find harsh they befriend that by which the ignorant are estranged this sentence bears among other things on how the remembrance of death its certainty and the renunciation of this world that certainty demands works upon the souls of the true sages to begin with what the extravagant the greedy worldly sort find harsh is outward hardship difficulty and loss the quran views all such circumstances as the trials that must accompany life in this world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 28, NULL, '"And We shall try you with something of fear and hunger and loss of property and life and fruits; but give glad tidings to the patient, those who, when struck by affliction say: Verily, we belong to God and verily unto Him we are ever-returning. These are the ones upon whom there are blessings from their Lord, and mercy; and these are the ones who are rightly guided" (Al-Baqarah: 155-157).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'and we shall try you with something of fear and hunger and loss of property and life and fruits but give glad tidings to the patient those who when struck by affliction say verily we belong to god and verily unto him we are ever returning these are the ones upon whom there are blessings from their lord and mercy and these are the ones who are rightly guided al baqarah 155 157', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 29, NULL, 'The passage continues cleanly. Here is the articulated chapter prose.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'the passage continues cleanly here is the articulated chapter prose', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 30, NULL, 'The rightly-guided perceive the blessings poured out upon those who stay patient under affliction—a patience that grows from their knowledge of the truth: "By the Age, truly man is in a state of loss, except those who believe and do virtuous deeds and exhort one another to truth and exhort one another to patience" (Al-Asr: 1-3). These believers stand firm through trials, rooted in their awareness of where they came from and where they return, and in the knowledge that unto Him we are ever-returning. So they can make the trials and hardships of life easy to bear, while the extravagant meet those same trials only as harshness and bitterness. The ease folded into every difficulty stays hidden from the ignorant but is plain to the wise: "Verily, with hardship cometh ease; verily with hardship cometh ease" (Ash-Sharh: 5-6). The wise do more than await ease as the certain fruit of hardship; they taste that fruit already as the seed hidden inside hardship itself, for they befriend the very thing that the ignorant flee.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'the rightly guided perceive the blessings poured out upon those who stay patient under affliction a patience that grows from their knowledge of the truth by the age truly man is in a state of loss except those who believe and do virtuous deeds and exhort one another to truth and exhort one another to patience al asr 1 3 these believers stand firm through trials rooted in their awareness of where they came from and where they return and in the knowledge that unto him we are ever returning so they can make the trials and hardships of life easy to bear while the extravagant meet those same trials only as harshness and bitterness the ease folded into every difficulty stays hidden from the ignorant but is plain to the wise verily with hardship cometh ease verily with hardship cometh ease ash sharh 5 6 the wise do more than await ease as the certain fruit of hardship they taste that fruit already as the seed hidden inside hardship itself for they befriend the very thing that the ignorant flee', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 31, NULL, 'One layer of this meaning is lit by a saying of Ali: "Death is more intimate to me than the breast of the mother is to the suckling babe." In the verse cited above, the mention of trials and hardships follows a reminder that those slain in the path of God are not truly dead, "nay, they are alive but ye perceive not." This affirms the life hereafter, but it also points to the inner meaning of being slain for God: اَلْفَنَاءُ فِي اللَّهِ, extinction in God. The Imam''s intimacy with death can be understood in relation to this death while still alive, which he touches on in another saying: "I am the death of the dead." Because life in the world is itself a kind of death—a limitation, and so a lack—set against the boundless fullness of the divine realms, dying to this death amounts to true life:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'one layer of this meaning is lit by a saying of ali death is more intimate to me than the breast of the mother is to the suckling babe in the verse cited above the mention of trials and hardships follows a reminder that those slain in the path of god are not truly dead nay they are alive but ye perceive not this affirms the life hereafter but it also points to the inner meaning of being slain for god الفناء في الله extinction in god the imams intimacy with death can be understood in relation to this death while still alive which he touches on in another saying i am the death of the dead because life in the world is itself a kind of death a limitation and so a lack set against the boundless fullness of the divine realms dying to this death amounts to true life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 32, NULL, 'Al-''Ankabut: 64وَمَا هَذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَهْوٌۭ وَلَعِبٌۭ ۚ وَإِنَّ ٱلدَّارَ ٱلْآخِرَةَ لَهِىَ ٱلْحَيَوَانُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ"And the life of this world is nothing but sport and play," says the Quran, "and verily, the abode of the Hereafter, that is true life, did they but know" (Al-Ankabut: 64).', '', NULL, 'Al-''Ankabut: 64', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'al ankabut 64وما هذه الحيوه الدنيا الا لهو ولعب وان الدار الاخره لهي الحيوان لو كانوا يعلمون and the life of this world is nothing but sport and play says the quran and verily the abode of the hereafter that is true life did they but know al ankabut 64', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 33, NULL, 'What must be negated is not the physical world as such, but worldliness—the self-centered attachment to the world. One key principle of the Imam''s outlook, stressed again and again throughout the Nahj al-balagha, bears directly here: the principle of زُهْدٌ, which no single English word can render adequately. It gathers several meanings: asceticism, austerity, abstention, detachment, doing without, and making little of. The following passage from the Nahj conveys well the attitude of the zahid toward this world:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'what must be negated is not the physical world as such but worldliness the self centered attachment to the world one key principle of the imams outlook stressed again and again throughout the nahj al balagha bears directly here the principle of زهد which no single english word can render adequately it gathers several meanings asceticism austerity abstention detachment doing without and making little of the following passage from the nahj conveys well the attitude of the zahid toward this world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 34, NULL, 'The world is an abode for which annihilation is ordained, and for its people departure from it is decreed. It is sweet and green, and it hastens to one who seeks it, and confounds the heart that gazes upon it. So set out from it with the best of the provision available to you, and ask not from it above what suffices and seek not from it more than what can be attained.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'the world is an abode for which annihilation is ordained and for its people departure from it is decreed it is sweet and green and it hastens to one who seeks it and confounds the heart that gazes upon it so set out from it with the best of the provision available to you and ask not from it above what suffices and seek not from it more than what can be attained', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 35, NULL, 'What is this best of provision, this زَادٌ? In many places the Nahj describes it as تَقْوَى, another word that resists simple translation, its meaning spanning piety, fear of God, awe, and God-consciousness. "I exhort you, O slaves of God, to تَقْوَى, which is the provision," says the Imam. This provision for the next world is won only in the measure of one''s detachment from the perishable side of the life of this world, for "whoso desireth that which hasteneth away, in that We hasten for him what We will":', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'what is this best of provision this زاد in many places the nahj describes it as تقوي another word that resists simple translation its meaning spanning piety fear of god awe and god consciousness i exhort you o slaves of god to تقوي which is the provision says the imam this provision for the next world is won only in the measure of ones detachment from the perishable side of the life of this world for whoso desireth that which hasteneth away in that we hasten for him what we will', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 36, NULL, 'Al-Isra: 18مَّن كَانَ يُرِيدُ ٱلْعَاجِلَةَ عَجَّلْنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلْنَا لَهُۥ جَهَنَّمَ يَصْلَىٰهَا مَذْمُومًۭا مَّدْحُورًۭا"Whoever desires the fleeting life, We hasten for him therein what We will, for whom We intend; then We appoint for him Hell, wherein he burns, disgraced and rejected." (Al-Isra: 18)', '', NULL, 'Al-Isra: 18', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'al isra 18من كان يريد العاجله عجلنا له فيها ما نشاء لمن نريد ثم جعلنا له جهنم يصلاها مذموما مدحورا whoever desires the fleeting life we hasten for him therein what we will for whom we intend then we appoint for him hell wherein he burns disgraced and rejected al isra 18', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 37, NULL, 'The Imam describes the contemptible side of the world in vivid terms. "By God, this world of yours is more contemptible in my eyes than a chewed-up bone of a pig in the hand of a leper." "An image of the world is the snake, soft to touch, but virulent poison within." The world is "as worthless to me as that which drips from the nose of a goat." It is the grandeur and beauty of God that renders the world small and distasteful; only in the light of the Absolute do the world''s pleasures and attractions show themselves as fleeting and illusory: "The greatness of the Creator for you belittles creatures in your view." In the same spirit, the Imam speaks of a brother in God: "What made him great in my eyes was the smallness of the world in his eyes (وَكَانَ يُعَظِّمُهُ فِي عَيْنِي صِغَرُ الدُّنْيَا فِي عَيْنِهِ)."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'the imam describes the contemptible side of the world in vivid terms by god this world of yours is more contemptible in my eyes than a chewed up bone of a pig in the hand of a leper an image of the world is the snake soft to touch but virulent poison within the world is as worthless to me as that which drips from the nose of a goat it is the grandeur and beauty of god that renders the world small and distasteful only in the light of the absolute do the worlds pleasures and attractions show themselves as fleeting and illusory the greatness of the creator for you belittles creatures in your view in the same spirit the imam speaks of a brother in god what made him great in my eyes was the smallness of the world in his eyes وكان يعظمه في عيني صغر الدنيا في عينه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 38, NULL, 'This, in the Quranic usage of zahid, is the real meaning of زُهْدٌ. In the sura named after Joseph (يُوسُفُ), the brothers of Yusuf held him of little value in selling him for a small price, and in relation to him they are described as زَاهِدِينَ:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'this in the quranic usage of zahid is the real meaning of زهد in the sura named after joseph يوسف the brothers of yusuf held him of little value in selling him for a small price and in relation to him they are described as زاهدين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 39, NULL, 'Yusuf: 20وَشَرَوْهُ بِثَمَنٍۭ بَخْسٍۢ دَرَهِمَ مَعْدُودَةٍۢ وَكَانُوا۟ فِيهِ مِنَ ٱلزَّهِدِينَ"And they sold him for a paltry price, a few dirhams counted out, and they were of those who deemed him of little worth." (Yusuf: 20)', '', NULL, 'Yusuf: 20', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'yusuf 20وشروه بثمن بخس درهم معدوده وكانوا فيه من الزهدين and they sold him for a paltry price a few dirhams counted out and they were of those who deemed him of little worth yusuf 20', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 40, NULL, 'In the Imam''s outlook the world is likewise held of little value—not valueless outright, but rendered all but insignificant beside the Hereafter, beside eternity, beside ultimate reality. All created things shrink to tiny, fleeting shadows bound for annihilation: "Everything perishes except His Face":', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'in the imams outlook the world is likewise held of little value not valueless outright but rendered all but insignificant beside the hereafter beside eternity beside ultimate reality all created things shrink to tiny fleeting shadows bound for annihilation everything perishes except his face', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 41, NULL, 'Al-Qasas: 88وَلَا تَدْعُ مَعَ ٱللَّهِ إِلَهًا آخَرَ ۘ لَآ إِلَهَ إِلَّا هُوَ ۚ كُلُّ شَىْءٍ هَالِكٌ إِلَّا وَجْهَهُۥ ۚ لَهُ ٱلْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ"And do not invoke with God another deity. There is no deity except Him. Everything will perish except His Face. His is the judgment, and to Him you will be returned." (Al-Qasas: 88)', '', NULL, 'Al-Qasas: 88', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'al qasas 88ولا تدع مع الله الها اخر لا اله الا هو كل شيء هالك الا وجهه له الحكم واليه ترجعون and do not invoke with god another deity there is no deity except him everything will perish except his face his is the judgment and to him you will be returned al qasas 88', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 42, NULL, 'Yet the world is not stripped of all value; indeed, its significance lies precisely in what it cannot help but signify: "And there is nothing that does not hymn His glory with praise":', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'yet the world is not stripped of all value indeed its significance lies precisely in what it cannot help but signify and there is nothing that does not hymn his glory with praise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 43, NULL, 'Al-Isra: 44تُسَبِّحُ لَهُ ٱلسَّمَوَتُ ٱلسَّبْعُ وَٱلْأَرْضُ وَمَن فِيهِنَّ ۚ وَإِن مِّن شَىْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِۦ وَلَكِن لَّا تَفْقَهُونَ تَسْبِيحَهُمْ ۗ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًۭا"The seven heavens and the earth and whatever is in them exalt Him. And there is not a thing except that it exalts Him by His praise, but you do not understand their way of exalting. Indeed, He is ever Forbearing and Forgiving." (Al-Isra: 44)', '', NULL, 'Al-Isra: 44', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'al isra 44تسبح له السموت السبع والارض ومن فيهن وان من شيء الا يسبح بحمده ولكن لا تفقهون تسبيحهم انه كان حليما غفورا the seven heavens and the earth and whatever is in them exalt him and there is not a thing except that it exalts him by his praise but you do not understand their way of exalting indeed he is ever forbearing and forgiving al isra 44', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 44, NULL, 'Everything in the world, every creature in existence, proclaims the boundless creativity of the Creator. So that the imagination might grasp the mystery of this universal praise, the Quran says: "And the birds in flight, each one knoweth its prayer and glorification":', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'everything in the world every creature in existence proclaims the boundless creativity of the creator so that the imagination might grasp the mystery of this universal praise the quran says and the birds in flight each one knoweth its prayer and glorification', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 45, NULL, 'An-Nur: 41أَلَمْ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِى ٱلسَّمَوَتِ وَٱلْأَرْضِ وَٱلطَّيْرُ صَٓفَّتٍۢ ۖ كُلٌّۭ قَدْ عَلِمَ صَلَاتَهُۥ وَتَسْبِيحَهُۥ ۗ وَٱللَّهُ عَلِيمٌۢ بِمَا يَفْعَلُونَ"Do you not see that God is exalted by whoever is within the heavens and the earth and by the birds with wings spread in flight? Each one has known its prayer and its exalting, and God is Knowing of what they do." (An-Nur: 41)', '', NULL, 'An-Nur: 41', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'an nur 41الم تر ان الله يسبح له من في السموت والارض والطير صفت كل قد علم صلاته وتسبيحه والله عليم بما يفعلون do you not see that god is exalted by whoever is within the heavens and the earth and by the birds with wings spread in flight each one has known its prayer and its exalting and god is knowing of what they do an nur 41', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 46, NULL, 'There is thus no contradiction in the Imam''s despising the world and yet growing lyrical over the beauties of untouched nature, including that unsurpassable marvel, the peacock. This comes in a sermon that also describes birds in general, along with ants, serpents, and elephants. The sermon ends with a stirring description of Paradise, setting the marvels of this world beside the delights of the next; in the light of the latter, all earthly things fade into insignificance. For once the eye of the heart turns toward Paradise, "your soul would become averse to the marvels of this world, its passions, its pleasures and its embellished scenery."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'there is thus no contradiction in the imams despising the world and yet growing lyrical over the beauties of untouched nature including that unsurpassable marvel the peacock this comes in a sermon that also describes birds in general along with ants serpents and elephants the sermon ends with a stirring description of paradise setting the marvels of this world beside the delights of the next in the light of the latter all earthly things fade into insignificance for once the eye of the heart turns toward paradise your soul would become averse to the marvels of this world its passions its pleasures and its embellished scenery', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 47, NULL, 'It might seem contradictory to hold together such apparently opposed qualities as joy in certainty, discussed above, and the befriending of hardship. Yet the latter is in fact the fruit of the former. Every difficulty without exception is borne through the spiritual resources that faith makes available when it is joined to intellectual assimilation—or rather, in the measure that faith is intellectually assimilated and so becomes marifa (معرفۃ) or gnosis, holding a certainty so deep and so complete that "even if the veil be lifted" it cannot increase, according to the famous saying noted earlier. It is possible to believe, at one level of the mind, that there is no god but God. The Imam, however, draws attention to what this apparently simple belief should imply when it is sincere or pure: "I bear witness that there is no god but God alone Who has no partner, a testimony whose sincerity has been tested and whose essence has been assimilated with conviction (mutaqadan musaffaha)."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'it might seem contradictory to hold together such apparently opposed qualities as joy in certainty discussed above and the befriending of hardship yet the latter is in fact the fruit of the former every difficulty without exception is borne through the spiritual resources that faith makes available when it is joined to intellectual assimilation or rather in the measure that faith is intellectually assimilated and so becomes marifa معرفه or gnosis holding a certainty so deep and so complete that even if the veil be lifted it cannot increase according to the famous saying noted earlier it is possible to believe at one level of the mind that there is no god but god the imam however draws attention to what this apparently simple belief should imply when it is sincere or pure i bear witness that there is no god but god alone who has no partner a testimony whose sincerity has been tested and whose essence has been assimilated with conviction mutaqadan musaffaha', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 48, NULL, 'The word مُصَفَّى names the choicest and purest part of any substance, its very essence. The root massa means "to suck," the idea being that the liquid or juice of a substance or fruit holds its essence, the part drawn out from it. Here the Imam is stressing the spiritual substance of the testimony, as distinct from mere spoken affirmation or mental grasp of the words. He affirms a heartfelt bond with the reality to which the testimony bears witness; the words that define it are an echo of the reality they carry, and are not to be confused with that reality itself. He continues: "We cling to it always, for as long as we endure, storing it up as protection against the terrors that will befall us. For truly, it renders faith resolute, opens up spiritual virtue, pleases al-Rahman (the All-Compassionate), repels al-shaytan (the devil)."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'the word مصفي names the choicest and purest part of any substance its very essence the root massa means to suck the idea being that the liquid or juice of a substance or fruit holds its essence the part drawn out from it here the imam is stressing the spiritual substance of the testimony as distinct from mere spoken affirmation or mental grasp of the words he affirms a heartfelt bond with the reality to which the testimony bears witness the words that define it are an echo of the reality they carry and are not to be confused with that reality itself he continues we cling to it always for as long as we endure storing it up as protection against the terrors that will befall us for truly it renders faith resolute opens up spiritual virtue pleases al rahman the all compassionate repels al shaytan the devil', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 49, NULL, 'Returning to "befriending that by which the ignorant are estranged," this points not only to the trials of life—a source of strength for the wise and of repulsion for the ignorant—but also to the inescapability of death. For the wise, death means release, the meeting with God, blissful eternity—in short, a mode of تَوْحِيد, whereby the soul enjoys ever deeper degrees of integration within higher principles. For the ignorant, by contrast, death appears as a terrifying disintegration, the end of their world rather than the beginning of endless life. There is also the prefiguration of death in life already noted above: فَنَاء, "extinction," "effacement," the "perishing" of egoistic consciousness before the Absolute. The ignorant recoil in horror at the prospect of losing what they falsely take to be their life, not seeing that this sacrifice of egoistic and limited self-consciousness is the very ground on which infinite consciousness is glimpsed or tasted. The ocean of the Real can be tasted only by being drowned in it.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'returning to befriending that by which the ignorant are estranged this points not only to the trials of life a source of strength for the wise and of repulsion for the ignorant but also to the inescapability of death for the wise death means release the meeting with god blissful eternity in short a mode of توحيد whereby the soul enjoys ever deeper degrees of integration within higher principles for the ignorant by contrast death appears as a terrifying disintegration the end of their world rather than the beginning of endless life there is also the prefiguration of death in life already noted above فناء extinction effacement the perishing of egoistic consciousness before the absolute the ignorant recoil in horror at the prospect of losing what they falsely take to be their life not seeing that this sacrifice of egoistic and limited self consciousness is the very ground on which infinite consciousness is glimpsed or tasted the ocean of the real can be tasted only by being drowned in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 50, NULL, 'The means to this ultimate attainment is likewise embraced by the wise and feared by the ignorant: the act of pure prayer, total concentration on the Real. Such concentration shuts out every worldly or egotistic preoccupation; the sheer intensity of focus upon the Absolute burns away thoughts of the relative, and for those who ignorantly identify with relativities, inward and outward alike, this amounts to a kind of death. For the wise, by contrast, this concentration on the Absolute, the unsullied remembrance of God, is a joyous contemplation of reality before which the ego is displaced and all illusions dissolve. This leads straight to the next sentence of the passage: "With their bodies, they keep company with the world, while their spirits are tied to the transcendent realm."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'the means to this ultimate attainment is likewise embraced by the wise and feared by the ignorant the act of pure prayer total concentration on the real such concentration shuts out every worldly or egotistic preoccupation the sheer intensity of focus upon the absolute burns away thoughts of the relative and for those who ignorantly identify with relativities inward and outward alike this amounts to a kind of death for the wise by contrast this concentration on the absolute the unsullied remembrance of god is a joyous contemplation of reality before which the ego is displaced and all illusions dissolve this leads straight to the next sentence of the passage with their bodies they keep company with the world while their spirits are tied to the transcendent realm', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 51, NULL, 'This sentence grows more concrete when read alongside another well-known expression of the Imam. He describes himself as belonging to a group whose spiritual degree is such that "their hearts are in the Gardens of Paradise while their bodies are at work." To be tied or attached to that realm—which takes in the paradisal abodes and reaches up to the divine Presence itself—means that they already dwell within that transcendent realm more fully than within this earthly one. This helps explain the saying quoted earlier: God keeps man perpetually in that which his soul desires. Those whose hearts or spirits are in the transcendent domain are those whose consciousness is shaped, substantially and not merely conceptually, by transcendent realities. Those whose consciousness, by contrast, is shaped by worldly concerns are in this world in the sense of being enclosed by its formal limits; their orientation and imagination are trapped within a worldly frame. Their actions bear the mark of this worldliness, whereas the actions of the wise are the fruits of their immersion in a higher reality. Their outward actions in the world belie their inward transcendence of all action; they act, yet are not bound by the fruits of their action. As noted earlier, they know that action, all action, is dust, except what is purified, done sincerely, within it.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'this sentence grows more concrete when read alongside another well known expression of the imam he describes himself as belonging to a group whose spiritual degree is such that their hearts are in the gardens of paradise while their bodies are at work to be tied or attached to that realm which takes in the paradisal abodes and reaches up to the divine presence itself means that they already dwell within that transcendent realm more fully than within this earthly one this helps explain the saying quoted earlier god keeps man perpetually in that which his soul desires those whose hearts or spirits are in the transcendent domain are those whose consciousness is shaped substantially and not merely conceptually by transcendent realities those whose consciousness by contrast is shaped by worldly concerns are in this world in the sense of being enclosed by its formal limits their orientation and imagination are trapped within a worldly frame their actions bear the mark of this worldliness whereas the actions of the wise are the fruits of their immersion in a higher reality their outward actions in the world belie their inward transcendence of all action they act yet are not bound by the fruits of their action as noted earlier they know that action all action is dust except what is purified done sincerely within it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 52, NULL, 'At this point the notion of the Hereafter deserves consideration within the Imam''s ethical framework. The Hereafter is invoked again and again in the Imam''s discourses. Is this simply a matter of holding out a heavenly reward and threatening a hellish punishment to enjoin the good and forbid the evil? Even if the answer is partly yes, there is a deeper dimension to this apparently straightforward use of divine warnings and promises as levers for moral action.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'at this point the notion of the hereafter deserves consideration within the imams ethical framework the hereafter is invoked again and again in the imams discourses is this simply a matter of holding out a heavenly reward and threatening a hellish punishment to enjoin the good and forbid the evil even if the answer is partly yes there is a deeper dimension to this apparently straightforward use of divine warnings and promises as levers for moral action', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 53, NULL, 'The ethical orientation here is defined not merely by belief in God but by the spiritual reality of the Hereafter as well, both objectively, in itself, and subjectively, insofar as the individual assimilates it. It thereby becomes a living dimension, a process, an orientation, a reflux, within the believer''s own soul, rather than a bare belief or hope. Anticipation of the Hereafter marks every believer in principle; its realization marks the soul of the wali Allah, the friend of God, the saint and the sage. As noted earlier, the Imam speaks in a famous sentence that bears witness to his total immersion in the reality of which he is certain: "Were the veil to be removed, I would not increase in certitude (law kushifal-ghita, ma azdadtu yaqinan)." The anticipation—or better, the foretaste—of the Hereafter deepens rather than fades in proportion to one''s virtue, piety, and sanctity; it does not dwindle into a mere heuristic device whose value is spent once its moral impact is achieved. The following moving passage from the Nahj deserves reflection in this light. What appears here is the description of a blissful vision of the reality of Paradise, not merely a rhetorical flourish in the service of moral exhortation:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'the ethical orientation here is defined not merely by belief in god but by the spiritual reality of the hereafter as well both objectively in itself and subjectively insofar as the individual assimilates it it thereby becomes a living dimension a process an orientation a reflux within the believers own soul rather than a bare belief or hope anticipation of the hereafter marks every believer in principle its realization marks the soul of the wali allah the friend of god the saint and the sage as noted earlier the imam speaks in a famous sentence that bears witness to his total immersion in the reality of which he is certain were the veil to be removed i would not increase in certitude law kushifal ghita ma azdadtu yaqinan the anticipation or better the foretaste of the hereafter deepens rather than fades in proportion to ones virtue piety and sanctity it does not dwindle into a mere heuristic device whose value is spent once its moral impact is achieved the following moving passage from the nahj deserves reflection in this light what appears here is the description of a blissful vision of the reality of paradise not merely a rhetorical flourish in the service of moral exhortation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 54, NULL, 'If you were to cast the eye of your heart toward what is described for you of the Garden, your soul would become averse to the marvels of this world, its passions, its pleasures and its embellished scenery. And your soul would be rapt in contemplation of the swaying trees whose roots lie hidden in dunes of musk on the banks of the rivers of the Garden, and the clusters of dazzling pearls hanging down from the branches of its trees …', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'if you were to cast the eye of your heart toward what is described for you of the garden your soul would become averse to the marvels of this world its passions its pleasures and its embellished scenery and your soul would be rapt in contemplation of the swaying trees whose roots lie hidden in dunes of musk on the banks of the rivers of the garden and the clusters of dazzling pearls hanging down from the branches of its trees', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 55, NULL, 'The highest degree of spirituality does, of course, transcend the desire for Paradise and the fear of Hell, along with the moral conduct proportioned to them. But this means that when such higher degrees of realization are attained, the soul''s state can properly be called paradisal—that is, already so utterly content in the beatific presence of God that it desires nothing more. This state of soul is called in the Quran اَلنَّفْسُ الْمُطْمَئِنَّةُ, "the soul at peace in absolute certainty":', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'the highest degree of spirituality does of course transcend the desire for paradise and the fear of hell along with the moral conduct proportioned to them but this means that when such higher degrees of realization are attained the souls state can properly be called paradisal that is already so utterly content in the beatific presence of god that it desires nothing more this state of soul is called in the quran النفس المطمينه the soul at peace in absolute certainty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 56, NULL, 'Al-Fajr: 27يَٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ"O reassured soul." (Al-Fajr: 27)', '', NULL, 'Al-Fajr: 27', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'al fajr 27يايتها النفس المطمينه o reassured soul al fajr 27', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 57, NULL, 'The Imam frequently echoes, implicitly if not explicitly, the Quranic principle that "the Hereafter is better and more lasting":', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'the imam frequently echoes implicitly if not explicitly the quranic principle that the hereafter is better and more lasting', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 58, NULL, 'Al-A''la: 17وَٱلْآخِرَةُ خَيْرٌۭ وَأَبْقَىٰٓ"But the Hereafter is better and more enduring." (Al-Ala: 17)', '', NULL, 'Al-A''la: 17', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'al ala 17والاخره خير وابقي but the hereafter is better and more enduring al ala 17', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 59, NULL, 'The Hereafter is not only the time at which divine warnings and promises reach their fulfillment; it is also the space in which all positive qualities—human, angelic, divine—are manifested in their fullness, those qualities that appear on earth as reflections of higher realities and that encompass and subtly penetrate the whole sphere of earthly existence. The Quran, perhaps more than any other scripture, furnishes the imagination with numerous and complex descriptions of paradisal bliss. One of the key functions of these descriptions is alluded to in the Quran itself: "Assuredly, We purify them with a pure quality, remembrance of the Abode of the Hereafter":', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'the hereafter is not only the time at which divine warnings and promises reach their fulfillment it is also the space in which all positive qualities human angelic divine are manifested in their fullness those qualities that appear on earth as reflections of higher realities and that encompass and subtly penetrate the whole sphere of earthly existence the quran perhaps more than any other scripture furnishes the imagination with numerous and complex descriptions of paradisal bliss one of the key functions of these descriptions is alluded to in the quran itself assuredly we purify them with a pure quality remembrance of the abode of the hereafter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 60, NULL, 'Sad: 46إِنَّآ أَخْلَصْنَهُم بِخَالِصَةٍۢ ذِكْرَى ٱلدَّارِ"Indeed, We chose them for an exclusive quality: remembrance of the Home of the Hereafter." (Sad: 46)', '', NULL, 'Sad: 46', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'sad 46انا اخلصنهم بخالصه ذكري الدار indeed we chose them for an exclusive quality remembrance of the home of the hereafter sad 46', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 61, NULL, 'The mere thought of Paradise is itself a purification of mind and heart, a way of guarding the soul against the ever-present temptation to seek its ultimate happiness and well-being in this world alone. Conversely, one''s well-being here below, where action is concerned, lies in the doing of good deeds, and such well-being is proportioned to the depth of one''s belief that "Whatever good ye send before for your souls, ye will find it with God, better and more tremendous as reward":', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'the mere thought of paradise is itself a purification of mind and heart a way of guarding the soul against the ever present temptation to seek its ultimate happiness and well being in this world alone conversely ones well being here below where action is concerned lies in the doing of good deeds and such well being is proportioned to the depth of ones belief that whatever good ye send before for your souls ye will find it with god better and more tremendous as reward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'verse', 'the fruits of certainty', '5. The Fruits of Certainty', 62, NULL, 'Al-Muzzammil: 20إِنَّ رَبَّكَ يَعْلَمُ أَنَّكَ تَقُومُ أَدْنَىٰ مِن ثُلُثَىِ ٱلَّيْلِ وَنِصْفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٌۭ مِّنَ ٱلَّذِينَ مَعَكَ ۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيْلَ وَٱلنَّهَارَ ۚ عَلِمَ أَن لَّن تُحْصُوهُ فَتَابَ عَلَيْكُمْ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنَ ٱلْقُرْآنِ ۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرْضَىٰ ۙ وَآخَرُونَ يَضْرِبُونَ فِى ٱلْأَرْضِ يَبْتَغُونَ مِن فَضْلِ ٱللَّهِ ۙ وَآخَرُونَ يُقَتِلُونَ فِى سَبِيلِ ٱللَّهِ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنْهُ ۚ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَآتُوا۟ ٱلزَّكَوٰةَ وَأَقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًۭا ۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍۢ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيْرًۭا وَأَعْظَمَ أَجْرًۭا ۚ وَٱسْتَغْفِرُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۢ"And whatever good you put forward for yourselves, you will find it with God. It is better and greater in reward." (Al-Muzzammil: 20)', '', 'إِنَّ رَبَّكَ يَعْلَمُ أَنَّكَ تَقُومُ أَدْنَىٰ مِن ثُلُثَىِ ٱلَّيْلِ وَنِصْفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٌۭ مِّنَ ٱلَّذِينَ مَعَكَ ۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيْلَ وَٱلنَّهَارَ ۚ عَلِمَ أَن لَّن تُحْصُوهُ فَتَابَ عَلَيْكُمْ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنَ ٱلْقُرْآنِ ۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرْضَىٰ ۙ وَآخَرُونَ يَضْرِبُونَ فِى ٱلْأَرْضِ يَبْتَغُونَ مِن فَضْلِ ٱللَّهِ ۙ وَآخَرُونَ يُقَتِلُونَ فِى سَبِيلِ ٱللَّهِ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنْهُ ۚ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَآتُوا۟ ٱلزَّكَوٰةَ وَأَقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًۭا ۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍۢ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيْرًۭا وَأَعْظَمَ أَجْرًۭا ۚ وَٱسْتَغْفِرُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۢ', 'Al-Muzzammil: 20', 73, 20, 'spiritual ethos 5 the fruits of certainty', 'al muzzammil 20ان ربك يعلم انك تقوم ادني من ثلثي اليل ونصفه وثلثه وطايفه من الذين معك والله يقدر اليل والنهار علم ان لن تحصوه فتاب عليكم فاقرءوا ما تيسر من القران علم ان سيكون منكم مرضي واخرون يضربون في الارض يبتغون من فضل الله واخرون يقتلون في سبيل الله فاقرءوا ما تيسر منه واقيموا الصلوه واتوا الزكوه واقرضوا الله قرضا حسنا وما تقدموا لانفسكم من خير تجدوه عند الله هو خيرا واعظم اجرا واستغفروا الله ان الله غفور رحيم and whatever good you put forward for yourselves you will find it with god it is better and greater in reward al muzzammil 20', 'ان ربك يعلم انك تقوم ادني من ثلثي اليل ونصفه وثلثه وطايفه من الذين معك والله يقدر اليل والنهار علم ان لن تحصوه فتاب عليكم فاقرءوا ما تيسر من القران علم ان سيكون منكم مرضي واخرون يضربون في الارض يبتغون من فضل الله واخرون يقتلون في سبيل الله فاقرءوا ما تيسر منه واقيموا الصلوه واتوا الزكوه واقرضوا الله قرضا حسنا وما تقدموا لانفسكم من خير تجدوه عند الله هو خيرا واعظم اجرا واستغفروا الله ان الله غفور رحيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 63, NULL, 'In other words, a sincere orientation toward the Hereafter is transformed into a perception of heavenly beatitude already here below, in the form of those very acts and attitudes which, being good, share the same nature as the felicity to which they lead. In this light, morally good actions and noble intentions are grasped by one who sees beyond the veil of this world as vivid prefigurations of heavenly realities, not merely as ethical prerequisites for salvation. Goodness, in other words, does not simply lead to a heavenly reward; it already participates in that reward: "Is the reward of goodness (احسان) aught but goodness?":', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'in other words a sincere orientation toward the hereafter is transformed into a perception of heavenly beatitude already here below in the form of those very acts and attitudes which being good share the same nature as the felicity to which they lead in this light morally good actions and noble intentions are grasped by one who sees beyond the veil of this world as vivid prefigurations of heavenly realities not merely as ethical prerequisites for salvation goodness in other words does not simply lead to a heavenly reward it already participates in that reward is the reward of goodness احسان aught but goodness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 64, NULL, 'Ar-Rahman: 60هَلْ جَزَآءُ ٱلْإِحْسَنِ إِلَّا ٱلْإِحْسَنُ"Is the reward for good anything but good?" (Ar-Rahman: 60)', '', NULL, 'Ar-Rahman: 60', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'ar rahman 60هل جزاء الاحسن الا الاحسن is the reward for good anything but good ar rahman 60', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 65, NULL, 'The Imam''s saying, "The fruit of good action is like its root," can be read as an echo of the idea that the end is already present in the means that lead to it. Fitting to close is the following verse of the Quran, which also serves as an introduction to what follows:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'the imams saying the fruit of good action is like its root can be read as an echo of the idea that the end is already present in the means that lead to it fitting to close is the following verse of the quran which also serves as an introduction to what follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 66, NULL, 'Al-Baqarah: 25وَبَشِّرِ ٱلَّذِينَ آمَنُوا۟ وَعَمِلُوا۟ ٱلصَّلِحَتِ أَنَّ لَهُمْ جَنَّتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَرُ ۖ كُلَّمَا رُزِقُوا۟ مِنْهَا مِن ثَمَرَةٍۢ رِّزْقًۭا ۙ قَالُوا۟ هَذَا ٱلَّذِى رُزِقْنَا مِن قَبْلُ ۖ وَأُتُوا۟ بِهِۦ مُتَشَبِهًۭا ۖ وَلَهُمْ فِيهَآ أَزْوَجٌۭ مُّطَهَّرَةٌۭ ۖ وَهُمْ فِيهَا خَلِدُونَ"And give good tidings to those who believe and perform virtuous deeds, that for them are Gardens underneath which rivers flow. Every time they are given to eat from the fruits thereof, they say: This is what we were given to eat before. And they were given the like thereof." (Al-Baqarah: 25)', '', NULL, 'Al-Baqarah: 25', NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'al baqarah 25وبشر الذين امنوا وعملوا الصلحت ان لهم جنت تجري من تحتها الانهر كلما رزقوا منها من ثمره رزقا قالوا هذا الذي رزقنا من قبل واتوا به متشبها ولهم فيها ازوج مطهره وهم فيها خلدون and give good tidings to those who believe and perform virtuous deeds that for them are gardens underneath which rivers flow every time they are given to eat from the fruits thereof they say this is what we were given to eat before and they were given the like thereof al baqarah 25', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 67, NULL, 'The fruits of the paradisal gardens are thus tasted already here below, in the form of all goodness, beauty, and truth, and the diverse modes of happiness that flow from them. All such experiences are so many foretastes of the ultimate beatitude in Paradise. On the ethical plane, the doing of good deeds, and, even more directly, the realization of intrinsic virtue, احسان, is therefore not simply a prerequisite for posthumous salvation, but is already a kind of deliverance, here and now: a deliverance from the imprisonment of sin on the outward plane, and from the bondage of egocentricity on the inward plane. This theme of salvation here and now, grounded in unshakeable certitude, is fundamental to the spirit of the Imam''s teachings and will be explored further throughout the rest of this book. In the following chapter, the cardinal virtue of justice will be considered within Ali s perspective, rooted as it is in احسان, a virtue defined by the Prophet as worshipping God as if one saw Him, and concretely affirmed by the Imam as real and not merely hypothetical, for God is indeed seen by the pure of heart through the verities of faith.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'the fruits of the paradisal gardens are thus tasted already here below in the form of all goodness beauty and truth and the diverse modes of happiness that flow from them all such experiences are so many foretastes of the ultimate beatitude in paradise on the ethical plane the doing of good deeds and even more directly the realization of intrinsic virtue احسان is therefore not simply a prerequisite for posthumous salvation but is already a kind of deliverance here and now a deliverance from the imprisonment of sin on the outward plane and from the bondage of egocentricity on the inward plane this theme of salvation here and now grounded in unshakeable certitude is fundamental to the spirit of the imams teachings and will be explored further throughout the rest of this book in the following chapter the cardinal virtue of justice will be considered within ali s perspective rooted as it is in احسان a virtue defined by the prophet as worshipping god as if one saw him and concretely affirmed by the imam as real and not merely hypothetical for god is indeed seen by the pure of heart through the verities of faith', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the fruits of certainty', '5. The Fruits of Certainty', 68, NULL, 'Editorial note (tradition-grounded). A related teaching preserved in this tradition names ihsan as the highest form of a single root, ح-س-ن, in which goodness and beauty are one word — so that to do well is to make something beautiful. What that tradition adds is a definition this chapter''s own argument reaches toward: ihsan is to worship and act as though seeing God, giving every deed its full inward beauty. This joins the two threads the chapter holds side by side — the intimate certainty that touches its divine object, and the virtue that "makes the soul beautiful." The one who acts as though seeing God is at once the person of certainty and the person of ihsan; the beauty of outward and inward that Ali praises is simply what such worship looks like from without and within.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 5 the fruits of certainty', 'editorial note tradition grounded a related teaching preserved in this tradition names ihsan as the highest form of a single root ح س ن in which goodness and beauty are one word so that to do well is to make something beautiful what that tradition adds is a definition this chapters own argument reaches toward ihsan is to worship and act as though seeing god giving every deed its full inward beauty this joins the two threads the chapter holds side by side the intimate certainty that touches its divine object and the virtue that makes the soul beautiful the one who acts as though seeing god is at once the person of certainty and the person of ihsan the beauty of outward and inward that ali praises is simply what such worship looks like from without and within', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 0, NULL, 'A Sacred Conception of Justice', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'a sacred conception of justice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 1, NULL, 'The reflections on justice that follow are not an exercise in theoretical speculation about what justice means in Ali (ع)s letter to Malik al-Ashtar, written fourteen centuries ago. Nor are they the kind of definition found in a dictionary, where justice amounts to little more than fairness, equality, and fair play. The aim is, first of all, to bring the discussion of justice into alignment with the concept and the reality of the sacred — the reality of the sacred One, القدس. On one side, the principle of justice carries a sacred and spiritual dimension that contemporary discussion so often overlooks. On the other, a careful appreciation of what the sacred means opens a deeper understanding of the roots of justice within the divine nature itself, and a fuller awareness of why justice is necessary, both in the world and in the soul.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'the reflections on justice that follow are not an exercise in theoretical speculation about what justice means in ali ع s letter to malik al ashtar written fourteen centuries ago nor are they the kind of definition found in a dictionary where justice amounts to little more than fairness equality and fair play the aim is first of all to bring the discussion of justice into alignment with the concept and the reality of the sacred the reality of the sacred one القدس on one side the principle of justice carries a sacred and spiritual dimension that contemporary discussion so often overlooks on the other a careful appreciation of what the sacred means opens a deeper understanding of the roots of justice within the divine nature itself and a fuller awareness of why justice is necessary both in the world and in the soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 2, NULL, 'The central argument is this. In Ali s worldview, the ethical orientation toward justice is immeasurably deepened once it is consciously tied to the spiritual precepts of the Islamic faith. The spirit that underlies moral rules and ethical values is strengthened by a commitment to transcendent principles — even though, or precisely because, those principles rise above the realm of action in which the rules themselves operate. The شریعۃ may be pictured as having a body and a spirit, much as a person does. Its body is made up of actions: prayer, fasting, the paying of زکوۃ. But the spirit that animates those actions rests on the nature of the divine, which is justice. To adhere to the شریعۃ is therefore to train in becoming like the divine through the principles of justice, and so action must be joined by contemplation of the divine. Here contemplation and action complete each other rather than conflict, for their union lies at the very heart of the Islamic message of تَوْحِيد, توحید — an integrating oneness that makes theory and practice one, so that a person becomes a true موحد. This unity shines with dazzling clarity in the life of the Imam, as it does in the life of the Prophet. The harmony between the two principles — contemplation and action, being and doing, theory and practice, ideal and reality — runs throughout the remarkable document that is the subject of these reflections.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'the central argument is this in ali s worldview the ethical orientation toward justice is immeasurably deepened once it is consciously tied to the spiritual precepts of the islamic faith the spirit that underlies moral rules and ethical values is strengthened by a commitment to transcendent principles even though or precisely because those principles rise above the realm of action in which the rules themselves operate the شريعه may be pictured as having a body and a spirit much as a person does its body is made up of actions prayer fasting the paying of زكوه but the spirit that animates those actions rests on the nature of the divine which is justice to adhere to the شريعه is therefore to train in becoming like the divine through the principles of justice and so action must be joined by contemplation of the divine here contemplation and action complete each other rather than conflict for their union lies at the very heart of the islamic message of توحيد توحيد an integrating oneness that makes theory and practice one so that a person becomes a true موحد this unity shines with dazzling clarity in the life of the imam as it does in the life of the prophet the harmony between the two principles contemplation and action being and doing theory and practice ideal and reality runs throughout the remarkable document that is the subject of these reflections', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 3, NULL, 'These reflections stand against the background of contemporary ethical discourse and may be seen as a modest contribution, from an Islamic perspective, to the scholarly debates on virtue and ethics. In particular, they should be understood in light of one of the most serious and far-reaching critiques of modern and postmodern conceptions of virtue in general, and of justice in particular — that of Alasdair MacIntyre. Put simply, his critique holds that for several centuries ethical discourse in Western society has drifted far from its moorings in absolute values. He argues, compellingly, that debates about morality and ethics, together with their philosophical foundations, are no longer grounded in any conception of the good life or of the Good as such. As a result, MacIntyre holds, various shades of relativism, nihilism, utilitarianism, and opportunism have emerged in practice as the shifting bases on which ethical values are formed, if they are formed at all. Relativism holds that knowledge, truth, and morality are not absolute but relative, existing only in relation to a culture, a society, or a historical moment. Nihilism rejects all religious and moral principles and takes life to be essentially meaningless. Utilitarianism counts an action right only if it is useful or benefits a majority, so that good and bad rest on nothing more than a calculation of greater benefit or loss. And opportunism seizes whatever advantage circumstances offer, heedless of any plan or principle — the way of the manipulator, who flatters, performs, or deceives to get what he wants.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'these reflections stand against the background of contemporary ethical discourse and may be seen as a modest contribution from an islamic perspective to the scholarly debates on virtue and ethics in particular they should be understood in light of one of the most serious and far reaching critiques of modern and postmodern conceptions of virtue in general and of justice in particular that of alasdair macintyre put simply his critique holds that for several centuries ethical discourse in western society has drifted far from its moorings in absolute values he argues compellingly that debates about morality and ethics together with their philosophical foundations are no longer grounded in any conception of the good life or of the good as such as a result macintyre holds various shades of relativism nihilism utilitarianism and opportunism have emerged in practice as the shifting bases on which ethical values are formed if they are formed at all relativism holds that knowledge truth and morality are not absolute but relative existing only in relation to a culture a society or a historical moment nihilism rejects all religious and moral principles and takes life to be essentially meaningless utilitarianism counts an action right only if it is useful or benefits a majority so that good and bad rest on nothing more than a calculation of greater benefit or loss and opportunism seizes whatever advantage circumstances offer heedless of any plan or principle the way of the manipulator who flatters performs or deceives to get what he wants', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 4, NULL, 'Whatever value these human-made theories occasionally yield, none of it is rooted in the divine; and so, even where they happen to mirror the values of faith, they remain baseless, without spirit — dead corpses. Virtue practiced on an ad hoc basis is not virtue properly speaking. It is a series of pragmatic adjustments to changing circumstances, made in the absence of any genuine principle of virtue. Truthfulness illustrates this. The underlying reason for always speaking the truth is twofold: that truth is the very nature of our Creator — الحق, the absolute truth — and that our purpose in this world is to take on the virtues of our Creator. If one resolves to speak the truth without grasping that reason, truthfulness will in the end become situational and self-serving, something to be compromised whenever circumstances seem to warrant it, spoken when it profits and abandoned when it costs. But once truth is seen as the nature of the divine, it becomes everlasting and eternal, indifferent to consequence, because one speaks it in emulation of the immortal nature of God. The virtue itself becomes immortal, and the need to practice it on an ad hoc basis falls away. We are looking, writes MacIntyre, for a conception of the good which will enable us to order other goods, for a conception of the good which will enable us to extend our understanding of the purpose and content of the virtues, for a conception of the good which will enable us to understand the place of integrity and consistency in life ...', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'whatever value these human made theories occasionally yield none of it is rooted in the divine and so even where they happen to mirror the values of faith they remain baseless without spirit dead corpses virtue practiced on an ad hoc basis is not virtue properly speaking it is a series of pragmatic adjustments to changing circumstances made in the absence of any genuine principle of virtue truthfulness illustrates this the underlying reason for always speaking the truth is twofold that truth is the very nature of our creator الحق the absolute truth and that our purpose in this world is to take on the virtues of our creator if one resolves to speak the truth without grasping that reason truthfulness will in the end become situational and self serving something to be compromised whenever circumstances seem to warrant it spoken when it profits and abandoned when it costs but once truth is seen as the nature of the divine it becomes everlasting and eternal indifferent to consequence because one speaks it in emulation of the immortal nature of god the virtue itself becomes immortal and the need to practice it on an ad hoc basis falls away we are looking writes macintyre for a conception of the good which will enable us to order other goods for a conception of the good which will enable us to extend our understanding of the purpose and content of the virtues for a conception of the good which will enable us to understand the place of integrity and consistency in life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 5, NULL, 'It is at this level, in particular, that the insights of Ali and other sages of the Islamic tradition are especially relevant. MacIntyre''s proposed solution to the crisis — a reformulation of an Aristotelian conception of ethics grounded in a Thomistic worldview — shares a great deal with the Islamic tradition of ethical discourse (أَخْلَاق). But one can argue further: a careful engagement with the Imam''s legacy yields far more than a merely theoretical approach to the question of justice, and this in two respects. First, the Imam was himself a paragon of justice, and thus a living embodiment of this and other fundamental virtues. In his life one sees a perfect, indeed unflinching, adherence to this cardinal virtue — a life governed not by his نفس but entirely by the divine nature of God. The remarkable deeds recorded of him, at which one marvels, are the fruit of his irresistible attraction toward the nature of الحق, for his whole existence was oriented toward God. His attention rested never on the action itself but on the source of the principles that generated it; fixing upon the beauty of the divine nature and striving to take it on, he found good actions arising from him naturally and inevitably. Although this work does not enter into many details of his life and its lessons, certain incidents and events that help illustrate the point will be recalled. Secondly — and more important for the present purpose — the discourses, letters, and sayings attributed to Ali offer a rich source of reflection on the dynamic spirituality that lies at the root of a life of virtue. In them one is granted a glimpse of a way of life wholly governed by the sacred, one in which the desire for the good life emerges as the fruit of an irresistible attraction toward the Good as such, which is identical to the absolutely Real, اَلْحَقّ.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'it is at this level in particular that the insights of ali and other sages of the islamic tradition are especially relevant macintyres proposed solution to the crisis a reformulation of an aristotelian conception of ethics grounded in a thomistic worldview shares a great deal with the islamic tradition of ethical discourse اخلاق but one can argue further a careful engagement with the imams legacy yields far more than a merely theoretical approach to the question of justice and this in two respects first the imam was himself a paragon of justice and thus a living embodiment of this and other fundamental virtues in his life one sees a perfect indeed unflinching adherence to this cardinal virtue a life governed not by his نفس but entirely by the divine nature of god the remarkable deeds recorded of him at which one marvels are the fruit of his irresistible attraction toward the nature of الحق for his whole existence was oriented toward god his attention rested never on the action itself but on the source of the principles that generated it fixing upon the beauty of the divine nature and striving to take it on he found good actions arising from him naturally and inevitably although this work does not enter into many details of his life and its lessons certain incidents and events that help illustrate the point will be recalled secondly and more important for the present purpose the discourses letters and sayings attributed to ali offer a rich source of reflection on the dynamic spirituality that lies at the root of a life of virtue in them one is granted a glimpse of a way of life wholly governed by the sacred one in which the desire for the good life emerges as the fruit of an irresistible attraction toward the good as such which is identical to the absolutely real الحق', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 6, NULL, 'In other words, one is ethically inspired by the Good in direct proportion to one''s existential orientation toward the Real. If moral rules rest on ethical perspectives, and those perspectives rest in turn on a conception of the good life, then that conception of the Good is itself drawn from the moral agent''s fundamental understanding of what life means. Amyn B. Sajoo, in a recent thoughtful work on Muslim ethics, draws a careful distinction between ethics and morals. Ethical discourse, he argues, is concerned more with conceptions of the good, while morals pertain more specifically to rules about right and wrong. Ethics deals with the soul and the spirit of the good, the باطن, and out of ethics morals are born. Certainly, he continues, the concepts overlap substantially in theory and practice; but it is well to bear in mind the more encompassing sense of reality that typifies ethics. To set ethics within the wider framework of spiritual virtue — in the sense of احسان, احسان — widens the compass of both ethics and morality still further, lending each a dimension of existential depth and grounding both in a more organic and all-encompassing whole. For the spiritual life has three components: Islam, which supplies the outer aspects of morality; ایمان, which is the framework of ethics; and the union of the two, serving as their underlying principle, which issues in احسان — the good life, the beautiful life. Abstract questions of right and wrong thus come to rest on the more definitive principle that emerges in answer to the question: what is reality?', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'in other words one is ethically inspired by the good in direct proportion to ones existential orientation toward the real if moral rules rest on ethical perspectives and those perspectives rest in turn on a conception of the good life then that conception of the good is itself drawn from the moral agents fundamental understanding of what life means amyn b sajoo in a recent thoughtful work on muslim ethics draws a careful distinction between ethics and morals ethical discourse he argues is concerned more with conceptions of the good while morals pertain more specifically to rules about right and wrong ethics deals with the soul and the spirit of the good the باطن and out of ethics morals are born certainly he continues the concepts overlap substantially in theory and practice but it is well to bear in mind the more encompassing sense of reality that typifies ethics to set ethics within the wider framework of spiritual virtue in the sense of احسان احسان widens the compass of both ethics and morality still further lending each a dimension of existential depth and grounding both in a more organic and all encompassing whole for the spiritual life has three components islam which supplies the outer aspects of morality ايمان which is the framework of ethics and the union of the two serving as their underlying principle which issues in احسان the good life the beautiful life abstract questions of right and wrong thus come to rest on the more definitive principle that emerges in answer to the question what is reality', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 7, NULL, 'The previous chapter''s discussion of the deeper meanings of divine unity bears on this. In the Imam''s spiritual vision of تَوْحِيد, one perceives, according to one''s capacity, an ultimate reality that not only has no second but also has no moral opposite. People tend to picture the world as good against evil, God against شیطان, forever thinking in opposites; yet the Imam teaches that God has no opposite at all. Satan does not stand against God, for nothing has the power to stand against God. He stands against God''s creation, and his whole effort is to drive people away from their inherent divine nature by making its opposite beautiful — beautifying arrogance where God''s nature is modest, lewdness where it is decent, boastfulness where it is humble. For the goodness proper to God is not the moral opposite of evil. It occupies an altogether different plane, that of اَلْحَقّ, الحق, the absolutely Real, whose only opposite is unreality, or nothingness. Goodness is at one with the pure positivity of the Absolute, while evil arises solely from a negative capacity to negate the Real, the Good. The essence of all goodness and beauty, in other words, is identified with the Creator, whereas evil is a mode of the created — the corrupted state of a creation that has deviated from the divine nature. This is strongly implied in the Quranic verse of سُورَۃُ الْفَلَقِ, which calls the believer to seek refuge in God from the evil of that which He created (Al-Falaq: 2):', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'the previous chapters discussion of the deeper meanings of divine unity bears on this in the imams spiritual vision of توحيد one perceives according to ones capacity an ultimate reality that not only has no second but also has no moral opposite people tend to picture the world as good against evil god against شيطان forever thinking in opposites yet the imam teaches that god has no opposite at all satan does not stand against god for nothing has the power to stand against god he stands against gods creation and his whole effort is to drive people away from their inherent divine nature by making its opposite beautiful beautifying arrogance where gods nature is modest lewdness where it is decent boastfulness where it is humble for the goodness proper to god is not the moral opposite of evil it occupies an altogether different plane that of الحق الحق the absolutely real whose only opposite is unreality or nothingness goodness is at one with the pure positivity of the absolute while evil arises solely from a negative capacity to negate the real the good the essence of all goodness and beauty in other words is identified with the creator whereas evil is a mode of the created the corrupted state of a creation that has deviated from the divine nature this is strongly implied in the quranic verse of سوره الفلق which calls the believer to seek refuge in god from the evil of that which he created al falaq 2', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 8, NULL, 'Al-Falaq: 1-2قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ ۱ مِنْ شَرِّ مَا خَلَقَ ۲Say: I seek refuge with the Lord of the daybreak, from the evil of what He has created.', '', NULL, 'Al-Falaq: 1-2', NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'al falaq 1 2قل اعوذ برب الفلق ۱ من شر ما خلق ۲say i seek refuge with the lord of the daybreak from the evil of what he has created', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 9, NULL, 'This verse is often mistranslated as from the evil which He created, which is wrong both theologically and lexically. The expression min sharri ma khalaqa, مِن شَرِّ مَا خَلَقَ, plainly refers to the evil that derives from creation, not to creation as such. In theological terms, God creates morally free agents, and it is they who are the authors of evil in creation; when creation, by its own free will, chooses to negate the divine nature of its Creator, evil is born. God may be said to create all actions only in the metaphysical sense that He is the source of all being, and so of all modes within being, of which action is one; He cannot be said to have created evil as such, but only the conditions within which evil arises. Evil is thus the negation of the Good, which is at one with the Real, and as such it has no ultimate ontological principle. It is only a temporary state of deviation from that pure and divine nature — an illusion witnessed by the eye of the heart.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'this verse is often mistranslated as from the evil which he created which is wrong both theologically and lexically the expression min sharri ma khalaqa من شر ما خلق plainly refers to the evil that derives from creation not to creation as such in theological terms god creates morally free agents and it is they who are the authors of evil in creation when creation by its own free will chooses to negate the divine nature of its creator evil is born god may be said to create all actions only in the metaphysical sense that he is the source of all being and so of all modes within being of which action is one he cannot be said to have created evil as such but only the conditions within which evil arises evil is thus the negation of the good which is at one with the real and as such it has no ultimate ontological principle it is only a temporary state of deviation from that pure and divine nature an illusion witnessed by the eye of the heart', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 10, NULL, 'The verse, then, may be understood as a call to seek refuge in the Real from the unreal, since between goodness and evil there is no common measure in being. Goodness can be opposed only by the appearance of evil — an appearance the eye of the heart grasps as illusion, that eye which truly sees'' God through the verities of faith. This vision of the merely relative reality of evil, far from breeding indifference toward it, greatly strengthens the spiritual resolve to overcome it, for the moral effort to be good intensifies in proportion to one''s conviction of accountability to that goodness. That conviction is in turn carried inward, from the mind to the heart, by the certainty that goodness is more real than evil — a certainty itself nourished by the spiritual vision of the good as the Real. To perceive the radical incommensurability between good and evil, therefore, leads not to indifference in the face of evil but to a more existentially compelling orientation toward the good. In the Imam''s perspective, the notions of right and rightful due gathered within the meaning of haqq, حق, are charged with an aura of absoluteness. To understand what is right leads to the commitment to fulfill one''s obligations; what is rightfully due is the restoration of reality through the removal of illusory evil; and both are equally infused with reality, which is justice. The moral notions of rectitude and propriety are expressions of a principle that transcends morality, a principle belonging to ultimate reality. One''s commitment to fulfilling one''s obligations — to giving every being its rightful due — becomes charged, likewise, with a powerful sense of reality, and the resolve to be just is made more absolute by the very absoluteness proper to the Real.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'the verse then may be understood as a call to seek refuge in the real from the unreal since between goodness and evil there is no common measure in being goodness can be opposed only by the appearance of evil an appearance the eye of the heart grasps as illusion that eye which truly sees god through the verities of faith this vision of the merely relative reality of evil far from breeding indifference toward it greatly strengthens the spiritual resolve to overcome it for the moral effort to be good intensifies in proportion to ones conviction of accountability to that goodness that conviction is in turn carried inward from the mind to the heart by the certainty that goodness is more real than evil a certainty itself nourished by the spiritual vision of the good as the real to perceive the radical incommensurability between good and evil therefore leads not to indifference in the face of evil but to a more existentially compelling orientation toward the good in the imams perspective the notions of right and rightful due gathered within the meaning of haqq حق are charged with an aura of absoluteness to understand what is right leads to the commitment to fulfill ones obligations what is rightfully due is the restoration of reality through the removal of illusory evil and both are equally infused with reality which is justice the moral notions of rectitude and propriety are expressions of a principle that transcends morality a principle belonging to ultimate reality ones commitment to fulfilling ones obligations to giving every being its rightful due becomes charged likewise with a powerful sense of reality and the resolve to be just is made more absolute by the very absoluteness proper to the real', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 11, NULL, 'This duty to give each and every being its due connects to the most explicit definition of justice the Imam gives: وَضَعَ الشَّئُی حَقَّ مَحَلِّہِ, Justice puts everything in its right place. One is just in so far as one gives everything its proper due, rendering the haqq owed to each person — indeed to each and every thing in existence; and the capacity to be just in this demanding, universal sense grows in proportion to one''s attunement to اَلْحَقّ, the Real. As the previous chapter makes clear, this spiritual conception of virtue not only takes in one''s duty to all but engages all that one is. One must be good before one can do good, and the only way to be is to be at one with the Real — that which alone truly is''.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'this duty to give each and every being its due connects to the most explicit definition of justice the imam gives وضع الشيي حق محله justice puts everything in its right place one is just in so far as one gives everything its proper due rendering the haqq owed to each person indeed to each and every thing in existence and the capacity to be just in this demanding universal sense grows in proportion to ones attunement to الحق the real as the previous chapter makes clear this spiritual conception of virtue not only takes in ones duty to all but engages all that one is one must be good before one can do good and the only way to be is to be at one with the real that which alone truly is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 12, NULL, 'The Imam''s remark on justice calls to mind the more famous definition of Plato: ...we have laid down, as a universal principle, that everyone ought to perform the one function in the community for which his nature best suited him... that principle, or some form of it, is justice. There are indeed many remarkable parallels between Plato''s Republic and the Imam''s letter to Malik al-Ashtar. Some of the more obvious correspondences deserve attention, along with the way the Imam''s explicit spirituality illuminates what stays implicit in Plato''s philosophy: namely, how one may actually attain the vision of the Real, which Plato calls gazing upon the Good. It is this contemplation of the Good as such that serves as the source of one''s capacity to act ethically at every level, for it lets one take the Good as a pattern for the right ordering of the state and of the individual.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'the imams remark on justice calls to mind the more famous definition of plato we have laid down as a universal principle that everyone ought to perform the one function in the community for which his nature best suited him that principle or some form of it is justice there are indeed many remarkable parallels between platos republic and the imams letter to malik al ashtar some of the more obvious correspondences deserve attention along with the way the imams explicit spirituality illuminates what stays implicit in platos philosophy namely how one may actually attain the vision of the real which plato calls gazing upon the good it is this contemplation of the good as such that serves as the source of ones capacity to act ethically at every level for it lets one take the good as a pattern for the right ordering of the state and of the individual', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 13, NULL, 'Platonic and Neoplatonic ideas of justice have left a well-documented mark on the way ethics came to be discussed in Islam. In that discussion, justice is not one virtue standing beside others; it is the perfection, the sum, of all the rest — above all of the three chief Platonic virtues: temperance, courage, and wisdom. These belong, in turn, to the appetitive, the spirited, and the rational parts of the soul. When every part of the soul is filled out by its proper virtue and stands in its right place, the soul may be called "just."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'platonic and neoplatonic ideas of justice have left a well documented mark on the way ethics came to be discussed in islam in that discussion justice is not one virtue standing beside others it is the perfection the sum of all the rest above all of the three chief platonic virtues temperance courage and wisdom these belong in turn to the appetitive the spirited and the rational parts of the soul when every part of the soul is filled out by its proper virtue and stands in its right place the soul may be called just', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 14, NULL, 'What has not received enough attention is how closely Plato''s chief means of reaching the vision of the Good — anamnesis — corresponds, at the spiritual level, to the central place of dhikr in Islam. Both words can be rendered in English as "remembrance." And how is this justice achieved? What releases its power is precisely this remembrance: the recollection of ultimate reality and of unchanging principles as they apply at their several levels. It is not a matter of learning something new, but of calling back to mind principles already present in the very substance of the intellect — principles by which all things can be understood, and which are rooted, finally, in the Sovereign Good itself. Such remembrance is the ground on which ethical thought rests, both as knowledge and as reasoning. That its importance has been largely overlooked is a symptom of the modern habit of cutting ethics off from spirituality, treating each as though it were sealed away from the other. Ethics is still taken seriously, as a branch of philosophy and a discipline in its own right; spirituality, by contrast, is too often waved aside as beside the point in serious scholarship and consigned to the realm of the imaginary, the vague, and the mythological. This pushing of spirituality to the margins of supposedly serious discourse is closely bound up with the shrunken view of knowledge that has increasingly marked Western thought since the Renaissance — a narrowing that goes hand in hand with the steady draining away of the sacred dimension of life.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'what has not received enough attention is how closely platos chief means of reaching the vision of the good anamnesis corresponds at the spiritual level to the central place of dhikr in islam both words can be rendered in english as remembrance and how is this justice achieved what releases its power is precisely this remembrance the recollection of ultimate reality and of unchanging principles as they apply at their several levels it is not a matter of learning something new but of calling back to mind principles already present in the very substance of the intellect principles by which all things can be understood and which are rooted finally in the sovereign good itself such remembrance is the ground on which ethical thought rests both as knowledge and as reasoning that its importance has been largely overlooked is a symptom of the modern habit of cutting ethics off from spirituality treating each as though it were sealed away from the other ethics is still taken seriously as a branch of philosophy and a discipline in its own right spirituality by contrast is too often waved aside as beside the point in serious scholarship and consigned to the realm of the imaginary the vague and the mythological this pushing of spirituality to the margins of supposedly serious discourse is closely bound up with the shrunken view of knowledge that has increasingly marked western thought since the renaissance a narrowing that goes hand in hand with the steady draining away of the sacred dimension of life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 15, NULL, 'In the Islamic tradition, ethics and spirituality are closely bound together. This shows nowhere more clearly than in the Sufi tradition, which is now often, and rightly, called the ihsani tradition. The word احسان is taken here in the sense the Prophet gave it in a saying of central importance about the three foundations of the Islamic way. That saying is known as "the hadith of Gabriel," because the man who put the questions — though the Companions present did not know it — was the angel Gabriel (جبرئیل) in human form. He came up to the Prophet as he sat among his Companions and said:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'in the islamic tradition ethics and spirituality are closely bound together this shows nowhere more clearly than in the sufi tradition which is now often and rightly called the ihsani tradition the word احسان is taken here in the sense the prophet gave it in a saying of central importance about the three foundations of the islamic way that saying is known as the hadith of gabriel because the man who put the questions though the companions present did not know it was the angel gabriel جبرييل in human form he came up to the prophet as he sat among his companions and said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 16, NULL, 'O Muhammad, tell me about submission (الْإِسْلَام), يَا Muhammad، أَخْبِرْنِي عَنِ الْإِسْلَامِ.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'o muhammad tell me about submission الاسلام يا muhammad اخبرني عن الاسلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 17, NULL, 'The Prophet replied: الإِسْلاَمُ أَنْ تَشْهَدَ أَنْ لاَ إِلهَ إِلاَ اللهُ وَأَنَّ Muhammadاً رَسُولُ اللهِ، وَتُقِيمَ الصَّلاَةَ، وَتُؤْتِيَ al-zakat، وَتَصُومَ رَمَضَانَ، وَتَحُجَّ الْبَيْتَ إِنِ اسْتَطَعْتَ إِلَيْهِ سَبِيلاً, الْإِسْلَام is to testify that there is no god but God and Muhammad is the messenger of God, to perform the prayers, to pay the poor-due (الزَّكَاةَ), to fast in Ramadan, and to make the pilgrimage to the House if you are able to do so.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'the prophet replied الاسلام ان تشهد ان لا اله الا الله وان muhammadا رسول الله وتقيم الصلاه وتوتي al zakat وتصوم رمضان وتحج البيت ان استطعت اليه سبيلا الاسلام is to testify that there is no god but god and muhammad is the messenger of god to perform the prayers to pay the poor due الزكاه to fast in ramadan and to make the pilgrimage to the house if you are able to do so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 18, NULL, 'You have spoken truly (صَدَقْتَ), Gabriel said. The Companions, who saw only a man and did not know he was an angel, were astonished that he should question the Prophet and then declare that he had spoken truly.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'you have spoken truly صدقت gabriel said the companions who saw only a man and did not know he was an angel were astonished that he should question the prophet and then declare that he had spoken truly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 19, NULL, 'Then tell me about faith (الإِيْمَانِ), he said, فَأَخْبِرْنِي عَنِ الإِيْمَانِ.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'then tell me about faith الايمان he said فاخبرني عن الايمان', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 20, NULL, 'The Prophet said: أَنْ تُؤْمِنَ بِاللهِ، وَمَلاَئِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ, It is to believe in God, His angels, His books, His messengers, and the Last Day, and to believe in divine destiny, both the good and the evil thereof.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'the prophet said ان تومن بالله وملايكته وكتبه ورسله واليوم الاخر وتومن بالقدر خيره وشره it is to believe in god his angels his books his messengers and the last day and to believe in divine destiny both the good and the evil thereof', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 21, NULL, 'You have spoken truly (صَدَقْتَ), he said. Then tell me about virtue (الإِحْسَانِ), he said, فَأَخْبِرْنِي عَنِ الإِحْسَانِ.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'you have spoken truly صدقت he said then tell me about virtue الاحسان he said فاخبرني عن الاحسان', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 22, NULL, 'He said: أَنْ تَعْبُدَ اللهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ, It is to worship God as though you see Him, and if you see Him not, yet truly He sees you.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'he said ان تعبد الله كانك تراه فان لم تكن تراه فانه يراك it is to worship god as though you see him and if you see him not yet truly he sees you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 23, NULL, 'The word احسان can also be translated literally as "doing what is beautiful," since its root (حَسَنَ) is bound up first of all with beauty, حَسَنَ. In Islamic ethical discourse, virtue and vice are often called حَسَنَ and qubh (قُبْح) — beauty and ugliness. In the end it is the vision of divine beauty that awakens virtue, which is beauty of soul, just as turning away from the divine qualities is what leaves the soul ugly (قُبْح). It is no surprise, then, that — broadly speaking — while the jurists, the فُقَهَاءُ, have been the specialists in outward action, and the theologians the specialists in formal belief, it fell to the mystics to be the guardians of spiritual virtue, of "making beautiful." And it is no accident that the great majority of artists in the Islamic world — calligraphers, painters, poets, musicians, and the rest — have been practicing Sufis.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'the word احسان can also be translated literally as doing what is beautiful since its root حسن is bound up first of all with beauty حسن in islamic ethical discourse virtue and vice are often called حسن and qubh قبح beauty and ugliness in the end it is the vision of divine beauty that awakens virtue which is beauty of soul just as turning away from the divine qualities is what leaves the soul ugly قبح it is no surprise then that broadly speaking while the jurists the فقهاء have been the specialists in outward action and the theologians the specialists in formal belief it fell to the mystics to be the guardians of spiritual virtue of making beautiful and it is no accident that the great majority of artists in the islamic world calligraphers painters poets musicians and the rest have been practicing sufis', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 24, NULL, 'The Prophet''s definition of احسان as "worshipping God as if one could see Him" makes plain the crucial bond between worship and virtue — between spirituality and ethics, between devotion to the Creator and goodness toward His creatures. One cannot be had without the other. This bond lies at the very heart of the spiritual tradition in Islam. And it is the denial and betrayal of that tradition by some modern Muslims that, more than any other single cause, lies behind the atrocities now being committed by Muslims in the name of Islam.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'the prophets definition of احسان as worshipping god as if one could see him makes plain the crucial bond between worship and virtue between spirituality and ethics between devotion to the creator and goodness toward his creatures one cannot be had without the other this bond lies at the very heart of the spiritual tradition in islam and it is the denial and betrayal of that tradition by some modern muslims that more than any other single cause lies behind the atrocities now being committed by muslims in the name of islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 25, NULL, 'Both the theory and the practice of ethics have always been part of the very fabric of Sufism. Even some who wrote in more philosophical and less openly spiritual terms — al-Farabi among them — were known to be practicing Sufis as well. The figure in whom spirituality and ethics meet most powerfully is, of course, al-Ghazali, whose great Revival of the Sciences of Religion stands as a monument to what Islam''s deepest spirit does to the ethical temper of the believing soul. He has rightly been called the greatest thinker on ethics in Islam; and since his thought is shaped through and through by Sufism, this by itself testifies to how closely Sufism and ethics are joined. It would be no exaggeration to say that most treatises written by Sufis are in fact treatises on "ethics" — provided ethics is understood not only as أَخْلَاق in the narrow sense, but also as the fruit of احسان, of spiritual virtue. The various spiritual stations (مَقَامَات) the Sufis describe often bear the names of particular virtues: patience (صَبْرٌ), gratitude (شُكْرٌ), contentment (رِضَاءٌ), generosity (كَرَم), and so on.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'both the theory and the practice of ethics have always been part of the very fabric of sufism even some who wrote in more philosophical and less openly spiritual terms al farabi among them were known to be practicing sufis as well the figure in whom spirituality and ethics meet most powerfully is of course al ghazali whose great revival of the sciences of religion stands as a monument to what islams deepest spirit does to the ethical temper of the believing soul he has rightly been called the greatest thinker on ethics in islam and since his thought is shaped through and through by sufism this by itself testifies to how closely sufism and ethics are joined it would be no exaggeration to say that most treatises written by sufis are in fact treatises on ethics provided ethics is understood not only as اخلاق in the narrow sense but also as the fruit of احسان of spiritual virtue the various spiritual stations مقامات the sufis describe often bear the names of particular virtues patience صبر gratitude شكر contentment رضاء generosity كرم and so on', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 26, NULL, 'The thread running through all these stations is a transforming awareness of God — the principle of being and acting "as if you could see God," of carrying and composing oneself in the constant awareness of standing in the divine presence, for even if one cannot see Him, "He sees you." The call of احسان thus lies at the very root of a life of virtue in the spiritual world of Islam. In his sermons in the نَھْجُ الْبَلَاغَۃِ, Ali turns his hearers again and again to the "vision" of God, in whatever measure, as the true ground of a virtuous life, and warns again and again against its opposite — the all-absorbing vision of oneself — as the source of every vice. On the one hand the Imam says, "Know that your every action is dependent upon your prayer," that is, upon one''s way of "gazing upon the Good," to put it in Platonic terms. On the other, he warns against vanity, conceit, and the lavish praise of oneself by others, for these are Satan''s (شَیْطَان) surest openings for effacing the virtue, the احسان, of the virtuous (المُحسنین). Set against each other here are two visions. The true, objective vision of اَلْحَقّ, the Real, is reached by effacing oneself in prayer, for in the prostration (سَجْدَۃ) of prayer one effaces one''s own ego, one''s nafs (نَفْس). Opposed to it stands the distorted, self-centered vision of the ego, swollen by pride — which is exactly what Iblis (اِبْلِیس) desires. The first leads to justice, putting all things in their proper place, and, most fundamentally, the ego itself; the second leads to every injustice that flows from self-aggrandizement, fanaticism and bigotry among them. For Satan, the very embodiment of pride and disobedience, is described as "the leader of the fanatics and the forerunner of the proud" (اِمَامُ الْمُتَعَصِّبِینَ وَ سَلَفُ الْمُسْتَکْبِرِینَ, imam al-mutaassibin wa salaf al-mustakbirin). Bigotry is intolerance toward those who hold different opinions; and fanatical bigotry is an especially fierce form of injustice, for it carries that poisonous prejudice which bends the objective demands of justice to the supposed privileges of one''s own self — whether that self is defined as the individual, the family, the clan, the tribe, the nation, or the religion.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'the thread running through all these stations is a transforming awareness of god the principle of being and acting as if you could see god of carrying and composing oneself in the constant awareness of standing in the divine presence for even if one cannot see him he sees you the call of احسان thus lies at the very root of a life of virtue in the spiritual world of islam in his sermons in the نهج البلاغه ali turns his hearers again and again to the vision of god in whatever measure as the true ground of a virtuous life and warns again and again against its opposite the all absorbing vision of oneself as the source of every vice on the one hand the imam says know that your every action is dependent upon your prayer that is upon ones way of gazing upon the good to put it in platonic terms on the other he warns against vanity conceit and the lavish praise of oneself by others for these are satans شيطان surest openings for effacing the virtue the احسان of the virtuous المحسنين set against each other here are two visions the true objective vision of الحق the real is reached by effacing oneself in prayer for in the prostration سجده of prayer one effaces ones own ego ones nafs نفس opposed to it stands the distorted self centered vision of the ego swollen by pride which is exactly what iblis ابليس desires the first leads to justice putting all things in their proper place and most fundamentally the ego itself the second leads to every injustice that flows from self aggrandizement fanaticism and bigotry among them for satan the very embodiment of pride and disobedience is described as the leader of the fanatics and the forerunner of the proud امام المتعصبين و سلف المستكبرين imam al mutaassibin wa salaf al mustakbirin bigotry is intolerance toward those who hold different opinions and fanatical bigotry is an especially fierce form of injustice for it carries that poisonous prejudice which bends the objective demands of justice to the supposed privileges of ones own self whether that self is defined as the individual the family the clan the tribe the nation or the religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 27, NULL, 'The Imam''s letter appointing Malik al-Ashtar as his governor of Egypt appears as letter 52 in most editions of the نَھْجُ الْبَلَاغَۃِ. Across the centuries it has served as a source of inspiration, read as an ideal constitution for Islamic government. In its fairly detailed account of the duties and rights of the ruler, of the various officers of the state, and of the main classes of society, it fills out the more general framework of principles set down in the famous "Constitution of Medina" that the Prophet dictated. Yet the counsel in the letter goes far beyond the bounds usually set by political or legal texts on government. Though it is addressed in the first place to the ruler or governor, much of its counsel in fact concerns ethical principles that hold everywhere, and so it speaks as much to the governed as to those who govern. The letter is as much a statement of ethics as of politics — not a worked-out "system" or theory of ethics, to be sure, but a moving expression of the spiritual ethos the Imam embodied and radiated. That ethos flows straight from the sources of the Islamic revelation, and so it lays bare the roots of virtue and ethics within a world governed by the all-embracing principle of revelation. The document can therefore be read as a commentary on that revelation as well — one that, in turn, draws its readers to look more deeply into the meanings held within the revealed texts. Malik al-Ashtar was a long-standing and devoted follower of the Imam, spoken of as one of his "right-hand" men. Muawiya, the Imam''s chief opponent in the civil war that dominated his caliphate, was among those who used the phrase — notably on hearing that his plot to have Malik poisoned had succeeded before Malik could take up his post as governor of Egypt. Tabari reports Muawiya as saying: "Ali ibn Abi Talib had two right hands. One of them was cut off at Siffin, and the other today." The Imam, for his part, met the news of Malik''s assassination with these words: "Malik, and what was Malik! By God, were he a mountain, he would be the solitary one soaring above all others, and were he a rock, he would have been impenetrably solid. No horse could ascend such a mountain, no bird could fly up to it."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'the imams letter appointing malik al ashtar as his governor of egypt appears as letter 52 in most editions of the نهج البلاغه across the centuries it has served as a source of inspiration read as an ideal constitution for islamic government in its fairly detailed account of the duties and rights of the ruler of the various officers of the state and of the main classes of society it fills out the more general framework of principles set down in the famous constitution of medina that the prophet dictated yet the counsel in the letter goes far beyond the bounds usually set by political or legal texts on government though it is addressed in the first place to the ruler or governor much of its counsel in fact concerns ethical principles that hold everywhere and so it speaks as much to the governed as to those who govern the letter is as much a statement of ethics as of politics not a worked out system or theory of ethics to be sure but a moving expression of the spiritual ethos the imam embodied and radiated that ethos flows straight from the sources of the islamic revelation and so it lays bare the roots of virtue and ethics within a world governed by the all embracing principle of revelation the document can therefore be read as a commentary on that revelation as well one that in turn draws its readers to look more deeply into the meanings held within the revealed texts malik al ashtar was a long standing and devoted follower of the imam spoken of as one of his right hand men muawiya the imams chief opponent in the civil war that dominated his caliphate was among those who used the phrase notably on hearing that his plot to have malik poisoned had succeeded before malik could take up his post as governor of egypt tabari reports muawiya as saying ali ibn abi talib had two right hands one of them was cut off at siffin and the other today the imam for his part met the news of maliks assassination with these words malik and what was malik by god were he a mountain he would be the solitary one soaring above all others and were he a rock he would have been impenetrably solid no horse could ascend such a mountain no bird could fly up to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 28, NULL, 'The Imam''s definition of justice stands at the center of what follows: "Justice puts everything in its right place." In everyday speech, justice means little more than fairness, equality, and fair play — a workable account, but a merely formal one. The idea at work here is of an altogether different order. It joins justice to the sacred, to القدس, the All-Holy, and finds the very roots of justice within the divine nature itself. What ties this conception of justice to the sacred is the demand that one first put one''s relationship with God in its right place; everything else follows from that spiritual demand. The same order of priority is set out plainly in an important line of the Imam''s letter to Malik: "Be just with God and be just with people [giving them what is their due] from yourself."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'the imams definition of justice stands at the center of what follows justice puts everything in its right place in everyday speech justice means little more than fairness equality and fair play a workable account but a merely formal one the idea at work here is of an altogether different order it joins justice to the sacred to القدس the all holy and finds the very roots of justice within the divine nature itself what ties this conception of justice to the sacred is the demand that one first put ones relationship with god in its right place everything else follows from that spiritual demand the same order of priority is set out plainly in an important line of the imams letter to malik be just with god and be just with people giving them what is their due from yourself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 29, NULL, 'Being just with God means, among other things, conforming as far as one can to His own nature — which is not merely the source of justice but is justice. The weight falls on that word is. Justice is not one attribute among His many, ranged beside His mercy, His wrath, and His love; it is the very essence of His nature, and all His other qualities flow from it. His mercy is an expression of His justice, and so are His anger, His love, His creating, and His destroying. "I bear witness," says the Imam in one of his sermons, "that He is Justice (عَدْل) and He acts justly."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'being just with god means among other things conforming as far as one can to his own nature which is not merely the source of justice but is justice the weight falls on that word is justice is not one attribute among his many ranged beside his mercy his wrath and his love it is the very essence of his nature and all his other qualities flow from it his mercy is an expression of his justice and so are his anger his love his creating and his destroying i bear witness says the imam in one of his sermons that he is justice عدل and he acts justly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 30, NULL, 'It might be objected that there is a deep gulf between justice as a divine reality and justice as a human act. In God, justice means that everything is in its right place; in man, justice means the effort to put everything in its right place — an unchanging metaphysical quality on the divine side, a living act of will on the human side. To this the reply is that man''s moral effort to act justly, in a world where things are not in their right place, springs from an inborn spiritual leaning toward justice. Just action thus expresses the principle of justice, which, in man as in God, is that unchanging principle by which everything stands in its right place. As divine action in creation, judgment, and elsewhere expresses absolute justice, so in man just action expresses not only a moral, willed, and intellectual effort to bring justice about, but also a spiritual kinship with the ultimate nature of reality — with things as they truly are in God, and therefore as they ought to be here on earth.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'it might be objected that there is a deep gulf between justice as a divine reality and justice as a human act in god justice means that everything is in its right place in man justice means the effort to put everything in its right place an unchanging metaphysical quality on the divine side a living act of will on the human side to this the reply is that mans moral effort to act justly in a world where things are not in their right place springs from an inborn spiritual leaning toward justice just action thus expresses the principle of justice which in man as in god is that unchanging principle by which everything stands in its right place as divine action in creation judgment and elsewhere expresses absolute justice so in man just action expresses not only a moral willed and intellectual effort to bring justice about but also a spiritual kinship with the ultimate nature of reality with things as they truly are in god and therefore as they ought to be here on earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 31, NULL, 'Applied to state and society, one of the plainest consequences of this conception of justice is that rulers must be pious and upright. As the Imam says in another sermon: "The most momentous of the reciprocal rights that God has made obligatory is the right of the ruler over the subjects, and the right of the subjects over the ruler, a reciprocal obligation which God has ordained for them." He then makes a point wholly indispensable to any account of good governance in Islam: "The subjects will not be righteous except through the righteousness of the rulers, and the rulers will not be righteous except through the uprightness of the subjects. So if the subjects render to the ruler his rightful due and he renders them theirs, then will right be honored among them, the ways of religion will be upheld, and the banners of justice will be erected." This insistence on the ruler''s piety is, as one would expect, central to the Imam''s message to his governor; but it involves far more than a simple call to keep the formal rules of Islamic law.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'applied to state and society one of the plainest consequences of this conception of justice is that rulers must be pious and upright as the imam says in another sermon the most momentous of the reciprocal rights that god has made obligatory is the right of the ruler over the subjects and the right of the subjects over the ruler a reciprocal obligation which god has ordained for them he then makes a point wholly indispensable to any account of good governance in islam the subjects will not be righteous except through the righteousness of the rulers and the rulers will not be righteous except through the uprightness of the subjects so if the subjects render to the ruler his rightful due and he renders them theirs then will right be honored among them the ways of religion will be upheld and the banners of justice will be erected this insistence on the rulers piety is as one would expect central to the imams message to his governor but it involves far more than a simple call to keep the formal rules of islamic law', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 32, NULL, 'The whole of the Imam''s life can be seen as a quest to conform as perfectly as he could to the divine nature, and to this quality of justice above all. The principle has far too many sides — social, economic, political, legal — as they appear in his life and teachings to be treated in a short space. One defining moment in his caliphate shows the rigor with which he held to justice whatever it cost. The revolt of Muawiya, and the civil war into which the young Muslim empire was thereby plunged, can be said to have begun not at Siffin but in Medina. When Ali took up the caliphate, his cousin Ibn al-Abbas advised him to confirm all of Uthman''s governors in their posts for the time being, and then, once the new order was secure, to remove them. The Imam''s reply to this proposal was reported thus: "I do not doubt that this would be best for the sake of reconciliation in this world. But there is my obligation to the Truth (الَّذِي يَلْزَمُنِي مِنَ الْحَقِّ) and my knowledge of Uthman''s governors, so, by God, I shall never appoint one of them."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'the whole of the imams life can be seen as a quest to conform as perfectly as he could to the divine nature and to this quality of justice above all the principle has far too many sides social economic political legal as they appear in his life and teachings to be treated in a short space one defining moment in his caliphate shows the rigor with which he held to justice whatever it cost the revolt of muawiya and the civil war into which the young muslim empire was thereby plunged can be said to have begun not at siffin but in medina when ali took up the caliphate his cousin ibn al abbas advised him to confirm all of uthmans governors in their posts for the time being and then once the new order was secure to remove them the imams reply to this proposal was reported thus i do not doubt that this would be best for the sake of reconciliation in this world but there is my obligation to the truth الذي يلزمني من الحق and my knowledge of uthmans governors so by god i shall never appoint one of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 33, NULL, 'And so the die was cast: the Imam dismissed Muawiya along with all of his predecessor''s governors. The Imam saw clearly that Ibn al-Abbas'' proposal had every chance of working; he knew that all Muawiya wanted was worldly power, and that Muawiya would have been content to govern Syria had the Imam allowed it. Commentators have taken this episode — which made the governors'' revolt all but inevitable — as evidence of Ali s want of political shrewdness and his stubbornness. It should rather be understood as an expression of his disdain for worldly ease when that ease can be bought only at the price of essential principles. As he says in one of his sayings: "People renounce no part of their religion for the sake of rectifying their world without God opening them up to something worse than it" — that is, worse than the very defect they were trying to set right.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'and so the die was cast the imam dismissed muawiya along with all of his predecessors governors the imam saw clearly that ibn al abbas proposal had every chance of working he knew that all muawiya wanted was worldly power and that muawiya would have been content to govern syria had the imam allowed it commentators have taken this episode which made the governors revolt all but inevitable as evidence of ali s want of political shrewdness and his stubbornness it should rather be understood as an expression of his disdain for worldly ease when that ease can be bought only at the price of essential principles as he says in one of his sayings people renounce no part of their religion for the sake of rectifying their world without god opening them up to something worse than it that is worse than the very defect they were trying to set right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 34, NULL, 'Clearly, to keep in power governors whose corruption was beyond both doubt and remedy would have amounted, for the Imam, to "renouncing" a part of his religion — for religion without justice is not religion. To support unjust governors, even as a tactical move, was a compromise of religious principle simply unthinkable to him. This attitude ran through countless episodes of his life, all of which show that the principles set down in the letter to Malik al-Ashtar were far from merely theoretical.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'clearly to keep in power governors whose corruption was beyond both doubt and remedy would have amounted for the imam to renouncing a part of his religion for religion without justice is not religion to support unjust governors even as a tactical move was a compromise of religious principle simply unthinkable to him this attitude ran through countless episodes of his life all of which show that the principles set down in the letter to malik al ashtar were far from merely theoretical', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 35, NULL, 'What follows examines one particular dimension of justice — political on the surface, ethical in its outward expression, but spiritual in its depth: the justice of the political ruler, understood against its most clearly definable opposite, which is injustice, tyranny, oppression, and corruption. A deep taking-in of the Imam''s spirituality can lend a real, existential power to the moral effort to live justly — a power that is missing when justice is conceived only in individual or horizontal terms, that is, as a secular moral philosophy cut off from religious or spiritual principles. The crucial place of devotion and worship, both formal and beyond-formal, belongs to this same inquiry. Contemplation of the divine Reality is the wellspring from which whole and undivided virtue flows freely and without end — a point brought into sharper relief by comparison with Plato''s "gazing" upon the Sovereign Good as the source of all virtue.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'what follows examines one particular dimension of justice political on the surface ethical in its outward expression but spiritual in its depth the justice of the political ruler understood against its most clearly definable opposite which is injustice tyranny oppression and corruption a deep taking in of the imams spirituality can lend a real existential power to the moral effort to live justly a power that is missing when justice is conceived only in individual or horizontal terms that is as a secular moral philosophy cut off from religious or spiritual principles the crucial place of devotion and worship both formal and beyond formal belongs to this same inquiry contemplation of the divine reality is the wellspring from which whole and undivided virtue flows freely and without end a point brought into sharper relief by comparison with platos gazing upon the sovereign good as the source of all virtue', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 36, NULL, 'The inquiry that follows takes its bearings from a single document above all others: the letter of Ali to Malik al-Ashtar. It is there that a sacred conception of justice is set out most fully, and it is from its key passages that the present analysis draws.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'the inquiry that follows takes its bearings from a single document above all others the letter of ali to malik al ashtar it is there that a sacred conception of justice is set out most fully and it is from its key passages that the present analysis draws', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 37, NULL, 'Around that letter stand the Imam''s other writings. His further letters, his sermons, and his sayings are gathered here as they bear on the same theme, extending and deepening what the letter to Malik sets down. Treated in this way, justice is not read out of one text in isolation but heard across the whole body of his counsel.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'around that letter stand the imams other writings his further letters his sermons and his sayings are gathered here as they bear on the same theme extending and deepening what the letter to malik sets down treated in this way justice is not read out of one text in isolation but heard across the whole body of his counsel', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 38, NULL, 'Beyond the words of Ali himself, the analysis turns to certain traditions of the Prophet and to verses of the Quran. These are brought forward not as ornament but as light, for they illuminate the very themes the letter raises and lay bare the ground on which its conception of justice rests.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'beyond the words of ali himself the analysis turns to certain traditions of the prophet and to verses of the quran these are brought forward not as ornament but as light for they illuminate the very themes the letter raises and lay bare the ground on which its conception of justice rests', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'a sacred conception of justice', '6. A Sacred Conception of Justice', 39, NULL, 'Editorial note (tradition-grounded). The chapter turns on tawhid — the "integrating oneness" that binds contemplation to action and makes one a muwahhid. A related teaching preserved in this tradition clarifies the word itself: it is built from a root meaning "to be one," and as a form-II noun it names not the mere counting of God as a single item but the deliberate act of declaring Him one — a oneness that admits no partner, division, or second. That grammatical shape is worth holding onto here, because it mirrors exactly what the chapter argues: unity is not something passively observed but something a person actively enacts, joining theory to practice until being and doing become one. Read this way, becoming a muwahhid is itself the work of justice the chapter describes — the willed alignment of the soul with the undivided nature of the divine.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 6 a sacred conception of justice', 'editorial note tradition grounded the chapter turns on tawhid the integrating oneness that binds contemplation to action and makes one a muwahhid a related teaching preserved in this tradition clarifies the word itself it is built from a root meaning to be one and as a form ii noun it names not the mere counting of god as a single item but the deliberate act of declaring him one a oneness that admits no partner division or second that grammatical shape is worth holding onto here because it mirrors exactly what the chapter argues unity is not something passively observed but something a person actively enacts joining theory to practice until being and doing become one read this way becoming a muwahhid is itself the work of justice the chapter describes the willed alignment of the soul with the undivided nature of the divine', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 0, NULL, 'The letter is addressed to one of the Imam''s closest and most trusted companions. For that reason, its warnings about injustice and oppression carry a very precise force, over and above the universal theme they express. They apply to everyone who lives under Islam and its laws, and who begins with every right intention, yet remains vulnerable to the temptations of political power. They reckon fully with an unfortunate but proven truth, caught in the maxim that power corrupts — or, in the Imam''s own words, he who rules, appropriates (مَنْ مَلَكَ اسْتَأْثَرَ).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'the letter is addressed to one of the imams closest and most trusted companions for that reason its warnings about injustice and oppression carry a very precise force over and above the universal theme they express they apply to everyone who lives under islam and its laws and who begins with every right intention yet remains vulnerable to the temptations of political power they reckon fully with an unfortunate but proven truth caught in the maxim that power corrupts or in the imams own words he who rules appropriates من ملك استاثر', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 1, NULL, 'The Imam''s understanding of justice plainly reaches beyond both its own historical moment and the formal boundaries of the Islamic faith. The letter can be read as speaking not only to those who wish to govern by just principles, but to all who, though not corrupt at the outset, are corruptible — a class that takes in the overwhelming majority of humanity.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'the imams understanding of justice plainly reaches beyond both its own historical moment and the formal boundaries of the islamic faith the letter can be read as speaking not only to those who wish to govern by just principles but to all who though not corrupt at the outset are corruptible a class that takes in the overwhelming majority of humanity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 2, NULL, 'A note of somber realism sounds from the very opening of the letter. Man''s potential for evil, once he is left to his own devices and cut off from divine grace, dominates the mood of the preamble. Hence its emphasis on abiding by God''s wajibat, the religious obligations binding on every Muslim. Malik is instructed to set obedience to God above all else, to abide by what He has commanded in His Book ... for no one prospers except through abiding by them, and no one is wretched except through repudiating and neglecting them. The preamble is introductory, but by no means perfunctory. Obedience to the divine commands is to be understood not merely as legally binding but as spiritually liberating. Such obedience plays a crucial part in freeing a person from the tyranny of the soul which incites to evil (النَّفْسُ الْأَمَّارَةُ بِالسُّوءِ) — to which the Imam turns at once after calling Malik to obedience: For truly, the soul incites to evil, unless God has mercy. This sentence is almost identical to the words of the Prophet Joseph in the Quran (Yusuf: 53), and it matters greatly in setting the scene for the ethical and socio-political instructions that follow. The relationship that determines the spiritual substance of the soul — and all the more its moral conduct — is the relationship between the human soul and divine grace. Without grace the soul inclines toward evil; with God''s help it is freed from its base inclinations and guided back to its true, original nature, its fitra, to which the Quran refers in the verse that follows:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'a note of somber realism sounds from the very opening of the letter mans potential for evil once he is left to his own devices and cut off from divine grace dominates the mood of the preamble hence its emphasis on abiding by gods wajibat the religious obligations binding on every muslim malik is instructed to set obedience to god above all else to abide by what he has commanded in his book for no one prospers except through abiding by them and no one is wretched except through repudiating and neglecting them the preamble is introductory but by no means perfunctory obedience to the divine commands is to be understood not merely as legally binding but as spiritually liberating such obedience plays a crucial part in freeing a person from the tyranny of the soul which incites to evil النفس الاماره بالسوء to which the imam turns at once after calling malik to obedience for truly the soul incites to evil unless god has mercy this sentence is almost identical to the words of the prophet joseph in the quran yusuf 53 and it matters greatly in setting the scene for the ethical and socio political instructions that follow the relationship that determines the spiritual substance of the soul and all the more its moral conduct is the relationship between the human soul and divine grace without grace the soul inclines toward evil with gods help it is freed from its base inclinations and guided back to its true original nature its fitra to which the quran refers in the verse that follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 3, NULL, 'So set thy purpose for religion with unswerving devotion: the nature of God (firat Allah), according to which He hath created man. There is no altering God''s creation. That is the right religion (ٱلدِّينُ ٱلْقَيِّمُ), but most men know not. (Ar-Rum: 30)', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'so set thy purpose for religion with unswerving devotion the nature of god firat allah according to which he hath created man there is no altering gods creation that is the right religion الدين القيم but most men know not ar rum 30', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 4, NULL, 'The present state of the fallen soul, then, is called to give way to the ideal state of original human nature. That nature is both the origin and the end of the human condition, and at once the true substance of every human soul — always accessible in principle, even if for most people it stays clouded by fallen nature in practice. The quest to revive this original nature turns on the complementary work of the human intellect and divine revelation. In the first sermon of the Nahj, the Imam states that God sent mankind His messengers, dispatching prophets in succession, in order to claim from them [His creatures] the fulfillment of the covenant of His creation; to remind them of His forgotten graces; to remonstrate with them through communication [of His revelation]; to unearth for them the buried treasures of the intellects (دَفْعُ الْعُقُولِ).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'the present state of the fallen soul then is called to give way to the ideal state of original human nature that nature is both the origin and the end of the human condition and at once the true substance of every human soul always accessible in principle even if for most people it stays clouded by fallen nature in practice the quest to revive this original nature turns on the complementary work of the human intellect and divine revelation in the first sermon of the nahj the imam states that god sent mankind his messengers dispatching prophets in succession in order to claim from them his creatures the fulfillment of the covenant of his creation to remind them of his forgotten graces to remonstrate with them through communication of his revelation to unearth for them the buried treasures of the intellects دفع العقول', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 5, NULL, 'These buried treasures'' can be identified with the original, God-given knowledge that belongs to the fitra. Out of this whole human nature, in complete harmony with the divine nature, all the essential virtues flow freely and unhindered. Let your most beloved treasure be the treasure of virtuous acts'', the Imam writes. Virtue will indeed be the most beloved treasure of one who reverses the natural inclinations of the self-centered soul and sets a supernatural orientation toward its own deepest nature — and by that very act, toward the divine Reality that furnishes the foundations in being of all authentic virtue. For اَلْحَقّ, the Real, is not only the deepest foundation of virtue; it is the true substance of every positive quality, and, in the end, of every single thing that exists. As one of the most celebrated supplications attributed to the Imam puts it:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'these buried treasures can be identified with the original god given knowledge that belongs to the fitra out of this whole human nature in complete harmony with the divine nature all the essential virtues flow freely and unhindered let your most beloved treasure be the treasure of virtuous acts the imam writes virtue will indeed be the most beloved treasure of one who reverses the natural inclinations of the self centered soul and sets a supernatural orientation toward its own deepest nature and by that very act toward the divine reality that furnishes the foundations in being of all authentic virtue for الحق the real is not only the deepest foundation of virtue it is the true substance of every positive quality and in the end of every single thing that exists as one of the most celebrated supplications attributed to the imam puts it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 6, NULL, 'By Thy tremendousness (بِعَظَمَتِكَ), which has filled all things ... by Thy Names which have filled the foundations of all things, by Thy knowledge which encompasses all things, by the light of Thy face, through which all things are illumined ...', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'by thy tremendousness بعظمتك which has filled all things by thy names which have filled the foundations of all things by thy knowledge which encompasses all things by the light of thy face through which all things are illumined', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 7, NULL, 'From this vantage point, every virtue can be seen as the reflection, on the human plane, of a divine attribute — what is called a divine Name. Hence a theme running through the whole ihsani tradition, the path of spiritual excellence (احسان) that the Prophet defined as worshipping God as though one could see Him, knowing that even if one does not see Him, He sees him. That theme finds expression in the saying: Assume the character traits of God (تَخَلَّقُوا بِأَخْلَاقِ اللهِ).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'from this vantage point every virtue can be seen as the reflection on the human plane of a divine attribute what is called a divine name hence a theme running through the whole ihsani tradition the path of spiritual excellence احسان that the prophet defined as worshipping god as though one could see him knowing that even if one does not see him he sees him that theme finds expression in the saying assume the character traits of god تخلقوا باخلاق الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 8, NULL, 'The link between human virtue and divine reality is wholly indispensable in the Imam''s perspective. Subjectively, the practice of virtue draws down the matching divine quality; objectively, the divine quality is the source and — in accordance with true تَوْحِيد — the actual substance of all human virtue. Every positive quality, both in itself and in its manifestation, belongs to God, the One who has no partner theologically and has no second ontologically. This mystical grasp of the principle of تَوْحِيد is strongly implied in the Quranic verse, And thou threw not when thou didst throw [a handful of dust], but God it was who threw (Al-Anfal: 17). These divine qualities are not to be seen as purely transcendent, as though they were wholly one with the divine essence and utterly beyond the soul''s reach. They are also to be grasped as exemplars, as patterns of perfection for the soul to imitate as fully as it can. The goal is to become as much like God as possible; yet this growth can unfold only within the bounds of one''s servitude to Him. A person is generous for the sake of God, because God is الکریم, the Generous; he is compassionate and merciful because He is الرحمن الرحیم — never out of any claim that I am generous'' or I am merciful, for the aim is to imitate God''s qualities, not to claim to embody Him in person. The individual must therefore be effaced before God in order to be truly virtuous, and must at the same time share in and embody the very qualities he wishes God to show him. He stays lowly, humble, and effaced throughout, certain that no measure of virtue or intelligence can ever lessen or match the qualities of God — there being no proportion between the Absolute and the relative, the Creator and the created. His effort to embody these qualities is strengthened to the degree that he apprehends the divine attributes existentially, through intuition, rather than merely through reason, in theory. It is like gazing into a mirror: what one sees is a reflection, but an inverted one. The aim is to catch, on the human plane, the inverted reflection of divine transcendence. For man is at once خَلِیفَۃُ اللَّہِ, God''s vicegerent upon the earth, and عِبَادُ اللّٰہِ, His slave. The awareness of servitude keeps him, even while he represents God, from slipping into rivalry with Him in grandeur; the active commitment to representing God''s attributes guards him from the spiritual paralysis of neglecting his duties toward the world. Such is the meaning of the verse, يَٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلْفُقَرَآءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ, O mankind, you are the destitute before God, and God is the Self-sufficient, the Praiseworthy (Fatir: 15). There must be a synthesis between the active human virtues and the spiritual awareness of one''s nothingness before the divine Reality. The bond between intelligence and humility deserves emphasis here: intellectual perception of the divine attributes produces humility, and the effacement of the soul in turn draws attention away from the ego and toward the transcendent reality as the source of all virtue and truth.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'the link between human virtue and divine reality is wholly indispensable in the imams perspective subjectively the practice of virtue draws down the matching divine quality objectively the divine quality is the source and in accordance with true توحيد the actual substance of all human virtue every positive quality both in itself and in its manifestation belongs to god the one who has no partner theologically and has no second ontologically this mystical grasp of the principle of توحيد is strongly implied in the quranic verse and thou threw not when thou didst throw a handful of dust but god it was who threw al anfal 17 these divine qualities are not to be seen as purely transcendent as though they were wholly one with the divine essence and utterly beyond the souls reach they are also to be grasped as exemplars as patterns of perfection for the soul to imitate as fully as it can the goal is to become as much like god as possible yet this growth can unfold only within the bounds of ones servitude to him a person is generous for the sake of god because god is الكريم the generous he is compassionate and merciful because he is الرحمن الرحيم never out of any claim that i am generous or i am merciful for the aim is to imitate gods qualities not to claim to embody him in person the individual must therefore be effaced before god in order to be truly virtuous and must at the same time share in and embody the very qualities he wishes god to show him he stays lowly humble and effaced throughout certain that no measure of virtue or intelligence can ever lessen or match the qualities of god there being no proportion between the absolute and the relative the creator and the created his effort to embody these qualities is strengthened to the degree that he apprehends the divine attributes existentially through intuition rather than merely through reason in theory it is like gazing into a mirror what one sees is a reflection but an inverted one the aim is to catch on the human plane the inverted reflection of divine transcendence for man is at once خليفه الله gods vicegerent upon the earth and عباد الله his slave the awareness of servitude keeps him even while he represents god from slipping into rivalry with him in grandeur the active commitment to representing gods attributes guards him from the spiritual paralysis of neglecting his duties toward the world such is the meaning of the verse يايها الناس انتم الفقراء الي الله والله هو الغني الحميد o mankind you are the destitute before god and god is the self sufficient the praiseworthy fatir 15 there must be a synthesis between the active human virtues and the spiritual awareness of ones nothingness before the divine reality the bond between intelligence and humility deserves emphasis here intellectual perception of the divine attributes produces humility and the effacement of the soul in turn draws attention away from the ego and toward the transcendent reality as the source of all virtue and truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 9, NULL, 'The notion of the soul which incites to evil, and the Quranic story of Joseph (يُوسُفُ) in which it arises, deserves closer attention. The Imam could assume that his readers knew this context well, and he clearly meant it to stay before the mind of Malik, and of anyone else reading this letter on governance.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'the notion of the soul which incites to evil and the quranic story of joseph يوسف in which it arises deserves closer attention the imam could assume that his readers knew this context well and he clearly meant it to stay before the mind of malik and of anyone else reading this letter on governance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 10, NULL, 'Joseph gives this description of man''s base inclinations after his innocence of every charge has been established before the Egyptian king. Even so, he says, I do not exonerate myself. Truly, the soul incites to evil, unless my Lord has mercy. On the two occasions when he faced the seductive temptations of Zulaykha, the Quran makes clear that he resisted not through his own moral resources but through the grace of God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'joseph gives this description of mans base inclinations after his innocence of every charge has been established before the egyptian king even so he says i do not exonerate myself truly the soul incites to evil unless my lord has mercy on the two occasions when he faced the seductive temptations of zulaykha the quran makes clear that he resisted not through his own moral resources but through the grace of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 11, NULL, 'This theme of human helplessness before gratification that is alluring but immoral is strongly implied in the Imam''s repetition of the Quranic phrase, Truly the soul incites to evil, unless God has mercy. Here, then, are the two poles that draw the ordinary soul, the soul not yet at peace: its own base inclinations toward the negative possibilities of the fleeting world of appearances, and the higher pull toward the grace of God, which draws the soul back toward the pure positivity of ultimate reality. The sheer sharpness of the contrast within this powerful Quranic sentence quickens an awareness of the soul''s absolute and unconditional need of God in every circumstance. It is a most fitting way to open a letter of instruction to a man about to be given authority over a vast and wealthy country, where temptations lie in wait on every side. It stands as a solemn reminder of the soul''s openness to allurement on every plane, gross and subtle alike — an openness the soul cannot neutralize by itself, but only through the mercy and grace of God. And yet, to return to Joseph''s words, the vision of the evidence of God implies active discernment and, as its moral consequence, firm self-control. Human effort to avoid sin therefore does not contradict the need for grace in the attainment of virtue; rather, it expresses a grace already given, already present within the conscientious soul. The very capacity of the human will to strive for virtue is itself a grace already there, set within the spiritual constitution, or fitra — though a grace that must be made present, or actualized, through the sincere effort to draw upon this God-given power.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'this theme of human helplessness before gratification that is alluring but immoral is strongly implied in the imams repetition of the quranic phrase truly the soul incites to evil unless god has mercy here then are the two poles that draw the ordinary soul the soul not yet at peace its own base inclinations toward the negative possibilities of the fleeting world of appearances and the higher pull toward the grace of god which draws the soul back toward the pure positivity of ultimate reality the sheer sharpness of the contrast within this powerful quranic sentence quickens an awareness of the souls absolute and unconditional need of god in every circumstance it is a most fitting way to open a letter of instruction to a man about to be given authority over a vast and wealthy country where temptations lie in wait on every side it stands as a solemn reminder of the souls openness to allurement on every plane gross and subtle alike an openness the soul cannot neutralize by itself but only through the mercy and grace of god and yet to return to josephs words the vision of the evidence of god implies active discernment and as its moral consequence firm self control human effort to avoid sin therefore does not contradict the need for grace in the attainment of virtue rather it expresses a grace already given already present within the conscientious soul the very capacity of the human will to strive for virtue is itself a grace already there set within the spiritual constitution or fitra though a grace that must be made present or actualized through the sincere effort to draw upon this god given power', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 12, NULL, 'How this grace enters the soul as a shaping force of moral and spiritual life becomes clearer later in the Imam''s letter. For now, the negative side of the question calls for more elaboration, since the ruler''s ever-present temptation to abuse his power and commit injustice and tyranny deserves more than a passing mention. One might argue that how to refrain from injustice is a far harder and subtler question than its positive counterpart, how to act with justice. The Imam sets out the positive rules of political governance directly and plainly; what is far less plain is whether any holder of office can actually stay faithful to those rules when the temptations of power press upon him. Laws can be framed to punish corruption, but what no law can supply is the will, or the capacity, to stay incorruptible before the blandishments of political authority. This helps explain why the Imam''s exhortations take on so markedly negative a cast in the early part of the letter — the command to break the soul in the face of passionate desires'', to dominate your inclination, to withhold yourself from that which is not lawful for you. It also explains why the moral demand of justice must be set firmly within a lived spirituality. Without that grounding, commands to be fair, just, and honest lack the existential quality that turns them from abstract propositions into unquestionable realities, and that turns formal obedience to rules imposed from outside into a spiritual kinship with the source of those rules.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'how this grace enters the soul as a shaping force of moral and spiritual life becomes clearer later in the imams letter for now the negative side of the question calls for more elaboration since the rulers ever present temptation to abuse his power and commit injustice and tyranny deserves more than a passing mention one might argue that how to refrain from injustice is a far harder and subtler question than its positive counterpart how to act with justice the imam sets out the positive rules of political governance directly and plainly what is far less plain is whether any holder of office can actually stay faithful to those rules when the temptations of power press upon him laws can be framed to punish corruption but what no law can supply is the will or the capacity to stay incorruptible before the blandishments of political authority this helps explain why the imams exhortations take on so markedly negative a cast in the early part of the letter the command to break the soul in the face of passionate desires to dominate your inclination to withhold yourself from that which is not lawful for you it also explains why the moral demand of justice must be set firmly within a lived spirituality without that grounding commands to be fair just and honest lack the existential quality that turns them from abstract propositions into unquestionable realities and that turns formal obedience to rules imposed from outside into a spiritual kinship with the source of those rules', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 13, NULL, 'Living by just precepts then stops being a matter of compliance with something imposed from outside and becomes instead the moral companion of one''s inner being. In other words, a whole approach to justice leads to an identification with what is right, with اَلْحَقّ itself, rather than merely to the doing of what is right. There is a shift of consciousness from doing to being, from action to contemplation — yet without any weakening or undermining of action. On the contrary, action comes to reflect, on its own plane, the divine object of contemplation, and so becomes more effective, not less. An orientation toward the Real lends a deeper degree of reality both to what one does and to one''s own mode of being. One does what is right insofar as one is real; the Islamic spiritual tradition names this process of realization تَحْقِيق, making real. One''s ethical conduct is made real through spirituality, and spirituality, in turn, is expressed by, and made more concrete through, the practice of virtue.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'living by just precepts then stops being a matter of compliance with something imposed from outside and becomes instead the moral companion of ones inner being in other words a whole approach to justice leads to an identification with what is right with الحق itself rather than merely to the doing of what is right there is a shift of consciousness from doing to being from action to contemplation yet without any weakening or undermining of action on the contrary action comes to reflect on its own plane the divine object of contemplation and so becomes more effective not less an orientation toward the real lends a deeper degree of reality both to what one does and to ones own mode of being one does what is right insofar as one is real the islamic spiritual tradition names this process of realization تحقيق making real ones ethical conduct is made real through spirituality and spirituality in turn is expressed by and made more concrete through the practice of virtue', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 14, NULL, 'The Imam then issues a stern warning: وَلاَ تَنْصِبَنَّ نَفْسَكَ لِحَرْبِ اللهِ, Do not set your soul up for war with God. One may well ask what this means, and what kinds of acts or attitudes place the soul at war with God. The phrase seems to reach deeper than plain disobedience, deeper than the many breaches of religious obligation named at the letter''s outset. That is the most obvious sense of fighting against God, but it does not rule out subtler forms of opposition to divine reality — attitudes that may go along with outward acts of obedience yet contradict their very spirit. One example is the cardinal vice of pride (takabbur, or kibr), against which the Imam warns again and again: the inner state in which a person feels superior and treats others highhandedly, its signs so plain in his conduct that they cannot be hidden. A ruler''s pride is a theft of a divine attribute, a seizing of a greatness that belongs to God alone, who declares: الْكِبْرِيَاءُ رِدَائِي، وَالْعَظَمَةُ إِزَارِي، فَمَنْ نَازَعَنِي وَاحِدًا مِنْهُمَا، قَذَفْتُهُ فِي النَّارِ, Pride is My cloak and greatness is My robe; whoever contends with Me over either of them, I shall cast him into the Fire. God alone has the right to takabbur, and God alone may be called, without offense, al-Mutakabbir, the Proud. To vaunt oneself before others is, in effect, to defy God''s authority inwardly, and so to deny in an unspoken way His unique and incomparable majesty. This denial of something inseparable from divine sovereignty can itself be understood as a kind of war with God, for a subject who openly defies his king is, in effect, waging war against him. In short, enmity toward transcendent reality is the invisible substance that pervades all pride, and every act of arrogance or oppression a ruler commits against those beneath him.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'the imam then issues a stern warning ولا تنصبن نفسك لحرب الله do not set your soul up for war with god one may well ask what this means and what kinds of acts or attitudes place the soul at war with god the phrase seems to reach deeper than plain disobedience deeper than the many breaches of religious obligation named at the letters outset that is the most obvious sense of fighting against god but it does not rule out subtler forms of opposition to divine reality attitudes that may go along with outward acts of obedience yet contradict their very spirit one example is the cardinal vice of pride takabbur or kibr against which the imam warns again and again the inner state in which a person feels superior and treats others highhandedly its signs so plain in his conduct that they cannot be hidden a rulers pride is a theft of a divine attribute a seizing of a greatness that belongs to god alone who declares الكبرياء ردايي والعظمه ازاري فمن نازعني واحدا منهما قذفته في النار pride is my cloak and greatness is my robe whoever contends with me over either of them i shall cast him into the fire god alone has the right to takabbur and god alone may be called without offense al mutakabbir the proud to vaunt oneself before others is in effect to defy gods authority inwardly and so to deny in an unspoken way his unique and incomparable majesty this denial of something inseparable from divine sovereignty can itself be understood as a kind of war with god for a subject who openly defies his king is in effect waging war against him in short enmity toward transcendent reality is the invisible substance that pervades all pride and every act of arrogance or oppression a ruler commits against those beneath him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 15, NULL, 'The paradox here can be grasped only through a sense of spiritual values: an attitude of superiority toward those below is in fact an act of rebellion against that which is above. An injustice toward creatures does two things at once — it draws down upon its perpetrator the justice of the Creator, and it is, in itself, outright opposition to the Creator. What looks like a horizontal vice — horizontal in the sense that it belongs to this world — is in reality a spiritual disorder. The outward immorality of corruption is only the symptom of an inner spiritual malaise: an unspoken denial that the source of all power and authority is absolute, and hence unique, and a forgetting of the truth expressed in the Quranic verse, لِّمَنِ ٱلْمُلْكُ ٱلْيَوْم لِلَّهِ ٱلْوَحِدِ ٱلْقَهَّارِ, To whom belongeth the dominion this day? To God, the One, the All-Conquering (Ghafir: 16). This truth should sound constantly in the ears of every ruler, this day understood as every day, not only the Day of Judgment. In the Imam''s sermon known as al-Qasia (القاسیۃ), the Abasement, so named because it humbles the proud, Iblis (اِبْلِیس) is described as the first of those who competed with God in grandeur, and thus as the very embodiment of pride and arrogance. When he was commanded to prostrate before Adam, Iblis refused, as the Quran recounts:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'the paradox here can be grasped only through a sense of spiritual values an attitude of superiority toward those below is in fact an act of rebellion against that which is above an injustice toward creatures does two things at once it draws down upon its perpetrator the justice of the creator and it is in itself outright opposition to the creator what looks like a horizontal vice horizontal in the sense that it belongs to this world is in reality a spiritual disorder the outward immorality of corruption is only the symptom of an inner spiritual malaise an unspoken denial that the source of all power and authority is absolute and hence unique and a forgetting of the truth expressed in the quranic verse لمن الملك اليوم لله الوحد القهار to whom belongeth the dominion this day to god the one the all conquering ghafir 16 this truth should sound constantly in the ears of every ruler this day understood as every day not only the day of judgment in the imams sermon known as al qasia القاسيه the abasement so named because it humbles the proud iblis ابليس is described as the first of those who competed with god in grandeur and thus as the very embodiment of pride and arrogance when he was commanded to prostrate before adam iblis refused as the quran recounts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 16, NULL, 'إِذْ قَالَ رَبُّكَ لِلْمَلَٓئِكَةِ إِنِّى خَلِقٌۢ بَشَرًۭا مِّن طِينٍۢ ۝ فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُ سَجِدِينَ ۝ فَسَجَدَ ٱلْمَلَٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ ۝ إِلَّآ إِبْلِيسَ ٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَفِرِينَ, When your Lord said to the angels: Truly I am going to create man from clay; and when I have fashioned him and breathed into him of My spirit, then fall down before him prostrate. So the angels prostrated themselves, all of them together; save Iblis: he was proud and was one of the disbelievers'' (Sad: 71-74).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'اذ قال ربك للمليكه اني خلق بشرا من طين فاذا سويته ونفخت فيه من روحي فقعوا له سجدين فسجد المليكه كلهم اجمعون الا ابليس استكبر وكان من الكفرين when your lord said to the angels truly i am going to create man from clay and when i have fashioned him and breathed into him of my spirit then fall down before him prostrate so the angels prostrated themselves all of them together save iblis he was proud and was one of the disbelievers sad 71 74', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 17, NULL, 'He refused because vehement passion overcame him. He judged himself superior to Adam on the grounds that he was made of fire while Adam was made of clay, خَلَقْتَنِی مِنْ نَارٍ وَ خَلَقْتَہُ مِنْ طِینٍ. In taking pride in this presumed superiority, and thereby rebelling against God''s command, Iblis becomes not only the first enemy of God but also the leader of the bigots and the forerunner of the proud (imam al-muta assibin wa salaf al-mustakbirin, اِمَامُ الْمُتَعَصِّبِینَ وَ سَلَفُ الْمُسْتَکْبِرِینَ). The Imam warns his listeners: Beware lest he infect you with his disease through his insinuations, whisperings, and machinations. He urges them: Be resolute in placing self-abasement over your heads, casting self-glorification beneath your feet, and removing pride from your necks. And take up humility as the fortified watchtower between you and your enemy.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'he refused because vehement passion overcame him he judged himself superior to adam on the grounds that he was made of fire while adam was made of clay خلقتني من نار و خلقته من طين in taking pride in this presumed superiority and thereby rebelling against gods command iblis becomes not only the first enemy of god but also the leader of the bigots and the forerunner of the proud imam al muta assibin wa salaf al mustakbirin امام المتعصبين و سلف المستكبرين the imam warns his listeners beware lest he infect you with his disease through his insinuations whisperings and machinations he urges them be resolute in placing self abasement over your heads casting self glorification beneath your feet and removing pride from your necks and take up humility as the fortified watchtower between you and your enemy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 18, NULL, 'Humility is the chief weapon in the war against Iblis, whose own aim is the reverse: to instil pride. For pride is not only the worst of vices but the poison that infects and destroys every virtue. A virtue is turned into a vice the moment pride accompanies it. The sin that grieves you is better, in the sight of God, than the virtue that makes you proud. Bound up with this is the point made earlier about the dangers of excessive praise and the conceit it breeds, which are among Satan''s most reliable opportunities to efface the virtue of one who is virtuous''.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'humility is the chief weapon in the war against iblis whose own aim is the reverse to instil pride for pride is not only the worst of vices but the poison that infects and destroys every virtue a virtue is turned into a vice the moment pride accompanies it the sin that grieves you is better in the sight of god than the virtue that makes you proud bound up with this is the point made earlier about the dangers of excessive praise and the conceit it breeds which are among satans most reliable opportunities to efface the virtue of one who is virtuous', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 19, NULL, 'Taken together, these statements form a commentary on the Quranic account of Iblis'' disgrace. They grasp a simple act of disobedience at its spiritual root, and in doing so bring home the ever-present danger of falling prey to that hidden form of شِرْك (polytheism) to which the Prophet refers in these words: الشِّرْكُ فِي هَذِهِ الْأُمَّةِ akhfa مِنْ دَبِيبِ النَّمْلِ عَلَی حَجَرِ الْأَسْوَدِ فِی لِیلَۃِ الظُّلْمَا — The creeping of شِرْك in my community is more hidden (أَخْفَى) than the creeping of a black ant over a hard rock on a dark night. شِرْك is commonly taken to mean the worship of material idols, شِرْکُ الْجَلِیِّ, its open and manifest form; but it must be understood more subtly as شِرْکُ الْخَفِیِّ, the hidden form — false gods concealed within one''s intentions, attitudes, and orientations, all the elements of hidden pride, vanity, ostentation, and pretentiousness. As the Imam says, Know that the slightest pretension (رِيَاء — ریا) is polytheism. To act for the sake of earning others'' praise is to act for others rather than for God, and so to attribute partners to God without saying so: Whoso acts for other than God, God entrusts him to those for whose sake he acted.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'taken together these statements form a commentary on the quranic account of iblis disgrace they grasp a simple act of disobedience at its spiritual root and in doing so bring home the ever present danger of falling prey to that hidden form of شرك polytheism to which the prophet refers in these words الشرك في هذه الامه akhfa من دبيب النمل علي حجر الاسود في ليله الظلما the creeping of شرك in my community is more hidden اخفي than the creeping of a black ant over a hard rock on a dark night شرك is commonly taken to mean the worship of material idols شرك الجلي its open and manifest form but it must be understood more subtly as شرك الخفي the hidden form false gods concealed within ones intentions attitudes and orientations all the elements of hidden pride vanity ostentation and pretentiousness as the imam says know that the slightest pretension رياء ريا is polytheism to act for the sake of earning others praise is to act for others rather than for god and so to attribute partners to god without saying so whoso acts for other than god god entrusts him to those for whose sake he acted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 20, NULL, 'In this light the meaning of Iblis'' disobedience can be understood more deeply. It is the outward moral consequence of an inner spiritual malaise, rooted in that pride which is tantamount to hidden polytheism and which brings a disgraceful humiliation in its train. Iblis is disgraced because he disobeyed God, and he disobeyed God on account of pride. Pride is therefore, in and of itself, a disgrace — a state of dis-grace, a perversion of the human condition that carries within it the seed of its own inexorable inversion. Do you not see how God humiliated him through his pride? the Imam asks. To be proud is already, in reality, a form of humiliation, for to make oneself great is tantamount to self-destruction.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'in this light the meaning of iblis disobedience can be understood more deeply it is the outward moral consequence of an inner spiritual malaise rooted in that pride which is tantamount to hidden polytheism and which brings a disgraceful humiliation in its train iblis is disgraced because he disobeyed god and he disobeyed god on account of pride pride is therefore in and of itself a disgrace a state of dis grace a perversion of the human condition that carries within it the seed of its own inexorable inversion do you not see how god humiliated him through his pride the imam asks to be proud is already in reality a form of humiliation for to make oneself great is tantamount to self destruction', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 21, NULL, 'Returning to the pride of those in power, the Imam sets out concisely the train of thought that starts up in the mind of a ruler as he steps onto the slippery slope toward oppression: وَلاَ تَقُولَنَّ: إِنِّي مُؤَمَّرٌ! آمُرُ! فَأُطَاعُ! إِنَّ ذلِكَ إِدْغَالٌ فِي الْقَلْبِ، وَمَنْهَكَةٌ لِلدِّينِ — Do not say, "I have been given authority, I order and am obeyed", for this leads to corruption in the heart and the erosion of religion. This self-glorification is seen as producing first an inner, spiritual corruption, that of the heart, and only then the destruction of religion. The order of priority makes a point: the outward prescriptions of religion require the right inward attitude if they are to be applied with integrity and maintained with stability. The Imam''s thought might be restated thus: when power goes to the head, faith departs from the heart; and conversely, for faith to be properly manifested in the world, it must flow from a heart suffused with humility. This is another aspect of putting each thing in its proper place, وضع کل شئی حق محلہ.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'returning to the pride of those in power the imam sets out concisely the train of thought that starts up in the mind of a ruler as he steps onto the slippery slope toward oppression ولا تقولن اني مومر امر فاطاع ان ذلك ادغال في القلب ومنهكه للدين do not say i have been given authority i order and am obeyed for this leads to corruption in the heart and the erosion of religion this self glorification is seen as producing first an inner spiritual corruption that of the heart and only then the destruction of religion the order of priority makes a point the outward prescriptions of religion require the right inward attitude if they are to be applied with integrity and maintained with stability the imams thought might be restated thus when power goes to the head faith departs from the heart and conversely for faith to be properly manifested in the world it must flow from a heart suffused with humility this is another aspect of putting each thing in its proper place وضع كل شيي حق محله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 22, NULL, 'The Imam continues: وَإِذَا أَحْدَثَ لَكَ مَا أَنْتَ فِيهِ مِنْ سُلْطَانِكَ أُبَّهَةً أَوْ مَخِيلَةً، فَانْظُرْ إِلَى عِظَمِ مُلْكِ اللهِ فَوْقَكَ، فَإِنَّ ذلِكَ يُطَامِنُ إِلَيْكَ مِنْ طِمَاحِكَ، وَيَكُفُّ عَنْكَ مِنْ غَرْبِكَ،يَفِيءُ إِلَيْكَ بِمَا عَزَبَ عَنْكَ مِنْ عَقْلِكَ — If the authority of your position engenders vanity and arrogance, then look at the grandeur of God''s dominion above you … this will calm your ambition, restrain you from your own vehemence, and restore to you what had strayed from your intellect. The bond between intellect and humility deserves close attention here. The part of the intellect that strays'' when vanity and arrogance take hold is precisely the part that is conscious of God''s absolute reality and of the relative, derivative, and ultimately illusory character of everything else. It is telling that the word for arrogance, makhila (مَخِيلَةً), comes from the same root as the word for imagination, khayal (خیال), and is thus intimately connected with the realm of the imaginary, the fanciful, the illusory, and the unreal: when imagination fastens upon the unreal, it becomes infused with pride and turns into مخیلۃ, arrogance. Arrogant pride is therefore an intense form of self-delusion rooted in a defect of the intellect. It manifests as a vice, but its cause runs deeper than the moral level, for it involves not merely an overestimation of oneself but, more fundamentally, an underestimation of the Absolute. Seen this way, the overt egotism of the tyrant is an intensification of the congenital egocentricity that clings to anyone who has not realized the truth of God''s sole reality and the ultimately illusory nature of all else. The sage alone fully assimilates the truth expressed in such Quranic verses as: كُلُّ شَىْءٍ هَالِكٌ إِلَّا وَجْهَهُ — Everything is dying away except His countenance (Al-Qasas: 88); كُلُّ مَنْ عَلَيْهَا فَانٍۢ ۝ وَيَبْقَىٰ وَجْهُ رَبِّكَ ذُو ٱلْجَلَلِ وَٱلْإِكْرَامِ — Everything that is thereon is perishing, and there subsisteth but the Face of thy Lord, possessor of Glory and Bounty (Ar-Rahman: 26-27); and وَقُلْ جَآءَ ٱلْحَقُّ وَزَهَقَ ٱلْبَطِلُ ۚ إِنَّ ٱلْبَطِلَ كَانَ زَهُوقًۭا — The Truth hath come and falsehood hath passed away; indeed, falsehood is ever passing away (Al-Isra: 81). Only the sage draws from this truth the humility that dissolves all individualism and egocentricity — the roots of pride, vanity, and arrogance, which are in turn the lifeblood of tyranny and oppression.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'the imam continues واذا احدث لك ما انت فيه من سلطانك ابهه او مخيله فانظر الي عظم ملك الله فوقك فان ذلك يطامن اليك من طماحك ويكف عنك من غربك يفيء اليك بما عزب عنك من عقلك if the authority of your position engenders vanity and arrogance then look at the grandeur of gods dominion above you this will calm your ambition restrain you from your own vehemence and restore to you what had strayed from your intellect the bond between intellect and humility deserves close attention here the part of the intellect that strays when vanity and arrogance take hold is precisely the part that is conscious of gods absolute reality and of the relative derivative and ultimately illusory character of everything else it is telling that the word for arrogance makhila مخيله comes from the same root as the word for imagination khayal خيال and is thus intimately connected with the realm of the imaginary the fanciful the illusory and the unreal when imagination fastens upon the unreal it becomes infused with pride and turns into مخيله arrogance arrogant pride is therefore an intense form of self delusion rooted in a defect of the intellect it manifests as a vice but its cause runs deeper than the moral level for it involves not merely an overestimation of oneself but more fundamentally an underestimation of the absolute seen this way the overt egotism of the tyrant is an intensification of the congenital egocentricity that clings to anyone who has not realized the truth of gods sole reality and the ultimately illusory nature of all else the sage alone fully assimilates the truth expressed in such quranic verses as كل شيء هالك الا وجهه everything is dying away except his countenance al qasas 88 كل من عليها فان ويبقي وجه ربك ذو الجلل والاكرام everything that is thereon is perishing and there subsisteth but the face of thy lord possessor of glory and bounty ar rahman 26 27 and وقل جاء الحق وزهق البطل ان البطل كان زهوقا the truth hath come and falsehood hath passed away indeed falsehood is ever passing away al isra 81 only the sage draws from this truth the humility that dissolves all individualism and egocentricity the roots of pride vanity and arrogance which are in turn the lifeblood of tyranny and oppression', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 23, NULL, 'The Imam''s warning can now be better appreciated: إِيَّاكَ وَمُسَامَةَ اللهِ فِي عَظَمَتِهِ، وَالتَّشَبُّهَ بِهِ فِي جَبَرُوتِهِ، فَإِنَّ اللهَ يُذِلُّ كُلَّ جَبَّار، وَيُهِينُ كُلَّ مُخْتَال — Beware of comparing [yourself] with God in greatness and likening [yourself] to Him in might, for God abases every tyrant and disgraces every braggart. A ruler who does not act with justice toward God and His creatures — for the Imam commands, أَنْصِفِ اللهَ وَأَنْصِفِ النَّاسَ مِنْ نَفْسِكَ، وَمِنْ خَاصَّةِ أَهْلِكَ، وَمَنْ لَكَ فِيهِ هَوىً مِنْ رَعِيَّتِكَ، فَإِنَّكَ إِلاَّ تَفْعَلْ تَظْلِمْ — will find that not only His creatures but God Himself becomes his adversary: وَمَنْ ظَلَمَ عِبَادَ اللهِ كَانَ اللهُ خَصْمَهُ دُونَ عِبَادِهِ، وَمَنْ خَاصَمَهُ اللهُ أَدْحَضَ حُجَّتَهُ، وَكَانَ للهِ حَرْباً حَتَّى يَنْزِعَ وَيَتُوبَ — He remains at war with God until he desists and repents. The tyrant will in the end be compelled to repent, even if only at the moment of death and imminent judgment. And even if he seems to have escaped the consequences of his tyranny in this life, he cannot escape them in the Hereafter.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'the imams warning can now be better appreciated اياك ومسامه الله في عظمته والتشبه به في جبروته فان الله يذل كل جبار ويهين كل مختال beware of comparing yourself with god in greatness and likening yourself to him in might for god abases every tyrant and disgraces every braggart a ruler who does not act with justice toward god and his creatures for the imam commands انصف الله وانصف الناس من نفسك ومن خاصه اهلك ومن لك فيه هوي من رعيتك فانك الا تفعل تظلم will find that not only his creatures but god himself becomes his adversary ومن ظلم عباد الله كان الله خصمه دون عباده ومن خاصمه الله ادحض حجته وكان لله حربا حتي ينزع ويتوب he remains at war with god until he desists and repents the tyrant will in the end be compelled to repent even if only at the moment of death and imminent judgment and even if he seems to have escaped the consequences of his tyranny in this life he cannot escape them in the hereafter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 24, NULL, 'As for the nature of the tyrant''s war against God in this world — that is, before repentance or judgment overtakes him — it consists in his implicit opposition to ultimate reality, his violation of the deepest nature of things, of the true nature of his own being, his فطرۃ. This war takes various forms.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'as for the nature of the tyrants war against god in this world that is before repentance or judgment overtakes him it consists in his implicit opposition to ultimate reality his violation of the deepest nature of things of the true nature of his own being his فطره this war takes various forms', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice and the tyrant''s pride', '7. Justice and the Tyrant''s Pride', 25, NULL, 'One form is the very persistence of tyranny itself. The longer it continues, the more wretched the tyrant''s soul becomes, and the more firmly the seeds of misery are planted in his being. This is what is implied by the Quranic doctrine of istidraj (اِسْتِدْرَاج), the drawing out of punishment by degrees. The word derives from درج, meaning stages — as even in Urdu one says درجہ بدرجہ, step by step. God uses it in Surat al-Araf: ‏وَمِمَّنْ خَلَقْنَآ أُمَّةٌۭ يَهْدُونَ بِٱلْحَقِّ وَبِهِ يَعْدِلُونَ ‎۱۸۱‏وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَتِنَا سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ ‎۱۸۲ — Of those We have created are people who guide with truth and dispense justice therewith. But those who reject Our signs, We will lead them on by degrees [to punishment] from whence they know not (Al-Araf: 181-2). This punishment meted out by degrees can take the form of apparent worldly success, as the verse makes clear: ‏وَلَا تُعْجِبْكَ أَمْوَلُهُمْ وَأَوْلَدُهُمْ ۚ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِى ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَفِرُونَ ‎۸۵ — Let not their wealth nor their children please thee. God desireth only to punish them thereby in the world, that their souls shall pass away while they are disbelievers'' (At-Tawbah: 85). A tyrant or oppressor can be a Muslim in the formal sense and yet at the same time be guilty of a mode of disbelief — taking the word kafir in its strictly etymological sense, as one who covers over the truth and its moral concomitants, both in his very being and in his actions. This connects directly with the contrast drawn in the verses just quoted (Al-Araf: 181-2): between those who dispense justice in accordance with the truth and those who reject Our signs'' — the oppressors and tyrants, precisely.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 7 justice and the tyrants pride', 'one form is the very persistence of tyranny itself the longer it continues the more wretched the tyrants soul becomes and the more firmly the seeds of misery are planted in his being this is what is implied by the quranic doctrine of istidraj استدراج the drawing out of punishment by degrees the word derives from درج meaning stages as even in urdu one says درجه بدرجه step by step god uses it in surat al araf وممن خلقنا امه يهدون بالحق وبه يعدلون ۱۸۱ والذين كذبوا بايتنا سنستدرجهم من حيث لا يعلمون ۱۸۲ of those we have created are people who guide with truth and dispense justice therewith but those who reject our signs we will lead them on by degrees to punishment from whence they know not al araf 181 2 this punishment meted out by degrees can take the form of apparent worldly success as the verse makes clear ولا تعجبك امولهم واولدهم انما يريد الله ان يعذبهم بها في الدنيا وتزهق انفسهم وهم كفرون ۸۵ let not their wealth nor their children please thee god desireth only to punish them thereby in the world that their souls shall pass away while they are disbelievers at tawbah 85 a tyrant or oppressor can be a muslim in the formal sense and yet at the same time be guilty of a mode of disbelief taking the word kafir in its strictly etymological sense as one who covers over the truth and its moral concomitants both in his very being and in his actions this connects directly with the contrast drawn in the verses just quoted al araf 181 2 between those who dispense justice in accordance with the truth and those who reject our signs the oppressors and tyrants precisely', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 0, NULL, 'One form this enmity with God takes is the inner war against one''s own conscience — what Urdu calls the ⟪ar:ضمیر⟫. The voice of conscience is the whole substance of secular ethics, and it can be understood here within its fuller context, not merely as the overgrown foundation of individual morality that secular ethical thought has made of it. That fuller context is the source — beyond the individual, beyond the physical — from which individual conscience springs: the divine infusion of spiritual discernment into the soul, the divine inspiration that lies beneath every distinction between right and wrong. At the level of the morally responsible soul, then, the divine quality of justice becomes the voice of inner conscience:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'one form this enmity with god takes is the inner war against ones own conscience what urdu calls the ar ضمير the voice of conscience is the whole substance of secular ethics and it can be understood here within its fuller context not merely as the overgrown foundation of individual morality that secular ethical thought has made of it that fuller context is the source beyond the individual beyond the physical from which individual conscience springs the divine infusion of spiritual discernment into the soul the divine inspiration that lies beneath every distinction between right and wrong at the level of the morally responsible soul then the divine quality of justice becomes the voice of inner conscience', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 1, NULL, 'Ash-Shams: 7-8وَنَفْسٍۢ وَمَا سَوَّىٰهَا ۷ فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا ۸And the soul and that which perfected it, inspiring it with [consciousness of] its wickedness and its righteousness'' (Ash-Shams: 7-8).', '', NULL, 'Ash-Shams: 7-8', NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'ash shams 7 8ونفس وما سواها ۷ فالهمها فجورها وتقواها ۸and the soul and that which perfected it inspiring it with consciousness of its wickedness and its righteousness ash shams 7 8', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 2, NULL, 'The war against one''s own conscience, even when the oppressor scarcely acknowledges it, is in truth a war against God, and all the more so.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the war against ones own conscience even when the oppressor scarcely acknowledges it is in truth a war against god and all the more so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 3, NULL, 'At a deeper level, then, this war against God is revealed as a war against the very reality that makes the soul a soul. The soul contains not only a moral conscience — a built-in, inseparable awareness of the difference between good and evil, placed in it by God — but also an inborn consciousness of God''s lordship and of its own answering servitude as a creature. Spiritual consciousness is therefore the source of moral conscience. The Quran describes how this spiritual consciousness dwells within each soul in terms that stress its nature before and beyond existence, calling up a moment at the very dawn of creation — a moment, or degree of being, that comes before the human condition itself yet enters into the very shaping of the human soul:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'at a deeper level then this war against god is revealed as a war against the very reality that makes the soul a soul the soul contains not only a moral conscience a built in inseparable awareness of the difference between good and evil placed in it by god but also an inborn consciousness of gods lordship and of its own answering servitude as a creature spiritual consciousness is therefore the source of moral conscience the quran describes how this spiritual consciousness dwells within each soul in terms that stress its nature before and beyond existence calling up a moment at the very dawn of creation a moment or degree of being that comes before the human condition itself yet enters into the very shaping of the human soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 4, NULL, 'Al-A''raf: 172وَإِذْ أَخَذَ رَبُّكَ مِنۢ بَنِىٓ آدَمَ مِن ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَىٰٓ أَنفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ ۖ قَالُوا۟ بَلَىٰ ۛ شَهِدْنَآ ۛ أَن تَقُولُوا۟ يَوْمَ ٱلْقِيَمَةِ إِنَّا كُنَّا عَنْ هَذَا غَفِلِينَ ۱۷۲And when thy Lord brought forth from the children of Adam, from their loins, their seed, and made them testify against their souls [saying], "Am I not your Lord?" They said, "Yes, verily, we testify." [This was] lest ye say on the Day of Resurrection, "Truly, of this we were unaware" (Al-Araf: 172).', '', NULL, 'Al-A''raf: 172', NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'al araf 172واذ اخذ ربك من بني ادم من ظهورهم ذريتهم واشهدهم علي انفسهم الست بربكم قالوا بلي شهدنا ان تقولوا يوم القيمه انا كنا عن هذا غفلين ۱۷۲and when thy lord brought forth from the children of adam from their loins their seed and made them testify against their souls saying am i not your lord they said yes verily we testify this was lest ye say on the day of resurrection truly of this we were unaware al araf 172', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 5, NULL, 'The moment He created them He made them witness His glory and testify to it, so that they could plead no ignorance on the Day of Judgment.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the moment he created them he made them witness his glory and testify to it so that they could plead no ignorance on the day of judgment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 6, NULL, 'What comes to light here is that the source of morality rises above the human level even while forming part of the very definition of what it is to be human. Seen this way, what makes the human soul fully human is precisely that element of transcendence which infinitely surpasses the soul and yet, mysteriously, supplies its own deepest being. In this light, tyranny and oppression take on a subtler meaning: these vices are drawn much closer to the lived reality of every soul, rather than confined to those who hold and abuse political power. The tyrant is, before anything else, one who violates his own soul, one who lets it be ruled by the soul which commands evil, النَّفْس al-ammara (⟪ar:النَّفْسُ الْاَمَّارَۃُ بِالسُّوءِ⟫). And so the saying the Imam cites as summing up the attitude of one on the way to corrupting his own soul and becoming an oppressor — وَلاَ تَقُولَنَّ: إِنِّي مُؤَمَّرٌ آمُرُ فَأُطَاعُ, I order and am obeyed — is to be understood not only in social terms but also within the small world of the soul. It becomes the utterance of the evil element within the soul: the nafs al-ammara, which literally orders'' (آمُرُ) and is obeyed by every other faculty of the soul — intelligence, imagination, will, sentiment, sensibility, and the rest.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'what comes to light here is that the source of morality rises above the human level even while forming part of the very definition of what it is to be human seen this way what makes the human soul fully human is precisely that element of transcendence which infinitely surpasses the soul and yet mysteriously supplies its own deepest being in this light tyranny and oppression take on a subtler meaning these vices are drawn much closer to the lived reality of every soul rather than confined to those who hold and abuse political power the tyrant is before anything else one who violates his own soul one who lets it be ruled by the soul which commands evil النفس al ammara ar النفس الاماره بالسوء and so the saying the imam cites as summing up the attitude of one on the way to corrupting his own soul and becoming an oppressor ولا تقولن اني مومر امر فاطاع i order and am obeyed is to be understood not only in social terms but also within the small world of the soul it becomes the utterance of the evil element within the soul the nafs al ammara which literally orders امر and is obeyed by every other faculty of the soul intelligence imagination will sentiment sensibility and the rest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 7, NULL, 'The struggle against one''s own soul (mujahadat النَّفْس, ⟪ar:مُجَاھَدَۃُ النَّفْسِ⟫) is a theme the Imam returns to again and again. The need to wrestle with and master one''s own faults is an essential part of justice in the sense defined earlier: to put each thing in its proper place begins with setting oneself right before presuming to reform or govern others; it means restoring the divine nature within oneself. As the Imam says, If your aspiration is to reform the people, begin with yourself, for your pursuit of the reform of others while your own soul is corrupt is the greatest of faults. In his letter appointing Muhammad b. Abi Bakr (⟪ar:مُحَمَّدُ بْنُ اَبِی بَکْرٍ⟫), the governor of Egypt before Malik (⟪ar:مَالِکُ اَشْتَرُ⟫), the Imam draws a firm link between the granting of power and the duty to resist one''s own soul: And be aware, O Muhammad b. Abi Bakr, that I have appointed you as governor over the most immense of the forces at my disposal, the people of Egypt, so you are obliged to oppose your soul and protect your religion. The tie between the size of the power placed in one''s hands and the spiritual responsibility that comes with it is worth close attention. A ruler must be on guard, first against his own soul and its desires, and second in regard to the religion. The greater the power at hand, the greater the duty to control and restrain oneself; for if the soul gives way to its desires and satisfies them through that power, the outcome is the corruption not only of the ruler himself but of the very religion he is charged to uphold. Here again priorities are set by a principle that is essentially spiritual: the outward form and practice of religion depends for its integrity on the inward state of the Muslim''s soul. This is one more expression of the principle of putting each thing in its proper place. The commanding soul that claims for itself the right to independence and mastery is described with terse precision in the Quranic verse:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the struggle against ones own soul mujahadat النفس ar مجاهده النفس is a theme the imam returns to again and again the need to wrestle with and master ones own faults is an essential part of justice in the sense defined earlier to put each thing in its proper place begins with setting oneself right before presuming to reform or govern others it means restoring the divine nature within oneself as the imam says if your aspiration is to reform the people begin with yourself for your pursuit of the reform of others while your own soul is corrupt is the greatest of faults in his letter appointing muhammad b abi bakr ar محمد بن ابي بكر the governor of egypt before malik ar مالك اشتر the imam draws a firm link between the granting of power and the duty to resist ones own soul and be aware o muhammad b abi bakr that i have appointed you as governor over the most immense of the forces at my disposal the people of egypt so you are obliged to oppose your soul and protect your religion the tie between the size of the power placed in ones hands and the spiritual responsibility that comes with it is worth close attention a ruler must be on guard first against his own soul and its desires and second in regard to the religion the greater the power at hand the greater the duty to control and restrain oneself for if the soul gives way to its desires and satisfies them through that power the outcome is the corruption not only of the ruler himself but of the very religion he is charged to uphold here again priorities are set by a principle that is essentially spiritual the outward form and practice of religion depends for its integrity on the inward state of the muslims soul this is one more expression of the principle of putting each thing in its proper place the commanding soul that claims for itself the right to independence and mastery is described with terse precision in the quranic verse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 8, NULL, 'Al-''Alaq: 6-7كَلَّآ إِنَّ ٱلْإِنْسَنَ لَيَطْغَىٰٓ ۶ أَنْ رَّآهُ ٱسْتَغْنَىٰٓ ۷Truly man is rebellious, in that he deemeth himself independent (Al-Alaq: 6-7).', '', NULL, 'Al-''Alaq: 6-7', NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'al alaq 6 7كلا ان الانسن ليطغي ۶ ان راه استغني ۷truly man is rebellious in that he deemeth himself independent al alaq 6 7', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 9, NULL, 'Insofar as the soul pretends to be self-sufficient and tries to cut itself off from its total dependence on God, it sets itself up as a god in its own right — the person coming to believe that he himself is God. Herein lies the true portrait of the tyrant, the one who, as the Quran puts it, taketh his own desire as his god (Al-Jathiyah: 23): أَفَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَهَهُۥ هَوَىٰهُ. To know one''s own nothingness before God, and therefore one''s absolute need of Him, is the chief means of loosening the grip of the soul that commands to evil. For only the soul that already commands itself to evil will command others to evil; and only the soul that is lowly before God will be humble, compassionate, and just in its dealings with people.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'insofar as the soul pretends to be self sufficient and tries to cut itself off from its total dependence on god it sets itself up as a god in its own right the person coming to believe that he himself is god herein lies the true portrait of the tyrant the one who as the quran puts it taketh his own desire as his god al jathiyah 23 افرءيت من اتخذ الهه هواه to know ones own nothingness before god and therefore ones absolute need of him is the chief means of loosening the grip of the soul that commands to evil for only the soul that already commands itself to evil will command others to evil and only the soul that is lowly before god will be humble compassionate and just in its dealings with people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 10, NULL, 'This principle emerges clearly from these words of the Imam: Let the most beloved of affairs to you be those most centered upon the right, the most comprehensive in justice, and the most inclusive of popular approval, for the disapproval of the common folk undermines the approval of the elite ... This stress on the importance of the common people is not only sound practical counsel for fair and effective government; it can also be read as an echo of the spiritual duty to recognize man''s real lowliness before God, and so as a way of pressing the ruler to identify with the poor rather than the rich, in keeping with the principle:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'this principle emerges clearly from these words of the imam let the most beloved of affairs to you be those most centered upon the right the most comprehensive in justice and the most inclusive of popular approval for the disapproval of the common folk undermines the approval of the elite this stress on the importance of the common people is not only sound practical counsel for fair and effective government it can also be read as an echo of the spiritual duty to recognize mans real lowliness before god and so as a way of pressing the ruler to identify with the poor rather than the rich in keeping with the principle', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 11, NULL, 'Fatir: 15يَٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلْفُقَرَآءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُO mankind, ye are the poor before God, and God, He is the Rich, the absolutely Praiseworthy (Fatir: 15).', '', NULL, 'Fatir: 15', NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'fatir 15يايها الناس انتم الفقراء الي الله والله هو الغني الحميدo mankind ye are the poor before god and god he is the rich the absolutely praiseworthy fatir 15', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 12, NULL, 'The Imam''s own poverty and severe austerity were proverbial. Yet this was far from a simple turning away from the world for its own sake, as his exchange with an ascetic, Asim b. Ziyad, makes clear. Asim''s family had complained to the Imam that he denied himself too much, and the Imam told him to think of his family and not to cut himself off from the good things (الطَّيِّبَاتُ) that God has permitted. Asim retorted, O Commander of the Faithful, and yet here you are, in your rough clothes and your coarse food! The Imam replied, Woe to you, I am not like you. God, the Exalted, has made it incumbent on true leaders (أَئِمَّةُ الْحَقِّ) that they proportion themselves to the weakest among the people (يُقَدِّرُ أَنْفُسَهُمْ بِضَعَفَةِ النَّاسِ), so that the poverty of the poor will not engender covetousness. Here is a rigorous statement of the duty of the most powerful to identify themselves, in material terms, with the most powerless. It is hard to imagine a more effective way of lessening worldliness and strengthening spirituality in a society than this deliberate self-lowering, in purely material terms, to the level of the weakest people one rules. He who could have the most chooses to have the least. The Imam implies that if a leader is to stand among the أَئِمَّةُ الْحَقِّ, he must show his attachment to اَلْحَقّ — the ultimate spiritual reality, in whose light material wealth counts for nothing. So even though the most powerful and the most powerless may both be poor in material terms, both alike have access to the treasures of the spiritual realm, in proportion to how far they grasp the truth expressed in the verse already cited: O mankind, ye are the poor before God, and God, He is the Rich, the absolutely Praiseworthy. On the level of social psychology, too, the Imam''s insistence that rulers live like the poor, borne out in his own life, is an effective way of ensuring that the unavoidable inequalities of a society will not breed envy among the poor.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the imams own poverty and severe austerity were proverbial yet this was far from a simple turning away from the world for its own sake as his exchange with an ascetic asim b ziyad makes clear asims family had complained to the imam that he denied himself too much and the imam told him to think of his family and not to cut himself off from the good things الطيبات that god has permitted asim retorted o commander of the faithful and yet here you are in your rough clothes and your coarse food the imam replied woe to you i am not like you god the exalted has made it incumbent on true leaders ايمه الحق that they proportion themselves to the weakest among the people يقدر انفسهم بضعفه الناس so that the poverty of the poor will not engender covetousness here is a rigorous statement of the duty of the most powerful to identify themselves in material terms with the most powerless it is hard to imagine a more effective way of lessening worldliness and strengthening spirituality in a society than this deliberate self lowering in purely material terms to the level of the weakest people one rules he who could have the most chooses to have the least the imam implies that if a leader is to stand among the ايمه الحق he must show his attachment to الحق the ultimate spiritual reality in whose light material wealth counts for nothing so even though the most powerful and the most powerless may both be poor in material terms both alike have access to the treasures of the spiritual realm in proportion to how far they grasp the truth expressed in the verse already cited o mankind ye are the poor before god and god he is the rich the absolutely praiseworthy on the level of social psychology too the imams insistence that rulers live like the poor borne out in his own life is an effective way of ensuring that the unavoidable inequalities of a society will not breed envy among the poor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 13, NULL, 'The compassion of justice', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the compassion of justice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 14, NULL, 'Identification with the poor also deepens a ruler''s awareness of his own unceasing need of God, helping him to live more fully in reliance on divine mercy, in hope and trust; and the natural companion of such a life is the giving of mercy and compassion to one''s fellow human beings. The capacity to act with compassion in no way conflicts with the demands of justice; it is, rather, an intrinsic part of justice understood ontologically — that is, in accordance with the fundamental nature of reality. Acting with compassion agrees with justice not only in the sense of putting things in their right place, since compassion is to be extended wherever and whenever it is called for; it also agrees with justice by being at one with the true nature of things, with the intrinsic character of the Real. This is why, at the head of every chapter of the Quran but one, the name Allah is followed by the infinitely Compassionate, the ever-Merciful (al-Rahman, al-Rahim). To put it another way, the capacity for compassion springs not so much from personal feeling as from an inborn kinship with the very nature of divine reality — that higher reality in which, as the Quran tells us, My mercy encompasseth all things'' (Al-Araf: 156); a reality in which thy Lord has prescribed for Himself mercy (Al-Anam: 54); a reality whose essential character is fixed by the principle, My mercy takes precedence over My wrath. Among the many sayings of Ali (ع) on the need to show mercy are these: The dispensing of mercy brings down [divine] mercy. As you grant mercy, so will you be granted mercy. I am astounded by the person who hopes for mercy from one above him, while he is not merciful to those beneath him.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'identification with the poor also deepens a rulers awareness of his own unceasing need of god helping him to live more fully in reliance on divine mercy in hope and trust and the natural companion of such a life is the giving of mercy and compassion to ones fellow human beings the capacity to act with compassion in no way conflicts with the demands of justice it is rather an intrinsic part of justice understood ontologically that is in accordance with the fundamental nature of reality acting with compassion agrees with justice not only in the sense of putting things in their right place since compassion is to be extended wherever and whenever it is called for it also agrees with justice by being at one with the true nature of things with the intrinsic character of the real this is why at the head of every chapter of the quran but one the name allah is followed by the infinitely compassionate the ever merciful al rahman al rahim to put it another way the capacity for compassion springs not so much from personal feeling as from an inborn kinship with the very nature of divine reality that higher reality in which as the quran tells us my mercy encompasseth all things al araf 156 a reality in which thy lord has prescribed for himself mercy al anam 54 a reality whose essential character is fixed by the principle my mercy takes precedence over my wrath among the many sayings of ali ع on the need to show mercy are these the dispensing of mercy brings down divine mercy as you grant mercy so will you be granted mercy i am astounded by the person who hopes for mercy from one above him while he is not merciful to those beneath him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 15, NULL, 'Neither the severe aspect of the nature of things nor the wrathful side of God is denied here, but both are clearly placed beneath the higher ontological principle of mercy. There is, in other words, no common measure between the merely relative things that are subject to wrath and punishment and the realities — blessed in their very nature — to which divine mercy and compassion open the way. A soul is therefore more real the more it reflects this predominance of mercy, both in its spiritual orientation and in its moral conduct. And within human society, it lies in the very nature of justice, understood in this sacred way, to lean toward compassion wherever possible, even though there must also be a place for the strict application of corrective penalty where that cannot be avoided. Indeed, in his letter the Imam goes on to instruct Malik to inflict corporal punishment on any executive officer found guilty of misappropriating public funds. The Imam''s counsels and letters are full of stern warnings of swift and severe retribution to his governors, the severity of these warnings matching his unflinching fidelity to the demands of fairness and honesty in handling public revenues. For example, he writes to Ziyad b. Abihi, deputy to the governor of Basra — Ali s cousin Abd Allah b. al-Abbas:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'neither the severe aspect of the nature of things nor the wrathful side of god is denied here but both are clearly placed beneath the higher ontological principle of mercy there is in other words no common measure between the merely relative things that are subject to wrath and punishment and the realities blessed in their very nature to which divine mercy and compassion open the way a soul is therefore more real the more it reflects this predominance of mercy both in its spiritual orientation and in its moral conduct and within human society it lies in the very nature of justice understood in this sacred way to lean toward compassion wherever possible even though there must also be a place for the strict application of corrective penalty where that cannot be avoided indeed in his letter the imam goes on to instruct malik to inflict corporal punishment on any executive officer found guilty of misappropriating public funds the imams counsels and letters are full of stern warnings of swift and severe retribution to his governors the severity of these warnings matching his unflinching fidelity to the demands of fairness and honesty in handling public revenues for example he writes to ziyad b abihi deputy to the governor of basra ali s cousin abd allah b al abbas', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 16, NULL, 'I swear by God an oath in all sincerity: if news reaches me that you have misappropriated the revenue of the Muslims, whether a small or large amount, I shall inflict a severe punishment upon you, one which will lighten your wealth, burden your back, and degrade your affair.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'i swear by god an oath in all sincerity if news reaches me that you have misappropriated the revenue of the muslims whether a small or large amount i shall inflict a severe punishment upon you one which will lighten your wealth burden your back and degrade your affair', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 17, NULL, 'The Imam was just as severe toward his own relatives at the least hint of a request for favors that would require the abuse of public funds. In one sermon he recalls an incident in which his blind brother, الْعَاقِل b. Abi Talib, asked for funds from the treasury beyond what was his due. He thought I would sell my religion for him, the Imam said. His response was to bring a red-hot piece of iron close to his brother''s body, telling him that by making such a request he was urging Ali himself to enter a far fiercer fire. In the same way, when told of the misappropriation of funds by his cousin and long-standing ally Abd Allah b. al-Abbas, the Imam answered with a thundering rebuke. He ordered his cousin: Fear God and return their property to these people. If you do not, and God gives me authority over you, I excuse myself before God in regard to you [and your wrongdoing], and I shall indeed strike you with my sword, with which whomever I have struck enters the fire [of Hell]. By God, even if Hasan and Husayn had done the like of what you have done, they would not have been granted any leniency by me.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the imam was just as severe toward his own relatives at the least hint of a request for favors that would require the abuse of public funds in one sermon he recalls an incident in which his blind brother العاقل b abi talib asked for funds from the treasury beyond what was his due he thought i would sell my religion for him the imam said his response was to bring a red hot piece of iron close to his brothers body telling him that by making such a request he was urging ali himself to enter a far fiercer fire in the same way when told of the misappropriation of funds by his cousin and long standing ally abd allah b al abbas the imam answered with a thundering rebuke he ordered his cousin fear god and return their property to these people if you do not and god gives me authority over you i excuse myself before god in regard to you and your wrongdoing and i shall indeed strike you with my sword with which whomever i have struck enters the fire of hell by god even if hasan and husayn had done the like of what you have done they would not have been granted any leniency by me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 18, NULL, 'The mention of the Prophet''s grandsons is telling. However close the tie to a wrongdoer, however exalted his standing, the principle of justice demands complete impartiality: there are to be no favors for one''s favorites. This stance is not only the exact opposite of the nepotism that had undermined the rule of the Imam''s predecessor; it is also precisely what the Quran commands: O ye who believe, be staunch in justice, witnesses of God, even though it be against yourselves, your parents or your near of kin ... (An-Nisa: 135).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the mention of the prophets grandsons is telling however close the tie to a wrongdoer however exalted his standing the principle of justice demands complete impartiality there are to be no favors for ones favorites this stance is not only the exact opposite of the nepotism that had undermined the rule of the imams predecessor it is also precisely what the quran commands o ye who believe be staunch in justice witnesses of god even though it be against yourselves your parents or your near of kin an nisa 135', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 19, NULL, 'On the theme of mercy, the passage that follows places the necessity of compassion in a universal context. It stands as one of the Imam''s most important statements on the unity of the human race and the equality of all human beings, and as a corrective to every form of prejudice, particularism, and sectarianism that would confine justice or compassion to members of one''s own group, however it is defined:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'on the theme of mercy the passage that follows places the necessity of compassion in a universal context it stands as one of the imams most important statements on the unity of the human race and the equality of all human beings and as a corrective to every form of prejudice particularism and sectarianism that would confine justice or compassion to members of ones own group however it is defined', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 20, NULL, 'Infuse your heart with mercy for the subjects, love for them and kindness toward them. Be not like a ravenous beast of prey above them, seeking to devour them. For they are of two types: either your brother in religion or your like in creation. Mistakes slip from them, defects emerge from them, deliberately or accidentally. So bestow upon them your forgiveness and your pardon, just as you would have God bestow upon you His forgiveness and pardon; for you are above them, and the one who has authority over you is above you, and God is above him who appointed you ... and through them He tests you.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'infuse your heart with mercy for the subjects love for them and kindness toward them be not like a ravenous beast of prey above them seeking to devour them for they are of two types either your brother in religion or your like in creation mistakes slip from them defects emerge from them deliberately or accidentally so bestow upon them your forgiveness and your pardon just as you would have god bestow upon you his forgiveness and pardon for you are above them and the one who has authority over you is above you and god is above him who appointed you and through them he tests you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 21, NULL, 'Here the universal reach of compassion is joined to a reminder of God''s absolute sovereignty. No man — neither a governor nor the ruler who appointed him — is anything more than a slave of God, wholly dependent upon His mercy. Anyone who stands in some position of superiority over others must therefore keep his own lowness before the Absolute always in mind. That awareness works in two directions at once: it moves him to compassion toward those below him, and it draws down upon him the compassion of God above him.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'here the universal reach of compassion is joined to a reminder of gods absolute sovereignty no man neither a governor nor the ruler who appointed him is anything more than a slave of god wholly dependent upon his mercy anyone who stands in some position of superiority over others must therefore keep his own lowness before the absolute always in mind that awareness works in two directions at once it moves him to compassion toward those below him and it draws down upon him the compassion of god above him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 22, NULL, 'One incident shows well how the Imam put justice into practice with compassion, and gives vivid form to the principle already noted, that all people are your like in creation. The Imam came upon an old, blind beggar and asked about him. He was told that the man was a Christian. He said to those around him, You have employed him until he is old and infirm, and now you refuse to help him. Give him maintenance from the public funds (بَيْتُ الْمَالِ). The words state in brief the Islamic principle of social welfare (مَصْلَحَة), which rests on redistributive justice and on a strict refusal to discriminate between Muslims and others. Social justice and religious equality flow from a compassion understood not as mere sentiment but as an intrinsic dimension of the Real; and so they become a fundamental religious duty binding on every Muslim, ruler and citizen alike.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'one incident shows well how the imam put justice into practice with compassion and gives vivid form to the principle already noted that all people are your like in creation the imam came upon an old blind beggar and asked about him he was told that the man was a christian he said to those around him you have employed him until he is old and infirm and now you refuse to help him give him maintenance from the public funds بيت المال the words state in brief the islamic principle of social welfare مصلحه which rests on redistributive justice and on a strict refusal to discriminate between muslims and others social justice and religious equality flow from a compassion understood not as mere sentiment but as an intrinsic dimension of the real and so they become a fundamental religious duty binding on every muslim ruler and citizen alike', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 23, NULL, 'The last sentence of the passage quoted earlier — which warns the governor to regard his power over his subjects not as a privilege but as a trial from God — expresses the Imam''s own attitude to rulership. In the famous sermon al-Shiqshiqiyya he says that he accepted power only as an unavoidable duty:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the last sentence of the passage quoted earlier which warns the governor to regard his power over his subjects not as a privilege but as a trial from god expresses the imams own attitude to rulership in the famous sermon al shiqshiqiyya he says that he accepted power only as an unavoidable duty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 24, NULL, 'Had God not taken from the learned [a promise] that they would not acquiesce in the rapacity of the tyrant nor in the hunger of the oppressed ... I would truly have flung its reins [that of the caliphate] back upon its withers ... and you would indeed have discovered that this world of yours is as insignificant to me as that which drips from the nose of a goat.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'had god not taken from the learned a promise that they would not acquiesce in the rapacity of the tyrant nor in the hunger of the oppressed i would truly have flung its reins that of the caliphate back upon its withers and you would indeed have discovered that this world of yours is as insignificant to me as that which drips from the nose of a goat', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 25, NULL, 'This is a striking embodiment of Plato''s ideal attitude toward power — the attitude of the true philosopher, who rules solely for the sake of the people, not regarding it as a distinction, but as an unavoidable task ... caring only for the right and the honors to be gained from that, and above all, for justice as the one indispensable thing in whose service and maintenance they will reorganize their own state.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'this is a striking embodiment of platos ideal attitude toward power the attitude of the true philosopher who rules solely for the sake of the people not regarding it as a distinction but as an unavoidable task caring only for the right and the honors to be gained from that and above all for justice as the one indispensable thing in whose service and maintenance they will reorganize their own state', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 26, NULL, 'The principle behind this approach to authority and governance is plainly that of noblesse oblige. To be granted the grace, the blessing, or the privilege of knowledge, together with a clear sense of justice, is to be placed under a correspondingly greater obligation: one''s duty to God grows in proportion to the graces bestowed. The Imam gives the principle memorable form in one of his sermons, spoken after one of his supporters had praised him: The blessings of God upon a person do not become immense without the right of God over him becoming immense.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the principle behind this approach to authority and governance is plainly that of noblesse oblige to be granted the grace the blessing or the privilege of knowledge together with a clear sense of justice is to be placed under a correspondingly greater obligation ones duty to god grows in proportion to the graces bestowed the imam gives the principle memorable form in one of his sermons spoken after one of his supporters had praised him the blessings of god upon a person do not become immense without the right of god over him becoming immense', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 27, NULL, 'A good opinion of God', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'a good opinion of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 28, NULL, 'A subtle point in the letter is easily overlooked, both because it is put so tersely and because its positive counterpart is never stated outright. It comes as the Imam instructs Malik about the kind of advisers he should keep near him, telling him to avoid misers and cowards:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'a subtle point in the letter is easily overlooked both because it is put so tersely and because its positive counterpart is never stated outright it comes as the imam instructs malik about the kind of advisers he should keep near him telling him to avoid misers and cowards', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 29, NULL, 'Sayingوَلاَ تُدْخِلَنَّ فِي مَشُورَتِكَ بَخِيلاً يَعْدِلُ بِكَ عَنِ الْفَضْلِ، وَيَعِدُكَ الْفَقْرَ، وَلاَ جَبَاناً يُضعِّفُكَ عَنِ الاْمُورِ، وَلاَ حَرِيصاً يُزَيِّنُ لَكَ الشَّرَهَ بِالْجَوْرِ، فَإِنَّ الْبُخْلَ وَالْجُبْنَ وَالْحِرْصَ غَرَائِزُ شَتَّى يَجْمَعُهَا سُوءُ الظَّنِّ بِاللهِ.', '', 'وَلاَ تُدْخِلَنَّ فِي مَشُورَتِكَ بَخِيلاً يَعْدِلُ بِكَ عَنِ الْفَضْلِ، وَيَعِدُكَ الْفَقْرَ، وَلاَ جَبَاناً يُضعِّفُكَ عَنِ الاْمُورِ، وَلاَ حَرِيصاً يُزَيِّنُ لَكَ الشَّرَهَ بِالْجَوْرِ، فَإِنَّ الْبُخْلَ وَالْجُبْنَ وَالْحِرْصَ غَرَائِزُ شَتَّى يَجْمَعُهَا سُوءُ الظَّنِّ بِاللهِ.', 'Saying', NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'sayingولا تدخلن في مشورتك بخيلا يعدل بك عن الفضل ويعدك الفقر ولا جبانا يضعفك عن الامور ولا حريصا يزين لك الشره بالجور فان البخل والجبن والحرص غرايز شتي يجمعها سوء الظن بالله', 'ولا تدخلن في مشورتك بخيلا يعدل بك عن الفضل ويعدك الفقر ولا جبانا يضعفك عن الامور ولا حريصا يزين لك الشره بالجور فان البخل والجبن والحرص غرايز شتي يجمعها سوء الظن بالله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 30, NULL, 'Do not include among those you consult a miser who would hold you back from generosity and warn you of destitution; nor a coward who would make you feel too weak for your affairs; nor a greedy person who would make the amassing of wealth by evil means seem attractive to you. For miserliness, cowardice and avarice are so many diverse inclinations, all united by a bad opinion of God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'do not include among those you consult a miser who would hold you back from generosity and warn you of destitution nor a coward who would make you feel too weak for your affairs nor a greedy person who would make the amassing of wealth by evil means seem attractive to you for miserliness cowardice and avarice are so many diverse inclinations all united by a bad opinion of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 31, NULL, 'The phrase a bad opinion (سُوءُ الظَّنِّ بِاللهِ, su al-zann) points to a basic misunderstanding of the divine nature, and from that misunderstanding a whole series of false ideas about the qualities of God follows. Each vice grows from it. The miser holds the bad opinion that God may fail to provide in time to come; the coward, that God may fail to protect him; the greedy person, that God has given him less than he needs. Seen this way, every human vice traces back to a failure of the intellect, which is itself the fruit of weak faith, or even of outright atheism — for to disbelieve in God is to deny His reality, and so to hold the worst opinion of Him. The converse follows just as plainly. A strong and deep faith produces a good opinion (حُسْنُ الظَّنّ, حَسَنَ al-zann) of God: a true perception of the divine Reality, both intellectual and contemplative. And this good opinion in turn lets the soul be genuinely, and not merely superficially, marked by the divine qualities that Reality contains. Those qualities are to be understood as transcendent — absolutely one with the divine Essence, and utterly beyond the reach of the human soul — but also as models, exemplars, patterns, and perfections that the soul is to imitate so far as it can.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the phrase a bad opinion سوء الظن بالله su al zann points to a basic misunderstanding of the divine nature and from that misunderstanding a whole series of false ideas about the qualities of god follows each vice grows from it the miser holds the bad opinion that god may fail to provide in time to come the coward that god may fail to protect him the greedy person that god has given him less than he needs seen this way every human vice traces back to a failure of the intellect which is itself the fruit of weak faith or even of outright atheism for to disbelieve in god is to deny his reality and so to hold the worst opinion of him the converse follows just as plainly a strong and deep faith produces a good opinion حسن الظن حسن al zann of god a true perception of the divine reality both intellectual and contemplative and this good opinion in turn lets the soul be genuinely and not merely superficially marked by the divine qualities that reality contains those qualities are to be understood as transcendent absolutely one with the divine essence and utterly beyond the reach of the human soul but also as models exemplars patterns and perfections that the soul is to imitate so far as it can', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 32, NULL, 'This is the very opposite of comparing oneself with God in greatness''. One must become as like God as possible, yet this growth unfolds entirely within the unchanging fact of one''s servitude to Him: it is the imitation of God''s qualities, never the personification of God. One must be generous because God is al-Karim (اَلْکَرِیم), the Generous, and compassionate and merciful because He is al-Rahman (الرحمن الرحیم), the Compassionate — not because one is generous or merciful in oneself. Yet one must be equally lowly, humble, and self-effacing, for no measure of virtue or intelligence can lessen the gulf between the Absolute and the relative, between the Creator and the created. Humility and self-effacement, and virtues like them, are so many ways of expressing the human being''s utter dependence upon God, or of manifesting the transcendence of the Absolute. Between the human and the divine, then, there is analogy of two kinds, positive and inverse. By the first, He who shows not mercy will not have mercy shown to him; by the second, as quoted above:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'this is the very opposite of comparing oneself with god in greatness one must become as like god as possible yet this growth unfolds entirely within the unchanging fact of ones servitude to him it is the imitation of gods qualities never the personification of god one must be generous because god is al karim الكريم the generous and compassionate and merciful because he is al rahman الرحمن الرحيم the compassionate not because one is generous or merciful in oneself yet one must be equally lowly humble and self effacing for no measure of virtue or intelligence can lessen the gulf between the absolute and the relative between the creator and the created humility and self effacement and virtues like them are so many ways of expressing the human beings utter dependence upon god or of manifesting the transcendence of the absolute between the human and the divine then there is analogy of two kinds positive and inverse by the first he who shows not mercy will not have mercy shown to him by the second as quoted above', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 33, NULL, 'Fatir: 15يَٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلْفُقَرَآءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُO mankind, ye are the poor before God, and God, He is the Rich, the absolutely Praiseworthy (Fatir: 15).', '', NULL, 'Fatir: 15', NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'fatir 15يايها الناس انتم الفقراء الي الله والله هو الغني الحميدo mankind ye are the poor before god and god he is the rich the absolutely praiseworthy fatir 15', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 34, NULL, 'The two must therefore be brought together: the active human virtues, which are positive reflections of the divine qualities, and the spiritual awareness of one''s own nothingness before the divine Reality, which is, on the human plane, the inverted reflection of divine transcendence. The image is that of a mirror. What one sees in a mirror is oneself, but reversed; and to look into the divine mirror is to see, on the human plane, that same inverted reflection of God''s transcendence. A human being is at once the slave and the representative of God — abduLlah (عِبَادُ اللّٰہِ) and khalifatuLlah (خَلِیفَۃُ اللَّہِ). Awareness of one''s servitude keeps one from sliding, even without knowing it, from representing God to rivalling Him in grandeur. A living commitment to representing God keeps that awareness of servitude from sinking into forgetfulness of the dignity and the responsibilities of the human state — a forgetfulness that ends in spiritual paralysis and the neglect of one''s duty toward the world. The balance between these two sides of human existence is itself a further aspect of sacred justice, of setting things in their right order, and it tunes the quality of moral action to the harmony of pure being.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the two must therefore be brought together the active human virtues which are positive reflections of the divine qualities and the spiritual awareness of ones own nothingness before the divine reality which is on the human plane the inverted reflection of divine transcendence the image is that of a mirror what one sees in a mirror is oneself but reversed and to look into the divine mirror is to see on the human plane that same inverted reflection of gods transcendence a human being is at once the slave and the representative of god abdullah عباد الله and khalifatullah خليفه الله awareness of ones servitude keeps one from sliding even without knowing it from representing god to rivalling him in grandeur a living commitment to representing god keeps that awareness of servitude from sinking into forgetfulness of the dignity and the responsibilities of the human state a forgetfulness that ends in spiritual paralysis and the neglect of ones duty toward the world the balance between these two sides of human existence is itself a further aspect of sacred justice of setting things in their right order and it tunes the quality of moral action to the harmony of pure being', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 35, NULL, 'State and society', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'state and society', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 36, NULL, 'The Imam then describes in the letter the different classes of people within state and society — the army, the scribes, the judiciary, executive officers, tax-collectors, peasants, merchants, artisans, and last of all the destitute — each with its own rights and duties. The instructions in this part of the letter may be regarded as justice at its sharpest edge in practice, taking full account of the demands of social and political life. The governor is to treat every class under his authority as holding both rights and obligations; yet the essential character of his relationship to society as a whole is once again fixed by his primary duty to God. For it is God who has assigned each class its share, and who has laid down, as a binding covenant from Him, the limits and duties of each, according to His Book or the Sunna of the Prophet:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the imam then describes in the letter the different classes of people within state and society the army the scribes the judiciary executive officers tax collectors peasants merchants artisans and last of all the destitute each with its own rights and duties the instructions in this part of the letter may be regarded as justice at its sharpest edge in practice taking full account of the demands of social and political life the governor is to treat every class under his authority as holding both rights and obligations yet the essential character of his relationship to society as a whole is once again fixed by his primary duty to god for it is god who has assigned each class its share and who has laid down as a binding covenant from him the limits and duties of each according to his book or the sunna of the prophet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 37, NULL, 'Sayingوَكُلٌّ قَدْ سَمَّى اللهُ سَهْمَهُ، وَوَضَعَ عَلَى حَدِّهِ وَفَرِيضَتِهِ فِي كِتَابِهِ أَوْ سُنَّةِ نَبِيِّهِ (صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ) عَهْداً مِنْهُ عِنْدَنَا مَحْفُوظاً', '', 'وَكُلٌّ قَدْ سَمَّى اللهُ سَهْمَهُ، وَوَضَعَ عَلَى حَدِّهِ وَفَرِيضَتِهِ فِي كِتَابِهِ أَوْ سُنَّةِ نَبِيِّهِ ( صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ) عَهْداً مِنْهُ عِنْدَنَا مَحْفُوظاً', 'Saying', NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'sayingوكل قد سمي الله سهمه ووضع علي حده وفريضته في كتابه او سنه نبيه صلي الله عليه واله عهدا منه عندنا محفوظا', 'وكل قد سمي الله سهمه ووضع علي حده وفريضته في كتابه او سنه نبيه صلي الله عليه واله عهدا منه عندنا محفوظا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 38, NULL, 'God has ordained the share of every one of them and laid down His covenant about the limits of each in His Book and the Sunna of His Prophet by way of a settlement which is preserved with us.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'god has ordained the share of every one of them and laid down his covenant about the limits of each in his book and the sunna of his prophet by way of a settlement which is preserved with us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 39, NULL, 'The governor''s duty to society is therefore part of the universal covenant between man and God — the ahd (عہد) that recurs so often in the Quran. By calling on this Quranic term to reinforce the duty of acting justly toward every class of society, the Imam knew that his words would gain immeasurably in force from their resonance with verses such as these:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the governors duty to society is therefore part of the universal covenant between man and god the ahd عهد that recurs so often in the quran by calling on this quranic term to reinforce the duty of acting justly toward every class of society the imam knew that his words would gain immeasurably in force from their resonance with verses such as these', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 40, NULL, 'Ar-Ra''d: 19-20أَفَمَن يَعْلَمُ أَنَّمَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ كَمَنْ هُوَ أَعْمَىٰٓ ۚ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَبِ ۱۹ ٱلَّذِينَ يُوفُونَ بِعَهْدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلْمِيثَقَ ۲۰Is one who knoweth that what is revealed to thee from thy Lord is the truth like one who is blind? But only men of substance take heed, those who abide by the covenant (عہد) of God, and break not the tryst (ٱلْمِيثَقَ) (Ar-Ra''d: 19-20).', '', NULL, 'Ar-Ra''d: 19-20', NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'ar rad 19 20افمن يعلم انما انزل اليك من ربك الحق كمن هو اعمي انما يتذكر اولوا الالبب ۱۹ الذين يوفون بعهد الله ولا ينقضون الميثق ۲۰is one who knoweth that what is revealed to thee from thy lord is the truth like one who is blind but only men of substance take heed those who abide by the covenant عهد of god and break not the tryst الميثق ar rad 19 20', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 41, NULL, 'and:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'and', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 42, NULL, 'Al-Isra: 34وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ ۚ وَأَوْفُوا۟ بِٱلْعَهْدِ ۖ إِنَّ ٱلْعَهْدَ كَانَ مَسْـُٔولًۭا ۳۴Approach not the wealth of the orphan except with that which is more right, until he attains maturity; and abide by the covenant, truly, the covenant will be asked about (Al-Isra: 34).', '', NULL, 'Al-Isra: 34', NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'al isra 34ولا تقربوا مال اليتيم الا بالتي هي احسن حتي يبلغ اشده واوفوا بالعهد ان العهد كان مسولا ۳۴approach not the wealth of the orphan except with that which is more right until he attains maturity and abide by the covenant truly the covenant will be asked about al isra 34', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 43, NULL, 'Significantly, just before the instructions quoted above, the Imam advises Malik to study long with the scholars'' (الَعُلَمَاءِ) and to converse long with the sages'' (الْحُكَمَاءِ):', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'significantly just before the instructions quoted above the imam advises malik to study long with the scholars العلماء and to converse long with the sages الحكماء', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 44, NULL, 'Sayingوَأَكْثِرْ مُدَارَسَةَ الَعُلَمَاءِ، وَمُنَافَثَةَ الْحُكَمَاءِ، فِي تَثْبِيتِ مَا صَلَحَ عَلَيْهِ أَمْرُ بِلاَدِكَ، وَإِقَامَةِ مَا اسْتَقَامَ بِهِ النَّاسُ قَبْلَكَ', '', 'وَأَكْثِرْ مُدَارَسَةَ الَعُلَمَاءِ، وَمُنَافَثَةَ الْحُكَمَاءِ، فِي تَثْبِيتِ مَا صَلَحَ عَلَيْهِ أَمْرُ بِلاَدِكَ، وَإِقَامَةِ مَا اسْتَقَامَ بِهِ النَّاسُ قَبْلَكَ', 'Saying', NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'sayingواكثر مدارسه العلماء ومنافثه الحكماء في تثبيت ما صلح عليه امر بلادك واقامه ما استقام به الناس قبلك', 'واكثر مدارسه العلماء ومنافثه الحكماء في تثبيت ما صلح عليه امر بلادك واقامه ما استقام به الناس قبلك');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 45, NULL, 'The purpose is to consolidate that which brings well-being to your lands, and to further entrench that which has already been established by your predecessors. The distinction between scholars and sages matters here. The scholars (عُلَمَاء) know the formal rules as set down in the Quran and the Sunna — the letter of the law, the Sharia (شریعۃ). The sages (حکما) know how to apply that knowledge; theirs is the spirit of wisdom, for wisdom is knowledge put into practice. The distinction is between the letter of the law and the spirit behind it — the spirit without which the rules cannot be applied with care and sensitivity.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the purpose is to consolidate that which brings well being to your lands and to further entrench that which has already been established by your predecessors the distinction between scholars and sages matters here the scholars علماء know the formal rules as set down in the quran and the sunna the letter of the law the sharia شريعه the sages حكما know how to apply that knowledge theirs is the spirit of wisdom for wisdom is knowledge put into practice the distinction is between the letter of the law and the spirit behind it the spirit without which the rules cannot be applied with care and sensitivity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 46, NULL, 'There follows a passage that describes, with admirable concision, how each class or segment of society depends upon the others. It begins with the army as the foundation of the state and ends with the governor himself as the center around which the different elements turn. The image is that of a wheel. The governor is the hub, working on the horizontal plane, among created things; the various classes — the army, the scribes, the executive officers, the dispensers of justice, the tax-collectors, the merchants, the artisans, and, lowest of all, the needy and destitute — are the spokes that radiate from him to the rim. Yet the hub is nothing without the axle that turns it. This horizontal center is nothing without the vertical axis that joins it, and through it the whole of society, to the Real. As a hub is useless without its link to the axle, so all the governor''s efforts are useless without his link to the Absolute, on which he must wholly depend if society is truly to flourish. The soldiers are called the fortresses'' of the subjects; and at the close of the passage the governor is told that he cannot accomplish what God requires of him without resolute determination and recourse to Him (al-ihtimam and al-istiana) — a point driven home later in the letter, where the needs of the poor are addressed. Of the instructions concerning the several classes of state and society, a few salient points are enough. For the commander of the troops, Malik is told to choose the man who is the most sincere in relation to God, the Prophet and your Imam, the purest of heart, the one most excellent in forbearance (حِلْم), who is slow to anger, happy to pardon, kind to the weak, severe with the strong; one who is neither stirred by violence nor held back by weakness.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'there follows a passage that describes with admirable concision how each class or segment of society depends upon the others it begins with the army as the foundation of the state and ends with the governor himself as the center around which the different elements turn the image is that of a wheel the governor is the hub working on the horizontal plane among created things the various classes the army the scribes the executive officers the dispensers of justice the tax collectors the merchants the artisans and lowest of all the needy and destitute are the spokes that radiate from him to the rim yet the hub is nothing without the axle that turns it this horizontal center is nothing without the vertical axis that joins it and through it the whole of society to the real as a hub is useless without its link to the axle so all the governors efforts are useless without his link to the absolute on which he must wholly depend if society is truly to flourish the soldiers are called the fortresses of the subjects and at the close of the passage the governor is told that he cannot accomplish what god requires of him without resolute determination and recourse to him al ihtimam and al istiana a point driven home later in the letter where the needs of the poor are addressed of the instructions concerning the several classes of state and society a few salient points are enough for the commander of the troops malik is told to choose the man who is the most sincere in relation to god the prophet and your imam the purest of heart the one most excellent in forbearance حلم who is slow to anger happy to pardon kind to the weak severe with the strong one who is neither stirred by violence nor held back by weakness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 47, NULL, 'This portrait of the ideal commander reflects the Imam''s own character. What stands out is its emphasis on kindness, gentleness, and forbearance — qualities not usually associated with fighting men. Here is a spiritually refined approach to an activity that, left to itself, easily tramples the norms of decency and propriety. Once again the Imam''s description of the perfect warrior resembles Plato''s description of the guardian, the protector of the ideal state. Plato states the central difficulty in raising a force to protect and defend the city as this: how are men whose nature is spirited and courageous to be kept from behaving pugnaciously to one another and to the rest of their countrymen? For they must be gentle to their own people and dangerous only to their enemies. This echoes the Quranic description of those who are with the Prophet as severe against the disbelievers, compassionate among themselves'' (Al-Fath: 29) — hence the Imam''s insistence on the gentle qualities a warrior needs as the essential complement to the martial ones.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'this portrait of the ideal commander reflects the imams own character what stands out is its emphasis on kindness gentleness and forbearance qualities not usually associated with fighting men here is a spiritually refined approach to an activity that left to itself easily tramples the norms of decency and propriety once again the imams description of the perfect warrior resembles platos description of the guardian the protector of the ideal state plato states the central difficulty in raising a force to protect and defend the city as this how are men whose nature is spirited and courageous to be kept from behaving pugnaciously to one another and to the rest of their countrymen for they must be gentle to their own people and dangerous only to their enemies this echoes the quranic description of those who are with the prophet as severe against the disbelievers compassionate among themselves al fath 29 hence the imams insistence on the gentle qualities a warrior needs as the essential complement to the martial ones', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 48, NULL, 'For the next class, the judges, the Imam names the virtues that must be present in those who dispense legal justice: they must not be confused by complexities or provoked by litigants; they must be unflinching before the truth, free from greed, unsatisfied by shallow solutions, rigorous in argument, steadfast in seeking out the truth of every matter, and proof against praise and temptation. Such people, the Imam adds, are indeed rare. He also recommends that judges be paid generously, so that any deficiency will be removed, thus diminishing the need for help from people — a condition for keeping any judiciary incorruptible.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'for the next class the judges the imam names the virtues that must be present in those who dispense legal justice they must not be confused by complexities or provoked by litigants they must be unflinching before the truth free from greed unsatisfied by shallow solutions rigorous in argument steadfast in seeking out the truth of every matter and proof against praise and temptation such people the imam adds are indeed rare he also recommends that judges be paid generously so that any deficiency will be removed thus diminishing the need for help from people a condition for keeping any judiciary incorruptible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 49, NULL, 'For the administrators, Malik is told to test their honesty before employing them and to take scrupulous care that no partiality or favouritism sways his choices. He is to keep watching and investigating their conduct; and, as noted earlier, severe punishments are to be imposed wherever there is evidence of abuse of privilege or misuse of public funds.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'for the administrators malik is told to test their honesty before employing them and to take scrupulous care that no partiality or favouritism sways his choices he is to keep watching and investigating their conduct and as noted earlier severe punishments are to be imposed wherever there is evidence of abuse of privilege or misuse of public funds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 50, NULL, 'For those who till the soil, from whom the land tax is collected, the Imam offers this wise maxim: Let your concern with the cultivation of the land outweigh your concern with the collection of the tax, for no tax will be collected if there be no cultivation. And whoever exacts the tax without cultivating the land ruins the land and destroys the people. His further urgings to attend to the needs of the tillers and to deal fairly with all who seek redress of wrongs close with this warning:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'for those who till the soil from whom the land tax is collected the imam offers this wise maxim let your concern with the cultivation of the land outweigh your concern with the collection of the tax for no tax will be collected if there be no cultivation and whoever exacts the tax without cultivating the land ruins the land and destroys the people his further urgings to attend to the needs of the tillers and to deal fairly with all who seek redress of wrongs close with this warning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 51, NULL, 'The devastation of the land only comes about through the destitution of its inhabitants; and the destitution of its inhabitants only comes about when the desire to amass wealth rules the souls of the governors, when they have doubts about what endures, and when they profit little from exemplary teachings.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the devastation of the land only comes about through the destitution of its inhabitants and the destitution of its inhabitants only comes about when the desire to amass wealth rules the souls of the governors when they have doubts about what endures and when they profit little from exemplary teachings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 52, NULL, 'As for the phrase having doubts about what endures'' (سُوءُ ظَنِّهِمْ بِالْبَقَاءِ), the commentators suggest two meanings. It may be that the governors think they will last forever, forgetting that they will die and be judged in the Hereafter; or it may be that they doubt their position will last long, and so seize whatever opportunities they can while they can. The first reading seems the more likely, so closely does it echo the following Quranic verses — which may themselves be counted among the exemplary teachings'' (عِبْرَة) the Imam names at the very end of the sentence: Woe be to every slandering backbiter, who amasseth wealth and counteth it. He thinketh that his wealth will render him immortal. Nay, but he will be flung to the all-consuming Fire (Al-Humazah: 1-4).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'as for the phrase having doubts about what endures سوء ظنهم بالبقاء the commentators suggest two meanings it may be that the governors think they will last forever forgetting that they will die and be judged in the hereafter or it may be that they doubt their position will last long and so seize whatever opportunities they can while they can the first reading seems the more likely so closely does it echo the following quranic verses which may themselves be counted among the exemplary teachings عبره the imam names at the very end of the sentence woe be to every slandering backbiter who amasseth wealth and counteth it he thinketh that his wealth will render him immortal nay but he will be flung to the all consuming fire al humazah 1 4', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 53, NULL, 'The Imam uses for the amassing of wealth the same word, jamaa, that appears in this verse. The lesson is plain: greed is a symptom of spiritual short-sightedness. Forgetfulness of what truly endures breeds greed in one degree or another — greed being, here, the craving for a false material richness in place of a true spiritual plenitude — and greed in turn breeds exploitation and oppression. Once more the Imam''s vision shows that the vice of injustice does not merely produce corruption; it is itself the product of a chain of causes rooted in a fundamental inversion of spiritual values, a failure to see the true nature of things.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the imam uses for the amassing of wealth the same word jamaa that appears in this verse the lesson is plain greed is a symptom of spiritual short sightedness forgetfulness of what truly endures breeds greed in one degree or another greed being here the craving for a false material richness in place of a true spiritual plenitude and greed in turn breeds exploitation and oppression once more the imams vision shows that the vice of injustice does not merely produce corruption it is itself the product of a chain of causes rooted in a fundamental inversion of spiritual values a failure to see the true nature of things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 54, NULL, 'Conscience, Compassion, and the Ordering of Society', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'conscience compassion and the ordering of society', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 55, NULL, 'The same vision that traces injustice to a disorder within the soul governs the more practical counsel that follows, where the ordering of society is shown to rest upon the conscience of those who hold authority. Even the advice on appointing scribes is sealed with a spiritual message. Malik is told to resist the temptation to appoint only those who have shown him their best side. The governor is to examine each candidate''s past record along with the impression he has left upon ordinary people, and then to appoint only those well known for trustworthiness. To do all this is called proof of your sincerity toward God. The choice of officials is thus no mere matter of administration; it is a measure of the ruler''s own truthfulness before his Lord, and the care he takes in it answers to God, not to the men who court his favor.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'the same vision that traces injustice to a disorder within the soul governs the more practical counsel that follows where the ordering of society is shown to rest upon the conscience of those who hold authority even the advice on appointing scribes is sealed with a spiritual message malik is told to resist the temptation to appoint only those who have shown him their best side the governor is to examine each candidates past record along with the impression he has left upon ordinary people and then to appoint only those well known for trustworthiness to do all this is called proof of your sincerity toward god the choice of officials is thus no mere matter of administration it is a measure of the rulers own truthfulness before his lord and the care he takes in it answers to god not to the men who court his favor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 56, NULL, 'Merchants and craftsmen the Imam then describes as those who bring many benefits to society and must therefore be treated well. On the whole they are a peaceable class, and should be left in peace to go about their work. Yet the vices they are prone to must be held in check: hoarding, miserliness, and cheating. Here again the outward regulation of trade rests upon an inward discernment — one that tells apart the honest labor that enriches a community from the greed that preys upon it.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'merchants and craftsmen the imam then describes as those who bring many benefits to society and must therefore be treated well on the whole they are a peaceable class and should be left in peace to go about their work yet the vices they are prone to must be held in check hoarding miserliness and cheating here again the outward regulation of trade rests upon an inward discernment one that tells apart the honest labor that enriches a community from the greed that preys upon it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'conscience, compassion, and the ordering of society', '8. Conscience, Compassion, and the Ordering of Society', 57, NULL, 'Editorial note (tradition-grounded). A note on the two words this chapter turns on. In the wider tradition, nafs derives from a root meaning "to breathe" — the nafs is the breathing self, and in spiritual usage it names the lower self or ego whose cravings the seeker must master; this is exactly the "commanding soul," al-nafs al-ammara, the chapter warns against. The covenant is worth pausing on too. The root of ahd is the language of solemn promise — to bind oneself by a pledge and be charged with keeping it. In this tradition it reaches in two directions at once: the primordial compact between God and humanity ("Am I not your Lord?") and the charge of office a ruler receives — the very pledge Ali lays on his governor Malik al-Ashtar. The chapter draws on both, and the single word shows why they are one duty: the pledge made and the trust to be kept.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 8 conscience compassion and the ordering of society', 'editorial note tradition grounded a note on the two words this chapter turns on in the wider tradition nafs derives from a root meaning to breathe the nafs is the breathing self and in spiritual usage it names the lower self or ego whose cravings the seeker must master this is exactly the commanding soul al nafs al ammara the chapter warns against the covenant is worth pausing on too the root of ahd is the language of solemn promise to bind oneself by a pledge and be charged with keeping it in this tradition it reaches in two directions at once the primordial compact between god and humanity am i not your lord and the charge of office a ruler receives the very pledge ali lays on his governor malik al ashtar the chapter draws on both and the single word shows why they are one duty the pledge made and the trust to be kept', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice for the poor and the sincerity of intention', '9. Justice for the Poor and the Sincerity of Intention', 0, NULL, 'The Imam now turns Malik toward those who most need justice, opening the passage with the exclamation "Allah, Allah" to mark its urgency. The instruction concerns those with no resources whatsoever: the destitute, the crippled, orphans, the elderly, those most in need of justice from a governor, who must be treated in such a way that "God may excuse you on the day you meet Him." The governor is to provide for all of these, and for others who are in need but too proud to beg. He ought to appoint an officer charged specifically with uncovering the needs of the most destitute and attending to them. The Imam then adds words that reach the heart of the matter: "This is onerous for the governors, and [the fulfillment of] all rights is onerous, but God makes it light for those who aspire to the Hereafter, who restrain their souls in patience, and trust in the truth of that which is promised them by God."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 9 justice for the poor and the sincerity of intention', 'the imam now turns malik toward those who most need justice opening the passage with the exclamation allah allah to mark its urgency the instruction concerns those with no resources whatsoever the destitute the crippled orphans the elderly those most in need of justice from a governor who must be treated in such a way that god may excuse you on the day you meet him the governor is to provide for all of these and for others who are in need but too proud to beg he ought to appoint an officer charged specifically with uncovering the needs of the most destitute and attending to them the imam then adds words that reach the heart of the matter this is onerous for the governors and the fulfillment of all rights is onerous but god makes it light for those who aspire to the hereafter who restrain their souls in patience and trust in the truth of that which is promised them by god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice for the poor and the sincerity of intention', '9. Justice for the Poor and the Sincerity of Intention', 1, NULL, 'It is the spiritual dimension that makes an otherwise crushing ideal workable. God''s help is assured to those whose attention is not confined to this world alone, but whose aspirations reach beyond it to the Hereafter. Only when this world is seen through to the next does a fully just attitude toward this world become possible. Those whose talab, their aspiration, does not reach beyond this world are far more likely to take the easy path and neglect the destitute; for in the purely horizontal reckoning of politics, the cost to a ruler of a policy of charity toward the poor may well outweigh any benefit he can see for himself. Here an ethics bound to a purely this-worldly assessment — to pragmatic politics or to personal interest — shows its inherent flaws. But when the sense of what is owed to the poor is charged with firm faith in God''s unfailing justice and boundless compassion, and filled with longing for the Hereafter, it generates an unflinching fidelity to the needs of the destitute and renews that fidelity again and again.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 9 justice for the poor and the sincerity of intention', 'it is the spiritual dimension that makes an otherwise crushing ideal workable gods help is assured to those whose attention is not confined to this world alone but whose aspirations reach beyond it to the hereafter only when this world is seen through to the next does a fully just attitude toward this world become possible those whose talab their aspiration does not reach beyond this world are far more likely to take the easy path and neglect the destitute for in the purely horizontal reckoning of politics the cost to a ruler of a policy of charity toward the poor may well outweigh any benefit he can see for himself here an ethics bound to a purely this worldly assessment to pragmatic politics or to personal interest shows its inherent flaws but when the sense of what is owed to the poor is charged with firm faith in gods unfailing justice and boundless compassion and filled with longing for the hereafter it generates an unflinching fidelity to the needs of the destitute and renews that fidelity again and again', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice for the poor and the sincerity of intention', '9. Justice for the Poor and the Sincerity of Intention', 2, NULL, 'Such an attitude goes far beyond conventional notions of charity or generosity. A person who has realized it to perfection cannot be swayed by any contrary suggestion rooted in self-serving pragmatism or individualism, still less in indifference or wilfulness. With this attitude firmly in place, the next quality the Imam names — patience — follows naturally. Given a concrete rather than merely notional foretaste of the absolute values at stake, patience can be sustained without limit; it no longer rests on personal will alone, but is upheld by the empowering grace that flows from heartfelt faith. The Imam completes the thought by noting that those with the right aspirations come, in consequence, to trust in the truth of God''s promise. If that promise — of His reward, His unfailing justice, His boundless compassion — is true, then the motive behind the governor''s effort to show the poor mercy and justice is immeasurably deepened. The task the Imam calls onerous — the duty to help the weak and helpless, from whom no political benefit can be gained — is transformed into an inescapable duty that follows directly from spiritual conviction. That conviction rests on the certainty that such generosity and compassion are not merely good, right, and proper, but that these virtues accord with the true and inalienable substance of ultimate reality. The moral implications of spiritual reality, and equally the spiritual consequences of virtue, are hidden from worldly rulers — by their covert prejudices at best, and their overt vices at worst. Such rulers are blind, too, to the divine promise of ultimate felicity, and equally blind to the warnings of retribution for the oppressors, al-zalimun. The zalim may be understood as one who defies the divine commandments concerning justice and, more fundamentally, violates the compassion that lies at the very heart of the divine nature.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 9 justice for the poor and the sincerity of intention', 'such an attitude goes far beyond conventional notions of charity or generosity a person who has realized it to perfection cannot be swayed by any contrary suggestion rooted in self serving pragmatism or individualism still less in indifference or wilfulness with this attitude firmly in place the next quality the imam names patience follows naturally given a concrete rather than merely notional foretaste of the absolute values at stake patience can be sustained without limit it no longer rests on personal will alone but is upheld by the empowering grace that flows from heartfelt faith the imam completes the thought by noting that those with the right aspirations come in consequence to trust in the truth of gods promise if that promise of his reward his unfailing justice his boundless compassion is true then the motive behind the governors effort to show the poor mercy and justice is immeasurably deepened the task the imam calls onerous the duty to help the weak and helpless from whom no political benefit can be gained is transformed into an inescapable duty that follows directly from spiritual conviction that conviction rests on the certainty that such generosity and compassion are not merely good right and proper but that these virtues accord with the true and inalienable substance of ultimate reality the moral implications of spiritual reality and equally the spiritual consequences of virtue are hidden from worldly rulers by their covert prejudices at best and their overt vices at worst such rulers are blind too to the divine promise of ultimate felicity and equally blind to the warnings of retribution for the oppressors al zalimun the zalim may be understood as one who defies the divine commandments concerning justice and more fundamentally violates the compassion that lies at the very heart of the divine nature', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice for the poor and the sincerity of intention', '9. Justice for the Poor and the Sincerity of Intention', 3, NULL, 'These considerations open onto the crucial question of intention. Even when the just person''s effort to live according to justice is thwarted by the uncertainties of worldly life, two things remain: the right intentions that move him, and his awareness of the immutable divine qualities that serve as the models and principles guiding his endeavor. Together these produce a real, inward "taste" of the grace that furnishes the spiritual foundation of his moral life. If God''s promise is true, and one is absolutely certain of that truth, then its effect on the soul of the sincere believer transforms a personal ethic into an unconditional imperative, and a desirable value into an undeniable reality. Morality is thus deepened by spirituality, and into it: a total way of being, one that embraces the whole of existence, within which the burden of individual duty is not only immeasurably lightened but becomes a companion to one''s taste of spiritual reality. One then acts justly out of gratitude for what one has already received — the joy of spiritual certainty — and not only out of hope for something not yet attained.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 9 justice for the poor and the sincerity of intention', 'these considerations open onto the crucial question of intention even when the just persons effort to live according to justice is thwarted by the uncertainties of worldly life two things remain the right intentions that move him and his awareness of the immutable divine qualities that serve as the models and principles guiding his endeavor together these produce a real inward taste of the grace that furnishes the spiritual foundation of his moral life if gods promise is true and one is absolutely certain of that truth then its effect on the soul of the sincere believer transforms a personal ethic into an unconditional imperative and a desirable value into an undeniable reality morality is thus deepened by spirituality and into it a total way of being one that embraces the whole of existence within which the burden of individual duty is not only immeasurably lightened but becomes a companion to ones taste of spiritual reality one then acts justly out of gratitude for what one has already received the joy of spiritual certainty and not only out of hope for something not yet attained', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice for the poor and the sincerity of intention', '9. Justice for the Poor and the Sincerity of Intention', 4, NULL, 'The Quran speaks of the reward of Paradise as something already granted to the true believer. For one whose certainty of Paradise is absolute, the future has already arrived: "We have given thee [the paradisal fountain of] al-Kawthar; so pray to thy Lord and sacrifice ..." (Al-Kawthar: 1-2). To worship God out of certainty of the blessedness to come — a blessedness that has, in one respect, already come — is well expressed in the following saying of the Imam:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 9 justice for the poor and the sincerity of intention', 'the quran speaks of the reward of paradise as something already granted to the true believer for one whose certainty of paradise is absolute the future has already arrived we have given thee the paradisal fountain of al kawthar so pray to thy lord and sacrifice al kawthar 1 2 to worship god out of certainty of the blessedness to come a blessedness that has in one respect already come is well expressed in the following saying of the imam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice for the poor and the sincerity of intention', '9. Justice for the Poor and the Sincerity of Intention', 5, NULL, 'Indeed there is a group who worship God out of desire [for something not yet attained]; and this is the worship of the merchants. And there is a group who worship God out of fear, and this is the worship of the slaves. And there is a group who worship God out of gratitude, and this is the worship of the free.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 9 justice for the poor and the sincerity of intention', 'indeed there is a group who worship god out of desire for something not yet attained and this is the worship of the merchants and there is a group who worship god out of fear and this is the worship of the slaves and there is a group who worship god out of gratitude and this is the worship of the free', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice for the poor and the sincerity of intention', '9. Justice for the Poor and the Sincerity of Intention', 6, NULL, 'The just person is further freed from the material consequences of his actions, in proportion to the uprightness and sincerity of his intentions, since in the Islamic view actions are judged not by their consequences but by their intentions. The intention is to be just — not for the sake of any earthly reward or tangible worldly result, but purely for the sake of justice itself. And this essence or principle of justice is in turn inseparable from the divine nature. For justice is one with God not simply because whatever God commands is just; rather, God commands just acts precisely because they are just, and because justice is one with His own nature: "I bear witness that He is Justice and He acts justly." Justice is not one attribute among others, something merely present in the divine nature; it is that nature. Were it only in His nature, it would stand alongside His other qualities; but because it is His very essence, all His other qualities essentially flow from it, so that His mercy no less than His wrath, His creation no less than His destruction, all proceed from His justice. If God acts justly by virtue of His very nature, which is pure justice, then the spiritual person will act justly out of a desire to conform to God''s nature, and not simply out of obedience to God''s commands, and never out of desire for any earthly reward.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 9 justice for the poor and the sincerity of intention', 'the just person is further freed from the material consequences of his actions in proportion to the uprightness and sincerity of his intentions since in the islamic view actions are judged not by their consequences but by their intentions the intention is to be just not for the sake of any earthly reward or tangible worldly result but purely for the sake of justice itself and this essence or principle of justice is in turn inseparable from the divine nature for justice is one with god not simply because whatever god commands is just rather god commands just acts precisely because they are just and because justice is one with his own nature i bear witness that he is justice and he acts justly justice is not one attribute among others something merely present in the divine nature it is that nature were it only in his nature it would stand alongside his other qualities but because it is his very essence all his other qualities essentially flow from it so that his mercy no less than his wrath his creation no less than his destruction all proceed from his justice if god acts justly by virtue of his very nature which is pure justice then the spiritual person will act justly out of a desire to conform to gods nature and not simply out of obedience to gods commands and never out of desire for any earthly reward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice for the poor and the sincerity of intention', '9. Justice for the Poor and the Sincerity of Intention', 7, NULL, 'This can be seen in any single virtue. If one speaks the truth without grasping the reason for it — that truth, الحق, is the very nature of the Creator, and that the goal in this world is to take on the qualities of that Creator — then truthfulness soon becomes situational and self-serving, open to compromise whenever circumstances seem to warrant it: I speak the truth when it benefits me and lie when lying benefits me. But once truth is seen as the nature of the divine, it becomes everlasting and eternal, and the consequences of speaking it cease to matter; one speaks it simply in emulation of الحق, the absolute truth. Virtue practiced on an ad hoc basis is no virtue at all, merely a series of pragmatic adaptations to shifting circumstances. This is why the life of Ali (ع), when studied, reflects an unflinching adherence to the divine virtues. His was a life governed not by his نفس but entirely by the divine nature of Allah, and his every celebrated action was the fruit of an irresistible attraction toward the nature of الحق. His gaze was never fixed on the action itself but on the source of the principles that generated it; by fixing his attention on the beauty of the divine nature and seeking to take it on, good actions emerged from him naturally and inevitably. As the Quran says:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 9 justice for the poor and the sincerity of intention', 'this can be seen in any single virtue if one speaks the truth without grasping the reason for it that truth الحق is the very nature of the creator and that the goal in this world is to take on the qualities of that creator then truthfulness soon becomes situational and self serving open to compromise whenever circumstances seem to warrant it i speak the truth when it benefits me and lie when lying benefits me but once truth is seen as the nature of the divine it becomes everlasting and eternal and the consequences of speaking it cease to matter one speaks it simply in emulation of الحق the absolute truth virtue practiced on an ad hoc basis is no virtue at all merely a series of pragmatic adaptations to shifting circumstances this is why the life of ali ع when studied reflects an unflinching adherence to the divine virtues his was a life governed not by his نفس but entirely by the divine nature of allah and his every celebrated action was the fruit of an irresistible attraction toward the nature of الحق his gaze was never fixed on the action itself but on the source of the principles that generated it by fixing his attention on the beauty of the divine nature and seeking to take it on good actions emerged from him naturally and inevitably as the quran says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice for the poor and the sincerity of intention', '9. Justice for the Poor and the Sincerity of Intention', 8, NULL, 'The most pious will be far removed from it [the punishment of Hell], he who giveth of his wealth to purify himself. And nobody possesseth, in the sight of such a person, any favor that might be bestowed on him as reward [for his generosity]. [His action is performed] seeking only the Countenance of his transcendent Lord, and he will be content (Al-Layl: 17-21).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 9 justice for the poor and the sincerity of intention', 'the most pious will be far removed from it the punishment of hell he who giveth of his wealth to purify himself and nobody possesseth in the sight of such a person any favor that might be bestowed on him as reward for his generosity his action is performed seeking only the countenance of his transcendent lord and he will be content al layl 17 21', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice for the poor and the sincerity of intention', '9. Justice for the Poor and the Sincerity of Intention', 9, NULL, 'The same principle appears in the description of the righteous, the abrar. Commentators on the Quran agree that the occasion of revelation, sabab al-nuzul, for the following verses was a time when Ali and his family went three days running without food. At the end of each day, just as they were about to break their fast, someone in greater need came and asked for what they had. The Quran relates this as follows: "They feed, out of love for God, the needy, the orphan and the prisoner, saying, We feed you only for the sake of God; we desire from you neither reward nor thanks''" (Al-Insan: 8-9).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 9 justice for the poor and the sincerity of intention', 'the same principle appears in the description of the righteous the abrar commentators on the quran agree that the occasion of revelation sabab al nuzul for the following verses was a time when ali and his family went three days running without food at the end of each day just as they were about to break their fast someone in greater need came and asked for what they had the quran relates this as follows they feed out of love for god the needy the orphan and the prisoner saying we feed you only for the sake of god we desire from you neither reward nor thanks al insan 8 9', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice for the poor and the sincerity of intention', '9. Justice for the Poor and the Sincerity of Intention', 10, NULL, 'In the very measure that a good action is performed for the sake of that absolute goodness which God is, the one performing it rests wholly content, untouched by the blame or praise of others, neither deflated when outward adversity thwarts his good actions nor inflated when they succeed. This understanding of the relation between action and intention illuminates the meaning of the Imam''s saying that "their hearts are in the Gardens [of Paradise] while their bodies are at work." Here again a difference emerges between a secular ethic of justice, one devoid of all spiritual or transcendental points of reference, and a spiritual conception of justice. A secular ethic stands or falls by how far it succeeds outwardly in realizing its ideal of justice; a spiritual conception already sees its ideal fulfilled in the sincere intention to be just. Even so, the fulfillment of a spiritual ideal of justice requires an unyielding struggle to achieve it, for without that struggle the intention proves to lack sincerity. Without matching action, aspirations and intentions remain shallow and purely theoretical. To hold an intention with total sincerity requires diligent, ceaseless striving toward its realization. Thus, however formidable the obstacles, however compelling the arguments of political pragmatism, however thoroughly his strenuous efforts are undone by the unavoidable pressures of outward life, the just person never despairs. He never abandons the effort to achieve justice, precisely because achieving justice in this world is not the whole of his aim. He knows that the intention is already, in an invisible but spiritually palpable way, its own fulfillment; and he knows, with sober realism, that the outward realization of any intention depends on circumstances beyond his control and, ultimately, on the grace of God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 9 justice for the poor and the sincerity of intention', 'in the very measure that a good action is performed for the sake of that absolute goodness which god is the one performing it rests wholly content untouched by the blame or praise of others neither deflated when outward adversity thwarts his good actions nor inflated when they succeed this understanding of the relation between action and intention illuminates the meaning of the imams saying that their hearts are in the gardens of paradise while their bodies are at work here again a difference emerges between a secular ethic of justice one devoid of all spiritual or transcendental points of reference and a spiritual conception of justice a secular ethic stands or falls by how far it succeeds outwardly in realizing its ideal of justice a spiritual conception already sees its ideal fulfilled in the sincere intention to be just even so the fulfillment of a spiritual ideal of justice requires an unyielding struggle to achieve it for without that struggle the intention proves to lack sincerity without matching action aspirations and intentions remain shallow and purely theoretical to hold an intention with total sincerity requires diligent ceaseless striving toward its realization thus however formidable the obstacles however compelling the arguments of political pragmatism however thoroughly his strenuous efforts are undone by the unavoidable pressures of outward life the just person never despairs he never abandons the effort to achieve justice precisely because achieving justice in this world is not the whole of his aim he knows that the intention is already in an invisible but spiritually palpable way its own fulfillment and he knows with sober realism that the outward realization of any intention depends on circumstances beyond his control and ultimately on the grace of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice for the poor and the sincerity of intention', '9. Justice for the Poor and the Sincerity of Intention', 11, NULL, 'On the surface this may seem to excuse the failure to achieve justice in society, and so to offer a subterfuge by which actual injustice is legitimated through an appeal to good but thwarted intentions. The very opposite is in fact the case. Far from betraying any lack of resolve in one moved by a sacred conception of justice, such a person''s efforts are, on the contrary, as ceaseless and unyielding as the eternal and unfailing reward in which he fervently believes. Those efforts are sustained, too, by an awareness of the subtle continuity between just intentions and the divine quality of justice, and through it the divine nature itself. An inalienable sense of the sacred sustains the just person in his pursuit of justice. The argument is not that all secular or atheistic conceptions of justice are without value; only that, set beside a sacred conception, they lack those immeasurable and inexhaustible spiritual resources that sincere faith nourishes. The theories that dominate the present age bear this out. Relativism holds that knowledge, truth, and morality are not absolute but exist only in relation to culture, society, or historical context. Nihilism rejects all religious and moral principle and holds that life is essentially meaningless. Utilitarianism counts an action right only insofar as it is useful or benefits the majority, reducing good and bad to a reckoning of gain and loss with no fundamental principle beneath them. And opportunism takes whatever advantage presents itself regardless of principle, in the manner of the manipulator who flatters, performs, and pretends, saying or doing whatever it takes to get what he wants. These are human constructions, and the world arrived at them by severing practice from principle. Whatever value may emerge from them is not rooted in the divine, so that even where they coincide with the values of faith they do so only by coincidence and remain, for all their machinery, without spirit — dead corpses. "With men this is impossible, but with God all things are possible," as Jesus says in the Gospel. Applied to the present context, that principle might be stated thus: when justice is conceived in isolation from spiritual principles, personal idealism lies acutely exposed to outward contingencies and is all too likely to disintegrate under the pressure of difficulty and disappointment; in a sacred conception of justice, by contrast, divine grace holds the incorruptible ideal of justice high above the frailties and upheavals to which both the human soul and human society are subject. The more one''s ideals are rooted in spiritual knowledge, the less one is prone to disappointment and despair in the face of difficulty.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 9 justice for the poor and the sincerity of intention', 'on the surface this may seem to excuse the failure to achieve justice in society and so to offer a subterfuge by which actual injustice is legitimated through an appeal to good but thwarted intentions the very opposite is in fact the case far from betraying any lack of resolve in one moved by a sacred conception of justice such a persons efforts are on the contrary as ceaseless and unyielding as the eternal and unfailing reward in which he fervently believes those efforts are sustained too by an awareness of the subtle continuity between just intentions and the divine quality of justice and through it the divine nature itself an inalienable sense of the sacred sustains the just person in his pursuit of justice the argument is not that all secular or atheistic conceptions of justice are without value only that set beside a sacred conception they lack those immeasurable and inexhaustible spiritual resources that sincere faith nourishes the theories that dominate the present age bear this out relativism holds that knowledge truth and morality are not absolute but exist only in relation to culture society or historical context nihilism rejects all religious and moral principle and holds that life is essentially meaningless utilitarianism counts an action right only insofar as it is useful or benefits the majority reducing good and bad to a reckoning of gain and loss with no fundamental principle beneath them and opportunism takes whatever advantage presents itself regardless of principle in the manner of the manipulator who flatters performs and pretends saying or doing whatever it takes to get what he wants these are human constructions and the world arrived at them by severing practice from principle whatever value may emerge from them is not rooted in the divine so that even where they coincide with the values of faith they do so only by coincidence and remain for all their machinery without spirit dead corpses with men this is impossible but with god all things are possible as jesus says in the gospel applied to the present context that principle might be stated thus when justice is conceived in isolation from spiritual principles personal idealism lies acutely exposed to outward contingencies and is all too likely to disintegrate under the pressure of difficulty and disappointment in a sacred conception of justice by contrast divine grace holds the incorruptible ideal of justice high above the frailties and upheavals to which both the human soul and human society are subject the more ones ideals are rooted in spiritual knowledge the less one is prone to disappointment and despair in the face of difficulty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'justice for the poor and the sincerity of intention', '9. Justice for the Poor and the Sincerity of Intention', 12, NULL, 'The importance of this ideal of justice is clearly visible in the Imam''s own experience as caliph. An unbroken succession of bloody conflicts against foes who professed Islam prevented him, outwardly, from enacting many of the principles and policies that flowed from his conception of truth and justice. Yet none of this produced dejection, despair, or cynicism, nor did it lessen in the slightest his efforts to achieve justice wherever and whenever possible. The quality of his own administration shows as much, as does the steady stream of letters and counsels to his officers and governors — the letter to Malik among them. Such despair is almost inconceivable for one whose inner life is shaped by the conviction that "No act is negligible if it is accompanied by piety." For such a person, despair is excluded by piety in the deepest sense of the word — the permanent awareness of divine Reality; for this degree of piety is the makhraj, the "way out," from the darkness of all earthly injustice. As the Imam says, "He who has pious awe toward God, for him God establishes a way out of tribulation, and a light out of darkness (اعْلَمُوا أَنَّهُ مَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا مِنَ الْفِتَنِ، وَنُورًا مِنَ الظُّلَمِ)."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 9 justice for the poor and the sincerity of intention', 'the importance of this ideal of justice is clearly visible in the imams own experience as caliph an unbroken succession of bloody conflicts against foes who professed islam prevented him outwardly from enacting many of the principles and policies that flowed from his conception of truth and justice yet none of this produced dejection despair or cynicism nor did it lessen in the slightest his efforts to achieve justice wherever and whenever possible the quality of his own administration shows as much as does the steady stream of letters and counsels to his officers and governors the letter to malik among them such despair is almost inconceivable for one whose inner life is shaped by the conviction that no act is negligible if it is accompanied by piety for such a person despair is excluded by piety in the deepest sense of the word the permanent awareness of divine reality for this degree of piety is the makhraj the way out from the darkness of all earthly injustice as the imam says he who has pious awe toward god for him god establishes a way out of tribulation and a light out of darkness اعلموا انه من يتق الله يجعل له مخرجا من الفتن ونورا من الظلم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 0, NULL, 'The lynchpin of the entire epistle now comes into view: prayer, the most important means by which the ruler takes into himself the sacred substance of all the virtues. At the opening of the letter the Imam began with a counsel to observe the obligatory prayers. Here, having stressed the need to perform every administrative task at its proper time, he instructs Malik to set apart the most excellent portion of his available time for what lies between him and God — for acts of worship and devotion. Malik is urged to give special attention to the obligatory prayers, the means by which he purifies his religion for God and makes his devotion to Him sincere. This is not merely an exhortation to perform the formal prayers. It must be understood above all in the light of a deeper meaning: the purifying of religion for God is the purifying of the very substance of the relationship between the soul and God, and it is the depth of that relationship which determines the quality of all human virtue. As the Imam put it in a saying already noted, "Know that your every act is dependent upon your prayer" — that is, every action depends upon the way one gazes upon God, who is the source of all good. What matters is not only the formal, physical, and verbal performance of the prayer, but the inward quality that accompanies it and gives it life from within. Sincerity, intensity, and frequency are essential to its efficacy. The Imam continues, "Give unto God of your vital energy in your nights and your days, and perform fully that by which you draw near to God, doing so perfectly, without becoming dull or deficient, taking your body to its limits (بَالِغًا مِنْ بَدَنِكَ مَا بَلَغَ)."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'the lynchpin of the entire epistle now comes into view prayer the most important means by which the ruler takes into himself the sacred substance of all the virtues at the opening of the letter the imam began with a counsel to observe the obligatory prayers here having stressed the need to perform every administrative task at its proper time he instructs malik to set apart the most excellent portion of his available time for what lies between him and god for acts of worship and devotion malik is urged to give special attention to the obligatory prayers the means by which he purifies his religion for god and makes his devotion to him sincere this is not merely an exhortation to perform the formal prayers it must be understood above all in the light of a deeper meaning the purifying of religion for god is the purifying of the very substance of the relationship between the soul and god and it is the depth of that relationship which determines the quality of all human virtue as the imam put it in a saying already noted know that your every act is dependent upon your prayer that is every action depends upon the way one gazes upon god who is the source of all good what matters is not only the formal physical and verbal performance of the prayer but the inward quality that accompanies it and gives it life from within sincerity intensity and frequency are essential to its efficacy the imam continues give unto god of your vital energy in your nights and your days and perform fully that by which you draw near to god doing so perfectly without becoming dull or deficient taking your body to its limits بالغا من بدنك ما بلغ', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 1, NULL, 'The whole emphasis here falls on the word taqarrub, drawing near. Divine nearness is attained most directly through deep devotion, offered up alone, in the dead of night, with all one''s heart. Once that nearness is realized, all one''s other actions in the world take on something of the spiritual quality gained through it. In this way all action can be drawn into devotion in the wider sense, all outward deeds coming to be governed by the sincere intention to give oneself to God. If the inner life is ruled by prayer, prayer comes to penetrate the outer life as well. And so the Imam, immediately after telling Malik to set apart the best of his time for God, adds, "all times [and the actions performed therein] are for God if the intention underlying them is good and if your subjects derive security as a consequence." In other words, the actions of a ruler partake of the sacred to the degree that his devotion truly reaches into the source of the sacred. There is an overflow, as it were, from the fountain of obligatory and voluntary prayer into the outward domain of action. This subtle truth is expressed in the famous hadith qudsi of the Prophet, often called the hadith of taqarrub:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'the whole emphasis here falls on the word taqarrub drawing near divine nearness is attained most directly through deep devotion offered up alone in the dead of night with all ones heart once that nearness is realized all ones other actions in the world take on something of the spiritual quality gained through it in this way all action can be drawn into devotion in the wider sense all outward deeds coming to be governed by the sincere intention to give oneself to god if the inner life is ruled by prayer prayer comes to penetrate the outer life as well and so the imam immediately after telling malik to set apart the best of his time for god adds all times and the actions performed therein are for god if the intention underlying them is good and if your subjects derive security as a consequence in other words the actions of a ruler partake of the sacred to the degree that his devotion truly reaches into the source of the sacred there is an overflow as it were from the fountain of obligatory and voluntary prayer into the outward domain of action this subtle truth is expressed in the famous hadith qudsi of the prophet often called the hadith of taqarrub', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 2, NULL, 'My slave draws near to Me through nothing I love more than that which I have made obligatory for him. My slave never ceases to draw near to Me through supererogatory acts until I love him. And when I love him, I am his hearing by which he hears, his sight by which he sees, his hand by which he grasps, and his foot by which he walks.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'my slave draws near to me through nothing i love more than that which i have made obligatory for him my slave never ceases to draw near to me through supererogatory acts until i love him and when i love him i am his hearing by which he hears his sight by which he sees his hand by which he grasps and his foot by which he walks', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 3, NULL, 'To see and to act through God can be understood, at one level, as seeing things as they really are and then acting upon that vision — which is to say, perfect justice, the placing of each thing in its proper order. This is why the Imam repeatedly draws the reader of his sermons back to the vision of God, setting that vision as the true foundation of a life of virtue. In prayer the ego is effaced through prostration, and this submission to God through self-effacement is itself what puts all things in their right place — including, and especially, the ego. The hadith qudsi marks a distinction between the obligatory and the supererogatory acts of devotion. Both are means of drawing near, but it is chiefly through the latter that the slave comes to perceive and act through the divine. The Imam''s phrase, taking your body to its limits, carries the same weight. Strenuous effort is called for; it is far from enough to perform the prayers and devotions in a mechanical or perfunctory way. "He who prays without making an effort," says the Imam, "is like one who shoots arrows without a bow." As noted earlier, the sincerity (أَخْلَاص) demanded by the Imam''s conception of the oneness of God calls for the integration of the soul, and it is in prayer that the deepest dimensions of the soul are expressed, cultivated, and integrated. The prayer must therefore be accomplished not merely with the tongue or the body, but with all that one is.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'to see and to act through god can be understood at one level as seeing things as they really are and then acting upon that vision which is to say perfect justice the placing of each thing in its proper order this is why the imam repeatedly draws the reader of his sermons back to the vision of god setting that vision as the true foundation of a life of virtue in prayer the ego is effaced through prostration and this submission to god through self effacement is itself what puts all things in their right place including and especially the ego the hadith qudsi marks a distinction between the obligatory and the supererogatory acts of devotion both are means of drawing near but it is chiefly through the latter that the slave comes to perceive and act through the divine the imams phrase taking your body to its limits carries the same weight strenuous effort is called for it is far from enough to perform the prayers and devotions in a mechanical or perfunctory way he who prays without making an effort says the imam is like one who shoots arrows without a bow as noted earlier the sincerity اخلاص demanded by the imams conception of the oneness of god calls for the integration of the soul and it is in prayer that the deepest dimensions of the soul are expressed cultivated and integrated the prayer must therefore be accomplished not merely with the tongue or the body but with all that one is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 4, NULL, 'Elsewhere, Ali (ع) points to the key supererogatory practice by which the spiritual station of nearness is attained. He does so in a commentary on the words of a Quranic verse, "… men whom neither commerce nor trade diverts from the remembrance of God" (An-Nur: 36).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'elsewhere ali ع points to the key supererogatory practice by which the spiritual station of nearness is attained he does so in a commentary on the words of a quranic verse men whom neither commerce nor trade diverts from the remembrance of god an nur 36', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 5, NULL, 'Truly God has made the remembrance (al-dhikr) a polish for the hearts, by which they hear after suffering from deafness, and see after being blind … There have always been slaves of God … with whom He held intimate discourse through their thoughts and spoke with them through the essence of their intellects. They diffused illumination through the awakened light in their hearing and their seeing and their hearts, calling unto the remembrance of the days of God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'truly god has made the remembrance al dhikr a polish for the hearts by which they hear after suffering from deafness and see after being blind there have always been slaves of god with whom he held intimate discourse through their thoughts and spoke with them through the essence of their intellects they diffused illumination through the awakened light in their hearing and their seeing and their hearts calling unto the remembrance of the days of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 6, NULL, 'The importance of the dhikr — both as a principle of awareness of ultimate reality and as a concrete means of attaining that awareness — is paramount in the Imam''s perspective. By the word dhikr the Imam means both a methodic practice of invoking a divine Name and a principle of permanent awareness of God that embraces all modes of worship, meditation, and reflection. It is to be understood not only as being aware of God or remembering God, but also as an intense mode of prolonged, prayerful meditation on ultimate reality, represented both symbolically and sacramentally by one or more of the divine Names. This remembrance is not the learning of new things from scratch. It is the recollection of ultimate reality — of the immutable, unchanging principles and divine attributes that are inherent in the very substance of our intellects, by which everything can be understood, and which are ultimately rooted in the divine nature of our Creator. This aspect of remembrance is treated more fully in the chapter that follows. The relationship between the remembrance of God and the cultivation of justice is made clear in this sermon, for the Imam describes those illuminated by the dhikr:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'the importance of the dhikr both as a principle of awareness of ultimate reality and as a concrete means of attaining that awareness is paramount in the imams perspective by the word dhikr the imam means both a methodic practice of invoking a divine name and a principle of permanent awareness of god that embraces all modes of worship meditation and reflection it is to be understood not only as being aware of god or remembering god but also as an intense mode of prolonged prayerful meditation on ultimate reality represented both symbolically and sacramentally by one or more of the divine names this remembrance is not the learning of new things from scratch it is the recollection of ultimate reality of the immutable unchanging principles and divine attributes that are inherent in the very substance of our intellects by which everything can be understood and which are ultimately rooted in the divine nature of our creator this aspect of remembrance is treated more fully in the chapter that follows the relationship between the remembrance of god and the cultivation of justice is made clear in this sermon for the imam describes those illuminated by the dhikr', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 7, NULL, 'Truly there are people who belong to the dhikr; they have adopted it in place of the world, such that "neither commerce nor trade" distracts them from it; they spend the days of their life in it … they instruct people about justice and themselves are steadfast therein.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'truly there are people who belong to the dhikr they have adopted it in place of the world such that neither commerce nor trade distracts them from it they spend the days of their life in it they instruct people about justice and themselves are steadfast therein', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 8, NULL, 'It is those souls who truly belong to the dhikr who are not only steadfast in justice but also able to instruct others in it. Putting first things first, they can show how to place all things in their proper order. Fervent, lived spirituality is therefore not opposed to dedicated activity in the world. It infuses that activity with an ethical depth springing from direct contact with the divine — a contact articulated by prayer in general and by the dhikr in particular. Just as the sincerity of a good intention is proven by the effort to realize it, so the sincerity of prayer is proven, and made efficacious, through the sustained effort to prolong and intensify it, taking your body to its limits. What this has to do with justice is plain. If justice is grasped as a quality rooted in the Real (اَلْحَقّ), then nearness to the Real cannot but draw one nearer to justice and to all positive qualities — spiritual, intellectual, and moral. The relationship between worship and justice must therefore be firmly established if the conception of justice is to be qualified as sacred. Seen thus, justice is both cause and consequence of worship. On the one hand, justice requires that everything be given its due, and God must accordingly be given His due, which entails — sacramentally — worship and prayer. On the other hand, justice emerges ethically as a consequence of that worship, as do all the virtues, in proportion to the nearness God grants His worshipper and in accordance with the radiant repercussions of that nearness.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'it is those souls who truly belong to the dhikr who are not only steadfast in justice but also able to instruct others in it putting first things first they can show how to place all things in their proper order fervent lived spirituality is therefore not opposed to dedicated activity in the world it infuses that activity with an ethical depth springing from direct contact with the divine a contact articulated by prayer in general and by the dhikr in particular just as the sincerity of a good intention is proven by the effort to realize it so the sincerity of prayer is proven and made efficacious through the sustained effort to prolong and intensify it taking your body to its limits what this has to do with justice is plain if justice is grasped as a quality rooted in the real الحق then nearness to the real cannot but draw one nearer to justice and to all positive qualities spiritual intellectual and moral the relationship between worship and justice must therefore be firmly established if the conception of justice is to be qualified as sacred seen thus justice is both cause and consequence of worship on the one hand justice requires that everything be given its due and god must accordingly be given his due which entails sacramentally worship and prayer on the other hand justice emerges ethically as a consequence of that worship as do all the virtues in proportion to the nearness god grants his worshipper and in accordance with the radiant repercussions of that nearness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 9, NULL, 'What the Imam offers, in his stress on prayer together with its essence, the remembrance of God, is a devotional principle that illuminates and, in a sense, sublimates Plato''s philosophical position. It may be seen as making explicit in spiritual terms what remains implicit in Plato''s pedagogy. After discussing the question of justice at great length, Socrates comes to the crux of the matter: the nature of the Sovereign Good, which is of paramount concern to the ideal ruler, the guardian, whose moral and intellectual formation lies at the heart of the dialogue''s practical dimension:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'what the imam offers in his stress on prayer together with its essence the remembrance of god is a devotional principle that illuminates and in a sense sublimates platos philosophical position it may be seen as making explicit in spiritual terms what remains implicit in platos pedagogy after discussing the question of justice at great length socrates comes to the crux of the matter the nature of the sovereign good which is of paramount concern to the ideal ruler the guardian whose moral and intellectual formation lies at the heart of the dialogues practical dimension', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 10, NULL, '… the highest object of knowledge is the essential nature of the Good, from which everything that is good and right derives its value for us … I need not tell you that, without that knowledge, to know everything else, however well, would be of no value to us …', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'the highest object of knowledge is the essential nature of the good from which everything that is good and right derives its value for us i need not tell you that without that knowledge to know everything else however well would be of no value to us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 11, NULL, 'Socrates declines Glaucon''s entreaties to describe the nature of this Good, offering instead to speak of its offspring. This leads him to draw an analogy between the Good and the Sun: what the Sun is to visibility, the Good is to intelligibility and being. He proceeds with the famous allegory of the cave, and then describes the educational program that would turn his prospective rulers'' attention from the world of shadows to the world of real objects — a program comprising mathematics, arithmetic, geometry, solid geometry, astronomy, harmonics, and dialectic. Having passed through all the stages of this education, "when they are fifty, those who have come safely through and proved the best at all points in action and in study must be brought at last to the goal. They must lift up the eye of the soul to gaze on that which sheds light on all things; and when they have seen the Good itself, take it as a pattern for the right ordering of the state and of the individual, themselves included." Yet Plato nowhere states what this gazing actually means, nor how it is to be achieved, nor by what means — intellective, contemplative, or methodic.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'socrates declines glaucons entreaties to describe the nature of this good offering instead to speak of its offspring this leads him to draw an analogy between the good and the sun what the sun is to visibility the good is to intelligibility and being he proceeds with the famous allegory of the cave and then describes the educational program that would turn his prospective rulers attention from the world of shadows to the world of real objects a program comprising mathematics arithmetic geometry solid geometry astronomy harmonics and dialectic having passed through all the stages of this education when they are fifty those who have come safely through and proved the best at all points in action and in study must be brought at last to the goal they must lift up the eye of the soul to gaze on that which sheds light on all things and when they have seen the good itself take it as a pattern for the right ordering of the state and of the individual themselves included yet plato nowhere states what this gazing actually means nor how it is to be achieved nor by what means intellective contemplative or methodic', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 12, NULL, 'At an important point in the Republic, Glaucon presses Socrates for a definition of the Sovereign Good: "But, Socrates, what is your account of the Good? Is it knowledge, or pleasure, or something else?" Socrates refuses a direct answer, saying after some further discussion, "I am afraid it is beyond my powers; with the best will in the world I should only disgrace myself and be laughed at." Very much in the manner of Glaucon, Dhilib al-Yamani provocatively asked Ali whether he had seen the object of his devotion. The Imam replied, "I would not be worshipping a lord whom I have not seen." Dhilib then asked, "O Commander of the Faithful! How did you see Him?" The Imam replied with the sentence that serves as one of the leitmotifs of this book: "O Dhilib! Eyes see Him not through sight''s observation, but hearts see Him through the verities of faith."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'at an important point in the republic glaucon presses socrates for a definition of the sovereign good but socrates what is your account of the good is it knowledge or pleasure or something else socrates refuses a direct answer saying after some further discussion i am afraid it is beyond my powers with the best will in the world i should only disgrace myself and be laughed at very much in the manner of glaucon dhilib al yamani provocatively asked ali whether he had seen the object of his devotion the imam replied i would not be worshipping a lord whom i have not seen dhilib then asked o commander of the faithful how did you see him the imam replied with the sentence that serves as one of the leitmotifs of this book o dhilib eyes see him not through sights observation but hearts see him through the verities of faith', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 13, NULL, 'The polishing of the heart effected by remembrance, by ذکر, comes to mind here, and this very word evokes the essence of Plato''s approach to knowledge as recollection, anamnesis. For remembrance in this sense is not the learning of something new from scratch, but the recollection of ultimate reality — of the immutable divine principles and attributes inherent in the very substance of our intellects, by which everything else can be understood. Yet in none of his dialogues does Plato make a direct reference to the devotional, methodic, or contemplative counterpart of his educational, ethical, and intellective endeavor. There is no explicitly postulated link between remembrance of the forms or ideas that engender true knowledge and the gazing upon the Good, the contemplation of that which sheds light on all things. It is not merely knowing and remembering the forms, but coming to know the Bestower of Forms — in Islam referred to by the divine Name al-Musawwir. Whether there was any spiritual method in Plato''s teaching, and if there was, why he did not divulge it, remains a matter of speculation. One answer may be gathered from a statement in Plato''s famous Seventh Letter, where he denies that any exposition can be given of the true reality of philosophy, and points instead to the disciplined way of life and rigorous daily routine that the subject demands if philosophy in the deepest sense is to be realized. "No treatise by me concerning it exists or ever will exist. It is not something that can be put into words like other branches of learning; only after long partnership in a common life devoted to this very thing does truth flash upon the soul, like a flame kindled by a leaping spark, and once it is born there, it nourishes itself thereafter." This returns to the importance of active spirituality for the practice of authentic virtue. If the Real, indefinable in its essence, is the foundation of all good, the means of assimilating the Real existentially — and not merely comprehending it mentally — cannot be set aside. Plato''s philosophical approach to the Good can be augmented and deepened by an appreciation of Ali s means of drawing near to the Real, for in the Imam''s perspective intellectual comprehension and spiritual devotion are inseparable and complementary. Integral, deep-rooted justice emerges as one of the fruits of this drawing near — just as, for Plato, gazing on that which sheds light on all things, the Good itself, results in the capacity to take the Good as a pattern for the right ordering of the state and of the individual.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'the polishing of the heart effected by remembrance by ذكر comes to mind here and this very word evokes the essence of platos approach to knowledge as recollection anamnesis for remembrance in this sense is not the learning of something new from scratch but the recollection of ultimate reality of the immutable divine principles and attributes inherent in the very substance of our intellects by which everything else can be understood yet in none of his dialogues does plato make a direct reference to the devotional methodic or contemplative counterpart of his educational ethical and intellective endeavor there is no explicitly postulated link between remembrance of the forms or ideas that engender true knowledge and the gazing upon the good the contemplation of that which sheds light on all things it is not merely knowing and remembering the forms but coming to know the bestower of forms in islam referred to by the divine name al musawwir whether there was any spiritual method in platos teaching and if there was why he did not divulge it remains a matter of speculation one answer may be gathered from a statement in platos famous seventh letter where he denies that any exposition can be given of the true reality of philosophy and points instead to the disciplined way of life and rigorous daily routine that the subject demands if philosophy in the deepest sense is to be realized no treatise by me concerning it exists or ever will exist it is not something that can be put into words like other branches of learning only after long partnership in a common life devoted to this very thing does truth flash upon the soul like a flame kindled by a leaping spark and once it is born there it nourishes itself thereafter this returns to the importance of active spirituality for the practice of authentic virtue if the real indefinable in its essence is the foundation of all good the means of assimilating the real existentially and not merely comprehending it mentally cannot be set aside platos philosophical approach to the good can be augmented and deepened by an appreciation of ali s means of drawing near to the real for in the imams perspective intellectual comprehension and spiritual devotion are inseparable and complementary integral deep rooted justice emerges as one of the fruits of this drawing near just as for plato gazing on that which sheds light on all things the good itself results in the capacity to take the good as a pattern for the right ordering of the state and of the individual', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 14, NULL, 'These pages have sketched the outlines of a spiritual approach to justice as it presents itself principally in the Imam''s letter to Malik al-Ashtar. The surface of this important subject has only been skimmed, yet the Imam''s illumination of the principle of justice — addressed in the first instance to a prospective governor of Egypt in the first century of the Islamic era — is by no means outmoded. Whether one operates in an avowedly Islamic or an overtly secular environment, whether the rule be autocratic or democratic, whether political institutions be strong or weak — wherever individuals are vested with power and authority, and by that very token exposed to the temptations that power offers, the approach to justice articulated in the Imam''s ethos will not be irrelevant. This ethos presupposes no particular form of government. It engages the universal theme of moral responsibility, but does so in terms of that which transcends the level of morality, offering insights drawn from a direct vision of ultimate spiritual realities. The principles contemplated through this vision surpass the domain of politics, and for that very reason can penetrate deeply and refashion, from above, the moral substance of political consciousness. Although the Imam''s perspective is particularly pertinent to the meeting of spirituality, morality, and governance within Islamic discourse and practice, its relevance extends to every context in which the sense of the sacred plays a part in the articulation of moral sensibility and the cultivation of political responsibility.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'these pages have sketched the outlines of a spiritual approach to justice as it presents itself principally in the imams letter to malik al ashtar the surface of this important subject has only been skimmed yet the imams illumination of the principle of justice addressed in the first instance to a prospective governor of egypt in the first century of the islamic era is by no means outmoded whether one operates in an avowedly islamic or an overtly secular environment whether the rule be autocratic or democratic whether political institutions be strong or weak wherever individuals are vested with power and authority and by that very token exposed to the temptations that power offers the approach to justice articulated in the imams ethos will not be irrelevant this ethos presupposes no particular form of government it engages the universal theme of moral responsibility but does so in terms of that which transcends the level of morality offering insights drawn from a direct vision of ultimate spiritual realities the principles contemplated through this vision surpass the domain of politics and for that very reason can penetrate deeply and refashion from above the moral substance of political consciousness although the imams perspective is particularly pertinent to the meeting of spirituality morality and governance within islamic discourse and practice its relevance extends to every context in which the sense of the sacred plays a part in the articulation of moral sensibility and the cultivation of political responsibility', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 15, NULL, 'The Imam''s letters and discourses are a vast and largely untapped source of inspired ideas, capable of illuminating the role of spiritual principles in the formation of ethical values and the shaping of political practice. In particular, any integral Islamic approach to politics and society must take into account the requirements and fruits of worship, understood in its widest sense. Sincere worship transforms the notion of the Absolute into a concrete reality, giving the soul an existential impetus and a spiritual resource that buttresses, stabilises, and deepens one''s moral life. What is derived from consciousness of the divine Reality is not so much a philosophy of ethics as a spiritual morality — an existential orientation that is at once the consequence of a lived spirituality and the cause of its continuous, dynamic, and ever-deepening realization of spiritual truth, the Real as such, اَلْحَقّ. This means that the haqq, the right due to each person or group, will be given in accordance with the principle of justice — that of putting each thing in its proper place, وَضَعَ الشَّئُی حَقَّ مَحَلِّہِ. Virtue, from such a perspective, is a form of ethical realism, where realism denotes an assimilation of spiritual reality, and morally correct behavior translates that realism into action on every plane — individual, social, and political.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'the imams letters and discourses are a vast and largely untapped source of inspired ideas capable of illuminating the role of spiritual principles in the formation of ethical values and the shaping of political practice in particular any integral islamic approach to politics and society must take into account the requirements and fruits of worship understood in its widest sense sincere worship transforms the notion of the absolute into a concrete reality giving the soul an existential impetus and a spiritual resource that buttresses stabilises and deepens ones moral life what is derived from consciousness of the divine reality is not so much a philosophy of ethics as a spiritual morality an existential orientation that is at once the consequence of a lived spirituality and the cause of its continuous dynamic and ever deepening realization of spiritual truth the real as such الحق this means that the haqq the right due to each person or group will be given in accordance with the principle of justice that of putting each thing in its proper place وضع الشيي حق محله virtue from such a perspective is a form of ethical realism where realism denotes an assimilation of spiritual reality and morally correct behavior translates that realism into action on every plane individual social and political', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 16, NULL, 'Should it be objected that this perspective is hopelessly utopian — the harsh exigencies of politics and the sublime ideals of spirituality being poles apart — the reply is this. If no effort is made to comprehend the deeper dimensions of Islamic piety and spirituality, then any ostensibly Islamic discourse, whether in politics, sociology, ethics, or any other field, is reduced to an outer shell, stripped of the inner life that gives it all its meaning and, more importantly, its transformative power. For Islamic concepts to be grasped aright, they must be assimilated not merely by the mind but by the heart; failing that, they remain mere abstractions. As the Imam insists, it is the heart — the inmost point of consciousness — that sees the true nature of things. This is why the vision of God as if one could see Him lays bare the crucial relationship between worship and virtue, between spirituality and ethics, and equally between devotion to the Creator and kindness toward His creation. One cannot have the one without the other, for to conduct oneself as though one could see God is to live in the consciousness of standing constantly in the divine presence, since even if we cannot see Him, He sees us. Without this vision there is no احسان in the ethico-spiritual sense discussed earlier, and without احسان the very integrity of the Islamic way of life is fatally undermined. It is precisely the denial and subversion of this tradition that bears ultimate responsibility for the atrocities committed by a tiny minority of Muslims in our times — people who betray the highest ideals of the Islamic ethical tradition by resorting to unbridled violence in its name, as though one might harm creation in order to please the Creator. Without احسان, religion is left acutely vulnerable, turned into an ideology, driven by individual passion and open to political manipulation. It is no surprise that those most prone to terrorism in the name of Islam have emerged from the currents most hostile to the ihsani, or mystical, tradition.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'should it be objected that this perspective is hopelessly utopian the harsh exigencies of politics and the sublime ideals of spirituality being poles apart the reply is this if no effort is made to comprehend the deeper dimensions of islamic piety and spirituality then any ostensibly islamic discourse whether in politics sociology ethics or any other field is reduced to an outer shell stripped of the inner life that gives it all its meaning and more importantly its transformative power for islamic concepts to be grasped aright they must be assimilated not merely by the mind but by the heart failing that they remain mere abstractions as the imam insists it is the heart the inmost point of consciousness that sees the true nature of things this is why the vision of god as if one could see him lays bare the crucial relationship between worship and virtue between spirituality and ethics and equally between devotion to the creator and kindness toward his creation one cannot have the one without the other for to conduct oneself as though one could see god is to live in the consciousness of standing constantly in the divine presence since even if we cannot see him he sees us without this vision there is no احسان in the ethico spiritual sense discussed earlier and without احسان the very integrity of the islamic way of life is fatally undermined it is precisely the denial and subversion of this tradition that bears ultimate responsibility for the atrocities committed by a tiny minority of muslims in our times people who betray the highest ideals of the islamic ethical tradition by resorting to unbridled violence in its name as though one might harm creation in order to please the creator without احسان religion is left acutely vulnerable turned into an ideology driven by individual passion and open to political manipulation it is no surprise that those most prone to terrorism in the name of islam have emerged from the currents most hostile to the ihsani or mystical tradition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 17, NULL, 'This returns to the devotional practices that are all too often regarded as the preserve of a minority — viewed as either mystical or misguided, depending on one''s standpoint — rather than understood as a God-given means of narrowing the gap between what one aspires to and what one is: of moving from the actual toward the ideal, of making concrete what would otherwise remain abstract, of living what is only thought about, and of rendering existentially galvanising what might otherwise be merely theoretically compelling. While the principles established here are universal in their import and applicability, it would be wrong to try to de-contextualise the Imam''s perspective by dismissing, as so much unnecessary superstructure, his repeated, insistent, and uncompromising emphasis on the imperative of prayer. The principle of justice requires that all the elements of one''s life — devotion, worship, ethics, action — be bound together in a harmonious, indissoluble, and interconnected whole, in accordance with the ideal of تَوْحِيد. And تَوْحِيد means precisely this integration, the making of many into one, so that when a person''s theory and practice have themselves become one, that person has become a true bearer of that oneness. There can be no question of detaching the domain of the virtues from that of spirituality, for in the Imam''s perspective the only true virtue is one that is rooted in, sustained by, and oriented toward the divine Reality. A virtue not so rooted — even one that happens by coincidence to mirror an Islamic value — is baseless and without spirit. Cut off from its source, it becomes situational and self-serving, open to compromise the moment circumstances warrant, and ceases to be a virtue at all, dwindling into a mere series of pragmatic adaptations to shifting conditions. Justice, together with all the other virtues, can be brought to fruition only in a soul, and in a society, permeated and penetrated by spirituality — the essence of which is the principle and practice of the remembrance of God. And this remembrance, this dhikr, is not the learning of something entirely new. It is a recollection of ultimate Reality, a recollection of the immutable principles and unchanging qualities inherent in the very substance of our intellects — principles by which everything else can be understood, and which are ultimately rooted in the divine nature of our Creator. Remembrance of this kind is nothing less than the cognitive and philosophical foundation of ethical thought in Islam. In the last analysis, it is the remembrance of God that determines the quality of human virtue. It is to the spiritual realization intended and cultivated by this remembrance that the following chapter is addressed.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'this returns to the devotional practices that are all too often regarded as the preserve of a minority viewed as either mystical or misguided depending on ones standpoint rather than understood as a god given means of narrowing the gap between what one aspires to and what one is of moving from the actual toward the ideal of making concrete what would otherwise remain abstract of living what is only thought about and of rendering existentially galvanising what might otherwise be merely theoretically compelling while the principles established here are universal in their import and applicability it would be wrong to try to de contextualise the imams perspective by dismissing as so much unnecessary superstructure his repeated insistent and uncompromising emphasis on the imperative of prayer the principle of justice requires that all the elements of ones life devotion worship ethics action be bound together in a harmonious indissoluble and interconnected whole in accordance with the ideal of توحيد and توحيد means precisely this integration the making of many into one so that when a persons theory and practice have themselves become one that person has become a true bearer of that oneness there can be no question of detaching the domain of the virtues from that of spirituality for in the imams perspective the only true virtue is one that is rooted in sustained by and oriented toward the divine reality a virtue not so rooted even one that happens by coincidence to mirror an islamic value is baseless and without spirit cut off from its source it becomes situational and self serving open to compromise the moment circumstances warrant and ceases to be a virtue at all dwindling into a mere series of pragmatic adaptations to shifting conditions justice together with all the other virtues can be brought to fruition only in a soul and in a society permeated and penetrated by spirituality the essence of which is the principle and practice of the remembrance of god and this remembrance this dhikr is not the learning of something entirely new it is a recollection of ultimate reality a recollection of the immutable principles and unchanging qualities inherent in the very substance of our intellects principles by which everything else can be understood and which are ultimately rooted in the divine nature of our creator remembrance of this kind is nothing less than the cognitive and philosophical foundation of ethical thought in islam in the last analysis it is the remembrance of god that determines the quality of human virtue it is to the spiritual realization intended and cultivated by this remembrance that the following chapter is addressed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'prayer, remembrance, and gazing on the good', '10. Prayer, Remembrance, and Gazing on the Good', 18, NULL, 'Editorial note (tradition-grounded). A note on two terms this chapter leans on. "Sincerity" here renders ikhlas, from a root meaning to be pure and free of anything mixed in; a related teaching preserved in this tradition understands it as purifying one''s intention so that worship is for God alone, with no trace of showing off blended in — which is precisely what "purifies his religion for God" asks of Malik. The Imam''s phrase for strenuous devotion, balighan min badanika ma balagha, draws on the root b-l-gh, which is about arriving — reaching a destination or driving a message home to its hearer. Read this way, "taking your body to its limits" names not mere exertion but effort that reaches its aim exactly; the same root titles Ali''s collected words, the Nahj al-Balagha, "the Way of Eloquence."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 10 prayer remembrance and gazing on the good', 'editorial note tradition grounded a note on two terms this chapter leans on sincerity here renders ikhlas from a root meaning to be pure and free of anything mixed in a related teaching preserved in this tradition understands it as purifying ones intention so that worship is for god alone with no trace of showing off blended in which is precisely what purifies his religion for god asks of malik the imams phrase for strenuous devotion balighan min badanika ma balagha draws on the root b l gh which is about arriving reaching a destination or driving a message home to its hearer read this way taking your body to its limits names not mere exertion but effort that reaches its aim exactly the same root titles alis collected words the nahj al balagha the way of eloquence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 0, NULL, 'The subject here is the meaning of dhikruLlah, the remembrance of God, one of the most fundamental principles in Islamic spirituality. Two sources open it up. The first is the sayings of the Imam, read essentially as commentaries on the Quranic idea of dhikruLlah. The second is the doctrinal formulations that arose within the mystical traditions of Islam. To speak of Ali (ع) is to speak of Islamic spirituality in its purest, most essential form. His influence is felt wherever spirituality has flourished in Islam — in the more clearly defined disciplines of Sufism and Shii Irfan, and equally in the realms of futuwwa (spiritual chivalry), the craft guilds, music, poetry and the arts. As the gate to the city of prophetic wisdom, he leaves his mark on all the noblest expressions of the spirit of Islam.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the subject here is the meaning of dhikrullah the remembrance of god one of the most fundamental principles in islamic spirituality two sources open it up the first is the sayings of the imam read essentially as commentaries on the quranic idea of dhikrullah the second is the doctrinal formulations that arose within the mystical traditions of islam to speak of ali ع is to speak of islamic spirituality in its purest most essential form his influence is felt wherever spirituality has flourished in islam in the more clearly defined disciplines of sufism and shii irfan and equally in the realms of futuwwa spiritual chivalry the craft guilds music poetry and the arts as the gate to the city of prophetic wisdom he leaves his mark on all the noblest expressions of the spirit of islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 1, NULL, 'The Sufi tradition in particular has a uniquely organic connection with the Imam. Sufi orders differ in every outward way — Shii or Sunni, Arab or Persian, Turk or Malay, Mauritanian or Bosnian — yet they are united in the figure of Ali. He stands at the summit of all the chains of affiliation (salasila, sing. silsila) through which the masters trace their spiritual lineage back to the Prophet. This same unifying role appears in relation to the most significant internal division within Islam, that between Sunnism and Shiism. The two traditions already share a vast common ground in essential beliefs and practices. Beyond that, they are drawn together in a direct and living way by a shared orientation: both look toward sanctity (وَلَايَة) and gnosis (معرفۃ) as the goal of the religious life. Seyyed Hossein Nasr writes: Islamic esotericism or gnosis crystallized into the form of Sufism in the Sunni world, while it poured into the whole structure of Shiism, especially during its early period. The esoteric core of Islam thus expresses itself in Sunni Sufism and in Shii Irfan with different accents. It takes on different forms and expressions, yet its attunement to the essence of تَوْحِيد is never fundamentally altered. According to Sayyid Haydar Amuli — one of the great figures in whom Shiism and Sufism converge — the true Shii cannot help being a Sufi, if he plumbs the mystical depths of the Imams'' teachings. The reverse holds too: the Sufi is a Shii, once he recognizes that the most important roots of Sufism lie in the Imams of the Ahl al-Bayt. These Imams were the first poles (aqtab, sing. قُطْبٌ) of the spiritual tradition, and through them the mystical blessings of the Prophet were transmitted within an initiatic setting. For Amuli, the differences of outward form between the two traditions dissolve in the fire of وَلَايَة, sanctity — the true substance and goal of both alike. And for both, Ali is the wali Allah, the friend and saint of God, beyond all others.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the sufi tradition in particular has a uniquely organic connection with the imam sufi orders differ in every outward way shii or sunni arab or persian turk or malay mauritanian or bosnian yet they are united in the figure of ali he stands at the summit of all the chains of affiliation salasila sing silsila through which the masters trace their spiritual lineage back to the prophet this same unifying role appears in relation to the most significant internal division within islam that between sunnism and shiism the two traditions already share a vast common ground in essential beliefs and practices beyond that they are drawn together in a direct and living way by a shared orientation both look toward sanctity ولايه and gnosis معرفه as the goal of the religious life seyyed hossein nasr writes islamic esotericism or gnosis crystallized into the form of sufism in the sunni world while it poured into the whole structure of shiism especially during its early period the esoteric core of islam thus expresses itself in sunni sufism and in shii irfan with different accents it takes on different forms and expressions yet its attunement to the essence of توحيد is never fundamentally altered according to sayyid haydar amuli one of the great figures in whom shiism and sufism converge the true shii cannot help being a sufi if he plumbs the mystical depths of the imams teachings the reverse holds too the sufi is a shii once he recognizes that the most important roots of sufism lie in the imams of the ahl al bayt these imams were the first poles aqtab sing قطب of the spiritual tradition and through them the mystical blessings of the prophet were transmitted within an initiatic setting for amuli the differences of outward form between the two traditions dissolve in the fire of ولايه sanctity the true substance and goal of both alike and for both ali is the wali allah the friend and saint of god beyond all others', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 2, NULL, 'The way Ali is regarded within the Sufi tradition is captured representatively by Ali Hujwiri, author of the first manual of Sufism written in Persian, the Kashf al-mahjub: Among them [the Sufis] is the son of Muhammad''s uncle, he who drowned in the ocean of trying affliction, and was consumed in the fire of loving passion (غَرِيقِ بَحْرِ بَلَاءٍ وَحَرِيقِ نَارِ وَلَاءٍ), the leader of the saints and the pure ones (مُقْتَدَایِ أَوْلِيَاءِ وَالْأَصْفِيَاءِ). In this Path he holds a place of tremendous honor and elevated degree. He had complete mastery over the precise expression of the principles of the supernal realities, such that Junayd said of him, "Ali is our master as regards principles and affliction (شَيْخُنَا فِي الْأُصُولِ وَالْبَلَاءِ)."... That is, Ali is the Imam of this Path in respect of both theoretical knowledge and practical application (اَنْدَرْ عِلْمِ وَ مُعَامَلَاتِ اِمَامِ اِیْن طَرِیْقَتْ), for the adepts of Sufism call the knowledge of this Path its "principles", while its practice is summed up in the endurance of affliction.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the way ali is regarded within the sufi tradition is captured representatively by ali hujwiri author of the first manual of sufism written in persian the kashf al mahjub among them the sufis is the son of muhammads uncle he who drowned in the ocean of trying affliction and was consumed in the fire of loving passion غريق بحر بلاء وحريق نار ولاء the leader of the saints and the pure ones مقتداي اولياء والاصفياء in this path he holds a place of tremendous honor and elevated degree he had complete mastery over the precise expression of the principles of the supernal realities such that junayd said of him ali is our master as regards principles and affliction شيخنا في الاصول والبلاء that is ali is the imam of this path in respect of both theoretical knowledge and practical application اندر علم و معاملات امام اين طريقت for the adepts of sufism call the knowledge of this path its principles while its practice is summed up in the endurance of affliction', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 3, NULL, 'The phrase endurance of affliction recalls the Imam''s description of the sages as those who befriend that by which the ignorant are estranged. One reading of that elliptical phrase is this: among the things the sages befriend and the ignorant flee is prayer — and more precisely, the act of pure concentration on the Absolute, which shuts out every other thought. Such concentration is a kind of death, for the ego and all its preoccupations are, as it were, sacrificed before the divine Reality on which the mind is fixed alone. The remembrance of God can be understood in two ways at once: as the fulfillment of that concentration, and as the path leading to the summit of spiritual realization — self-effacement before the sole reality of God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the phrase endurance of affliction recalls the imams description of the sages as those who befriend that by which the ignorant are estranged one reading of that elliptical phrase is this among the things the sages befriend and the ignorant flee is prayer and more precisely the act of pure concentration on the absolute which shuts out every other thought such concentration is a kind of death for the ego and all its preoccupations are as it were sacrificed before the divine reality on which the mind is fixed alone the remembrance of god can be understood in two ways at once as the fulfillment of that concentration and as the path leading to the summit of spiritual realization self effacement before the sole reality of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 4, NULL, 'The body of Ali s teachings sheds remarkable light on the meaning, the principle and the practice of dhikruLlah — a theme of central importance in both the Quran and the Sunna of the Prophet. The Imam''s sayings form a valuable commentary on those Quranic verses that speak of dhikr. And because the dhikr stands at the center of Sufi practice and doctrine, these sayings help explain why the Sufis regard the Imam as the first spiritual Pole (قُطْبٌ) of Sufism after the Prophet himself. The close bond between remembrance and spiritual realization is illumined from two directions: by the Imam''s own sayings, and by the expositions of the Sufi tradition — above all those of the school of Ibn al-Arabi, known in the tradition as al-Shaykh al-akbar, the greatest Master, for his towering influence on later Sufi thought. These expositions can be read as doctrinal echoes of the Imam''s dense, often elliptical pronouncements. Taken together, the Imam''s sayings and the Sufis'' elaborations bring key aspects of Islamic spirituality into sharp focus.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the body of ali s teachings sheds remarkable light on the meaning the principle and the practice of dhikrullah a theme of central importance in both the quran and the sunna of the prophet the imams sayings form a valuable commentary on those quranic verses that speak of dhikr and because the dhikr stands at the center of sufi practice and doctrine these sayings help explain why the sufis regard the imam as the first spiritual pole قطب of sufism after the prophet himself the close bond between remembrance and spiritual realization is illumined from two directions by the imams own sayings and by the expositions of the sufi tradition above all those of the school of ibn al arabi known in the tradition as al shaykh al akbar the greatest master for his towering influence on later sufi thought these expositions can be read as doctrinal echoes of the imams dense often elliptical pronouncements taken together the imams sayings and the sufis elaborations bring key aspects of islamic spirituality into sharp focus', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 5, NULL, 'The term dhikr deserves first consideration, along with the reason for its prominence in Islamic devotional practice. It is an extremely rich word, and no single English term can capture its full range. It carries the senses of remembrance, recollection, invocation, repetition, incantation and recitation; and also of memory, mention, telling, relating a story, praise, glorification, celebration, fame, eminence, honor, exhortation and warning; and it can denote the Quran itself, or any book of revelation or religion. The definition that comes closest to the spiritual principle the word expresses is the one given by al-Raghib al-Isfahani in his Quranic dictionary. He writes that dhikr is that by means of which man preserves that knowledge (معرفۃ) which he has attained, so it is akin to memory (حِفْظ), except that memory is spoken of in respect of its function of acquisition (إِحْرَاز), whereas dhikr is spoken of in respect of its function of rendering present (اِسْتِحْضَار). Dhikr is also used to refer to the presence of a thing in one''s consciousness (lit. "heart") or in one''s speech. Thus, it is said that there are two types of dhikr: dhikr of the heart and dhikr of the tongue, and each comprises two further kinds: a dhikr which follows forgetfulness, and a dhikr which does not follow forgetfulness but which, on the contrary, expresses a continuous remembering.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the term dhikr deserves first consideration along with the reason for its prominence in islamic devotional practice it is an extremely rich word and no single english term can capture its full range it carries the senses of remembrance recollection invocation repetition incantation and recitation and also of memory mention telling relating a story praise glorification celebration fame eminence honor exhortation and warning and it can denote the quran itself or any book of revelation or religion the definition that comes closest to the spiritual principle the word expresses is the one given by al raghib al isfahani in his quranic dictionary he writes that dhikr is that by means of which man preserves that knowledge معرفه which he has attained so it is akin to memory حفظ except that memory is spoken of in respect of its function of acquisition احراز whereas dhikr is spoken of in respect of its function of rendering present استحضار dhikr is also used to refer to the presence of a thing in ones consciousness lit heart or in ones speech thus it is said that there are two types of dhikr dhikr of the heart and dhikr of the tongue and each comprises two further kinds a dhikr which follows forgetfulness and a dhikr which does not follow forgetfulness but which on the contrary expresses a continuous remembering', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 6, NULL, 'Much in this definition resonates with the Imam''s own perspective. The key point is this: when the thing remembered, or rendered present to consciousness, is God, the importance of dhikruLlah as a principle becomes self-evident. DhikruLlah is to be understood, first and foremost, as a principle of awareness — a deep taking-in of the divine presence. But it must also be understood as an action, a practice or set of practices, and so as a spiritual discipline. DhikruLlah can therefore be grasped both as the end and as a means to that end: both as spiritual awareness, and as the methodic practice that cultivates that awareness. It is the Sufi tradition that works out most fully this relationship between the practice of the dhikr and the state of consciousness it intends. There the dhikr is presented in two lights at once: as a contemplative discipline centered on the methodic invocation or repetition of a Name of God, and as the cognitive consequence and mystical fruit of that discipline.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'much in this definition resonates with the imams own perspective the key point is this when the thing remembered or rendered present to consciousness is god the importance of dhikrullah as a principle becomes self evident dhikrullah is to be understood first and foremost as a principle of awareness a deep taking in of the divine presence but it must also be understood as an action a practice or set of practices and so as a spiritual discipline dhikrullah can therefore be grasped both as the end and as a means to that end both as spiritual awareness and as the methodic practice that cultivates that awareness it is the sufi tradition that works out most fully this relationship between the practice of the dhikr and the state of consciousness it intends there the dhikr is presented in two lights at once as a contemplative discipline centered on the methodic invocation or repetition of a name of god and as the cognitive consequence and mystical fruit of that discipline', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 7, NULL, 'The dhikr is thus the supreme spiritual method of the Sufis. It is a discipline that helps to realize within the heart what is already present to the mind, turning an abstract, notional grasp of certain ideas into a concrete perception of spiritual realities. Insofar as dhikruLlah means the permanent awareness of the divine Reality, it can be presented as the very essence of religion itself — that which once again binds'' (re-ligare) the human being to God, and so the reason for being of all religious rites and practices. If prayer is the core of religious practice, dhikruLlah is, as the Quran states simply, akbar — greater or greatest:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the dhikr is thus the supreme spiritual method of the sufis it is a discipline that helps to realize within the heart what is already present to the mind turning an abstract notional grasp of certain ideas into a concrete perception of spiritual realities insofar as dhikrullah means the permanent awareness of the divine reality it can be presented as the very essence of religion itself that which once again binds re ligare the human being to god and so the reason for being of all religious rites and practices if prayer is the core of religious practice dhikrullah is as the quran states simply akbar greater or greatest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 8, NULL, 'Al-''Ankabut: 45ٱتْلُ مَآ أُوحِىَ إِلَيْكَ مِنَ ٱلْكِتَبِ وَأَقِمِ ٱلصَّلَوٰةَ ۖ إِنَّ ٱلصَّلَوٰةَ تَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ ۗ وَلَذِكْرُ ٱللَّهِ أَكْبَرُ ۗ وَٱللَّهُ يَعْلَمُ مَا تَصْنَعُونَTruly, prayer keepeth [one] away from lewdness and iniquity, and the remembrance of God is greater (Al-Ankabut: 45).', '', NULL, 'Al-''Ankabut: 45', NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'al ankabut 45اتل ما اوحي اليك من الكتب واقم الصلوه ان الصلوه تنهي عن الفحشاء والمنكر ولذكر الله اكبر والله يعلم ما تصنعونtruly prayer keepeth one away from lewdness and iniquity and the remembrance of god is greater al ankabut 45', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 9, NULL, 'Many sayings of the Prophet attest to the pre-eminence of the remembrance of God. It is related that the Prophet asked his companions: Shall I not tell you about the best and purest of your works for your Lord, and the most exalted of them in your ranks, and the work that is better for you than giving silver and gold, and better for you than encountering your enemy, with you striking their necks and them striking your necks? Those he addressed replied: What is that, O emissary of God? He said, The perpetual invocation of God, exalted and glorious (ذِكْرُ اللَّهِ عَزَّ وَجَلَّ دَائِمًا).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'many sayings of the prophet attest to the pre eminence of the remembrance of god it is related that the prophet asked his companions shall i not tell you about the best and purest of your works for your lord and the most exalted of them in your ranks and the work that is better for you than giving silver and gold and better for you than encountering your enemy with you striking their necks and them striking your necks those he addressed replied what is that o emissary of god he said the perpetual invocation of god exalted and glorious ذكر الله عز وجل دايما', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 10, NULL, 'Ali affirms the same: Perpetuate the dhikr, for truly it illumines the heart, and it is the most excellent form of worship (هُوَ أَفْضَلُ الْعِبَادَةِ). The Shii tradition places much emphasis on the practice of dhikr, and records many sayings of the early Imams on the virtues of invoking the Names of God and various sacred phrases. Imam Jafar al-Sadiq described his followers specifically in these terms: Our Shia are those who, when alone (إِذَا خَلَوْا), invoke and remember God much. The khalwa — the spiritual retreat in which one seeks to be alone with God — is described by Allama Tabatabai, one of the most important masters of Shii gnosis in the twentieth century: As to the particular spiritual retreat (خَلْوَتِ خَاصٍّ) it is distancing oneself from people... it is especially required during certain types of verbal invocations (أَذْكَارٌ كَلَامِيَّةٌ)... and is considered essential by the masters of the path.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'ali affirms the same perpetuate the dhikr for truly it illumines the heart and it is the most excellent form of worship هو افضل العباده the shii tradition places much emphasis on the practice of dhikr and records many sayings of the early imams on the virtues of invoking the names of god and various sacred phrases imam jafar al sadiq described his followers specifically in these terms our shia are those who when alone اذا خلوا invoke and remember god much the khalwa the spiritual retreat in which one seeks to be alone with god is described by allama tabatabai one of the most important masters of shii gnosis in the twentieth century as to the particular spiritual retreat خلوت خاص it is distancing oneself from people it is especially required during certain types of verbal invocations اذكار كلاميه and is considered essential by the masters of the path', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 11, NULL, 'Within the Sufi tradition, the following statement on the dhikr by Shaykh Ahmad al-Alawi may be taken as entirely representative:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'within the sufi tradition the following statement on the dhikr by shaykh ahmad al alawi may be taken as entirely representative', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 12, NULL, 'Remembrance is the mightiest rule of the religion ... The law was not enjoined upon us, neither were the rites of worship ordained but for the sake of establishing the remembrance of God ... In a word, our performance of the rites of worship is considered strong or weak according to the degree of our remembrance while performing them.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'remembrance is the mightiest rule of the religion the law was not enjoined upon us neither were the rites of worship ordained but for the sake of establishing the remembrance of god in a word our performance of the rites of worship is considered strong or weak according to the degree of our remembrance while performing them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 13, NULL, 'Al-Ghazali raises the question of why the dhikr should be the most meritorious practice, when it is so simple to perform compared with all the other acts of worship, which demand so much effort. His answer is that this superiority can be fully understood only through the science of unveiling (عِلْمُ الْمُكَاشَفَةِ). What can be said from the standpoint of the practical religious sciences (عِلْمُ الْمُعَامَلَةِ) is that the most efficacious dhikr is the one performed continuously with the presence of the heart (حُضُورُ الْقَلْبِ): This is the aim of the dhikr, and it is this which takes precedence over all acts of worship; nay, it is through this that the other acts of worship are dignified; this is the ultimate fruit of the practical acts of worship. The principle of dhikruLlah thus reaches to the highest levels of religious practice, contemplative discipline and spiritual realization, and so to the very heart of Islamic spirituality. For all their variety across time and place, and all their differing perspectives and emphases, the Sufis are unanimous that dhikruLlah is central to their way. And for all their differences of name, orientation, school of thought or mode of practice, the Sufi orders are united in the pivotal figure of Ali, the one who connects every later master of the spiritual path to the Prophet himself. This meeting of the Imam and the dhikruLlah is far from accidental. The Imam explained the meaning of the dhikr and himself initiated disciples into its methodic practice; both belong to his role as spiritual guide — the wali Allah, or the Pole (قُطْبٌ) of his age — and so lie at the center of his esoteric function within the spiritual tradition of Islam, in both its Sunni and Shii forms.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'al ghazali raises the question of why the dhikr should be the most meritorious practice when it is so simple to perform compared with all the other acts of worship which demand so much effort his answer is that this superiority can be fully understood only through the science of unveiling علم المكاشفه what can be said from the standpoint of the practical religious sciences علم المعامله is that the most efficacious dhikr is the one performed continuously with the presence of the heart حضور القلب this is the aim of the dhikr and it is this which takes precedence over all acts of worship nay it is through this that the other acts of worship are dignified this is the ultimate fruit of the practical acts of worship the principle of dhikrullah thus reaches to the highest levels of religious practice contemplative discipline and spiritual realization and so to the very heart of islamic spirituality for all their variety across time and place and all their differing perspectives and emphases the sufis are unanimous that dhikrullah is central to their way and for all their differences of name orientation school of thought or mode of practice the sufi orders are united in the pivotal figure of ali the one who connects every later master of the spiritual path to the prophet himself this meeting of the imam and the dhikrullah is far from accidental the imam explained the meaning of the dhikr and himself initiated disciples into its methodic practice both belong to his role as spiritual guide the wali allah or the pole قطب of his age and so lie at the center of his esoteric function within the spiritual tradition of islam in both its sunni and shii forms', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 14, NULL, 'As for this esoteric function, very little firm historical information survives about the Imam''s initiatic role — that is, his actual initiation of disciples into the practice of invocation, known in the tradition as talqin. Just as little survives about his own initiation into the esoteric practice by the Prophet. This is hardly surprising, since the practice is, precisely, esoteric: it is not imposed on all as an obligatory rite. Rather, within both Sufism and Shii Irfan, the invocation is bestowed on those with a particular vocation, those who have received a calling to practice something beyond the obligatory rites binding on everyone. Even so, some historical accounts offer prima facie evidence of the Imam''s role in transmitting the dhikr. The people described in the earliest sources as devoted to the dhikr as a particular practice were known as close associates, if not disciples, of the Imam. His role in this initiatic domain is stressed in the orally transmitted sources of the Sufi way, and set down in several written sources too. These record reports of the dhikr passing from the Prophet to the Imam, and from him to several other disciples, who went on to initiate others into what later came to be called the way of tasawwuf.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'as for this esoteric function very little firm historical information survives about the imams initiatic role that is his actual initiation of disciples into the practice of invocation known in the tradition as talqin just as little survives about his own initiation into the esoteric practice by the prophet this is hardly surprising since the practice is precisely esoteric it is not imposed on all as an obligatory rite rather within both sufism and shii irfan the invocation is bestowed on those with a particular vocation those who have received a calling to practice something beyond the obligatory rites binding on everyone even so some historical accounts offer prima facie evidence of the imams role in transmitting the dhikr the people described in the earliest sources as devoted to the dhikr as a particular practice were known as close associates if not disciples of the imam his role in this initiatic domain is stressed in the orally transmitted sources of the sufi way and set down in several written sources too these record reports of the dhikr passing from the prophet to the imam and from him to several other disciples who went on to initiate others into what later came to be called the way of tasawwuf', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 15, NULL, 'Even though little historically sound material survives on the earliest use and transmission of dhikruLlah, there remains an extremely important body of literary evidence: the sayings recorded in the Nahj al-balagha and the Ghurar al-hikam, together with the supplications attributed to the Imam. Taken together, these sayings form a coherent corpus, a distinct body of doctrine. It offers a rich source of philosophical reflection, spiritual meditation and metaphysical insight into the nature and meaning of this practice, which holds so central a place in the mystical tradition of Islam.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'even though little historically sound material survives on the earliest use and transmission of dhikrullah there remains an extremely important body of literary evidence the sayings recorded in the nahj al balagha and the ghurar al hikam together with the supplications attributed to the imam taken together these sayings form a coherent corpus a distinct body of doctrine it offers a rich source of philosophical reflection spiritual meditation and metaphysical insight into the nature and meaning of this practice which holds so central a place in the mystical tradition of islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 16, NULL, 'These sayings shed light not only on the meaning of the practice of dhikr, but also on the philosophy and the theory of knowledge that underlie it; and they give precious hints of the fruits of its practice, its fulfillment in spiritual realization. On one side, the Imam''s sayings are an important source of commentary on the Quranic verses that treat this theme. On the other, they clearly foreshadow the more elaborate doctrines of the dhikr found in the later Sufi and Irfani traditions. They thus serve as a bridge, joining what came before the Imam — prophetic revelation — to what came after him, the work of mystical elaboration. The texts and manuals of the mystical tradition seem to make explicit what was, more often than not, implicit in the Imam''s sayings. The mystics drew out esoteric truths that the Imam had conveyed in sayings that were concise, often paradoxical and elliptical, yet always intellectually challenging and spiritually fruitful. Reflection on these sayings — read in the light of the Quran and the Sunna they illuminate, and of the later Sufi doctrine they anticipate — can bring one closer to a proper understanding of the role of dhikruLlah in the practical, operative and visionary dimensions of Islamic spirituality.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'these sayings shed light not only on the meaning of the practice of dhikr but also on the philosophy and the theory of knowledge that underlie it and they give precious hints of the fruits of its practice its fulfillment in spiritual realization on one side the imams sayings are an important source of commentary on the quranic verses that treat this theme on the other they clearly foreshadow the more elaborate doctrines of the dhikr found in the later sufi and irfani traditions they thus serve as a bridge joining what came before the imam prophetic revelation to what came after him the work of mystical elaboration the texts and manuals of the mystical tradition seem to make explicit what was more often than not implicit in the imams sayings the mystics drew out esoteric truths that the imam had conveyed in sayings that were concise often paradoxical and elliptical yet always intellectually challenging and spiritually fruitful reflection on these sayings read in the light of the quran and the sunna they illuminate and of the later sufi doctrine they anticipate can bring one closer to a proper understanding of the role of dhikrullah in the practical operative and visionary dimensions of islamic spirituality', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 17, NULL, 'Reflection on those sayings finds its most fitting starting point in the Imam''s comment on the dhikr in sermon 213 of the Nahj al-balagha. There the Imam first quotes words from verse 37 of Sura 24 of the Quran, entitled al-Nur (The Light), where the invocation of God''s Name is mentioned, and then comments on them. The words are these: men whom neither trade nor merchandise diverts from the remembrance of God. This fragment belongs to the preceding verse of light, the ayat al-nur so rich in mystical symbolism, and that bond gives the Imam''s comment a considerably deeper resonance. The Imam plainly knew that reciting the words from verse 37 would call the earlier verses to his listeners'' minds; by choosing not to quote the verse of light in full, he only sharpened the effect of the ellipsis — for such hints, implications, evocations and allusions are characteristic of Arabic balagha. His words are therefore best read alongside the verse of light in full:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'reflection on those sayings finds its most fitting starting point in the imams comment on the dhikr in sermon 213 of the nahj al balagha there the imam first quotes words from verse 37 of sura 24 of the quran entitled al nur the light where the invocation of gods name is mentioned and then comments on them the words are these men whom neither trade nor merchandise diverts from the remembrance of god this fragment belongs to the preceding verse of light the ayat al nur so rich in mystical symbolism and that bond gives the imams comment a considerably deeper resonance the imam plainly knew that reciting the words from verse 37 would call the earlier verses to his listeners minds by choosing not to quote the verse of light in full he only sharpened the effect of the ellipsis for such hints implications evocations and allusions are characteristic of arabic balagha his words are therefore best read alongside the verse of light in full', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 18, NULL, 'God is the light of the heavens and the earth. A similitude of His light is a niche wherein is a lamp; the lamp is enclosed in a glass; the glass is as it were a shining star. [The lamp] is lit [by the oil of] a blessed olive tree, neither of the East nor of the West. The oil well-nigh shineth forth, though fire touch it not. Light upon light! God guideth to His light whom He will; and God striketh similitudes for mankind; and God knoweth all things (An-Nur: 35).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'god is the light of the heavens and the earth a similitude of his light is a niche wherein is a lamp the lamp is enclosed in a glass the glass is as it were a shining star the lamp is lit by the oil of a blessed olive tree neither of the east nor of the west the oil well nigh shineth forth though fire touch it not light upon light god guideth to his light whom he will and god striketh similitudes for mankind and god knoweth all things an nur 35', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 19, NULL, 'After this verse come the following two:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'after this verse come the following two', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 20, NULL, 'In houses which God has allowed to be elevated, and that His Name be remembered therein, He is glorified in the mornings and in the evenings by men whom neither trade nor merchandise diverteth from the remembrance of God, and from establishing the prayer, and from the bestowing of alms ... (An-Nur: 36-7).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'in houses which god has allowed to be elevated and that his name be remembered therein he is glorified in the mornings and in the evenings by men whom neither trade nor merchandise diverteth from the remembrance of god and from establishing the prayer and from the bestowing of alms an nur 36 7', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 21, NULL, 'After reciting the words men whom neither trade nor merchandise diverteth from the remembrance of God, the Imam begins his sermon:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'after reciting the words men whom neither trade nor merchandise diverteth from the remembrance of god the imam begins his sermon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 22, NULL, 'Truly, God has made the remembrance (الذِّكْر) a polish for the hearts, by which they hear after being deaf, and see after being blind and yield after being resistant ... There have always been slaves of God ... with whom He held intimate discourse through their thoughts and spoke with them through the essence of their intellects. They diffused illumination through the awakened light in their hearing and their seeing and their hearts, calling unto the remembrance of the days of God ... Indeed, there is a special group (أَهْلٌ) who belong to the dhikr; they have adopted it in place of the world, such that neither trade nor merchandise distracts them from it. They spend the days of their life in it ... It is as though they had left this world for the Hereafter, and they are there, witnessing what is beyond this world ...', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'truly god has made the remembrance الذكر a polish for the hearts by which they hear after being deaf and see after being blind and yield after being resistant there have always been slaves of god with whom he held intimate discourse through their thoughts and spoke with them through the essence of their intellects they diffused illumination through the awakened light in their hearing and their seeing and their hearts calling unto the remembrance of the days of god indeed there is a special group اهل who belong to the dhikr they have adopted it in place of the world such that neither trade nor merchandise distracts them from it they spend the days of their life in it it is as though they had left this world for the hereafter and they are there witnessing what is beyond this world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 23, NULL, 'The weight of this passage lies in the Imam''s description of the dhikr as a polish for hearts'' (جِلَاءً لِلْقُلُوبِ), set beside his reference to the awakened light in the hearing, sight and hearts of those who have applied that polish. The link between the illumination of the heart and the verse of light is clear. The remembrance of God discloses the latent light of the heart, and the light within then shines together with the light from on high: light upon light. Once the heart is illumined, every other faculty shares in the luminosity the invocation generates, and so there is, again, further light upon light. The very word given for polish, jila, can itself be read as an implicit commentary on the light verse, for it derives from the verb jala, whose primary meaning is to become clear — exposed to view, disclosed, brought to light. The Quran speaks of the night when it enshroudeth in darkness, and the day when it shineth forth in brightness (إِذَا تَجَلَّى) (Al-Layl: 1-2), and likewise: By the day, as it bringeth to light [the sun] (إِذَا جَلَّىٰهَا) (Ash-Shams: 3). The consciousness that lies hidden within the heart is brought to light through the polishing worked by the remembrance of God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the weight of this passage lies in the imams description of the dhikr as a polish for hearts جلاء للقلوب set beside his reference to the awakened light in the hearing sight and hearts of those who have applied that polish the link between the illumination of the heart and the verse of light is clear the remembrance of god discloses the latent light of the heart and the light within then shines together with the light from on high light upon light once the heart is illumined every other faculty shares in the luminosity the invocation generates and so there is again further light upon light the very word given for polish jila can itself be read as an implicit commentary on the light verse for it derives from the verb jala whose primary meaning is to become clear exposed to view disclosed brought to light the quran speaks of the night when it enshroudeth in darkness and the day when it shineth forth in brightness اذا تجلي al layl 1 2 and likewise by the day as it bringeth to light the sun اذا جلاها ash shams 3 the consciousness that lies hidden within the heart is brought to light through the polishing worked by the remembrance of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 24, NULL, 'The concern here is to clarify the organ of consciousness, the spiritual heart — both so that it may function as a mirror reflecting truths from above, and so that its own hidden depths are revealed, disclosing truths from within: those concealed contents of consciousness the Imam calls the buried treasures of the intellect (دَفَائِنُ الْعُقُولِ). The dhikr is presented as a means of purifying this spiritual mode of perception, the heart, which cannot simply be identified with the rational faculty, still less with the organs of sensory perception, as discussed in Chapter 1.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the concern here is to clarify the organ of consciousness the spiritual heart both so that it may function as a mirror reflecting truths from above and so that its own hidden depths are revealed disclosing truths from within those concealed contents of consciousness the imam calls the buried treasures of the intellect دفاين العقول the dhikr is presented as a means of purifying this spiritual mode of perception the heart which cannot simply be identified with the rational faculty still less with the organs of sensory perception as discussed in chapter 1', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 25, NULL, 'The Quran points to the deeper significance of the heart and its distinctive mode of vision: Have they not traveled in the land, that they might have hearts with which to comprehend, and ears with which to hear? Indeed, it is not the eyes that are blind, but blind are the hearts that are in the breasts'' (Al-Hajj: 46). The outward sight of the eye reaches only the surface of things, whereas the heart''s proper vision is an insight that pierces beneath that surface to the reality concealed there. And again: They have hearts with which they understand not, eyes with which they see not, ears with which they hear not. They are like cattle, nay, even further astray. They are the heedless (الْغَافِلُونَ) (Al-Araf: 179). That closing reference to the heedless'', the ghafilun, returns to the dhikr, for the ghafil is the very opposite of the dhakir, the rememberer; and the verse immediately following is one of the most important methodic foundations of the mystical practice of dhikr: Unto God belong the most beautiful Names, so call Him by them. And leave behind those who desecrate His Names; they will be requited for what they do (Al-Araf: 180). The bond between remembrance and the heart is affirmed plainly in these verses: ... Those who believe and whose hearts are at peace in the remembrance of God, is it not in the remembrance of God that hearts are at peace? (Ar-Ra''d: 28); Truly, therein is a reminder (ذِكْرَى) for him who hath a heart (Qaf: 37); Those are true believers whose hearts quake with awe when God is invoked (Al-Anfal: 2); Is he whose breast God hath opened up to submission (اِسْلَام), such that he followeth a light from his Lord [like he who remains closed to submission and in darkness]? So woe be to those whose hearts are hardened against the remembrance of God, they are in plain error (Az-Zumar: 22).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the quran points to the deeper significance of the heart and its distinctive mode of vision have they not traveled in the land that they might have hearts with which to comprehend and ears with which to hear indeed it is not the eyes that are blind but blind are the hearts that are in the breasts al hajj 46 the outward sight of the eye reaches only the surface of things whereas the hearts proper vision is an insight that pierces beneath that surface to the reality concealed there and again they have hearts with which they understand not eyes with which they see not ears with which they hear not they are like cattle nay even further astray they are the heedless الغافلون al araf 179 that closing reference to the heedless the ghafilun returns to the dhikr for the ghafil is the very opposite of the dhakir the rememberer and the verse immediately following is one of the most important methodic foundations of the mystical practice of dhikr unto god belong the most beautiful names so call him by them and leave behind those who desecrate his names they will be requited for what they do al araf 180 the bond between remembrance and the heart is affirmed plainly in these verses those who believe and whose hearts are at peace in the remembrance of god is it not in the remembrance of god that hearts are at peace ar rad 28 truly therein is a reminder ذكري for him who hath a heart qaf 37 those are true believers whose hearts quake with awe when god is invoked al anfal 2 is he whose breast god hath opened up to submission اسلام such that he followeth a light from his lord like he who remains closed to submission and in darkness so woe be to those whose hearts are hardened against the remembrance of god they are in plain error az zumar 22', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 26, NULL, 'By contrast, the verse that follows speaks of hearts that soften to dhikruLlah: God hath revealed the most beautiful saying, a Book [containing] similitudes and paired [threats and promises] at which the skins of those who fear their Lord quiver; then their skins and their hearts soften to the remembrance of God (Az-Zumar: 23).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'by contrast the verse that follows speaks of hearts that soften to dhikrullah god hath revealed the most beautiful saying a book containing similitudes and paired threats and promises at which the skins of those who fear their lord quiver then their skins and their hearts soften to the remembrance of god az zumar 23', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 27, NULL, 'The Imam''s comment on verse 37 of the Light chapter should therefore be understood as shedding light on every Quranic verse that refers to the understanding, or spiritual vision, to which the heart has access in principle, and that names dhikruLlah as the means of turning this potentiality into actuality. The heart needs to be polished by the invocation of God. The Imam''s comment echoes and reinforces a saying of the Prophet often quoted in Sufi circles: For everything there is a polish (صِقَالَةٌ), and the polish of the hearts is the dhikruLlah.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the imams comment on verse 37 of the light chapter should therefore be understood as shedding light on every quranic verse that refers to the understanding or spiritual vision to which the heart has access in principle and that names dhikrullah as the means of turning this potentiality into actuality the heart needs to be polished by the invocation of god the imams comment echoes and reinforces a saying of the prophet often quoted in sufi circles for everything there is a polish صقاله and the polish of the hearts is the dhikrullah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 28, NULL, 'What is being referred to here is an actual discipline — a practice, an action, or a regular series of actions — though this in no way excludes the meaning of dhikr as awareness, as a state of recollectedness in the divine presence, a disposition of soul shaped by the consciousness that if you cannot see Him, He sees you. The polishing in question can be understood in two ways at once: as the work of purifying thought through reflection and meditation, and as a regular methodic practice — whether that takes the form of glorification (تَسْبِيح), magnification (تَمْجِيدٌ), praise (تَحْمِيدٌ), sanctification (تَقْدِيس), the declaration of divine unity (تَهْلِيلٌ), or the dhikr in the strict sense, the invocation of God''s Names, by which the rust of forgetfulness is removed. Ali also refers in his comment to a particular group who belong to the dhikr, calling them an ahl. The Prophet likewise spoke of the ahl الذِّكْر: God has angels who rove the pathways, seeking out the ahl الذِّكْر, and when they find a group of people (قَوْمٌ) invoking God, they call out to one another, "Come to that which you desire!"', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'what is being referred to here is an actual discipline a practice an action or a regular series of actions though this in no way excludes the meaning of dhikr as awareness as a state of recollectedness in the divine presence a disposition of soul shaped by the consciousness that if you cannot see him he sees you the polishing in question can be understood in two ways at once as the work of purifying thought through reflection and meditation and as a regular methodic practice whether that takes the form of glorification تسبيح magnification تمجيد praise تحميد sanctification تقديس the declaration of divine unity تهليل or the dhikr in the strict sense the invocation of gods names by which the rust of forgetfulness is removed ali also refers in his comment to a particular group who belong to the dhikr calling them an ahl the prophet likewise spoke of the ahl الذكر god has angels who rove the pathways seeking out the ahl الذكر and when they find a group of people قوم invoking god they call out to one another come to that which you desire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 29, NULL, 'Later in time, one of the greatest members of the qawm — one of the names by which the Sufis call themselves — gave poetic expression to the image of the heart polished by the dhikr. It is the custom of kings, Rumi tells in the Mathnawi, to place the Sufis right before them: for they are a mirror for the soul, and better than a mirror — breasts polished by invocation and meditation, such that the mirror of the heart receives the pure, virginal image.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'later in time one of the greatest members of the qawm one of the names by which the sufis call themselves gave poetic expression to the image of the heart polished by the dhikr it is the custom of kings rumi tells in the mathnawi to place the sufis right before them for they are a mirror for the soul and better than a mirror breasts polished by invocation and meditation such that the mirror of the heart receives the pure virginal image', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 30, NULL, 'Another aspect of the heart''s polishing deserves reflection: the nature of the vision experienced by the heart that the dhikr purifies and faith vivifies. In the Imam''s perspective this vision is divinely inspired; it is nothing less than the spiritual vision of God already referred to: Eyes see Him not through sight''s observation, but hearts see Him through the verities of faith.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'another aspect of the hearts polishing deserves reflection the nature of the vision experienced by the heart that the dhikr purifies and faith vivifies in the imams perspective this vision is divinely inspired it is nothing less than the spiritual vision of god already referred to eyes see him not through sights observation but hearts see him through the verities of faith', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 31, NULL, 'In another saying, the Imam calls pure hearts'' the places'' from which God can be seen: so whoever purifies his heart sees God. The connection between the purification of the heart and the remembrance of God is confirmed in this saying: Where are they whose actions are accomplished purely for God, and who purify their hearts [so that they become] places for the remembrance of God?', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'in another saying the imam calls pure hearts the places from which god can be seen so whoever purifies his heart sees god the connection between the purification of the heart and the remembrance of god is confirmed in this saying where are they whose actions are accomplished purely for god and who purify their hearts so that they become places for the remembrance of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 32, NULL, 'Taken together, these sayings of the Imam on the impact of the dhikr upon the heart can be read as a commentary on the important hadith qudsi cited in Chapter 2: My slave never ceases to draw near to Me through supererogatory acts (نَوَافِلُ) until I love him. And when I love him, I am his hearing by which he hears, his sight by which he sees, his hand by which he grasps, and his foot by which he walks. The Sufis regard this divine utterance as defining a foundational principle of their metaphysical doctrine, while at the same time pointing to the goal of their mystical practice.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'taken together these sayings of the imam on the impact of the dhikr upon the heart can be read as a commentary on the important hadith qudsi cited in chapter 2 my slave never ceases to draw near to me through supererogatory acts نوافل until i love him and when i love him i am his hearing by which he hears his sight by which he sees his hand by which he grasps and his foot by which he walks the sufis regard this divine utterance as defining a foundational principle of their metaphysical doctrine while at the same time pointing to the goal of their mystical practice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 33, NULL, 'A mutual confirmation stands between the Imam''s saying and the hadith qudsi. Through the dhikr — the supererogatory act par excellence — the individual''s perceptions and actions are mysteriously assimilated to the divine Reality, and the heart thereby attains spiritual vision. But the heart, as the center of consciousness, can then no longer be regarded in its purely relative, human dimension. Its inmost essence, or secret (سِرٌّ), belongs in truth to the divine, and this alone can see as God sees and, ultimately, see God Himself. As the Sufi master Abu Talib al-Makki wrote, None sees Him to whom nothing is similar but Him to whom nothing is similar. If God does indeed enter into the human acts of perception proper to the outward senses, then all the more must the supreme act of spiritual awareness, the vision of God, be in reality not a vision of God by man but a vision of God by God, effected through the individual''s heart rather than by it. The Imam says, Know God through God (اِعْرِفُوا اللهَ بِاللهِ). In the final analysis, then, it is God who both sees'' and is seen. On a typical Sufi reading of the Quranic verse by a witnesser and that which is witnessed (Al-Buruj: 3), it is God Himself who is both the witnesser (شَاهِدٌ) and the witnessed (مَشْهُود). Al-Kashani, for example, writes in his esoteric exegesis — until quite recently wrongly attributed to Ibn al-Arabi — that the human witness is effaced in his witnessing, so that it is God who witnesses Himself through the individual whose separative consciousness is extinguished, such that He is the identity of the witness, there being no difference between the two except in terms of notional expression.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'a mutual confirmation stands between the imams saying and the hadith qudsi through the dhikr the supererogatory act par excellence the individuals perceptions and actions are mysteriously assimilated to the divine reality and the heart thereby attains spiritual vision but the heart as the center of consciousness can then no longer be regarded in its purely relative human dimension its inmost essence or secret سر belongs in truth to the divine and this alone can see as god sees and ultimately see god himself as the sufi master abu talib al makki wrote none sees him to whom nothing is similar but him to whom nothing is similar if god does indeed enter into the human acts of perception proper to the outward senses then all the more must the supreme act of spiritual awareness the vision of god be in reality not a vision of god by man but a vision of god by god effected through the individuals heart rather than by it the imam says know god through god اعرفوا الله بالله in the final analysis then it is god who both sees and is seen on a typical sufi reading of the quranic verse by a witnesser and that which is witnessed al buruj 3 it is god himself who is both the witnesser شاهد and the witnessed مشهود al kashani for example writes in his esoteric exegesis until quite recently wrongly attributed to ibn al arabi that the human witness is effaced in his witnessing so that it is god who witnesses himself through the individual whose separative consciousness is extinguished such that he is the identity of the witness there being no difference between the two except in terms of notional expression', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 34, NULL, 'This anticipates the final section, where the ultimate fruits of invocation will be explored in terms of spiritual realization through self-effacement. For now the focus remains on a more relative aspect of the heart''s vision of God: that by which the reality of God is made clear and present to the heart through the verities of faith. The agent here is the inner dimension of human consciousness, and the object perceived is the divine Reality. In other words, profound faith reveals the objective presence of God — a presence that is everywhere and cannot be taken away, and that constitutes the ontological reality of all existing things. As the Imam''s famous Dua Kumayl puts it, noted earlier: By Thy tremendousness (عَظَمَتِكَ) which has filled all things ... by Thy Names which have filled the foundations of all things, by Thy knowledge which encompasses all things, by the light of Thy face, through which all things are illumined ... (emphasis added).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'this anticipates the final section where the ultimate fruits of invocation will be explored in terms of spiritual realization through self effacement for now the focus remains on a more relative aspect of the hearts vision of god that by which the reality of god is made clear and present to the heart through the verities of faith the agent here is the inner dimension of human consciousness and the object perceived is the divine reality in other words profound faith reveals the objective presence of god a presence that is everywhere and cannot be taken away and that constitutes the ontological reality of all existing things as the imams famous dua kumayl puts it noted earlier by thy tremendousness عظمتك which has filled all things by thy names which have filled the foundations of all things by thy knowledge which encompasses all things by the light of thy face through which all things are illumined emphasis added', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 35, NULL, 'Nothing can exist without the foundation — the ontological infrastructure, as it were — that the Name, or combination of Names, of God supplies for it. What constitutes the true being and the positive qualities of each manifested thing is therefore, in the end, a divine Name or combination of Names. To see things'' correctly means seeing the divine attributes manifested by and through them, and so perceiving them as existential reflections of principial realities — as so many tajalliyyat, or theophanies, self-disclosures of the divine Reality. The heart purified by invocation comes to see God everywhere.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'nothing can exist without the foundation the ontological infrastructure as it were that the name or combination of names of god supplies for it what constitutes the true being and the positive qualities of each manifested thing is therefore in the end a divine name or combination of names to see things correctly means seeing the divine attributes manifested by and through them and so perceiving them as existential reflections of principial realities as so many tajalliyyat or theophanies self disclosures of the divine reality the heart purified by invocation comes to see god everywhere', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 36, NULL, 'This vision of the divine in all things rests on two principles the Quran affirms: the first concerns the divine object, that is, the objective, metaphysical nature of reality; the second concerns the human subject and the mystical assimilation of that reality. On the one hand, nothing that exists — not even the most outward aspects of material existence — can be excluded from the divine Reality, for He is the First and the Last, and the Outward and the Inward (Al-Hadid: 3), and Wherever ye turn there is the Face of God (Al-Baqarah: 115). On the other hand, We shall show them Our signs on the horizons and in their own souls, until it be clear to them that He is the Real (Fussilat: 53). Everything around us thus provides a sign pointing back to its Creator.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'this vision of the divine in all things rests on two principles the quran affirms the first concerns the divine object that is the objective metaphysical nature of reality the second concerns the human subject and the mystical assimilation of that reality on the one hand nothing that exists not even the most outward aspects of material existence can be excluded from the divine reality for he is the first and the last and the outward and the inward al hadid 3 and wherever ye turn there is the face of god al baqarah 115 on the other hand we shall show them our signs on the horizons and in their own souls until it be clear to them that he is the real fussilat 53 everything around us thus provides a sign pointing back to its creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 37, NULL, 'The heart polished and purified by the dhikr can decipher these signs and so see God everywhere and in everything; yet the possibility of such a vision in no way reduces the divine Reality to the level of sensible phenomena. As noted earlier, the first sermon of the Nahj al-balagha proclaims that God is with every thing, but not through association; and other than every thing, but not through separation. This withness'' (مَعِيَّة) of God implies no relativization of God, no association or conjoining (مُقَارَنَةٌ) of the divine Reality with created things, and no diminution of divine transcendence. The interplay of ideas here can be read as a commentary both on the Quranic verses that proclaim divine immanence — the presence of God to and within all things — and on those that stress divine transcendence, surpassing and incomparable to all things. God may be absolutely close to us, yet we are infinitely far from Him. On the one hand, We are closer to man than the neck-artery (Qaf: 16) — He is as near to us as our own jugular vein — and on the other, ... there is none comparable unto Him (Al-Ikhlas: 4).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the heart polished and purified by the dhikr can decipher these signs and so see god everywhere and in everything yet the possibility of such a vision in no way reduces the divine reality to the level of sensible phenomena as noted earlier the first sermon of the nahj al balagha proclaims that god is with every thing but not through association and other than every thing but not through separation this withness معيه of god implies no relativization of god no association or conjoining مقارنه of the divine reality with created things and no diminution of divine transcendence the interplay of ideas here can be read as a commentary both on the quranic verses that proclaim divine immanence the presence of god to and within all things and on those that stress divine transcendence surpassing and incomparable to all things god may be absolutely close to us yet we are infinitely far from him on the one hand we are closer to man than the neck artery qaf 16 he is as near to us as our own jugular vein and on the other there is none comparable unto him al ikhlas 4', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 38, NULL, 'Nothing that exists can be wholly separate from the all-encompassing reality of God, and yet that reality has no common measure with anything that exists. His oneness both includes and excludes all things. To affirm God''s immanence within the world — His being with every thing — therefore takes nothing away from His transcendence; and to affirm His transcendence above the world — His being other than every thing — does not make Him absent from it. The oneness of God carries all of this, and at the same time it denies any merely numerical oneness, as the first chapter briefly discussed. In the Imam''s view, God is One not in the sense of a countable one, a single unit among other units, but in the sense that His oneness admits no other. In his own words, That which has no second does not enter into the category of numbers.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'nothing that exists can be wholly separate from the all encompassing reality of god and yet that reality has no common measure with anything that exists his oneness both includes and excludes all things to affirm gods immanence within the world his being with every thing therefore takes nothing away from his transcendence and to affirm his transcendence above the world his being other than every thing does not make him absent from it the oneness of god carries all of this and at the same time it denies any merely numerical oneness as the first chapter briefly discussed in the imams view god is one not in the sense of a countable one a single unit among other units but in the sense that his oneness admits no other in his own words that which has no second does not enter into the category of numbers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 39, NULL, 'This can be read as an esoteric commentary on the Quranic verse, Say: He, God is One (Al-Ikhlas: 1). The opposite of this divine oneness — the multiplicity of gods implied in the error of شِرْك — is refined by this conception and turned into a statement about being rather than about theology alone. The act of شِرْك, of associating partners'' with God, is thereby raised to a higher register, and shown to imply not simply the affirmation of false deities but the attribution to God of a merely numerical oneness. To reduce His oneness to number is to confine it within the wholly relative category of determinate entities. Each such entity is a unit, and on this reckoning God would be no more than one among other similar beings''. But the Imam insists that God has no second: there is no other being in being but Him. To call Him one in the ordinary sense is itself imprecise, for it implies that a second could follow in sequence. He is better described as unique. No entity or unit that appears to exist can, in reality, be compared with His being, which is one in an infinitely all-encompassing sense and unique in an absolutely exclusive sense — a oneness that includes all reality and excludes all otherness. This radical idea — of a oneness that absolutely excludes any otherness'' in Being — means that created entities are so many false gods, precisely to the extent that their apparent oneness'' in existence is set beside God''s true oneness, or rather beside God''s one-and-onliness''.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'this can be read as an esoteric commentary on the quranic verse say he god is one al ikhlas 1 the opposite of this divine oneness the multiplicity of gods implied in the error of شرك is refined by this conception and turned into a statement about being rather than about theology alone the act of شرك of associating partners with god is thereby raised to a higher register and shown to imply not simply the affirmation of false deities but the attribution to god of a merely numerical oneness to reduce his oneness to number is to confine it within the wholly relative category of determinate entities each such entity is a unit and on this reckoning god would be no more than one among other similar beings but the imam insists that god has no second there is no other being in being but him to call him one in the ordinary sense is itself imprecise for it implies that a second could follow in sequence he is better described as unique no entity or unit that appears to exist can in reality be compared with his being which is one in an infinitely all encompassing sense and unique in an absolutely exclusive sense a oneness that includes all reality and excludes all otherness this radical idea of a oneness that absolutely excludes any otherness in being means that created entities are so many false gods precisely to the extent that their apparent oneness in existence is set beside gods true oneness or rather beside gods one and onliness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 40, NULL, 'In another sermon, Ali turns to divine immanence, focusing this time on the kind of awareness the human intellect can have of the divine Reality — which returns to the question of what vision of God is possible for a human being:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'in another sermon ali turns to divine immanence focusing this time on the kind of awareness the human intellect can have of the divine reality which returns to the question of what vision of god is possible for a human being', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 41, NULL, '"Praise be to God who is present in the hidden inwardness of things, and whose being is indicated by the signs of manifest things. The eye of the onlooker cannot behold Him, so the eye of one who does not see Him cannot deny His reality, nor can the heart of one who affirms His reality see Him. He is utmost in elevation, so no thing is more elevated than He; but He is also close in His nearness, so no thing is closer than He ... God has not made the intellects capable of defining His qualities, but He has also not veiled the intellects from essential knowledge of Him."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'praise be to god who is present in the hidden inwardness of things and whose being is indicated by the signs of manifest things the eye of the onlooker cannot behold him so the eye of one who does not see him cannot deny his reality nor can the heart of one who affirms his reality see him he is utmost in elevation so no thing is more elevated than he but he is also close in his nearness so no thing is closer than he god has not made the intellects capable of defining his qualities but he has also not veiled the intellects from essential knowledge of him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 42, NULL, 'This passage says two things. On the one hand, human intellects cannot define, still less know, the divine attributes; on the other, essential knowledge of Him is attainable. The apparent contradiction resolves in another key dimension of dhikr — that of recollection, remembrance, recognition. What takes place is a re-collecting of fragments of a knowledge that already exists but has been forgotten. One recognizes what one has always known, and it is precisely for this reason that one can know it again. This does not mean the knowledge is made of parts to be reassembled, which would be empirical knowledge. The remembrance here is more like an awakening, an illumination that dawns as the clouds of inborn forgetfulness are dispelled.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'this passage says two things on the one hand human intellects cannot define still less know the divine attributes on the other essential knowledge of him is attainable the apparent contradiction resolves in another key dimension of dhikr that of recollection remembrance recognition what takes place is a re collecting of fragments of a knowledge that already exists but has been forgotten one recognizes what one has always known and it is precisely for this reason that one can know it again this does not mean the knowledge is made of parts to be reassembled which would be empirical knowledge the remembrance here is more like an awakening an illumination that dawns as the clouds of inborn forgetfulness are dispelled', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 43, NULL, 'This path to knowledge through remembrance recurs throughout the Imam''s sayings. In Sermon 1 of the Nahj, for instance, comes the phrase, "Foremost in religion is knowledge of Him (أَوَّلُ الدِّينِ مَعْرِفَتُهُ)." The word awwal literally means the first, and can be understood as the starting-point, the foundation, and so the foremost element of religion. The word marifa means not merely knowledge but also carries the sense of recognition. The implication is plain: the basis of all religious orientation is man''s pre-existing knowledge of the divine Reality. One re-cognizes what one has always known at the deepest level of consciousness; one ac-knowledges what one already knows but had seemingly forgotten.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'this path to knowledge through remembrance recurs throughout the imams sayings in sermon 1 of the nahj for instance comes the phrase foremost in religion is knowledge of him اول الدين معرفته the word awwal literally means the first and can be understood as the starting point the foundation and so the foremost element of religion the word marifa means not merely knowledge but also carries the sense of recognition the implication is plain the basis of all religious orientation is mans pre existing knowledge of the divine reality one re cognizes what one has always known at the deepest level of consciousness one ac knowledges what one already knows but had seemingly forgotten', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 44, NULL, 'Further on in the same sermon, God sent to mankind "His messengers, dispatching prophets in succession, in order to claim from them [His creatures] the fulfillment of the covenant of His creation; to remind them of His forgotten graces; to remonstrate with them through communication [of His revelation]; to unearth for them the buried treasures of the intellects ..." (دَفَائِنُ الْعُقُولِ).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'further on in the same sermon god sent to mankind his messengers dispatching prophets in succession in order to claim from them his creatures the fulfillment of the covenant of his creation to remind them of his forgotten graces to remonstrate with them through communication of his revelation to unearth for them the buried treasures of the intellects دفاين العقول', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 45, NULL, 'The buried treasures'' can be identified with the knowledge of divine realities ingrained in man''s deepest nature — the realities to which humanity was made to bear witness at the dawn of creation: "And when thy Lord brought forth from the children of Adam, from their loins, their seed, and made them testify of themselves, Am I not your Lord? They said, Yea, we testify. [This was] lest ye say on the Day of Resurrection, Truly, of this we were unaware" (Al-Araf: 172).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the buried treasures can be identified with the knowledge of divine realities ingrained in mans deepest nature the realities to which humanity was made to bear witness at the dawn of creation and when thy lord brought forth from the children of adam from their loins their seed and made them testify of themselves am i not your lord they said yea we testify this was lest ye say on the day of resurrection truly of this we were unaware al araf 172', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 46, NULL, 'These divine realities can also be understood by reference to the divine spirit breathed into man at the creation of the human soul: "Then He fashioned [man] and breathed into him of His Spirit" (As-Sajdah: 9); to the "names" taught by God to Adam: "And He taught Adam the names, all of them ..." (Al-Baqarah: 31); and to the fitra, the primordial nature of man, patterned upon the divine nature: "... the nature of God (fitrat Allah), that according to which He created man" (Ar-Rum: 30). The primordial nature of the human soul can thus be seen to hold the very element — knowledge of God — to which all of humanity is made to bear witness in the pact (ٱلْمِيثَقَ) named in the verse above. Imam Muhammad al-Baqir makes this identity between the fitra and the knowledge of God explicit, in a saying quoted by al-Khui as a commentary on that sentence of the first sermon. Al-Baqir was asked about the meaning of the Quranic words, "the nature of God, that according to which He created man." He answered, "He created them [such that their primordial nature was] in conformity with تَوْحِيد, at the covenant regarding knowledge of Him, [when they testified] that He is indeed their Lord."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'these divine realities can also be understood by reference to the divine spirit breathed into man at the creation of the human soul then he fashioned man and breathed into him of his spirit as sajdah 9 to the names taught by god to adam and he taught adam the names all of them al baqarah 31 and to the fitra the primordial nature of man patterned upon the divine nature the nature of god fitrat allah that according to which he created man ar rum 30 the primordial nature of the human soul can thus be seen to hold the very element knowledge of god to which all of humanity is made to bear witness in the pact الميثق named in the verse above imam muhammad al baqir makes this identity between the fitra and the knowledge of god explicit in a saying quoted by al khui as a commentary on that sentence of the first sermon al baqir was asked about the meaning of the quranic words the nature of god that according to which he created man he answered he created them such that their primordial nature was in conformity with توحيد at the covenant regarding knowledge of him when they testified that he is indeed their lord', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 47, NULL, 'Knowledge of God, then, essentially defines human nature; and for this reason the human intellect cannot be veiled, as the Imam said, from "essential knowledge of God." Yet although this knowledge is ingrained in human nature, forgetfulness (غَفْلَةٌ) has become man''s second nature. In Quranic terms, the mere passage of time smothers the heart and so hardens it: "Hath not the moment come for the believers, that their hearts be humbled to the remembrance of God, and to what hath been revealed of the truth; and that they not become as those who were given the Book aforetime. Then the term was prolonged for them, so their hearts were hardened; and many of them are evil-doers" (Al-Hadid: 16).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'knowledge of god then essentially defines human nature and for this reason the human intellect cannot be veiled as the imam said from essential knowledge of god yet although this knowledge is ingrained in human nature forgetfulness غفله has become mans second nature in quranic terms the mere passage of time smothers the heart and so hardens it hath not the moment come for the believers that their hearts be humbled to the remembrance of god and to what hath been revealed of the truth and that they not become as those who were given the book aforetime then the term was prolonged for them so their hearts were hardened and many of them are evil doers al hadid 16', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 48, NULL, 'The verse speaks both of this hardening of the heart over time — which can be identified with the غَفْلَةٌ of second nature — and of its opposite: the heart''s being present, here and now, to the dhikruLlah. To cure forgetfulness, more is needed than a simple factual reminder, some item of information, some piece of formal, conceptual, reasoned knowledge. No amount of empirical data, arriving only from without, can bring man to knowledge of God. Rather it is integral remembrance — a spiritual awareness that wells up from within and crystallizes on contact with revelation from without — that makes the innate knowledge of God present once again to heart and mind, the knowledge buried deep in the intellect. There is no common measure between this consciousness of God and ordinary empirical knowledge of things. The Imam expresses the gulf between the two kinds of knowledge in sayings such as, "Praise be to God who is well-known (مَعْرُوف) without being seen." A further wording of the same principle sharpens the paradox: "By things their Creator manifests Himself to the intellects; and by things He is guarded from the sight of the eyes." This opens onto a difficult theme in the Imam''s teaching: the nature of the veil formed by created things, and how it is to be understood in the light of the infinite and inalienable reality of God. On one hand, all created things are a veil, in that they keep the divine Essence from being seen by outward vision. On the other, all things cannot but manifest the divine, bearing witness to its creativity and revealing something of its reality — plain to the intellect in its normative state, and dazzlingly evident to the heart illumined and purified by the remembrance of God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the verse speaks both of this hardening of the heart over time which can be identified with the غفله of second nature and of its opposite the hearts being present here and now to the dhikrullah to cure forgetfulness more is needed than a simple factual reminder some item of information some piece of formal conceptual reasoned knowledge no amount of empirical data arriving only from without can bring man to knowledge of god rather it is integral remembrance a spiritual awareness that wells up from within and crystallizes on contact with revelation from without that makes the innate knowledge of god present once again to heart and mind the knowledge buried deep in the intellect there is no common measure between this consciousness of god and ordinary empirical knowledge of things the imam expresses the gulf between the two kinds of knowledge in sayings such as praise be to god who is well known معروف without being seen a further wording of the same principle sharpens the paradox by things their creator manifests himself to the intellects and by things he is guarded from the sight of the eyes this opens onto a difficult theme in the imams teaching the nature of the veil formed by created things and how it is to be understood in the light of the infinite and inalienable reality of god on one hand all created things are a veil in that they keep the divine essence from being seen by outward vision on the other all things cannot but manifest the divine bearing witness to its creativity and revealing something of its reality plain to the intellect in its normative state and dazzlingly evident to the heart illumined and purified by the remembrance of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 49, NULL, 'The following aphorisms of Ibn Ataillah — one of the great masters of Sufi gnosis, or marifa — are wholly to the point here. They read as a series of reflections on the paradox the Imam expressed so tersely. Ibn Ataillah writes: "That which shows you the existence of His omnipotence is that He veiled you from Himself by that which has no existence alongside of Him." In one respect God is "guarded from the eyes," in the Imam''s words, and so veiled by "things"; but since God alone truly "is," these "things" do not really exist, and so God is veiled by "nothing." Through their very "appearance" — both their coming into existence and their "apparent" existence — it is "by things" that "their Creator manifests Himself." The mystery of this self-manifestation of God by and through all things is pressed to the full by the following rhetorical questions of Ibn Ataillah:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the following aphorisms of ibn ataillah one of the great masters of sufi gnosis or marifa are wholly to the point here they read as a series of reflections on the paradox the imam expressed so tersely ibn ataillah writes that which shows you the existence of his omnipotence is that he veiled you from himself by that which has no existence alongside of him in one respect god is guarded from the eyes in the imams words and so veiled by things but since god alone truly is these things do not really exist and so god is veiled by nothing through their very appearance both their coming into existence and their apparent existence it is by things that their creator manifests himself the mystery of this self manifestation of god by and through all things is pressed to the full by the following rhetorical questions of ibn ataillah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 50, NULL, 'How can it be conceived that something veils Him, since He is the one who manifests everything?', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'how can it be conceived that something veils him since he is the one who manifests everything', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 51, NULL, 'How can it be conceived that something veils Him, since were it not for Him the existence of everything would not be manifest?', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'how can it be conceived that something veils him since were it not for him the existence of everything would not be manifest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 52, NULL, 'It is a marvel how Being has been manifested in non-being, and how the contingent has been established alongside of Him who possesses the attribute of Eternity!', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'it is a marvel how being has been manifested in non being and how the contingent has been established alongside of him who possesses the attribute of eternity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 53, NULL, 'The import of all these sayings can be grasped within a paradox the Imam expressed tersely: "The veils do not veil Him (لَا تَحْجُبُهُ الْحُجُبُ)." The veils cannot help revealing what they are meant to conceal. They are not merely transparent to the reality they cannot hide; in and of themselves they reveal it rather than conceal it. This recalls the Imam''s famous saying, so often quoted by the Sufis: "Were the veil to be removed, I would not increase in certitude" (لو کشف الغطاء ما ازدت یقینا). The veils of creation reveal in the end what they at first conceal, yet only the eye of the heart, purified through the dhikr, perceives this revelation — the heart that now "sees after being blind." The Imam continues, deepening the paradox further:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the import of all these sayings can be grasped within a paradox the imam expressed tersely the veils do not veil him لا تحجبه الحجب the veils cannot help revealing what they are meant to conceal they are not merely transparent to the reality they cannot hide in and of themselves they reveal it rather than conceal it this recalls the imams famous saying so often quoted by the sufis were the veil to be removed i would not increase in certitude لو كشف الغطاء ما ازدت يقينا the veils of creation reveal in the end what they at first conceal yet only the eye of the heart purified through the dhikr perceives this revelation the heart that now sees after being blind the imam continues deepening the paradox further', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 54, NULL, '"The veil between Him and His creatures is His very creation of them. [This veil is] for the sake of His prevention of that which is possible in their essences, and for the sake of making possible that which is prevented in regard to Him; and to distinguish the Creator from the created, and the limit from the limited, and the Lord from the vassal."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the veil between him and his creatures is his very creation of them this veil is for the sake of his prevention of that which is possible in their essences and for the sake of making possible that which is prevented in regard to him and to distinguish the creator from the created and the limit from the limited and the lord from the vassal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 55, NULL, 'All of creation, every "veil" it forms, is thus nothing other than the divine dimension of al-Zahir: the Apparent, the Clear, the Evident, the Manifest. Yet creation is al-Zahir not in its own right, but by virtue of the divine reality of which it is a projection, a form of tajalli. God, as al-Zahir, projects something of His "hidden treasure" within the creation and as the creation. The world manifests the "apparent" aspect of God — that which "appears" from Him, that which He can manifest or bring into being — while still concealing the mystery of God: that which remains "hidden," al-Batin, the supra-manifest source of being, the uncreated essence. The veil of creation is therefore nothing other than the self-revelation of God. Yet this holds only by virtue of what pierces the veil of its own apparent otherness — that divine creativity which creation cannot in fact conceal, even though in principle it has the character of a veil.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'all of creation every veil it forms is thus nothing other than the divine dimension of al zahir the apparent the clear the evident the manifest yet creation is al zahir not in its own right but by virtue of the divine reality of which it is a projection a form of tajalli god as al zahir projects something of his hidden treasure within the creation and as the creation the world manifests the apparent aspect of god that which appears from him that which he can manifest or bring into being while still concealing the mystery of god that which remains hidden al batin the supra manifest source of being the uncreated essence the veil of creation is therefore nothing other than the self revelation of god yet this holds only by virtue of what pierces the veil of its own apparent otherness that divine creativity which creation cannot in fact conceal even though in principle it has the character of a veil', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 56, NULL, 'The veil formed by creation prevents what the essences of creatures make possible. What the essences make possible is the realization of inmost identity with the divine Reality — تَوْحِيد at its highest level — a possibility that follows from the fact that this same divine Reality is the ground of being of "their essences." It is the divine Names, qualities, and attributes that "fill the foundations of all things." At the foundations, or within the "essences," there is but the one and only divine Reality. If the realization of this truth of identity is thus "possible," what the veil "prevents" is the affirmation of that identity at the wrong level of being — the level of empirical existence — rather than at the deepest level, where the "essences" of things are nothing other than the divine qualities, and thus the divine Reality itself. To equate created things with God amounts to pure شِرْك, the cardinal sin of "association," and it is against this that a vision of divine oneness must guard. One must always "distinguish the Creator from the created, and the limit from the limited, and the Lord from the vassal."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the veil formed by creation prevents what the essences of creatures make possible what the essences make possible is the realization of inmost identity with the divine reality توحيد at its highest level a possibility that follows from the fact that this same divine reality is the ground of being of their essences it is the divine names qualities and attributes that fill the foundations of all things at the foundations or within the essences there is but the one and only divine reality if the realization of this truth of identity is thus possible what the veil prevents is the affirmation of that identity at the wrong level of being the level of empirical existence rather than at the deepest level where the essences of things are nothing other than the divine qualities and thus the divine reality itself to equate created things with god amounts to pure شرك the cardinal sin of association and it is against this that a vision of divine oneness must guard one must always distinguish the creator from the created and the limit from the limited and the lord from the vassal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 57, NULL, 'The veil of creation, in other words, acts as a barrier against pantheism — the reduction of the Creator''s infinite transcendence to the finite forms of creatures. Yet since the veil has no existence apart from the self-manifestation of the Real, it also, paradoxically, makes possible "that which is prevented in regard to Him": made transparent to the divine Reality of which it is one expression, the veil cannot prevent the immanent reality of God from shining through and within all things. On one side stands essential identity, with no diminution of divine transcendence; on the other stands existential distinction, with no lessening of divine immanence. This returns to the founding sentence of the first sermon of the Nahj: "He is with every thing, but not through association; and other than every thing, but not through separation." It recalls too a central theme in Sufi metaphysics: the dynamic relationship between tanzih — the declaration of divine incomparability and transcendence — and tashbih — the affirmation of similarity and, at the deepest level, of immanence. In the words of Ibn al-Arabi:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'the veil of creation in other words acts as a barrier against pantheism the reduction of the creators infinite transcendence to the finite forms of creatures yet since the veil has no existence apart from the self manifestation of the real it also paradoxically makes possible that which is prevented in regard to him made transparent to the divine reality of which it is one expression the veil cannot prevent the immanent reality of god from shining through and within all things on one side stands essential identity with no diminution of divine transcendence on the other stands existential distinction with no lessening of divine immanence this returns to the founding sentence of the first sermon of the nahj he is with every thing but not through association and other than every thing but not through separation it recalls too a central theme in sufi metaphysics the dynamic relationship between tanzih the declaration of divine incomparability and transcendence and tashbih the affirmation of similarity and at the deepest level of immanence in the words of ibn al arabi', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 58, NULL, '"He is not declared incomparable in any manner that will remove Him from similarity, nor is He declared similar in any manner that would remove Him from incomparability. So do not declare Him nondelimited and thus delimited by being distinguished from delimitation! For if He is distinguished then He is delimited by His nondelimitation. And if He is delimited by His nondelimitation, then He is not He."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'he is not declared incomparable in any manner that will remove him from similarity nor is he declared similar in any manner that would remove him from incomparability so do not declare him nondelimited and thus delimited by being distinguished from delimitation for if he is distinguished then he is delimited by his nondelimitation and if he is delimited by his nondelimitation then he is not he', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 59, NULL, 'To return to the Imam''s powerfully evocative statement, "The veils do not veil Him." Both tanzih and tashbih can become veils unless each is seen in the light of the other; both transcendence and immanence can become veils unless the two are held together in spiritual vision; and both the creation, as divine manifestation, and the uncreated Essence, above and beyond all manifestation, can become veils unless they are integrated in the spiritual vision proper to تَوْحِيد, and so made transparent, each "revealing" the other. In the same way, a one-sided stress on God as "the Apparent" becomes a veil by blinding one to God as "the Hidden" — and the reverse holds too. For even the hidden aspect of God, taken in isolation, will, despite its non-manifest nature, form a conceptual veil that prevents the seeing of God''s "evidence," His "evident-ness," in the very heart of the created world. The "veils" are thus not only created things but also the limits built into every human conception of God, including the divine qualities and attributes. Hence the need for a radical negation, on the plane of human conception, of those divine attributes. Only on the basis of such an apophasis can consciousness begin to fathom the true nature of divine transcendence, and see through the veils that "do not veil Him."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'to return to the imams powerfully evocative statement the veils do not veil him both tanzih and tashbih can become veils unless each is seen in the light of the other both transcendence and immanence can become veils unless the two are held together in spiritual vision and both the creation as divine manifestation and the uncreated essence above and beyond all manifestation can become veils unless they are integrated in the spiritual vision proper to توحيد and so made transparent each revealing the other in the same way a one sided stress on god as the apparent becomes a veil by blinding one to god as the hidden and the reverse holds too for even the hidden aspect of god taken in isolation will despite its non manifest nature form a conceptual veil that prevents the seeing of gods evidence his evident ness in the very heart of the created world the veils are thus not only created things but also the limits built into every human conception of god including the divine qualities and attributes hence the need for a radical negation on the plane of human conception of those divine attributes only on the basis of such an apophasis can consciousness begin to fathom the true nature of divine transcendence and see through the veils that do not veil him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 60, NULL, 'These perspectives on the nature of the veil are better understood as the evocation of a spiritual vision than as the logical statement of empirical observation. They are the fruits of contemplative synthesis, not the conclusions of rational analysis. Such a vision resolves apparent contradiction through an intuitive awareness of the unitive simplicity of reality; it is not the product of some tortuous mental effort to reconcile the complexities of existence. It is at once a vision reflected by the heart burnished by the remembrance of God, and itself a form of that very remembrance. What the rational faculty will always perceive as irreducible contradiction, the spirit of the intellect can grasp as a fruitful paradox.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'these perspectives on the nature of the veil are better understood as the evocation of a spiritual vision than as the logical statement of empirical observation they are the fruits of contemplative synthesis not the conclusions of rational analysis such a vision resolves apparent contradiction through an intuitive awareness of the unitive simplicity of reality it is not the product of some tortuous mental effort to reconcile the complexities of existence it is at once a vision reflected by the heart burnished by the remembrance of god and itself a form of that very remembrance what the rational faculty will always perceive as irreducible contradiction the spirit of the intellect can grasp as a fruitful paradox', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 61, NULL, 'This aspect of the Imam''s teaching finds vivid expression in the words of the famous Sufi Abu Said al-Kharraz. Asked how he came to know God, he replied: through the fact that He brings opposites together (جَمْعُهُ الضِّدَّيْنِ). He then recited the Quranic verse, He is the First and the Last, and the Outward and the Inward.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'this aspect of the imams teaching finds vivid expression in the words of the famous sufi abu said al kharraz asked how he came to know god he replied through the fact that he brings opposites together جمعه الضدين he then recited the quranic verse he is the first and the last and the outward and the inward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 62, NULL, 'It is spiritual intuition that gives the capacity to see as one, in the unifying vision of تَوْحِيد, what appears on the surface as many. In sharpening the paradox on the conceptual plane, Ali is, in modern parlance, deconstructing the artifices of mental conception, and in doing so he opens the way to intuitive apprehension and spiritual contemplation. The very work of the intellect, عقل — a word whose root means to bind or restrain — is one of binding together. The realities the heart discloses through intuition and inspiration are drawn by it into the organic unity of تَوْحِيد through an exercise in logic, a movement of negation and affirmation, of constriction and expansion.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'it is spiritual intuition that gives the capacity to see as one in the unifying vision of توحيد what appears on the surface as many in sharpening the paradox on the conceptual plane ali is in modern parlance deconstructing the artifices of mental conception and in doing so he opens the way to intuitive apprehension and spiritual contemplation the very work of the intellect عقل a word whose root means to bind or restrain is one of binding together the realities the heart discloses through intuition and inspiration are drawn by it into the organic unity of توحيد through an exercise in logic a movement of negation and affirmation of constriction and expansion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'dhikr: the polish of the heart', '11. Dhikr: The Polish of the Heart', 63, NULL, 'It is only at these deeper levels of consciousness that the complementary process of reconstruction can take place: a re-cognition of the Real, اَلْحَقّ, arising from the heart''s vision of God through the verities of faith (حَقَائِقُ الْإِيمَان). Only these haqaiq are truly on a level with اَلْحَقّ. Only these realities, hidden within the depths of faith and brought to light in a heart polished by the remembrance of God, can do justice to the reality of God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 11 dhikr the polish of the heart', 'it is only at these deeper levels of consciousness that the complementary process of reconstruction can take place a re cognition of the real الحق arising from the hearts vision of god through the verities of faith حقايق الايمان only these haqaiq are truly on a level with الحق only these realities hidden within the depths of faith and brought to light in a heart polished by the remembrance of god can do justice to the reality of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 0, NULL, 'The practice of the remembrance of God, dhikruLlah, is best approached first through the Quranic verses that name it as a devotional discipline:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'the practice of the remembrance of god dhikrullah is best approached first through the quranic verses that name it as a devotional discipline', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 1, NULL, 'And invoke the Name of thy Lord morning and evening (Al-Insan: 25).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'and invoke the name of thy lord morning and evening al insan 25', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 2, NULL, 'And invoke the Name of thy Lord, devoting thyself to Him [or: it] with utter devotion (Al-Muzzammil: 8).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'and invoke the name of thy lord devoting thyself to him or it with utter devotion al muzzammil 8', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 3, NULL, 'O ye who believe! Invoke God with much invocation (Al-Ahzab: 41).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'o ye who believe invoke god with much invocation al ahzab 41', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 4, NULL, 'Call upon thy Lord in humility and in secret (Al-Araf: 55).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'call upon thy lord in humility and in secret al araf 55', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 5, NULL, 'And invoke thy Lord within thyself, in humility and awe, and beneath thy breath, in the morning and in the night (Al-Araf: 205).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'and invoke thy lord within thyself in humility and awe and beneath thy breath in the morning and in the night al araf 205', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 6, NULL, 'All these verses point to an actual practice, one to be maintained in different modes: within thyself, in humility, in awe, in secret, beneath thy breath, and so on. Most importantly, the invocation is to be performed abundantly, dhikran kathiran. The Quranic chapter al-Muzzammil (The Enwrapped) recalls how intense and how long the devotions of the Prophet and the first Muslims were, mentioning the long night vigils these early Muslims kept: Truly, thy Lord knoweth that thou standest in prayer for almost two-thirds of the night, and a half of it, and a third of it, as doth a group from those with thee (Al-Muzzammil: 20). The opening of this Sura contains the verse instructing the Prophet to remember/invoke the Name of thy Lord, and devote thyself to Him with utter devotion (Al-Muzzammil: 8). The pronoun in the word ilayhi, to Him, can refer either to Him as thy Lord or to it as the Name of thy Lord, so that the operative meaning of the verse becomes: Invoke the Name of God and devote yourself to this Name with utter devotion. This recalls the explicit injunction, Glorify the Name of thy Lord, the Exalted (Al-Ala: 1). In devotional practice, then, devotion to the Name of the Absolute amounts to devotion to the Absolute itself. The Absolute in itself lies above and beyond all forms, including all verbal forms. Yet it is made accessible through the divine Name — a Name that no human language invented, but that God bestowed by disclosing Himself, revealing the sacrament of His own Name. Distraction from the remembrance or invocation of the Name is, equally, distraction from God Himself, as two verses make clear: The devil hath overcome them, causing them to forget the remembrance of God (Al-Mujadila: 19), and O ye who believe, let not your wealth nor your children distract you from the remembrance of God (Al-Munafiqun: 9).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'all these verses point to an actual practice one to be maintained in different modes within thyself in humility in awe in secret beneath thy breath and so on most importantly the invocation is to be performed abundantly dhikran kathiran the quranic chapter al muzzammil the enwrapped recalls how intense and how long the devotions of the prophet and the first muslims were mentioning the long night vigils these early muslims kept truly thy lord knoweth that thou standest in prayer for almost two thirds of the night and a half of it and a third of it as doth a group from those with thee al muzzammil 20 the opening of this sura contains the verse instructing the prophet to remember invoke the name of thy lord and devote thyself to him with utter devotion al muzzammil 8 the pronoun in the word ilayhi to him can refer either to him as thy lord or to it as the name of thy lord so that the operative meaning of the verse becomes invoke the name of god and devote yourself to this name with utter devotion this recalls the explicit injunction glorify the name of thy lord the exalted al ala 1 in devotional practice then devotion to the name of the absolute amounts to devotion to the absolute itself the absolute in itself lies above and beyond all forms including all verbal forms yet it is made accessible through the divine name a name that no human language invented but that god bestowed by disclosing himself revealing the sacrament of his own name distraction from the remembrance or invocation of the name is equally distraction from god himself as two verses make clear the devil hath overcome them causing them to forget the remembrance of god al mujadila 19 and o ye who believe let not your wealth nor your children distract you from the remembrance of god al munafiqun 9', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 7, NULL, 'This identification of devoting oneself to God with devoting oneself to His Name follows from a principle Ali (ع) states in a simple affirmation: He who loves a thing dedicates himself fervently to its invocation (مَنْ أَحَبَّ شَيْئًا لَهِجَ بِذِكْرِهِ). The lover of God should therefore devote himself utterly to the invocation of the Name of God, giving himself to it in abundance, kathiran. The pairing of lahija, meaning both to be devoted to and to mention repeatedly, with dhikr, which indicates the constant verbal repetition of the invocation, also appears in the Dua Kumayl, there with an added explicit reference to the tongue: ... my tongue has devoted itself to thy invocation (مَا لَهِجَ بِهِ لِسَانِي مِنْ ذِكْرِكَ). He implores God, Make my times in the night and the day inhabited by Thy remembrance, and make my tongue invoke Thee with utter dedication (اجْعَلْ لِسَانِي بِذِكْرِكَ لَاهِجًا). The invocation as a practice is confirmed in his words: O He whose Name is a remedy and whose invocation is the cure (يَا مَنِ اسْمُهُ دَوَاءٌ وَذِكْرُهُ شِفَاءٌ).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'this identification of devoting oneself to god with devoting oneself to his name follows from a principle ali ع states in a simple affirmation he who loves a thing dedicates himself fervently to its invocation من احب شييا لهج بذكره the lover of god should therefore devote himself utterly to the invocation of the name of god giving himself to it in abundance kathiran the pairing of lahija meaning both to be devoted to and to mention repeatedly with dhikr which indicates the constant verbal repetition of the invocation also appears in the dua kumayl there with an added explicit reference to the tongue my tongue has devoted itself to thy invocation ما لهج به لساني من ذكرك he implores god make my times in the night and the day inhabited by thy remembrance and make my tongue invoke thee with utter dedication اجعل لساني بذكرك لاهجا the invocation as a practice is confirmed in his words o he whose name is a remedy and whose invocation is the cure يا من اسمه دواء وذكره شفاء', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 8, NULL, 'Here the Name of God is far more than a name among other names, a word or sound among other symbols: it is the remedy for man''s inborn forgetfulness, the spiritual amnesia, غَفْلَةٌ, that has become his second nature. But to be effective, the Name must be actively invoked rather than merely contemplated, just as a medicine must be taken and not merely thought about if it is to exercise its healing power. As the Imam puts it in one of his sermons, describing the greatness of the Quran: It has made the dhikr incumbent upon your tongues. And the invocation is to be performed kathiran, much, in abundance. The following hadith of the Prophet shows that dhikr is something to be done, a practice, and cannot be reduced to a purely theoretical interpretation of its meanings:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'here the name of god is far more than a name among other names a word or sound among other symbols it is the remedy for mans inborn forgetfulness the spiritual amnesia غفله that has become his second nature but to be effective the name must be actively invoked rather than merely contemplated just as a medicine must be taken and not merely thought about if it is to exercise its healing power as the imam puts it in one of his sermons describing the greatness of the quran it has made the dhikr incumbent upon your tongues and the invocation is to be performed kathiran much in abundance the following hadith of the prophet shows that dhikr is something to be done a practice and cannot be reduced to a purely theoretical interpretation of its meanings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 9, NULL, 'Abd Allah b. Busr reported that a man said, O Messenger of Allah, the laws of Islam are too many for me, so tell me something that I may cling to. He replied, may God bless him and give him peace, Let your tongue never cease to be moist from invoking Allah.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'abd allah b busr reported that a man said o messenger of allah the laws of islam are too many for me so tell me something that i may cling to he replied may god bless him and give him peace let your tongue never cease to be moist from invoking allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 10, NULL, 'The verses that follow the Quranic exhortation to invoke much deserve quotation: O ye who believe, invoke God with much invocation, and glorify Him early and late. He it is who blesseth you, as do His angels, so that He may bring you forth from darkness into light; and He is ever merciful to the believers'' (Al-Ahzab: 41-43).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'the verses that follow the quranic exhortation to invoke much deserve quotation o ye who believe invoke god with much invocation and glorify him early and late he it is who blesseth you as do his angels so that he may bring you forth from darkness into light and he is ever merciful to the believers al ahzab 41 43', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 11, NULL, 'There is a reciprocity here between the dhikr of the believers and the salat — the prayer, or blessing — of God upon the believers. The relationship between the human act of invocation and the divine act of blessing is more complex than it first appears. Exploring this relationship, and the ontological dimensions of the invocation, brings one close to the mystery expressed by the verse, Remember Me, I will remember you (Al-Baqarah: 152).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'there is a reciprocity here between the dhikr of the believers and the salat the prayer or blessing of god upon the believers the relationship between the human act of invocation and the divine act of blessing is more complex than it first appears exploring this relationship and the ontological dimensions of the invocation brings one close to the mystery expressed by the verse remember me i will remember you al baqarah 152', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 12, NULL, 'Within these same verses (Al-Ahzab: 41-43) lies a further relationship: that between invocation and illumination, between being brought from darkness into light. The Imam speaks of the way in which human invocation results in divine illumination, and his words may be read as a commentary on this dimension of those verses: Whoever invokes God, glorified be He, God enlivens his heart and illuminates his inner substance (لُبٌّ). The word لُبٌّ (pl. albab) here evokes the Quranic verse describing the ulul-albab, the possessors of substance, in which the dhikr again figures prominently: Truly in the creation of the heavens and the earth, and in the alternation between night and day, there are signs for those of substance, those who invoke God standing, sitting and reclining on their sides, and reflect upon the creation of the heavens and the earth ... (Ali Imran: 190-191).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'within these same verses al ahzab 41 43 lies a further relationship that between invocation and illumination between being brought from darkness into light the imam speaks of the way in which human invocation results in divine illumination and his words may be read as a commentary on this dimension of those verses whoever invokes god glorified be he god enlivens his heart and illuminates his inner substance لب the word لب pl albab here evokes the quranic verse describing the ulul albab the possessors of substance in which the dhikr again figures prominently truly in the creation of the heavens and the earth and in the alternation between night and day there are signs for those of substance those who invoke god standing sitting and reclining on their sides and reflect upon the creation of the heavens and the earth ali imran 190 191', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 13, NULL, 'Besides confirming that remembrance is a practice and a method, this passage points to the relationship between dhikr and fikr, between invocation and reflection or meditation. The practice of invocation polishes the inmost organ of awareness, and so deepens the capacity for meditation upon the signs of God in creation and within oneself. When the element of love is placed between invocation and meditation, for he who loves a thing dedicates himself fervently to its invocation, these three elements enter a virtuous circle in which each strengthens and deepens the other two. The more seriously one ponders the signs'' of God and appreciates their beauty, the more one comes to love God; the more one loves God, the more one invokes His Name; the more one invokes, the more keenly one perceives the sacred message of those signs'' in the universe. Thus fikr intensifies dhikr, and dhikr deepens fikr.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'besides confirming that remembrance is a practice and a method this passage points to the relationship between dhikr and fikr between invocation and reflection or meditation the practice of invocation polishes the inmost organ of awareness and so deepens the capacity for meditation upon the signs of god in creation and within oneself when the element of love is placed between invocation and meditation for he who loves a thing dedicates himself fervently to its invocation these three elements enter a virtuous circle in which each strengthens and deepens the other two the more seriously one ponders the signs of god and appreciates their beauty the more one comes to love god the more one loves god the more one invokes his name the more one invokes the more keenly one perceives the sacred message of those signs in the universe thus fikr intensifies dhikr and dhikr deepens fikr', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 14, NULL, 'These verses (Ali Imran: 190-191) also bring out the supra-formal dimension of invocation. The dhikr is presented here as the quintessence of all religious activity, the spiritual act par excellence. Its modes are universal: standing, sitting, reclining, as the verse states, and within thyself, in humility, in awe, in secret, beneath thy breath, as the verses cited above make clear. These modes transcend the formal rules governing the fixed canonical prayers, which prescribe specific words, movements, and conditions. The dhikr, by contrast, is to be performed at all times, in all places, and in all postures; it is something to be woven into the texture of everyday life rather than imposed upon life as an external, formalistic practice. According to Imam Jafar al-Sadiq, invocation is the one practice that should be carried out in all circumstances and at all times, with no limit placed upon it: Everything has a limit, at which it terminates, except the dhikr Allah. God has made obligatory the religious duties (الْفَرَائِضُ), so whoever fulfills them, that fulfillment constitutes their limit. For the month of Ramadan, whoever fasts therein, that constitutes its limit ... He goes on to mention other rites, then cites the Quranic verse: O ye who believe, invoke God with much invocation, and adds that his father, Imam Muhammad al-Baqir, never ceased invoking, even while eating and walking.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'these verses ali imran 190 191 also bring out the supra formal dimension of invocation the dhikr is presented here as the quintessence of all religious activity the spiritual act par excellence its modes are universal standing sitting reclining as the verse states and within thyself in humility in awe in secret beneath thy breath as the verses cited above make clear these modes transcend the formal rules governing the fixed canonical prayers which prescribe specific words movements and conditions the dhikr by contrast is to be performed at all times in all places and in all postures it is something to be woven into the texture of everyday life rather than imposed upon life as an external formalistic practice according to imam jafar al sadiq invocation is the one practice that should be carried out in all circumstances and at all times with no limit placed upon it everything has a limit at which it terminates except the dhikr allah god has made obligatory the religious duties الفرايض so whoever fulfills them that fulfillment constitutes their limit for the month of ramadan whoever fasts therein that constitutes its limit he goes on to mention other rites then cites the quranic verse o ye who believe invoke god with much invocation and adds that his father imam muhammad al baqir never ceased invoking even while eating and walking', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 15, NULL, 'In this light it becomes easier to understand those whom the Quran describes as men whom neither trade nor merchandise diverts from the remembrance of God. The verse also illuminates why believers are described as those who are perpetually at prayer (عَلَىٰ صَلَاتِهِمْ دَآئِمُونَ) (Al-Maarij: 23). Such people are not merely regular in performing the canonical prayer at its appointed times; for the men of substance, there is no moment when they are not at prayer, if one understands prayer as the remembrance of God. The Quran instructs mankind to establish the prayer for the sake of My remembrance (Ta-Ha: 14). The very purpose and goal of prayer, its spiritual value and substance, is thus the remembrance of God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'in this light it becomes easier to understand those whom the quran describes as men whom neither trade nor merchandise diverts from the remembrance of god the verse also illuminates why believers are described as those who are perpetually at prayer علي صلاتهم دايمون al maarij 23 such people are not merely regular in performing the canonical prayer at its appointed times for the men of substance there is no moment when they are not at prayer if one understands prayer as the remembrance of god the quran instructs mankind to establish the prayer for the sake of my remembrance ta ha 14 the very purpose and goal of prayer its spiritual value and substance is thus the remembrance of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 16, NULL, 'A saying of Ali bears directly on this: Continuous invocation is the food of the spirit and the key to prayer (مِفْتَاحُ الصَّلَاةِ). This sheds further light on why the Quran says that prayer keepeth [one] away from lewdness and iniquity, and the remembrance of God is greater (Al-Ankabut: 45). The formal, canonical prayer is described here in negative or constraining terms: it is a preventative. Its formality is a ritual necessity, but it is also, unavoidably, an existential limitation, performed and operative at one time and not another, expressed in certain forms and not others. The remembrance of God is greater in that it is the positive, enlivening substance of prayer; it is what liberates consciousness from the verbal, mental, and existential limits by which all formal prayer is defined. Formal prayer is inescapably bounded by such limits, and so its baraka, its blessedness, can all too easily become confined, in one''s own experience, within those same limits — so that one feels close to God only during formal prayer, and not in everyday life outside the prayer-times. It is dhikr, in the sense of recollectedness and constant awareness of God, that allows prayer, or the consciousness shaped by prayer, to open outward into its intended essence: an awareness of the unconditional presence of God. Dhikr thus transforms a preventative measure against moral transgression into a positive apprehension of spiritual reality. One might say that the dhikruLlah is greater than the ritual or canonical prayer in the measure that spiritual awareness transcends moral conscience, or in the measure that essence transcends form. The lesser is not negated by the greater but is rather contained within it, enriched by it, and brought to a fullness and scope it could never attain on its own. In this light one can better understand at least some of the reasons why the Imam, following the Prophet and the Quran, presents dhikruLlah as the quintessence of worship and devotion.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'a saying of ali bears directly on this continuous invocation is the food of the spirit and the key to prayer مفتاح الصلاه this sheds further light on why the quran says that prayer keepeth one away from lewdness and iniquity and the remembrance of god is greater al ankabut 45 the formal canonical prayer is described here in negative or constraining terms it is a preventative its formality is a ritual necessity but it is also unavoidably an existential limitation performed and operative at one time and not another expressed in certain forms and not others the remembrance of god is greater in that it is the positive enlivening substance of prayer it is what liberates consciousness from the verbal mental and existential limits by which all formal prayer is defined formal prayer is inescapably bounded by such limits and so its baraka its blessedness can all too easily become confined in ones own experience within those same limits so that one feels close to god only during formal prayer and not in everyday life outside the prayer times it is dhikr in the sense of recollectedness and constant awareness of god that allows prayer or the consciousness shaped by prayer to open outward into its intended essence an awareness of the unconditional presence of god dhikr thus transforms a preventative measure against moral transgression into a positive apprehension of spiritual reality one might say that the dhikrullah is greater than the ritual or canonical prayer in the measure that spiritual awareness transcends moral conscience or in the measure that essence transcends form the lesser is not negated by the greater but is rather contained within it enriched by it and brought to a fullness and scope it could never attain on its own in this light one can better understand at least some of the reasons why the imam following the prophet and the quran presents dhikrullah as the quintessence of worship and devotion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 17, NULL, 'What remains are the spiritual fruits of the remembrance of God, and in particular realization, تَحْقِيق: the process by which اَلْحَقّ, the Real, is made real within oneself. This is closely related to the process the Imam earlier described as tawahhud, self-integration, the spiritual assimilation of oneness within oneself, as distinct from the simple theological affirmation of oneness, تَوْحِيد, in its conventional sense. In keeping with the Imam''s characteristic use of paradox, the fruit of remembrance can be approached first by examining its very opposite: غَفْلَةٌ, heedlessness, or sahw, forgetfulness and distraction. Here again the Imam''s sayings function implicitly as a commentary on Quranic verses, while opening onto a rich terrain of mystical speculation and spiritual contemplation concerning the ultimate consequences of the invocation and remembrance of God. The Quran is severe in its condemnation of those who pray ostentatiously and hypocritically, those who give the lie to religion: Woe to those who pray, those who are heedless of their prayer, those who make a show, and who withhold simple assistance (Al-Maun: 4-7). The Imam likewise warns against remembering God heedlessly or distractedly, and in describing its opposite, perfect or complete dhikr, he articulates a paradoxical return to a kind of forgetting that goes to the very heart of the Sufi principle of extinction in remembrance (اَلْفَنَاءُ فِي الذِّكْرِ):', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'what remains are the spiritual fruits of the remembrance of god and in particular realization تحقيق the process by which الحق the real is made real within oneself this is closely related to the process the imam earlier described as tawahhud self integration the spiritual assimilation of oneness within oneself as distinct from the simple theological affirmation of oneness توحيد in its conventional sense in keeping with the imams characteristic use of paradox the fruit of remembrance can be approached first by examining its very opposite غفله heedlessness or sahw forgetfulness and distraction here again the imams sayings function implicitly as a commentary on quranic verses while opening onto a rich terrain of mystical speculation and spiritual contemplation concerning the ultimate consequences of the invocation and remembrance of god the quran is severe in its condemnation of those who pray ostentatiously and hypocritically those who give the lie to religion woe to those who pray those who are heedless of their prayer those who make a show and who withhold simple assistance al maun 4 7 the imam likewise warns against remembering god heedlessly or distractedly and in describing its opposite perfect or complete dhikr he articulates a paradoxical return to a kind of forgetting that goes to the very heart of the sufi principle of extinction in remembrance الفناء في الذكر', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 18, NULL, 'Do not remember God absent-mindedly (سَاهِيًا), nor forget Him in distraction; rather, remember Him with perfect remembrance (ذِكْرًا كَامِلًا), a remembrance in which your heart and tongue are in harmony, and what you conceal conforms with what you reveal. But you will not remember Him according to the true reality of the remembrance (حَقِيقَةُ الذِّكْرِ) until you forget your own soul in your remembrance.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'do not remember god absent mindedly ساهيا nor forget him in distraction rather remember him with perfect remembrance ذكرا كاملا a remembrance in which your heart and tongue are in harmony and what you conceal conforms with what you reveal but you will not remember him according to the true reality of the remembrance حقيقه الذكر until you forget your own soul in your remembrance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 19, NULL, 'This saying offers a summary of the entire mystical path. What is implied is the whole sequence of spiritual stations'' (مَقَامَات, sing. maqam) through which total sincerity is attained. Sufism is itself often described simply as sincerity, that is, sidq or إِخْلَاص. To be totally sincere in this sense is to orient oneself and one''s desires purely toward God, without any taint of impurity, where impurity means the presence, in one''s devotion, action, or intention, of any desire for something other than God. On one hand, the dhikr itself helps to realize sincerity by polishing the heart; on the other, it is sincerity that confers perfection or completion upon the spiritual efficacy of the dhikr. What matters at this stage of perfect dhikr is that the outward verbal form of the invocation must harmonize with heartfelt intention. There must be no contradiction between what the tongue articulates and what motivates the heart. Bringing heart and tongue into harmony means that the divine Reality invoked by the tongue reverberates in the heart, the very source of the soul''s fundamental dispositions, its virtues.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'this saying offers a summary of the entire mystical path what is implied is the whole sequence of spiritual stations مقامات sing maqam through which total sincerity is attained sufism is itself often described simply as sincerity that is sidq or اخلاص to be totally sincere in this sense is to orient oneself and ones desires purely toward god without any taint of impurity where impurity means the presence in ones devotion action or intention of any desire for something other than god on one hand the dhikr itself helps to realize sincerity by polishing the heart on the other it is sincerity that confers perfection or completion upon the spiritual efficacy of the dhikr what matters at this stage of perfect dhikr is that the outward verbal form of the invocation must harmonize with heartfelt intention there must be no contradiction between what the tongue articulates and what motivates the heart bringing heart and tongue into harmony means that the divine reality invoked by the tongue reverberates in the heart the very source of the souls fundamental dispositions its virtues', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 20, NULL, 'The divine qualities contained within the Name of the Absolute must, to some degree at least, be reflected in the heart and soul of the invoker as virtues — virtues that are summed up in the sincerity or purity of soul to which إِخْلَاص refers. When the soul is completely pure, sincerely and utterly at one with the highest ideals proclaimed by the tongue and the intellect, it becomes transparent to the spiritual qualities embedded within its own substance: the fitra, or primordial nature. These are the qualities brought to light, and brought to life, by the dhikr; they are the qualities that shine forth from the heart once it has been polished by the dhikr. In their absence, however, the purely technical act of invocation is heedless'' and without any effect. One who makes no effort to attain sincerity, who does not take up the greater jihad, is heedless of God, neglecting the moral qualities that accompany authentic remembrance and ignoring the moral conditions its efficacy requires.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'the divine qualities contained within the name of the absolute must to some degree at least be reflected in the heart and soul of the invoker as virtues virtues that are summed up in the sincerity or purity of soul to which اخلاص refers when the soul is completely pure sincerely and utterly at one with the highest ideals proclaimed by the tongue and the intellect it becomes transparent to the spiritual qualities embedded within its own substance the fitra or primordial nature these are the qualities brought to light and brought to life by the dhikr they are the qualities that shine forth from the heart once it has been polished by the dhikr in their absence however the purely technical act of invocation is heedless and without any effect one who makes no effort to attain sincerity who does not take up the greater jihad is heedless of god neglecting the moral qualities that accompany authentic remembrance and ignoring the moral conditions its efficacy requires', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 21, NULL, 'Yet what is most remarkable in this saying of the Imam is his presentation of the ultimate stage of dhikr in terms of its apparent opposite. The reality of dhikr, its haqiqa, opens outward into the supreme haqiqa, divine Reality as such. This degree of dhikr requires the forgetting of the individual: the veil of the self must be cast aside if the spiritual vision of divine Reality is to be attained. There can be no marifa without self-effacement at the outset, and extinction (فَنَاء) in the end. The reality of remembering calls for the most radical forgetting.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'yet what is most remarkable in this saying of the imam is his presentation of the ultimate stage of dhikr in terms of its apparent opposite the reality of dhikr its haqiqa opens outward into the supreme haqiqa divine reality as such this degree of dhikr requires the forgetting of the individual the veil of the self must be cast aside if the spiritual vision of divine reality is to be attained there can be no marifa without self effacement at the outset and extinction فناء in the end the reality of remembering calls for the most radical forgetting', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 22, NULL, 'In other words, a clear distinction — indeed a radical break — separates perfect dhikr from the reality of dhikr. To move from perfection to reality, from human perfection to divine Reality, is to make an ontological leap of consciousness. At the first level, the aim is to eliminate hypocrisy and to attain sincerity, integrity, and wholeness — in short, perfection on the plane of the human soul. Here the individual, as the agent of the dhikr, keeps his identity. The harmonious reverberation between hidden intent and outward act is what, at this stage, is called perfect dhikr. Yet it remains a dhikr belonging to the individual as agent. At the higher level, by contrast, the dhikr can no longer be defined in relation to the individual, for the individual has been forgotten — forgotten by himself. This can only mean that the center of consciousness has shifted from the invoker, al-dhakir, to the Invoked, الْمَذْكُورُ. The haqiqa of the dhikr is thus one with the object of invocation, the Real itself, اَلْحَقّ. Esoterically, then, the true agent of the invocation is God Himself. Man''s apparent invocation is no more than an outward appearance, an illusion that the very act of invocation extinguishes.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'in other words a clear distinction indeed a radical break separates perfect dhikr from the reality of dhikr to move from perfection to reality from human perfection to divine reality is to make an ontological leap of consciousness at the first level the aim is to eliminate hypocrisy and to attain sincerity integrity and wholeness in short perfection on the plane of the human soul here the individual as the agent of the dhikr keeps his identity the harmonious reverberation between hidden intent and outward act is what at this stage is called perfect dhikr yet it remains a dhikr belonging to the individual as agent at the higher level by contrast the dhikr can no longer be defined in relation to the individual for the individual has been forgotten forgotten by himself this can only mean that the center of consciousness has shifted from the invoker al dhakir to the invoked المذكور the haqiqa of the dhikr is thus one with the object of invocation the real itself الحق esoterically then the true agent of the invocation is god himself mans apparent invocation is no more than an outward appearance an illusion that the very act of invocation extinguishes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 23, NULL, 'The question of agency returns here. A hadith qudsi bears upon it: "My slave never ceases to draw near to Me through supererogatory acts (نَوَافِلُ) until I love him." In his commentary on the Quranic verses about those whom the world does not distract from the remembrance of God, the Imam made clear that these نَوَافِلُ center upon the practice of invocation. Invocation, then, can be understood as disclosing the reality of God''s ontological agency within all acts: God is the hearing and the seeing of the individual whom He loves as a result of his devotions. This account of the Divine penetrating the faculties of soul and body describes a universal reality, the true state of affairs — not any change of state, whether in God or in the individual. God does not "change" in order to enter into the acts and perceptions of one person rather than another.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'the question of agency returns here a hadith qudsi bears upon it my slave never ceases to draw near to me through supererogatory acts نوافل until i love him in his commentary on the quranic verses about those whom the world does not distract from the remembrance of god the imam made clear that these نوافل center upon the practice of invocation invocation then can be understood as disclosing the reality of gods ontological agency within all acts god is the hearing and the seeing of the individual whom he loves as a result of his devotions this account of the divine penetrating the faculties of soul and body describes a universal reality the true state of affairs not any change of state whether in god or in the individual god does not change in order to enter into the acts and perceptions of one person rather than another', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 24, NULL, 'His "becoming" one with the acts of perception must be understood as a reality "becoming clear" to the soul once it is unveiled, so that the soul sees through the illusory appearance of its own agency. Through the invocation, the soul is enabled to see the deeper meaning of two Quranic verses:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'his becoming one with the acts of perception must be understood as a reality becoming clear to the soul once it is unveiled so that the soul sees through the illusory appearance of its own agency through the invocation the soul is enabled to see the deeper meaning of two quranic verses', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 25, NULL, 'As-Saffat: 96وَٱللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ"God hath created you and what ye do" (As-Saffat: 96)', '', NULL, 'As-Saffat: 96', NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'as saffat 96والله خلقكم وما تعملون god hath created you and what ye do as saffat 96', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 26, NULL, 'and:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'and', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 27, NULL, 'Al-Anfal: 17وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَكِنَّ ٱللَّهَ رَمَىٰ"thou didst not throw when thou threwest [the stones], but God threw" (Al-Anfal: 17).', '', NULL, 'Al-Anfal: 17', NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'al anfal 17وما رميت اذ رميت ولكن الله رمي thou didst not throw when thou threwest the stones but god threw al anfal 17', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 28, NULL, 'The kind of "vision" the dhikr makes possible is illuminated by the very title of one of Ibn al-Arabi''s treatises, Kitab al-fana fil-mushahada (The Book of Extinction in Contemplation). The title seems to point directly at the Imam''s paradox of forgetting at the very heart of remembrance, for to be extinguished in contemplation is akin to being forgotten in invocation. At the opening of this treatise, Ibn al-Arabi writes that the divine Reality is too exalted to be witnessed by the creaturely eye. The vision of God is impossible so long as any "trace of the condition of the creature in the eye of the witness" remains. Only toward the end of the treatise is this seemingly insuperable barrier removed. Ibn al-Arabi resolves the problem by means of the Prophet''s definition of احسان: "It is to worship God as though you see Him, and if you see Him not, yet truly He sees you." The Arabic wording allows a pause to be placed in the middle of the phrase "if you see Him not (in lam takun: tarahu)," and that pause transforms the meaning entirely into: "if you are not, you see Him."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'the kind of vision the dhikr makes possible is illuminated by the very title of one of ibn al arabis treatises kitab al fana fil mushahada the book of extinction in contemplation the title seems to point directly at the imams paradox of forgetting at the very heart of remembrance for to be extinguished in contemplation is akin to being forgotten in invocation at the opening of this treatise ibn al arabi writes that the divine reality is too exalted to be witnessed by the creaturely eye the vision of god is impossible so long as any trace of the condition of the creature in the eye of the witness remains only toward the end of the treatise is this seemingly insuperable barrier removed ibn al arabi resolves the problem by means of the prophets definition of احسان it is to worship god as though you see him and if you see him not yet truly he sees you the arabic wording allows a pause to be placed in the middle of the phrase if you see him not in lam takun tarahu and that pause transforms the meaning entirely into if you are not you see him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 29, NULL, 'This vision of God cannot, then, belong to the individual — "forgotten" in the Imam''s words, or non-existent according to Ibn al-Arabi. The vision of God can only be by God, not by man. The metaphysical underpinnings of this "ontological transference," in relation to the divine Names, are taken up further on. The message of "extinction in contemplation" is reinforced by a dialogue Ibn al-Arabi narrates between himself and Moses in the sixth heaven, set within his account of his own visionary ascent through the heavens to the divine presence within his own soul.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'this vision of god cannot then belong to the individual forgotten in the imams words or non existent according to ibn al arabi the vision of god can only be by god not by man the metaphysical underpinnings of this ontological transference in relation to the divine names are taken up further on the message of extinction in contemplation is reinforced by a dialogue ibn al arabi narrates between himself and moses in the sixth heaven set within his account of his own visionary ascent through the heavens to the divine presence within his own soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 30, NULL, 'He addresses Moses: "You requested the vision (of God), while the Messenger of God (مُحَمَّد) said that not one of you will see his Lord until he dies."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'he addresses moses you requested the vision of god while the messenger of god محمد said that not one of you will see his lord until he dies', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 31, NULL, 'Moses replies: "And it was just like that: when I asked Him for the vision, He answered me, so that I fell down stunned (Al-Araf: 143). Then I saw Him in my (state of) being stunned."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'moses replies and it was just like that when i asked him for the vision he answered me so that i fell down stunned al araf 143 then i saw him in my state of being stunned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 32, NULL, 'Ibn al-Arabi asks: "While (you were) dead?"', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'ibn al arabi asks while you were dead', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 33, NULL, 'Moses: "While (I was) dead. I did not see God until I had died."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'moses while i was dead i did not see god until i had died', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 34, NULL, 'Here is a supra-personal vision entirely congruent with Ali s unselfconscious remembrance. What both forms of spiritual assimilation imply is the "ontological transference" of agency. The true vision of God cannot take place so long as anything creaturely remains in the "eye" of the beholder. The spiritual principle of this dialogue — and even some of its language — is rendered in condensed form in a supplication attributed to the Imam. He pleads with God to make him "one of those whom You have called and he has replied to You, upon whom You have glanced and who falls unconscious before Your majesty." The word saiqa ("to fall unconscious," "to be stunned") in this supplication is the same word used in the Quranic verse (Al-Araf: 143) for Moses'' state when God revealed Himself to the mountain. A single "glance" from the Real suffices to precipitate this undoing of self-awareness — the shadow cast, upon the plane of individual consciousness, by the blazing light of God''s self-disclosure, His tajalli.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'here is a supra personal vision entirely congruent with ali s unselfconscious remembrance what both forms of spiritual assimilation imply is the ontological transference of agency the true vision of god cannot take place so long as anything creaturely remains in the eye of the beholder the spiritual principle of this dialogue and even some of its language is rendered in condensed form in a supplication attributed to the imam he pleads with god to make him one of those whom you have called and he has replied to you upon whom you have glanced and who falls unconscious before your majesty the word saiqa to fall unconscious to be stunned in this supplication is the same word used in the quranic verse al araf 143 for moses state when god revealed himself to the mountain a single glance from the real suffices to precipitate this undoing of self awareness the shadow cast upon the plane of individual consciousness by the blazing light of gods self disclosure his tajalli', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 35, NULL, 'This divine "glance" (لَحْظَة) returns the discussion to Ibn al-Arabi''s evocative phrase "extinction in contemplation." In his Tarjuman al-ashwaq, he refers to divine wisdom as a peacock that "kills with her glances," and adds in his own commentary that this refers to "the station" of al-fana fil-mushahada (extinction in contemplation). Earlier in the same commentary, he refers to the "murderous glances" of this divine wisdom "which accrues to a man in his hours of solitude, and which assaults him with such violence that he is unable to behold his personality, and which exercises dominion over him." His commentary on the following lines is also instructive, underlining the relationship between dhikr and فَنَاء: "Wild is she, none can make her his friend; she has gotten in her solitary chamber (بَيْتُ خَلْوَتِهَا), a mausoleum for remembrance (ذِکْر)." The commentary adds: "because contemplation of the Essence is a passing away (فَنَاء). Her solitude is her looking on herself, for God says, Neither My earth nor My heaven contains Me, but I am contained by the heart of My believing servant, and since the heart which contains this essential wisdom of the race of Jesus is bare and empty of all attributes, it is like a desert and she is like a wild animal."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'this divine glance لحظه returns the discussion to ibn al arabis evocative phrase extinction in contemplation in his tarjuman al ashwaq he refers to divine wisdom as a peacock that kills with her glances and adds in his own commentary that this refers to the station of al fana fil mushahada extinction in contemplation earlier in the same commentary he refers to the murderous glances of this divine wisdom which accrues to a man in his hours of solitude and which assaults him with such violence that he is unable to behold his personality and which exercises dominion over him his commentary on the following lines is also instructive underlining the relationship between dhikr and فناء wild is she none can make her his friend she has gotten in her solitary chamber بيت خلوتها a mausoleum for remembrance ذكر the commentary adds because contemplation of the essence is a passing away فناء her solitude is her looking on herself for god says neither my earth nor my heaven contains me but i am contained by the heart of my believing servant and since the heart which contains this essential wisdom of the race of jesus is bare and empty of all attributes it is like a desert and she is like a wild animal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 36, NULL, 'Realization through remembrance, then, strictly implies the extinction of individual consciousness, the perishing of egoistic self-awareness before the Absolute. This principle is far from merely speculative. Quite apart from the wealth of Sufi literature on the states of consciousness (ahwal, sing. hal) through which the mystic passes, there is the evidence of the Imam''s own immersion in such states. Abul-Darda, an eminent companion of the Prophet, reported that he once found Ali lying in one of the palm orchards of Medina, his body seemingly lifeless, as stiff as wood. He went to condole with Ali s family, but was told by his wife Fatima, "My cousin has not died. Rather, in fear of God he has fainted. This condition overcomes him often." The "fear" in question is to be understood as "awe." It relates to the heavenly aspect of khawf — heavenly because Paradise is said to be the fruit of realizing this kind of fear to perfection, as the Quran indicates: "But whoso feareth (خَافَ) the station of his Lord and restraineth his soul from caprice, verily, the Garden will be his abode" (An-Naziat: 40-41). "Fear of God," in the spiritual rather than the moralistic sense, does not so much terrify as beatify. It produces not merely quaking awe before the transcendent Absolute, but also an intimate absorption within the immanent divine presence. As is often quoted in Sufism: when one fears creatures one flees from them, but when one fears God one flees to Him:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'realization through remembrance then strictly implies the extinction of individual consciousness the perishing of egoistic self awareness before the absolute this principle is far from merely speculative quite apart from the wealth of sufi literature on the states of consciousness ahwal sing hal through which the mystic passes there is the evidence of the imams own immersion in such states abul darda an eminent companion of the prophet reported that he once found ali lying in one of the palm orchards of medina his body seemingly lifeless as stiff as wood he went to condole with ali s family but was told by his wife fatima my cousin has not died rather in fear of god he has fainted this condition overcomes him often the fear in question is to be understood as awe it relates to the heavenly aspect of khawf heavenly because paradise is said to be the fruit of realizing this kind of fear to perfection as the quran indicates but whoso feareth خاف the station of his lord and restraineth his soul from caprice verily the garden will be his abode an naziat 40 41 fear of god in the spiritual rather than the moralistic sense does not so much terrify as beatify it produces not merely quaking awe before the transcendent absolute but also an intimate absorption within the immanent divine presence as is often quoted in sufism when one fears creatures one flees from them but when one fears god one flees to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 37, NULL, 'At-Tawbah: 118لَّا مَلْجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيْهِ"There is no refuge from God except [fleeing] to Him" (At-Tawbah: 118).', '', NULL, 'At-Tawbah: 118', NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'at tawbah 118لا ملجا من الله الا اليه there is no refuge from god except fleeing to him at tawbah 118', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 38, NULL, 'This report also shows that the following saying of the Imam is not mere extravagant rhetoric. It appears, rather, to allude to an authentic state of spiritual intoxication — a total re-absorption of consciousness within its divine source, and a description of the conditions leading up to the state that "overcomes him often," as Fatima put it:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'this report also shows that the following saying of the imam is not mere extravagant rhetoric it appears rather to allude to an authentic state of spiritual intoxication a total re absorption of consciousness within its divine source and a description of the conditions leading up to the state that overcomes him often as fatima put it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 39, NULL, 'Truly, God has a drink for His friends (أَوْلِيَائِهِ). When they drink it, they are intoxicated (سَكَرَ); and when they are intoxicated, they are enraptured (عَرِبَ); and when they are enraptured, they are blessed (طَابَ); and when they are blessed, they dissolve (ذَابَ); and when they dissolve, they are free (خَلَصَ); and when they are free, they devote themselves purely (أَخْلَصَ); and when they devote themselves purely, they seek (طَلَبَ); and when they seek, they find (وَجَدَ); and when they find, they arrive (وَصَلَ); and when they arrive, they are at one (اِتَّصَلَ); there is no difference between them and their Beloved.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'truly god has a drink for his friends اوليايه when they drink it they are intoxicated سكر and when they are intoxicated they are enraptured عرب and when they are enraptured they are blessed طاب and when they are blessed they dissolve ذاب and when they dissolve they are free خلص and when they are free they devote themselves purely اخلص and when they devote themselves purely they seek طلب and when they seek they find وجد and when they find they arrive وصل and when they arrive they are at one اتصل there is no difference between them and their beloved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 40, NULL, 'This saying of the Imam echoes that of the Prophet, who said he had states or "moments" (وَقْت) that no "angel brought close" nor "prophet sent forth" could encompass — the implication being that neither angel nor prophet can subsist as such in the ineffable "moments" of absolute تَوْحِيد. This is not "union"; it is, rather, the realization of oneness. Union implies two entities becoming one, whereas God is, as the Imam put it, "that which has no second." Even to call Him "one" falls short, since that word implies that a second might stand in sequence to Him. He is more truly named unique — a reality that admits no otherness. This ultimate realization of تَوْحِيد can be seen as the fruit of the invocation — the most potent of all intoxicating "drinks," if prayer may be called a drink. And it leads to a careful consideration of the true agent of the invocation, the true "drinker." What appears to be man''s invocation of God is transformed into the divine invocation of man. At the outset it seems that man "drinks" God through His Name; but the ultimate result of the invocation, unitive realization, reveals that it is in fact God who "drinks into Himself" the essence of human consciousness — an essence from which the impurity of self-consciousness has been extracted. The true nature of the dhikr, masked by the outward form of man''s invocation of God, is alluded to in another saying of the Imam: "The invocation is not a formality of speech nor a way of thinking; rather, it comes forth firstly from the Invoked, and secondly from the invoker (awwal min الْمَذْكُورُ wa thanin min al-dhakir)."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'this saying of the imam echoes that of the prophet who said he had states or moments وقت that no angel brought close nor prophet sent forth could encompass the implication being that neither angel nor prophet can subsist as such in the ineffable moments of absolute توحيد this is not union it is rather the realization of oneness union implies two entities becoming one whereas god is as the imam put it that which has no second even to call him one falls short since that word implies that a second might stand in sequence to him he is more truly named unique a reality that admits no otherness this ultimate realization of توحيد can be seen as the fruit of the invocation the most potent of all intoxicating drinks if prayer may be called a drink and it leads to a careful consideration of the true agent of the invocation the true drinker what appears to be mans invocation of god is transformed into the divine invocation of man at the outset it seems that man drinks god through his name but the ultimate result of the invocation unitive realization reveals that it is in fact god who drinks into himself the essence of human consciousness an essence from which the impurity of self consciousness has been extracted the true nature of the dhikr masked by the outward form of mans invocation of god is alluded to in another saying of the imam the invocation is not a formality of speech nor a way of thinking rather it comes forth firstly from the invoked and secondly from the invoker awwal min المذكور wa thanin min al dhakir', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 41, NULL, 'It is thus God Himself who performs the invocation, first and foremost; man''s invocation is but a shadow, a reflection, a consequence of this divine invocation. The many-sidedness of the Imam''s brief sentence opens onto a number of fruitful meditations upon the meaning, the origin, the end, and the very substance of the dhikr. Among these stands the Quranic verse cited earlier: "Remember Me, I will remember you."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'it is thus god himself who performs the invocation first and foremost mans invocation is but a shadow a reflection a consequence of this divine invocation the many sidedness of the imams brief sentence opens onto a number of fruitful meditations upon the meaning the origin the end and the very substance of the dhikr among these stands the quranic verse cited earlier remember me i will remember you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 42, NULL, 'This perception of the reality of the invocation reveals its spiritual efficacy more clearly. The reality denoted by the term dhikr is no longer confined within the boundaries of the individual, still less definable in terms of his verbal or mental activity. In its primary, metaphysical significance, dhikr opens out into the realm of engendering — it implies the function of bringing into existence, the effusion of Being. The creative Word uttered by God — "Be! (كُنْ)" — which brings the possibilities of being into existence, can be seen in this light as a form of dhikr: God utters the "name" of the possible thing, "calling" it from nonexistence into existence. This passage from nothingness to being is what renders the possible thing "remembered," madhkur. Here again, the Imam''s sentence can be read both as a commentary on a Quranic verse and as an anticipation of the highly elaborate cosmogony associated with Ibn al-Arabi.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'this perception of the reality of the invocation reveals its spiritual efficacy more clearly the reality denoted by the term dhikr is no longer confined within the boundaries of the individual still less definable in terms of his verbal or mental activity in its primary metaphysical significance dhikr opens out into the realm of engendering it implies the function of bringing into existence the effusion of being the creative word uttered by god be كن which brings the possibilities of being into existence can be seen in this light as a form of dhikr god utters the name of the possible thing calling it from nonexistence into existence this passage from nothingness to being is what renders the possible thing remembered madhkur here again the imams sentence can be read both as a commentary on a quranic verse and as an anticipation of the highly elaborate cosmogony associated with ibn al arabi', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 43, NULL, 'The Quran poses the following question:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'the quran poses the following question', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 44, NULL, 'Al-Insan: 1هَلْ أَتَىٰ عَلَى ٱلْإِنسَنِ حِينٌۭ مِّنَ ٱلدَّهْرِ لَمْ يَكُن شَيْـًۭٔا مَّذْكُورًا"Hath there come upon man any moment in time when he was not a thing remembered?" (Al-Insan: 1).', '', NULL, 'Al-Insan: 1', NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'al insan 1هل اتي علي الانسن حين من الدهر لم يكن شيا مذكورا hath there come upon man any moment in time when he was not a thing remembered al insan 1', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 45, NULL, 'Man''s being a "thing remembered" is here tantamount to his coming into being, and his nothingness is equivalent to his being "not remembered" — that is, not yet called forth from the abyss of pre-existential hiddenness into the light of manifest existence. In this pre-existential state, the human being is, according to Ibn al-Arabi, "known," malum, but only by God. He refers to this verse in the following lines of al-Futuhat al-makkiyya (The Meccan Illuminations):', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'mans being a thing remembered is here tantamount to his coming into being and his nothingness is equivalent to his being not remembered that is not yet called forth from the abyss of pre existential hiddenness into the light of manifest existence in this pre existential state the human being is according to ibn al arabi known malum but only by god he refers to this verse in the following lines of al futuhat al makkiyya the meccan illuminations', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 46, NULL, 'God said of Himself that He is al-Badi, the Originator, that is, He created that which had no like or exemplar in all the degrees of being, for He knows, by His all-encompassing nature, every single thing that enters into the degrees of being. Therefore He says, as regards the creation of man, that he "was not a thing remembered," for His is the remembrance, so a thing has being in the remembrance of the one who remembers it.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'god said of himself that he is al badi the originator that is he created that which had no like or exemplar in all the degrees of being for he knows by his all encompassing nature every single thing that enters into the degrees of being therefore he says as regards the creation of man that he was not a thing remembered for his is the remembrance so a thing has being in the remembrance of the one who remembers it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 47, NULL, 'God''s "remembrance" of man thus precedes man''s remembrance of God — ontologically, not merely temporally. This yields another interpretation of the verse cited earlier: "and the remembrance of God is greater" — infinitely greater, that is, than man''s remembrance of Him. The true being of man resides in the "remembrance" God has of him. While man''s devotion to God is articulated through the utterance of the divine Name, God''s creation of man is articulated through His utterance of the creative Word. In Ibn al-Arabi''s cosmogony, the utterance of this Word is not simply an event in time; that Word never ceases to reverberate, furnishing each human soul with its divine substrate, support, or foundation — its mustanad ilahi. This Word "breathes" existence upon the immutable entity, al-ayn al-thabita, which, though inexistent in itself, determines the contours, form, and configuration of the being that will be manifested through it — just as a prism refracts the light passing through it, or as water takes on the color of its cup, an image used by Junayd and often quoted by Ibn al-Arabi.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'gods remembrance of man thus precedes mans remembrance of god ontologically not merely temporally this yields another interpretation of the verse cited earlier and the remembrance of god is greater infinitely greater that is than mans remembrance of him the true being of man resides in the remembrance god has of him while mans devotion to god is articulated through the utterance of the divine name gods creation of man is articulated through his utterance of the creative word in ibn al arabis cosmogony the utterance of this word is not simply an event in time that word never ceases to reverberate furnishing each human soul with its divine substrate support or foundation its mustanad ilahi this word breathes existence upon the immutable entity al ayn al thabita which though inexistent in itself determines the contours form and configuration of the being that will be manifested through it just as a prism refracts the light passing through it or as water takes on the color of its cup an image used by junayd and often quoted by ibn al arabi', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 48, NULL, 'The hadith al-haqiqa, attributed to Ali, contains the essence of the Akbari doctrine of the tajalli of the unique Light of God upon the differentiated "receptacles," the loci of manifestation for that Light. The Imam''s disciple Kumayl questions him on the meaning of al-haqiqa. The response includes the following affirmations:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'the hadith al haqiqa attributed to ali contains the essence of the akbari doctrine of the tajalli of the unique light of god upon the differentiated receptacles the loci of manifestation for that light the imams disciple kumayl questions him on the meaning of al haqiqa the response includes the following affirmations', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 49, NULL, 'Al-haqiqa is the unveiling of the splendors of Majesty without any allusion; the effacement of what is falsely imagined (الْمَوْهُومُ) together with the clarity of what is truly known (الْمَعْلُومُ); the drawing of absolute unicity toward the quality of تَوْحِيد; a light dawning from the morning of eternity, its traces shimmering upon the temples of تَوْحِيد.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'al haqiqa is the unveiling of the splendors of majesty without any allusion the effacement of what is falsely imagined الموهوم together with the clarity of what is truly known المعلوم the drawing of absolute unicity toward the quality of توحيد a light dawning from the morning of eternity its traces shimmering upon the temples of توحيد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 50, NULL, 'Al-Kashani comments on this last image: "That is, the manifestation of the Light of the one Essence upon the loci of manifestation of the qualities of the Real, the Essence, these being the loci of the entities of existents (أَعْيَانُ الْمَوْجُودَاتِ), which the Imam calls temples of تَوْحِيد, that is, the forms of the divine Names in the station of تَوْحِيد." This mustanad ilahi, or divine support of each individual soul, is therefore its particular Lord, the divine Name that engenders and sustains it. The soul is but the locus of manifestation, the mazhar, where God discloses Himself in a particular, unique mode.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'al kashani comments on this last image that is the manifestation of the light of the one essence upon the loci of manifestation of the qualities of the real the essence these being the loci of the entities of existents اعيان الموجودات which the imam calls temples of توحيد that is the forms of the divine names in the station of توحيد this mustanad ilahi or divine support of each individual soul is therefore its particular lord the divine name that engenders and sustains it the soul is but the locus of manifestation the mazhar where god discloses himself in a particular unique mode', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 51, NULL, 'The very first words of the khutba with which Ibn al-Arabi opens the Futuhat al-makkiyya are these: "Praise be to Him who engendered things from nothing, then negated it; and established their being through the orientation toward them of His Words." When the divine Word turns toward a possible thing—this turning is تَوَجُّه—the Word''s properties become manifest according to what that possible thing can receive. The possibility is then "breathed" into existence and becomes like a "body," whose "heart" is the divine Name that brings it into being: "every slave has a Name which is its Lord; so it becomes the body of that Name, which is its heart."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'the very first words of the khutba with which ibn al arabi opens the futuhat al makkiyya are these praise be to him who engendered things from nothing then negated it and established their being through the orientation toward them of his words when the divine word turns toward a possible thing this turning is توجه the words properties become manifest according to what that possible thing can receive the possibility is then breathed into existence and becomes like a body whose heart is the divine name that brings it into being every slave has a name which is its lord so it becomes the body of that name which is its heart', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 52, NULL, 'This comparison recalls the Imam''s image of the dhikr as a "polish" for hearts. The Name revealed from "above" is mirrored by a Name that resounds from "within." This mutual reflection appears once the rust clouding the surface of the heart is removed by the polish of the dhikr. What is evoked here is a kind of union between two divine realities, and it brings to mind once more the phrase "light upon light."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'this comparison recalls the imams image of the dhikr as a polish for hearts the name revealed from above is mirrored by a name that resounds from within this mutual reflection appears once the rust clouding the surface of the heart is removed by the polish of the dhikr what is evoked here is a kind of union between two divine realities and it brings to mind once more the phrase light upon light', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 53, NULL, 'Earlier the Imam had spoken of the Names of God "which have filled the foundations of all things," a phrase that anticipates Ibn al-Arabi''s teaching that the divine Names are the supports and underlying ground of all things. A question arises here, and its answers bring one nearer to grasping the powerful and mysterious efficacy of the dhikr. What is the difference between the divine Names understood as the metaphysical roots of all things and the particular Names of God revealed in the Quran? On one side, the whole of creation is the "Book of God," and every phenomenon is one of God''s "words." On the other, the revealed text holds specific words and Names, and it is these that are to be recited and invoked. Why?', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'earlier the imam had spoken of the names of god which have filled the foundations of all things a phrase that anticipates ibn al arabis teaching that the divine names are the supports and underlying ground of all things a question arises here and its answers bring one nearer to grasping the powerful and mysterious efficacy of the dhikr what is the difference between the divine names understood as the metaphysical roots of all things and the particular names of god revealed in the quran on one side the whole of creation is the book of god and every phenomenon is one of gods words on the other the revealed text holds specific words and names and it is these that are to be recited and invoked why', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 54, NULL, 'One clear answer is given in the following verse:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'one clear answer is given in the following verse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 55, NULL, 'Al-Isra: 110قُلِ ٱدْعُوا۟ ٱللَّهَ أَوِ ٱدْعُوا۟ ٱلرَّحْمَنَ ۖ أَيًّۭا مَّا تَدْعُوا۟ فَلَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ ۚ وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَٱبْتَغِ بَيْنَ ذَلِكَ سَبِيلًۭا"Call upon Allah or call upon al-Rahman. By whatever Name you call upon Him, His are the most beautiful Names" (Al-Isra: 110).', '', NULL, 'Al-Isra: 110', NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'al isra 110قل ادعوا الله او ادعوا الرحمن ايا ما تدعوا فله الاسماء الحسني ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا call upon allah or call upon al rahman by whatever name you call upon him his are the most beautiful names al isra 110', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 56, NULL, 'The Quran itself commands believers to invoke these specific, revealed Names, and not others. These Names are therefore utterly unlike the names of the idolaters'' gods:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'the quran itself commands believers to invoke these specific revealed names and not others these names are therefore utterly unlike the names of the idolaters gods', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'verse', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 57, NULL, 'An-Najm: 23إِنْ هِىَ إِلَّآ أَسْمَآءٌۭ سَمَّيْتُمُوهَآ أَنتُمْ وَآبَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَنٍ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهْوَى ٱلْأَنفُسُ ۖ وَلَقَدْ جَآءَهُم مِّن رَّبِّهِمُ ٱلْهُدَىٰٓ"They are but names that ye have named, ye and your fathers, for which God hath revealed no authority" (An-Najm: 23).', '', 'إِنْ هِىَ إِلَّآ أَسْمَآءٌۭ سَمَّيْتُمُوهَآ أَنتُمْ وَآبَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَنٍ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهْوَى ٱلْأَنفُسُ ۖ وَلَقَدْ جَآءَهُم مِّن رَّبِّهِمُ ٱلْهُدَىٰٓ', 'An-Najm: 23', 53, 23, 'spiritual ethos 12 remembrance as the quintessence of worship', 'an najm 23ان هي الا اسماء سميتموها انتم واباوكم ما انزل الله بها من سلطن ان يتبعون الا الظن وما تهوي الانفس ولقد جاءهم من ربهم الهدي they are but names that ye have named ye and your fathers for which god hath revealed no authority an najm 23', 'ان هي الا اسماء سميتموها انتم واباوكم ما انزل الله بها من سلطن ان يتبعون الا الظن وما تهوي الانفس ولقد جاءهم من ربهم الهدي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 58, NULL, 'The names of idols are like the ordinary names given to things: arbitrary labels or signs with no real bond to the things themselves, and still less to the principles beneath those things. The Names of God, revealed by God, belong to another order. They are steeped in the very substance of the reality they name. For this reason they carry "authority" (سُلْطَان), and by virtue of that authority they have the power to transform and not merely to inform. They are, in other words, charged with a theurgic power, the capacity to render present to mind and heart the indwelling reality of God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'the names of idols are like the ordinary names given to things arbitrary labels or signs with no real bond to the things themselves and still less to the principles beneath those things the names of god revealed by god belong to another order they are steeped in the very substance of the reality they name for this reason they carry authority سلطان and by virtue of that authority they have the power to transform and not merely to inform they are in other words charged with a theurgic power the capacity to render present to mind and heart the indwelling reality of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 59, NULL, 'God''s presence cannot be taken away, since nothing that exists can lie "outside" His all-encompassing presence; yet that presence can still become veiled, at least from the side of the one who perceives. The heart can be veiled from God by the "rust" of forgetfulness that settles over it, so that the divine Reality comes to be hidden by the very phenomena that manifest it. The Imam raises the question of how it is that the Creator both manifests Himself "by things" and is hidden from sight "by things."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'gods presence cannot be taken away since nothing that exists can lie outside his all encompassing presence yet that presence can still become veiled at least from the side of the one who perceives the heart can be veiled from god by the rust of forgetfulness that settles over it so that the divine reality comes to be hidden by the very phenomena that manifest it the imam raises the question of how it is that the creator both manifests himself by things and is hidden from sight by things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 60, NULL, 'This being so, two things are needed to open oneself to the divine presence within and beyond all things: a polishing of one''s own "within" through the dhikr, and an unveiling or revelation from that "beyond." This second disclosure can be understood as a direct revelation of God within the indirect revelation of Him that is the whole created cosmos—a cosmos that reveals and veils the divine Reality at once. From one point of view the two revelations, cosmic and scriptural, are both manifestations of God; from another, the scriptural revelation is charged with a spiritual power that makes it incomparably more revealing than the created cosmos. As a spiritual method, the cosmos as manifested divine "Word" and Allah as a revealed Name of God share no common measure. The one is differentiated manifestation; the other, a unique revelation. The divine Name may also be called the quintessential manifestation, for it both sums up the entire realm of manifestation and transcends it.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'this being so two things are needed to open oneself to the divine presence within and beyond all things a polishing of ones own within through the dhikr and an unveiling or revelation from that beyond this second disclosure can be understood as a direct revelation of god within the indirect revelation of him that is the whole created cosmos a cosmos that reveals and veils the divine reality at once from one point of view the two revelations cosmic and scriptural are both manifestations of god from another the scriptural revelation is charged with a spiritual power that makes it incomparably more revealing than the created cosmos as a spiritual method the cosmos as manifested divine word and allah as a revealed name of god share no common measure the one is differentiated manifestation the other a unique revelation the divine name may also be called the quintessential manifestation for it both sums up the entire realm of manifestation and transcends it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 61, NULL, 'In one respect the difference between cosmic manifestation and scriptural revelation is like the difference between shadow and light. Revelation is like a projection of the pure Light of God, and is therefore of one substance with the source from which it emanates; manifestation is like the shadow cast by that light. Both are projections of one and the same reality, yet this does not lessen how far apart light and darkness stand. In the words of Ibn al-Arabi, "The very Being of the Real is a verified Light, the very existence of creation is a shadow following after."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'in one respect the difference between cosmic manifestation and scriptural revelation is like the difference between shadow and light revelation is like a projection of the pure light of god and is therefore of one substance with the source from which it emanates manifestation is like the shadow cast by that light both are projections of one and the same reality yet this does not lessen how far apart light and darkness stand in the words of ibn al arabi the very being of the real is a verified light the very existence of creation is a shadow following after', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 62, NULL, 'There is a remarkable supplication attributed to Ali, the Dua al-Mashlul, the "supplication of the lame man." It runs to one hundred and twenty-two verses, filled with a great many divine Names, attributes, and titles. Near its end comes a verse that may be taken as the key to the entire text: "I ask Thee by every Name with which Thou hast named Thyself." It is because God "names Himself" that His Names hold their theurgic power, their sacramental substance, their mystical efficacy. The revealed substance of the Names is what accounts for these distinctive properties and makes them unlike any other names. This is why, as Sufi texts so commonly affirm, the Name is the Named (اَلِاسْمُ هُوَ الْمُسَمَّى).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'there is a remarkable supplication attributed to ali the dua al mashlul the supplication of the lame man it runs to one hundred and twenty two verses filled with a great many divine names attributes and titles near its end comes a verse that may be taken as the key to the entire text i ask thee by every name with which thou hast named thyself it is because god names himself that his names hold their theurgic power their sacramental substance their mystical efficacy the revealed substance of the names is what accounts for these distinctive properties and makes them unlike any other names this is why as sufi texts so commonly affirm the name is the named الاسم هو المسمي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 63, NULL, 'These reflections on how the Names of God stand in relation to being do illuminate certain sides of the dhikr as a mystical practice, yet they fall short of explaining that leap of consciousness in the order of being, that extinction of self-awareness, to which the Imam points in the words, "you will not remember Him according to the true reality of the remembrance until you forget your own soul in your remembrance." A question then follows: why and how does the dhikr bring about this extinction of consciousness, this effacement of individual being, especially when the very work of the dhikr seems to be the opposite—to awaken and bring on a heightened mode of consciousness and to deepen one''s quality of being?', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'these reflections on how the names of god stand in relation to being do illuminate certain sides of the dhikr as a mystical practice yet they fall short of explaining that leap of consciousness in the order of being that extinction of self awareness to which the imam points in the words you will not remember him according to the true reality of the remembrance until you forget your own soul in your remembrance a question then follows why and how does the dhikr bring about this extinction of consciousness this effacement of individual being especially when the very work of the dhikr seems to be the opposite to awaken and bring on a heightened mode of consciousness and to deepen ones quality of being', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'remembrance as the quintessence of worship', '12. Remembrance as the Quintessence of Worship', 64, NULL, 'Editorial note (tradition-grounded). The "spiritual amnesia" this chapter names, ghafla, is worth pausing over, since the very remembrance it prescribes is defined against it. The Arabic root غ-ف-ل describes an untended emptiness — land with no landmark, a mind with no attention — and ghafla is its inward form: a heedless forgetfulness of God, the exact opposite of the wakeful remembrance that dhikr demands. That opposition is why the chapter can treat distraction from the Name as distraction from God Himself, and why the invocation must be performed abundantly rather than merely contemplated. To invoke much, in this light, is to keep the field of the heart tended against the very emptiness the word describes.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 12 remembrance as the quintessence of worship', 'editorial note tradition grounded the spiritual amnesia this chapter names ghafla is worth pausing over since the very remembrance it prescribes is defined against it the arabic root غ ف ل describes an untended emptiness land with no landmark a mind with no attention and ghafla is its inward form a heedless forgetfulness of god the exact opposite of the wakeful remembrance that dhikr demands that opposition is why the chapter can treat distraction from the name as distraction from god himself and why the invocation must be performed abundantly rather than merely contemplated to invoke much in this light is to keep the field of the heart tended against the very emptiness the word describes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 0, NULL, 'The first response to that question begins with a limit. A person cannot, by his own effort, cross from remembrance into forgetfulness. Someone who is conscious, and who is concentrating on the act of invocation, cannot make himself unconscious of himself in the course of that invocation. The Imam''s phrasing is exact: the soul is to be forgotten in the remembrance. Any effort to will oneself into unconsciousness comes from a conscious will, and so it deepens self-consciousness rather than erasing it. The point, then, is not to force oneself to forget oneself while invoking God. It is rather to concentrate on the Name so completely that no room is left in one''s awareness — no space, whether mental or existential — for anything but the Named, the reality being invoked. A first degree of self-effacement can therefore be understood as a natural by-product of that total concentration.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'the first response to that question begins with a limit a person cannot by his own effort cross from remembrance into forgetfulness someone who is conscious and who is concentrating on the act of invocation cannot make himself unconscious of himself in the course of that invocation the imams phrasing is exact the soul is to be forgotten in the remembrance any effort to will oneself into unconsciousness comes from a conscious will and so it deepens self consciousness rather than erasing it the point then is not to force oneself to forget oneself while invoking god it is rather to concentrate on the name so completely that no room is left in ones awareness no space whether mental or existential for anything but the named the reality being invoked a first degree of self effacement can therefore be understood as a natural by product of that total concentration', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 1, NULL, 'The full completion of self-effacement in فَنَاء, however, comes as a divine grace. It exceeds all individual effort, even though the act of invocation is understood to draw this grace down, or to clear from the heart the rust that hides from a person his own nothingness before the sole reality of God, that which has no second. This part of the response can be gathered up in an esoteric reading of the Quranic words, ... thou wilt not forget, unless God willeth it so (Al-Ala: 6-7). Al-Kalabadhi, who wrote one of the most important early manuals of Sufism, opens his chapter on dhikr with words that echo the Imam''s: The haqiqa of the dhikr is this: that you forget everything other than the madhkur (the Invoked) in the dhikr. For He says: "So remember thy Lord when thou hast forgotten" (Al-Kahf: 24). That is, when you have forgotten what is not God, then you have remembered God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'the full completion of self effacement in فناء however comes as a divine grace it exceeds all individual effort even though the act of invocation is understood to draw this grace down or to clear from the heart the rust that hides from a person his own nothingness before the sole reality of god that which has no second this part of the response can be gathered up in an esoteric reading of the quranic words thou wilt not forget unless god willeth it so al ala 6 7 al kalabadhi who wrote one of the most important early manuals of sufism opens his chapter on dhikr with words that echo the imams the haqiqa of the dhikr is this that you forget everything other than the madhkur the invoked in the dhikr for he says so remember thy lord when thou hast forgotten al kahf 24 that is when you have forgotten what is not god then you have remembered god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 2, NULL, 'The second response can be framed through the principle of inverse analogy. Human invocation is analogous to divine invocation: it is a kind of reflection of it. And like any reflected image, human invocation both shares in what it reflects and turns it upside down. In the first respect, the act of invocation brings the invoker a fuller consciousness and a fuller share in being. In the second respect, human invocation reaches its completion in what looks like the very opposite of this: the effacement of the individual in the object he invokes. Yet the opposition is only apparent. In reality this effacement is the fulfillment of that same growth in consciousness and being, though its final stage is a sudden leap — the negation of the very limits that make a person a separate individual. The individual is limited, and a limit is itself a kind of negation; so to negate this negation amounts to pure affirmation: the affirmation of unconditional being that lies beyond the individual. On the plane of the self, this negation of a negation can be seen as the reflection of the negation of nothingness that Ibn al-Arabi expresses in his line, Praise be to Him who engendered things from nothing, then negated it.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'the second response can be framed through the principle of inverse analogy human invocation is analogous to divine invocation it is a kind of reflection of it and like any reflected image human invocation both shares in what it reflects and turns it upside down in the first respect the act of invocation brings the invoker a fuller consciousness and a fuller share in being in the second respect human invocation reaches its completion in what looks like the very opposite of this the effacement of the individual in the object he invokes yet the opposition is only apparent in reality this effacement is the fulfillment of that same growth in consciousness and being though its final stage is a sudden leap the negation of the very limits that make a person a separate individual the individual is limited and a limit is itself a kind of negation so to negate this negation amounts to pure affirmation the affirmation of unconditional being that lies beyond the individual on the plane of the self this negation of a negation can be seen as the reflection of the negation of nothingness that ibn al arabi expresses in his line praise be to him who engendered things from nothing then negated it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 3, NULL, 'Here the Imam''s enigmatic saying returns: I am the death of the dead. It recalls the words Rumi places in the Imam''s mouth in these lines of his Mathnawi:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'here the imams enigmatic saying returns i am the death of the dead it recalls the words rumi places in the imams mouth in these lines of his mathnawi', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 4, NULL, 'He said, I am wielding the sword for God''s sake, I am the servant of God, I am not under the command of the body.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'he said i am wielding the sword for gods sake i am the servant of god i am not under the command of the body', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 5, NULL, 'I am the Lion of God, I am not the lion of my passion: my deed bears witness to my religion.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'i am the lion of god i am not the lion of my passion my deed bears witness to my religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 6, NULL, 'In war I am (manifesting the truth of) thou didst not throw when thou threwest: I am (but) as the sword, and the wielder is the (divine) Sun.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'in war i am manifesting the truth of thou didst not throw when thou threwest i am but as the sword and the wielder is the divine sun', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 7, NULL, 'I have removed the baggage of self out of the way, I have deemed (what is) other than God to be non-existence.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'i have removed the baggage of self out of the way i have deemed what is other than god to be non existence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 8, NULL, 'I am a shadow, the Sun is my lord; I am the chamberlain, I am not the curtain (which prevents approach) to Him.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'i am a shadow the sun is my lord i am the chamberlain i am not the curtain which prevents approach to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 9, NULL, 'I am filled with the pearls of union, like a (jewelled) sword: in battle I make (men) living, not slain.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'i am filled with the pearls of union like a jewelled sword in battle i make men living not slain', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 10, NULL, 'The cosmic unfolding of creation moves from God to man, and it requires the negation of a relative nothingness that is pregnant with the possibilities of being. Man''s realization of God moves the other way, and it requires the negation of that same nothingness'' once breathed into being by God. Ibn al-Arabi''s treatise Extinction in Contemplation names what is at stake: the extinction of that which never was ... and the subsistence of that which never ceased to be. The following Quranic verses are clearly implied: Everything thereon perisheth (فَانٍۢ), and there subsisteth (يَبْقَىٰ) only the Face of thy Lord, possessor of glory and bounty (Ar-Rahman: 26-27).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'the cosmic unfolding of creation moves from god to man and it requires the negation of a relative nothingness that is pregnant with the possibilities of being mans realization of god moves the other way and it requires the negation of that same nothingness once breathed into being by god ibn al arabis treatise extinction in contemplation names what is at stake the extinction of that which never was and the subsistence of that which never ceased to be the following quranic verses are clearly implied everything thereon perisheth فان and there subsisteth يبقي only the face of thy lord possessor of glory and bounty ar rahman 26 27', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 11, NULL, 'Yet everything that exists has two aspects, or two faces'': a divine face, which is the thing''s true being, and a created face, which is nothing. The Face of the Lord that alone subsists is therefore not only the divine Reality above and beyond all things, but that same reality within all things. This is the meaning of al-Ghazali''s esoteric commentary on the Quranic verse, Everything perisheth except His Face (Al-Qasas: 88). Al-Ghazali comments:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'yet everything that exists has two aspects or two faces a divine face which is the things true being and a created face which is nothing the face of the lord that alone subsists is therefore not only the divine reality above and beyond all things but that same reality within all things this is the meaning of al ghazalis esoteric commentary on the quranic verse everything perisheth except his face al qasas 88 al ghazali comments', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 12, NULL, '[it is] not that it perisheth at some particular moment, but rather it is forever perishing, since it cannot be conceived except as perishing. For each thing other than God is, when considered in and by itself, pure nothingness; and if considered from the face (وَجْهَهُ) to which existence flows to it from the Prime Reality, it is viewed as existing, but not in itself, solely from the face which accompanies Him Who gives it existence. Therefore, the divine face is the sole thing in reality.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'it is not that it perisheth at some particular moment but rather it is forever perishing since it cannot be conceived except as perishing for each thing other than god is when considered in and by itself pure nothingness and if considered from the face وجهه to which existence flows to it from the prime reality it is viewed as existing but not in itself solely from the face which accompanies him who gives it existence therefore the divine face is the sole thing in reality', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 13, NULL, 'He then ties the mystical realization of this oneness to the invocation of God and to the forgetting of the self within that invocation, and so he gives a valuable commentary on what this total dissolution of self-consciousness means. The Sufis who verify this oneness through mystical taste (ذَوْقٌ), he writes, are drowned in oneness'', so that they become dumbfounded:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'he then ties the mystical realization of this oneness to the invocation of god and to the forgetting of the self within that invocation and so he gives a valuable commentary on what this total dissolution of self consciousness means the sufis who verify this oneness through mystical taste ذوق he writes are drowned in oneness so that they become dumbfounded', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 14, NULL, 'No capacity remained within them save to recall Allah; yea, not so much as the capacity to recall their own selves ... when this state prevails, it is called in relation to him who experiences it Extinction, nay Extinction of Extinction, for the soul has become extinct to itself, extinct to its own extinction; for it becomes unconscious of itself and unconscious of its own unconsciousness, since were it conscious of its own unconsciousness, it would be conscious of itself.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'no capacity remained within them save to recall allah yea not so much as the capacity to recall their own selves when this state prevails it is called in relation to him who experiences it extinction nay extinction of extinction for the soul has become extinct to itself extinct to its own extinction for it becomes unconscious of itself and unconscious of its own unconsciousness since were it conscious of its own unconsciousness it would be conscious of itself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 15, NULL, 'Relevant here too is a saying that al-Qushayri attributes to Abu Uthman, which throws light on another side of the unconsciousness'' reached through invocation: Whoever has not tasted the loneliness of unconsciousness will not find the food of the intimacy of remembrance. Here losing consciousness of oneself is called loneliness'', while becoming fully conscious of God through invocation yields intimacy. One cannot find true intimacy with the divine Reality except by stripping the self of its false intimacy — that self-satisfied, habitual self-centeredness which is the shadow cast by self-awareness. It is this awareness of self that, in the Imam''s statement, must be forgotten. Such higher forgetfulness can arise only on the ground of the remembrance of God; for only the source of Being, unconditional Consciousness, and eternal Life can extinguish, eclipse, or efface the relative existence, partial consciousness, and apparent life of the individual. This, the haqiqa of the dhikr, is put with perfect economy in the Imam''s own words: ... forget your own soul in your remembrance.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'relevant here too is a saying that al qushayri attributes to abu uthman which throws light on another side of the unconsciousness reached through invocation whoever has not tasted the loneliness of unconsciousness will not find the food of the intimacy of remembrance here losing consciousness of oneself is called loneliness while becoming fully conscious of god through invocation yields intimacy one cannot find true intimacy with the divine reality except by stripping the self of its false intimacy that self satisfied habitual self centeredness which is the shadow cast by self awareness it is this awareness of self that in the imams statement must be forgotten such higher forgetfulness can arise only on the ground of the remembrance of god for only the source of being unconditional consciousness and eternal life can extinguish eclipse or efface the relative existence partial consciousness and apparent life of the individual this the haqiqa of the dhikr is put with perfect economy in the imams own words forget your own soul in your remembrance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 16, NULL, 'The state of فَنَاء, the highest degree of this forgetting of oneself, is therefore a grace. The individual cannot attain it, however hard he strives. Yet this does not mean the invoker gives up effort. On the contrary, as the Sufi tradition attests again and again, فَنَاء is closely bound to the practice of dhikr, and is in fact its very climax. After this state, or hal, of extinction comes the station, or maqam, of subsistence, baqa: a return of consciousness to the self — a self now transfigured by the knowledge of reality that was impressed upon the soul in the state of فَنَاء. For it is only in the state of فَنَاء that the final vision of absolute oneness is reached, a vision that leaves no room for the duality of being which clings inescapably to individuality. To assert the individual is to assert its correlate, the Lord, and so to affirm duality.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'the state of فناء the highest degree of this forgetting of oneself is therefore a grace the individual cannot attain it however hard he strives yet this does not mean the invoker gives up effort on the contrary as the sufi tradition attests again and again فناء is closely bound to the practice of dhikr and is in fact its very climax after this state or hal of extinction comes the station or maqam of subsistence baqa a return of consciousness to the self a self now transfigured by the knowledge of reality that was impressed upon the soul in the state of فناء for it is only in the state of فناء that the final vision of absolute oneness is reached a vision that leaves no room for the duality of being which clings inescapably to individuality to assert the individual is to assert its correlate the lord and so to affirm duality', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 17, NULL, 'Al-Kashani makes this point in his commentary on the Quranic verse, Remember Him as He hath guided you (Al-Baqarah: 198), where he traces the guided ascent through the degrees of the dhikr. The first is the dhikr of the tongue, which corresponds to the soul (النَّفْس). Then comes the dhikr of the heart (الْقَلْب), which corresponds to the divine acts, those that make His graces manifest. Then the dhikr of the secret (اَلسِّرُّ), which corresponds to the vision of the divine acts together with the unveiling of the sciences of the manifestation of the divine qualities''. Then the dhikr of the spirit (الرُّوح), corresponding to the contemplation of the lights of the manifestations of the divine qualities, with an apprehension of the light of the Essence. Then comes the dhikr of the hidden (الْخَفِيُّ), which is the contemplation of the beauty of the Essence along with the subsistence of duality. And finally the dhikr of the Essence, which is essential vision, attained through the removal of duality.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'al kashani makes this point in his commentary on the quranic verse remember him as he hath guided you al baqarah 198 where he traces the guided ascent through the degrees of the dhikr the first is the dhikr of the tongue which corresponds to the soul النفس then comes the dhikr of the heart القلب which corresponds to the divine acts those that make his graces manifest then the dhikr of the secret السر which corresponds to the vision of the divine acts together with the unveiling of the sciences of the manifestation of the divine qualities then the dhikr of the spirit الروح corresponding to the contemplation of the lights of the manifestations of the divine qualities with an apprehension of the light of the essence then comes the dhikr of the hidden الخفي which is the contemplation of the beauty of the essence along with the subsistence of duality and finally the dhikr of the essence which is essential vision attained through the removal of duality', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 18, NULL, 'The same point emerges from the counsel of Ibn Ataillah, which shows how the dhikr opens a person to the divine presence, and to the grace by which alone the individual can truly forget himself — that is, become unconscious of his own unconsciousness'', as al-Ghazali put it:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'the same point emerges from the counsel of ibn ataillah which shows how the dhikr opens a person to the divine presence and to the grace by which alone the individual can truly forget himself that is become unconscious of his own unconsciousness as al ghazali put it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 19, NULL, 'Do not abandon the invocation because you do not feel the Presence of God therein. For your forgetfulness of the invocation of Him is worse than your forgetfulness in the invocation of Him. Perhaps He will take you from an invocation with forgetfulness (غَفْلَةٌ) to one with vigilance (يَقَظَة), and from one with vigilance to one with the Presence of God (حُضُور), and from one with the Presence of God to one wherein everything but the Invoked (الْمَذْكُورُ) is absent. And that is not difficult for God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'do not abandon the invocation because you do not feel the presence of god therein for your forgetfulness of the invocation of him is worse than your forgetfulness in the invocation of him perhaps he will take you from an invocation with forgetfulness غفله to one with vigilance يقظه and from one with vigilance to one with the presence of god حضور and from one with the presence of god to one wherein everything but the invoked المذكور is absent and that is not difficult for god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 20, NULL, 'In his commentary on the Hikam, Ibn Ajiba adds: So, in the measure that one is extinguished in the Name, one is extinguished in the Essence. This follows from the principle that the Name is the Named. In another work, a commentary on a poem by Shushtari on the divine Name Allah, he sets out this central tenet of the invocatory discipline in Sufism more plainly. The first line of the poem reads, speaking of the letters that make up the word Allah: The alif before two lams, then a ha: coolness of the eyes. Ibn Ajiba comments: The "coolness of the eyes", this is joy, for tears of joy, as one knows by experience, are cool. The author means this: this Name is the joy of my heart, its happiness, its beatitude. He then quotes some lines from al-Hallaj on the letters of the Name Allah, adds a verse of his own, and follows with this comment: The Name is not other than the Named, for joy cannot come from anything but the essence of a thing, not from the name as such.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'in his commentary on the hikam ibn ajiba adds so in the measure that one is extinguished in the name one is extinguished in the essence this follows from the principle that the name is the named in another work a commentary on a poem by shushtari on the divine name allah he sets out this central tenet of the invocatory discipline in sufism more plainly the first line of the poem reads speaking of the letters that make up the word allah the alif before two lams then a ha coolness of the eyes ibn ajiba comments the coolness of the eyes this is joy for tears of joy as one knows by experience are cool the author means this this name is the joy of my heart its happiness its beatitude he then quotes some lines from al hallaj on the letters of the name allah adds a verse of his own and follows with this comment the name is not other than the named for joy cannot come from anything but the essence of a thing not from the name as such', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 21, NULL, 'This sums up the doctrine that the Name and the Named are identical — the rationale for the Sufi practice of dhikruLlah. Yet a problem arises here. However closely the Imam''s statements on the dhikr may agree with these later Sufi expressions of the same underlying principles, this particular emphasis on the identity of the Name and the Named appears, on the surface, to conflict with many sayings of the Shii Imams that deny the Name is the Named. Imam Jafar al-Sadiq, for instance, is reported to have said:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'this sums up the doctrine that the name and the named are identical the rationale for the sufi practice of dhikrullah yet a problem arises here however closely the imams statements on the dhikr may agree with these later sufi expressions of the same underlying principles this particular emphasis on the identity of the name and the named appears on the surface to conflict with many sayings of the shii imams that deny the name is the named imam jafar al sadiq for instance is reported to have said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 22, NULL, 'The Name of Allah is other than Him. For everything to which the name of a thing is applicable is a creation, hence other than God. For whatever the tongue expresses, or is worked on by the hand, is a creation ... everything described is created, and the Creator of things cannot be described within the limits of a named object.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'the name of allah is other than him for everything to which the name of a thing is applicable is a creation hence other than god for whatever the tongue expresses or is worked on by the hand is a creation everything described is created and the creator of things cannot be described within the limits of a named object', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 23, NULL, 'Allah has ninety-nine Names. If the Name were the Named, then every one of the Names would be a god. But Allah is the one meaning, or spiritual reality, mana, indicated by the Names, and all of them are other than Him.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'allah has ninety nine names if the name were the named then every one of the names would be a god but allah is the one meaning or spiritual reality mana indicated by the names and all of them are other than him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 24, NULL, 'This apparent contradiction can be resolved in two ways. First, one must weigh carefully what the word Name means in each of the two contexts: the context of doctrinal distinction, where the Absolute is held strictly apart from the relative, and the Essence from all forms; and the context of methodic concentration, where the Absolute is understood to be the reality of the very form through which it reveals itself. One can then turn to one of the most esoteric aspects of how the Shii Imams understood themselves: their references to their own selves as the most beautiful Names'' (ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'this apparent contradiction can be resolved in two ways first one must weigh carefully what the word name means in each of the two contexts the context of doctrinal distinction where the absolute is held strictly apart from the relative and the essence from all forms and the context of methodic concentration where the absolute is understood to be the reality of the very form through which it reveals itself one can then turn to one of the most esoteric aspects of how the shii imams understood themselves their references to their own selves as the most beautiful names الاسماء الحسني', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 25, NULL, 'As for the meaning of Name, Ibn al-Arabi offers a precise definition: [T]he Names have two connotations; the first connotation is God Himself who is what is named, the second that by which one Name is distinguished from another ... As being essentially the other, the Name is the Reality, while as being not the other, it is the imagined Reality. On the one hand, each Name is identical with every other Name, because each is essentially identical with the Named — the one Essence that is the source of all the Names. On the other hand, each Name has its own particular meaning and quality: it is the relationship through which the one Reality engages the created cosmos. In this second respect each Name is distinct from the others, and distinction implies limitation, and so relativity, and in the end a kind of illusion before the one and only Reality. It is in this sense that the Name takes on the character of imagined Reality. For Ibn al-Arabi, the Names have no separate existence of their own; they all return to the one and only Reality, that of the divine Essence. This dissolves the problem raised in the saying of Imam Jafar — the problem that different Names would imply different gods''.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'as for the meaning of name ibn al arabi offers a precise definition t he names have two connotations the first connotation is god himself who is what is named the second that by which one name is distinguished from another as being essentially the other the name is the reality while as being not the other it is the imagined reality on the one hand each name is identical with every other name because each is essentially identical with the named the one essence that is the source of all the names on the other hand each name has its own particular meaning and quality it is the relationship through which the one reality engages the created cosmos in this second respect each name is distinct from the others and distinction implies limitation and so relativity and in the end a kind of illusion before the one and only reality it is in this sense that the name takes on the character of imagined reality for ibn al arabi the names have no separate existence of their own they all return to the one and only reality that of the divine essence this dissolves the problem raised in the saying of imam jafar the problem that different names would imply different gods', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 26, NULL, 'A lexicon of Sufi terms, the Lataif al-ilam fi isharat ahl al-ilham (Subtle Disclosures in the Allusions of the Folk of Inspiration), attributed to al-Kashani, gives a definition of the divine Names that also helps to distinguish these two connotations. Under the term Names of the Divinity, the text reads:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'a lexicon of sufi terms the lataif al ilam fi isharat ahl al ilham subtle disclosures in the allusions of the folk of inspiration attributed to al kashani gives a definition of the divine names that also helps to distinguish these two connotations under the term names of the divinity the text reads', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 27, NULL, 'These are, in the terminology of the Sufis, expressive of the manifest aspect of being, in respect of its determination within a specific meaning. For every divine Name is the manifest aspect of being, which, in turn, is identical to the Essence, but not as the Essence is in itself; rather, in respect of its specification and determination within a particular meaning, or what one might call a quality. For example, the Name al-Hayy (The Living) is a Name of manifest, determined being, but in respect of its specification and determination as a particular meaning, it is Life. So in regard to being itself, al-Hayy is identical to the Essence, while in regard to its determination as a particular meaning, it is other than the Essence. If you have understood what we have said, you will know what is meant by the saying: the Name is not identical to the Essence, the Named, neither is it other than It.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'these are in the terminology of the sufis expressive of the manifest aspect of being in respect of its determination within a specific meaning for every divine name is the manifest aspect of being which in turn is identical to the essence but not as the essence is in itself rather in respect of its specification and determination within a particular meaning or what one might call a quality for example the name al hayy the living is a name of manifest determined being but in respect of its specification and determination as a particular meaning it is life so in regard to being itself al hayy is identical to the essence while in regard to its determination as a particular meaning it is other than the essence if you have understood what we have said you will know what is meant by the saying the name is not identical to the essence the named neither is it other than it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 28, NULL, 'The Name and the Named differ in name and in thought, and in this respect the Name is not the Named. Yet the two are also spiritually assimilated, and in this respect the Name is the Named. A further distinction must then be drawn. The spoken form of the Name is one thing; the Name as an attribute of the Essence is another. Taken as an attribute, the Name is nothing but the divine quality it designates, and that quality is in turn identical to the Essence. Taken as the name of this Name, it is merely a spoken form. Qaysari, another leading commentator on Ibn al-Arabi, brings this distinction to light in the introduction to his commentary on the Fusus al-hikam.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'the name and the named differ in name and in thought and in this respect the name is not the named yet the two are also spiritually assimilated and in this respect the name is the named a further distinction must then be drawn the spoken form of the name is one thing the name as an attribute of the essence is another taken as an attribute the name is nothing but the divine quality it designates and that quality is in turn identical to the essence taken as the name of this name it is merely a spoken form qaysari another leading commentator on ibn al arabi brings this distinction to light in the introduction to his commentary on the fusus al hikam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 29, NULL, 'The Essence receives a Name when it is considered together with some determined quality and in relation to one of Its theophanies. The Compassionate has an essence, which is compassion; The All-Conquering has an essence, which is all-conquering power. Such spoken Names are Names of Names, and this is how the saying is to be understood: the Name is identical to the Named.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'the essence receives a name when it is considered together with some determined quality and in relation to one of its theophanies the compassionate has an essence which is compassion the all conquering has an essence which is all conquering power such spoken names are names of names and this is how the saying is to be understood the name is identical to the named', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 30, NULL, 'In his monumental commentary on Qaysari''s introduction, Jalal al-Din Ashtiyani, a contemporary authority on Shii Irfan, adds an important observation after quoting this passage. It returns the discussion to two earlier threads: extinction through the invocation of the Name, and the point that the Imams themselves are the most beautiful Names''. The saints, Ashtiyani writes, often speak of the Names as one with the Named because they have in mind the referent (مِصْدَاقٌ), which is the الصِّفَة, the divine attribute or quality: The الصِّفَات are in one respect the specifications of the Essence, while in the station of unicity they are annihilated in the Essence, and are thus identical to the Essence.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'in his monumental commentary on qaysaris introduction jalal al din ashtiyani a contemporary authority on shii irfan adds an important observation after quoting this passage it returns the discussion to two earlier threads extinction through the invocation of the name and the point that the imams themselves are the most beautiful names the saints ashtiyani writes often speak of the names as one with the named because they have in mind the referent مصداق which is the الصفه the divine attribute or quality the الصفات are in one respect the specifications of the essence while in the station of unicity they are annihilated in the essence and are thus identical to the essence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 31, NULL, 'This metaphysical account of how the Name, the الصِّفَة, and the Essence stand to one another mirrors, on the objective and universal plane, the path the soul travels inwardly and mystically when it is extinguished in and by the invocation of the Name. This extinction is what فَنَاء means: the perishing of egoistic consciousness before the Absolute. The الصِّفَات are annihilated in the Essence and are thereby absolutely and unconditionally one with it; in the same way, the soul extinguished by the Name reaches at a single stroke both its total nullification and its ultimate realization — no longer as an individual soul. This extinction on the plane of the individual soul amounts to realization on the plane of transcendence only by virtue of the divine theophany, the particular divine Name, the heart that forms the soul''s true being, its mustanad ilahi. Here the deepest reality of تَوْحِيد comes to light. The individual no longer affirms that there is no god but God, for the individual has been extinguished by the reality that there is no reality but the one and only Reality. God is that which has no second. Just as No one has truly said Allah but Allah, so too no one realizes God but God. God alone comes to know or be Himself, and this is one aspect of the purpose of creation, as the hadith qudsi indicates: I was a hidden treasure and I loved to be known.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'this metaphysical account of how the name the الصفه and the essence stand to one another mirrors on the objective and universal plane the path the soul travels inwardly and mystically when it is extinguished in and by the invocation of the name this extinction is what فناء means the perishing of egoistic consciousness before the absolute the الصفات are annihilated in the essence and are thereby absolutely and unconditionally one with it in the same way the soul extinguished by the name reaches at a single stroke both its total nullification and its ultimate realization no longer as an individual soul this extinction on the plane of the individual soul amounts to realization on the plane of transcendence only by virtue of the divine theophany the particular divine name the heart that forms the souls true being its mustanad ilahi here the deepest reality of توحيد comes to light the individual no longer affirms that there is no god but god for the individual has been extinguished by the reality that there is no reality but the one and only reality god is that which has no second just as no one has truly said allah but allah so too no one realizes god but god god alone comes to know or be himself and this is one aspect of the purpose of creation as the hadith qudsi indicates i was a hidden treasure and i loved to be known', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 32, NULL, 'Seen in this light, the saints (اَلْأَوْلِيَاءُ) are perfectly self-realized theophanies, wholly effaced in that of which they are the theophanic manifestations; and their very effacement in the divine Reality is the ultimate source of their knowledge of it. This is all the more true of the Prophet himself, the prototype of all the saints and the perfect man, al-insan al-kamil. On this point Sabziwari, in his commentary on the divine Names, cites the saying of Ali (ع), We are the most beautiful Names'': There is no doubt that they are His most exalted indicators and His greatest signs (عَلَائِمِهِ الْعُظْمَى وَآيَاتِهِ الْكُبْرَى), as the Prophet said, God bless him and his family, "Whoso sees me has seen the Truth (اَلْحَقّ)." He goes on to equate the spiritual station, or inner reality, of the Imams with that of the divine Names and attributes, while stressing that the divine Essence transcends all Names and attributes and remains forever ineffable, known only to itself. The Prophet, the Imam, the saint, the perfect man, thus manifest those aspects of the divine nature that can be perceived on the human plane. The more the divine Essence is exalted in transcendence above all Names and attributes, the more brilliantly those Names and attributes are reflected in the mirror that the perfect man constitutes. The unknowable transcendence of the hidden treasure is, in some measure, offset by the faithful reflection of its communicable aspects in the friend of God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'seen in this light the saints الاولياء are perfectly self realized theophanies wholly effaced in that of which they are the theophanic manifestations and their very effacement in the divine reality is the ultimate source of their knowledge of it this is all the more true of the prophet himself the prototype of all the saints and the perfect man al insan al kamil on this point sabziwari in his commentary on the divine names cites the saying of ali ع we are the most beautiful names there is no doubt that they are his most exalted indicators and his greatest signs علايمه العظمي واياته الكبري as the prophet said god bless him and his family whoso sees me has seen the truth الحق he goes on to equate the spiritual station or inner reality of the imams with that of the divine names and attributes while stressing that the divine essence transcends all names and attributes and remains forever ineffable known only to itself the prophet the imam the saint the perfect man thus manifest those aspects of the divine nature that can be perceived on the human plane the more the divine essence is exalted in transcendence above all names and attributes the more brilliantly those names and attributes are reflected in the mirror that the perfect man constitutes the unknowable transcendence of the hidden treasure is in some measure offset by the faithful reflection of its communicable aspects in the friend of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 33, NULL, 'Identifying the Imam with the divine Name or attribute has implications worth weighing, for in one respect such an identification would appear to be شِرْك — the association of a creature, however exalted, with the transcendent Reality. The same charge appears to apply to the ecstatic utterances (شَطْحِيَّاتٌ) of many of the most celebrated Sufis, such as the anal-Haqq (I am the Real) of al-Hallaj and the subhani (Glory to me) of Bayazid. Yet from a viewpoint shaped by the Imam''s own conception of the divine attributes, a very different picture emerges — one that, far from being tainted by شِرْك, in fact reaches the most profound application of تَوْحِيد. The first sermon of the Nahj al-balagha contains these remarkable and highly important statements about the attributes of God:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'identifying the imam with the divine name or attribute has implications worth weighing for in one respect such an identification would appear to be شرك the association of a creature however exalted with the transcendent reality the same charge appears to apply to the ecstatic utterances شطحيات of many of the most celebrated sufis such as the anal haqq i am the real of al hallaj and the subhani glory to me of bayazid yet from a viewpoint shaped by the imams own conception of the divine attributes a very different picture emerges one that far from being tainted by شرك in fact reaches the most profound application of توحيد the first sermon of the nahj al balagha contains these remarkable and highly important statements about the attributes of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 34, NULL, 'The perfection of purification (أَخْلَاص) is to divest Him of all attributes (الصِّفَات) because of the testimony of every attribute that it is other than the object of attribution, and because of the testimony of every such object that it is other than the attribute. So whoever ascribes an attribute to God, glorified be He, has conjoined Him with something else; and whoever so conjoins Him has made Him twofold; and whoever makes Him twofold has fragmented Him; and whoever thus fragments Him is ignorant of Him.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'the perfection of purification اخلاص is to divest him of all attributes الصفات because of the testimony of every attribute that it is other than the object of attribution and because of the testimony of every such object that it is other than the attribute so whoever ascribes an attribute to god glorified be he has conjoined him with something else and whoever so conjoins him has made him twofold and whoever makes him twofold has fragmented him and whoever thus fragments him is ignorant of him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 35, NULL, 'When the Imam says that pure devotion to God requires stripping God of all attributes, what is negated is not the divine attributes themselves. What is negated is any notion of them as separate, self-standing, or added-on realities — as things substantially other than the Essence of God, or set apart from it in their very being. The reality of God''s attributes is plainly affirmed in an earlier phrase of the same sermon: He whose attribute has no binding limitation (الَّذِي لَيْسَ لِصِفَتِهِ حَدٌّ مَحْدُودٌ). What the sermon denies is that the reality of any divine attribute can be confined within the bounds of human thought and language. No divine attribute can stand apart from the divine nature; that nature is infinite; and so every attribute is of infinite scope as well, beyond all the limits that formal thought and verbal definition presuppose.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'when the imam says that pure devotion to god requires stripping god of all attributes what is negated is not the divine attributes themselves what is negated is any notion of them as separate self standing or added on realities as things substantially other than the essence of god or set apart from it in their very being the reality of gods attributes is plainly affirmed in an earlier phrase of the same sermon he whose attribute has no binding limitation الذي ليس لصفته حد محدود what the sermon denies is that the reality of any divine attribute can be confined within the bounds of human thought and language no divine attribute can stand apart from the divine nature that nature is infinite and so every attribute is of infinite scope as well beyond all the limits that formal thought and verbal definition presuppose', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 36, NULL, 'The attribute or Name, then, is to be affirmed in one respect and negated in another: affirmed as not other than the Essence, negated insofar as it is regarded in itself, on its own account. This same metaphysical view of how the attribute or Name stands to the Essence can be applied, mystically, to how the individual soul stands to the divine Reality. On its own account the individual is nothing; but in respect of the divine ground beneath it — the divine Name, the mustanad ilahi that forms its essential reality — it is not other than the unique Real. As Ibn al-Arabi puts it, The final end and ultimate return of the gnostics is that the Real is identical with them, while they do not exist. This captures perfectly the twofold aspect of the realized sage''s soul: insofar as he is aware that he does not exist, he knows that the Real is his true identity. However paradoxical it seems, the mystic''s realization of absolute Reality goes hand in hand with his realization of his own non-existence. Ibn al-Arabi expresses these two aspects of one and the same realization in compressed form. He describes the summit of his spiritual ascent, his miraj, recounting that God removed from him his contingent dimension (إِمْكَانٌ), resulting in the attainment of the inner realities of all the Names''. He continues:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'the attribute or name then is to be affirmed in one respect and negated in another affirmed as not other than the essence negated insofar as it is regarded in itself on its own account this same metaphysical view of how the attribute or name stands to the essence can be applied mystically to how the individual soul stands to the divine reality on its own account the individual is nothing but in respect of the divine ground beneath it the divine name the mustanad ilahi that forms its essential reality it is not other than the unique real as ibn al arabi puts it the final end and ultimate return of the gnostics is that the real is identical with them while they do not exist this captures perfectly the twofold aspect of the realized sages soul insofar as he is aware that he does not exist he knows that the real is his true identity however paradoxical it seems the mystics realization of absolute reality goes hand in hand with his realization of his own non existence ibn al arabi expresses these two aspects of one and the same realization in compressed form he describes the summit of his spiritual ascent his miraj recounting that god removed from him his contingent dimension امكان resulting in the attainment of the inner realities of all the names he continues', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 37, NULL, 'Thus I attained in this nocturnal journey the inner realities (مَعَانِي) of all the Names, and I saw them returning to One Subject (مُسَمَّى) and One Entity (عَيْنٌ): that Subject was what I witnessed and that Entity was my Being. For my voyage was only in myself and pointed to myself, and through this I came to know that I was a pure servant without a trace of lordship in me at all.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'thus i attained in this nocturnal journey the inner realities معاني of all the names and i saw them returning to one subject مسمي and one entity عين that subject was what i witnessed and that entity was my being for my voyage was only in myself and pointed to myself and through this i came to know that i was a pure servant without a trace of lordship in me at all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 38, NULL, 'This passage helps to explain so many of the ecstatic utterances of the Sufis and the seemingly self-deifying statements of the Imams. Their personal servitude to God is not denied. On the contrary, it is fully realized through the knowledge of their true identity, for that identity as the Named is reached only when their individuality is effaced. Like the divine attributes, they are mustahlak, annihilated in the divine Essence, so that no individual appropriation of the glory of God is possible. When the Imam appears to speak of his own greatness, this is nothing but the greatness of God expressed through him as a mazhar, a locus for the theophanic manifestation of the divine — and expressed precisely in the measure of his own effacement in that greatness.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'this passage helps to explain so many of the ecstatic utterances of the sufis and the seemingly self deifying statements of the imams their personal servitude to god is not denied on the contrary it is fully realized through the knowledge of their true identity for that identity as the named is reached only when their individuality is effaced like the divine attributes they are mustahlak annihilated in the divine essence so that no individual appropriation of the glory of god is possible when the imam appears to speak of his own greatness this is nothing but the greatness of god expressed through him as a mazhar a locus for the theophanic manifestation of the divine and expressed precisely in the measure of his own effacement in that greatness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 39, NULL, 'The same point is reinforced by what Attar recounts about Imam Jafar al-Sadiq in his Tadhkiratul-awliya. Someone accused him of being proud, and the Imam replied: I am not proud, for pride pertains to the divine greatness. Since I have gone beyond the pride of self, His pride has come and taken the place of my own pride. With pride of self present, there can be no divine greatness, but through the divine greatness, pride will be present. The divine qualities shine with greater brilliance, not less, through the prism of a soul made transparent to the divine Reality — a transparency that comes from the dissolving of all the clouds of egoism and passion.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'the same point is reinforced by what attar recounts about imam jafar al sadiq in his tadhkiratul awliya someone accused him of being proud and the imam replied i am not proud for pride pertains to the divine greatness since i have gone beyond the pride of self his pride has come and taken the place of my own pride with pride of self present there can be no divine greatness but through the divine greatness pride will be present the divine qualities shine with greater brilliance not less through the prism of a soul made transparent to the divine reality a transparency that comes from the dissolving of all the clouds of egoism and passion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 40, NULL, 'A holy utterance bears on this: My slave draws near to Me through nothing I love more than that which I have made obligatory for him. My slave never ceases to draw near to Me through supererogatory acts (نَوَافِلُ) until I love him. And when I love him, I am his hearing by which he hears, his sight by which he sees, his hand by which he grasps, and his foot by which he walks.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'a holy utterance bears on this my slave draws near to me through nothing i love more than that which i have made obligatory for him my slave never ceases to draw near to me through supererogatory acts نوافل until i love him and when i love him i am his hearing by which he hears his sight by which he sees his hand by which he grasps and his foot by which he walks', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 41, NULL, 'In the light of all this, the paradox this divine utterance contains can now be resolved. On the one hand, the thing most beloved to God appears to be the obligatory rites. On the other, it is the supererogatory rites that carry the slave near to God until He loves him — and that love seems the greater, since it issues in the divine penetration of the human faculties, the unitive realization proper to تَوْحِيد. The paradox dissolves once it is seen that God''s love for the obligatory rites is a love directed toward something apart from Himself, whereas His love for the slave — the pure slave effaced in his Lord — is infinitely greater, since it shares in God''s love for His own Self-manifestation, and so for Himself. In the beginning God loved to be known, and so He created the world. In knowing Himself through the effaced slave, the seeming other, His love to be known is realized through the saint whose greatest glory is precisely his own effacement, poverty, and emptiness of self.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'in the light of all this the paradox this divine utterance contains can now be resolved on the one hand the thing most beloved to god appears to be the obligatory rites on the other it is the supererogatory rites that carry the slave near to god until he loves him and that love seems the greater since it issues in the divine penetration of the human faculties the unitive realization proper to توحيد the paradox dissolves once it is seen that gods love for the obligatory rites is a love directed toward something apart from himself whereas his love for the slave the pure slave effaced in his lord is infinitely greater since it shares in gods love for his own self manifestation and so for himself in the beginning god loved to be known and so he created the world in knowing himself through the effaced slave the seeming other his love to be known is realized through the saint whose greatest glory is precisely his own effacement poverty and emptiness of self', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 42, NULL, 'It is in this sense that the following statement of the Imam is to be understood: Down from me torrents do pour; up to me no bird can soar. Torrents pour down from him because — and in the measure that — he is extinguished in the source of the torrent. The image recalls the Quranic description of the slaves of God who, unlike the righteous'', drink directly from the celestial spring of Kafur, identified in the end with the divine Essence: Truly, the righteous shall drink from a cup flavoured with Kafur, a spring wherefrom the slaves of God drink, making it gush forth abundantly (Al-Insan: 5-6). These slaves make the spring flow more abundantly because, in al-Kashani''s words, they are themselves the sources of this spring; there is no duality or otherness. Were it otherwise, it would not be the fountain of Kafur, because of the darkness of the veil of egoity (ana iyya) and duality.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'it is in this sense that the following statement of the imam is to be understood down from me torrents do pour up to me no bird can soar torrents pour down from him because and in the measure that he is extinguished in the source of the torrent the image recalls the quranic description of the slaves of god who unlike the righteous drink directly from the celestial spring of kafur identified in the end with the divine essence truly the righteous shall drink from a cup flavoured with kafur a spring wherefrom the slaves of god drink making it gush forth abundantly al insan 5 6 these slaves make the spring flow more abundantly because in al kashanis words they are themselves the sources of this spring there is no duality or otherness were it otherwise it would not be the fountain of kafur because of the darkness of the veil of egoity ana iyya and duality', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 43, NULL, 'The final degree of the dhikr, as al-Kashani defined it, is the dhikr of the Essence, which is essential vision, attained through the removal of duality. The dhikr polishes'' away not only the impurities of the heart and mind but, in the end, through the grace of the madhkur, every taint of duality — and above all that root supposition of duality, the individual as such. It removes all subtle or hidden شِرْك, the partners'' in being that are non-existent before the One that has no second, and it establishes the spiritual principle of تَوْحِيد, so that the heart, transfigured by the knowledge of the sole Reality, comes to see the light of that Reality reflected in all the mirrors of creation. To realize this one and only Reality — to make it real in the fullest sense — is, by the same stroke, to realize the unreality, or merely apparent reality, of everything else.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'the final degree of the dhikr as al kashani defined it is the dhikr of the essence which is essential vision attained through the removal of duality the dhikr polishes away not only the impurities of the heart and mind but in the end through the grace of the madhkur every taint of duality and above all that root supposition of duality the individual as such it removes all subtle or hidden شرك the partners in being that are non existent before the one that has no second and it establishes the spiritual principle of توحيد so that the heart transfigured by the knowledge of the sole reality comes to see the light of that reality reflected in all the mirrors of creation to realize this one and only reality to make it real in the fullest sense is by the same stroke to realize the unreality or merely apparent reality of everything else', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 44, NULL, 'At this level of realization a measure of perplexity inevitably attends the revelation of the divine Reality on every side. The more the divine Essence is exalted beyond all comprehension, the more unavoidable it becomes that creaturely consciousness must be utterly annihilated if that Essence is to be realized, if gnosis of it is to be reached. On the one hand, one knows'' God by knowing that His Essence is unknowable, utterly other, utterly transcendent — the essence of the Creator lying beyond the veil that creation itself forms. On the other hand, the very distinction between creature and Creator is effaced once the creature has forgotten itself, not merely as a notion but existentially, in a state of genuine contemplative extinction. It is then no longer a matter of one form of self-consciousness replacing another, but of the self being taken out of the reckoning altogether, leaving only pure consciousness as such — which cannot belong to any entity without being reduced to the relativity proper to that entity. Consciousness of the Absolute, that is, being conscious of the Absolute, is thus transmuted into absolute consciousness. The Real is realized not by another but through another, which is the source of the title al-arif biLlah, literally the knower through God rather than simply the knower of God. The Imam says, Know God through God. Knowledge of God at this deepest level is the Real knowing itself through the creature; and to say through implies an unobstructed passage, the creature being marked by perfect faqr — poverty, self-effacement, and, in the end, extinction.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'at this level of realization a measure of perplexity inevitably attends the revelation of the divine reality on every side the more the divine essence is exalted beyond all comprehension the more unavoidable it becomes that creaturely consciousness must be utterly annihilated if that essence is to be realized if gnosis of it is to be reached on the one hand one knows god by knowing that his essence is unknowable utterly other utterly transcendent the essence of the creator lying beyond the veil that creation itself forms on the other hand the very distinction between creature and creator is effaced once the creature has forgotten itself not merely as a notion but existentially in a state of genuine contemplative extinction it is then no longer a matter of one form of self consciousness replacing another but of the self being taken out of the reckoning altogether leaving only pure consciousness as such which cannot belong to any entity without being reduced to the relativity proper to that entity consciousness of the absolute that is being conscious of the absolute is thus transmuted into absolute consciousness the real is realized not by another but through another which is the source of the title al arif billah literally the knower through god rather than simply the knower of god the imam says know god through god knowledge of god at this deepest level is the real knowing itself through the creature and to say through implies an unobstructed passage the creature being marked by perfect faqr poverty self effacement and in the end extinction', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 45, NULL, 'Realization through remembrance, however, means not only "forgetting" everything in existence except God, but also discovering that in reality there is nothing in being but God. In the Imam''s image of the "polish" worked by remembrance, the heart — once blind and deaf — is made able to "see" and to "hear." It sees the Face of God wherever it turns, and it hears the cosmic hymn of remembrance and praise that the whole of creation sings, for every creature proclaims the boundless creativity of its Creator. As the Quran says:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'realization through remembrance however means not only forgetting everything in existence except god but also discovering that in reality there is nothing in being but god in the imams image of the polish worked by remembrance the heart once blind and deaf is made able to see and to hear it sees the face of god wherever it turns and it hears the cosmic hymn of remembrance and praise that the whole of creation sings for every creature proclaims the boundless creativity of its creator as the quran says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'verse', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 46, NULL, 'Al-Baqarah: 115وَلِلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ ۚ فَأَيْنَمَا تُوَلُّوا۟ فَثَمَّ وَجْهُ ٱللَّهِ ۚ إِنَّ ٱللَّهَ وَسِعٌ عَلِيمٌۭ"Wherever ye turn, there is the Face of God" (Al-Baqarah: 115).', '', 'وَلِلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ ۚ فَأَيْنَمَا تُوَلُّوا۟ فَثَمَّ وَجْهُ ٱللَّهِ ۚ إِنَّ ٱللَّهَ وَسِعٌ عَلِيمٌۭ', 'Al-Baqarah: 115', 2, 115, 'spiritual ethos 13 extinction and the name the death of the saint', 'al baqarah 115ولله المشرق والمغرب فاينما تولوا فثم وجه الله ان الله وسع عليم wherever ye turn there is the face of god al baqarah 115', 'ولله المشرق والمغرب فاينما تولوا فثم وجه الله ان الله وسع عليم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 47, NULL, 'An-Nur: 41أَلَمْ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِى ٱلسَّمَوَتِ وَٱلْأَرْضِ وَٱلطَّيْرُ صَٓفَّتٍۢ ۖ كُلٌّۭ قَدْ عَلِمَ صَلَاتَهُۥ وَتَسْبِيحَهُۥ ۗ وَٱللَّهُ عَلِيمٌۢ بِمَا يَفْعَلُونَ"Do you not see that God is the one who is glorified by everything in the heavens and the earth, and the birds with wings outstretched; each one indeed knows its prayer and its glorification, and God is All-Aware of what they do" (An-Nur: 41).', '', NULL, 'An-Nur: 41', NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'an nur 41الم تر ان الله يسبح له من في السموت والارض والطير صفت كل قد علم صلاته وتسبيحه والله عليم بما يفعلون do you not see that god is the one who is glorified by everything in the heavens and the earth and the birds with wings outstretched each one indeed knows its prayer and its glorification and god is all aware of what they do an nur 41', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 48, NULL, 'A final reflection turns to a passage from the Imam''s famous and much-disputed Khutbat al-bayan, "The Sermon of Clarifying Expression":', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'a final reflection turns to a passage from the imams famous and much disputed khutbat al bayan the sermon of clarifying expression', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 49, NULL, 'I am the Sign of the All-Powerful. I am the gnosis of the mysteries. I am the Threshold of Thresholds. I am the companion of the radiance of the divine Majesty. I am the First and the Last, the Manifest and the Hidden. I am the Face of God. I am the mirror of God, the supreme Pen, the Tabula secreta. I am he who in the Gospel is called Elijah. I am he who is in possession of the secret of God''s Messenger.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'i am the sign of the all powerful i am the gnosis of the mysteries i am the threshold of thresholds i am the companion of the radiance of the divine majesty i am the first and the last the manifest and the hidden i am the face of god i am the mirror of god the supreme pen the tabula secreta i am he who in the gospel is called elijah i am he who is in possession of the secret of gods messenger', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 50, NULL, 'This remarkable affirmation of the Imam''s inmost reality may seem shocking to the exoteric mentality, and is all too easily misread as a blasphemous self-deification of the kind associated with Hallaj. One key to understanding these declarations of "his" true nature correctly is the statement: "I am the gnosis of the mysteries." Once this is grasped, every other statement falls naturally into place. For here the Imam is not identifying himself with God, but with the knowledge of God — and not with his own knowledge of God, since that would still be a relative knowledge, belonging to him as a relative being. Only knowledge itself — the knowledge God has of Himself, not the knowledge a human being has of God — can be fully identified with its object. The distinctions between knowledge, knower, and known dissolve only at this transcendent level, just as the distinction between knowledge and being ceases to operate there. Thus the knower is the known, when the knowledge in question is that consciousness which the divine Reality has of itself. Individual consciousness reaches this knowledge only on one condition: the utter extinction of every trace of individual, creaturely selfhood. To "remember" God, one must have "forgotten" oneself. To "be" the knowledge of God is, by a kind of metaphysical reverberation, to "be" everything that God is; for the consciousness that is wholly at one with the Absolute is nothing other than "the radiance of the divine Majesty." Insofar as this consciousness is one with "the gnosis of the mysteries" — and these mysteries (أَسْرَارٌ) are all rooted in the ultimate mystery (اَلسِّرُّ), the one and only Essence of God — it is necessarily one with all the divine attributes. It is in this sense that the Imam can proclaim: "I am the First and the Last, the Manifest and the Hidden."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'this remarkable affirmation of the imams inmost reality may seem shocking to the exoteric mentality and is all too easily misread as a blasphemous self deification of the kind associated with hallaj one key to understanding these declarations of his true nature correctly is the statement i am the gnosis of the mysteries once this is grasped every other statement falls naturally into place for here the imam is not identifying himself with god but with the knowledge of god and not with his own knowledge of god since that would still be a relative knowledge belonging to him as a relative being only knowledge itself the knowledge god has of himself not the knowledge a human being has of god can be fully identified with its object the distinctions between knowledge knower and known dissolve only at this transcendent level just as the distinction between knowledge and being ceases to operate there thus the knower is the known when the knowledge in question is that consciousness which the divine reality has of itself individual consciousness reaches this knowledge only on one condition the utter extinction of every trace of individual creaturely selfhood to remember god one must have forgotten oneself to be the knowledge of god is by a kind of metaphysical reverberation to be everything that god is for the consciousness that is wholly at one with the absolute is nothing other than the radiance of the divine majesty insofar as this consciousness is one with the gnosis of the mysteries and these mysteries اسرار are all rooted in the ultimate mystery السر the one and only essence of god it is necessarily one with all the divine attributes it is in this sense that the imam can proclaim i am the first and the last the manifest and the hidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 51, NULL, 'The same reasoning applies to the claim to be "the Face of God" (wajh Allah). It becomes intelligible only once one grasps that the Imam describes himself as the "mirror" of God. A mirror loses its identity as a mirror when attention rests entirely on the object reflected in it: the mirror''s own surface becomes, as it were, invisible, and only the object is seen. Conversely, when the mirror itself becomes the object of attention, the face reflected in it can no longer be seen. The mirror is thus identified with what it reflects — which in a certain sense is "in" the mirror — yet the mirror does not cease to be a mirror, and the Face does not cease to be wholly independent of it. The "veil" here is the mirror itself. To attend to the mirror as a mirror prevents one from seeing the object it reflects; but once attention rests wholly on the image the mirror holds, the mirror ceases to be a veil and instead reveals the object itself. Within this symbolism, forgetting the mirror answers to the effacement of the self, and fixing on the image within it answers to the remembrance of God.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'the same reasoning applies to the claim to be the face of god wajh allah it becomes intelligible only once one grasps that the imam describes himself as the mirror of god a mirror loses its identity as a mirror when attention rests entirely on the object reflected in it the mirrors own surface becomes as it were invisible and only the object is seen conversely when the mirror itself becomes the object of attention the face reflected in it can no longer be seen the mirror is thus identified with what it reflects which in a certain sense is in the mirror yet the mirror does not cease to be a mirror and the face does not cease to be wholly independent of it the veil here is the mirror itself to attend to the mirror as a mirror prevents one from seeing the object it reflects but once attention rests wholly on the image the mirror holds the mirror ceases to be a veil and instead reveals the object itself within this symbolism forgetting the mirror answers to the effacement of the self and fixing on the image within it answers to the remembrance of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 52, NULL, 'Yet this leads to another paradox: the deepest effacement of individuality goes hand in hand with the most perfect expression of humanity. The "friends of God," who know themselves to be nothing before the Absolute, are precisely those who most faithfully reflect the divine Names and qualities — qualities that belong not to them but to God. This is why the great saints and sages are also models of virtue, virtue whose true foundations are the "most beautiful Names" and attributes of God. Those divine attributes shine through them most clearly because the mirrors of their hearts have been polished by the remembrance of God, and the most stubborn stains — those left by egotism — have been removed. The saint''s creativity is raised to its highest pitch precisely because the divine qualities reflected by the heart are no longer blocked — on the inner side, by the individual coagulations that egotism generates, nor, on the outer side, by the cosmic coagulations of this lower world. For such saints are those whose "hearts are in the Gardens [of Paradise] while their bodies are at work." Their hearts, bound and attached to that divine realm — the abodes and stations of paradise reaching all the way to the divine presence — are already "within" that transcendent realm; they already live more in that spiritual world than in this earthly one. And so, though they labor in this world with their bodies, their outward actions veil their inward transcendence of higher realities: they act, but they are not bound by the fruits of their action.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'yet this leads to another paradox the deepest effacement of individuality goes hand in hand with the most perfect expression of humanity the friends of god who know themselves to be nothing before the absolute are precisely those who most faithfully reflect the divine names and qualities qualities that belong not to them but to god this is why the great saints and sages are also models of virtue virtue whose true foundations are the most beautiful names and attributes of god those divine attributes shine through them most clearly because the mirrors of their hearts have been polished by the remembrance of god and the most stubborn stains those left by egotism have been removed the saints creativity is raised to its highest pitch precisely because the divine qualities reflected by the heart are no longer blocked on the inner side by the individual coagulations that egotism generates nor on the outer side by the cosmic coagulations of this lower world for such saints are those whose hearts are in the gardens of paradise while their bodies are at work their hearts bound and attached to that divine realm the abodes and stations of paradise reaching all the way to the divine presence are already within that transcendent realm they already live more in that spiritual world than in this earthly one and so though they labor in this world with their bodies their outward actions veil their inward transcendence of higher realities they act but they are not bound by the fruits of their action', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 53, NULL, 'Such souls have not merely understood this principle; they have been seized by it, in their very existence, at the root of their being. It is the principle voiced in the Quranic verse:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'such souls have not merely understood this principle they have been seized by it in their very existence at the root of their being it is the principle voiced in the quranic verse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 54, NULL, 'Al-''Ankabut: 64وَمَا هَذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَهْوٌۭ وَلَعِبٌۭ ۚ وَإِنَّ ٱلدَّارَ ٱلْآخِرَةَ لَهِىَ ٱلْحَيَوَانُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ"And the life of this world is naught but sport and play; and truly, the abode of the Hereafter, that is true life" (Al-Ankabut: 64).', '', NULL, 'Al-''Ankabut: 64', NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'al ankabut 64وما هذه الحيوه الدنيا الا لهو ولعب وان الدار الاخره لهي الحيوان لو كانوا يعلمون and the life of this world is naught but sport and play and truly the abode of the hereafter that is true life al ankabut 64', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 55, NULL, 'Their instincts are therefore always attuned to that higher reality. When Ali was struck by the poisoned sword of Ibn Muljam, the cry that broke from him was not one of pain but of triumph: "I have triumphed, by the Lord of the Kaba!" At the very moment of death there was in him nothing but the remembrance of God, and the Imam passed away, it is said, with his tongue still repeating the words la ilaha illaLlah. His death was thus completed exactly as his life had been lived, in accord with the wisdom of the Prophet, who, when asked which of all acts is the most meritorious, replied: "That you die while your tongue is moistened with the invocation of God."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'their instincts are therefore always attuned to that higher reality when ali was struck by the poisoned sword of ibn muljam the cry that broke from him was not one of pain but of triumph i have triumphed by the lord of the kaba at the very moment of death there was in him nothing but the remembrance of god and the imam passed away it is said with his tongue still repeating the words la ilaha illallah his death was thus completed exactly as his life had been lived in accord with the wisdom of the prophet who when asked which of all acts is the most meritorious replied that you die while your tongue is moistened with the invocation of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 56, NULL, 'All the rites and practices bound up with the chivalric orders of Islam were traced, without exception, back to the Prophet''s son-in-law, Ali, who was thereby established as the supreme source of the virtues of futuwwa, as Muhammad Jafar Mahjub observes in his "Chivalry and Early Persian Sufism." S. H. Nasr writes to similar effect that Ali, having received the "truth and power" of futuwwa from the Prophet, "became the supreme source of futuwwa in Islam for both Sunnis and Shiites... The personality of Ali, at once sage and knight, contemplative and protector of laborers and craftsmen, has continued to dominate through the centuries over the horizon of futuwwa as it has over much of Sufism." Nasr also draws attention to the organic link between futuwwa and the guilds, the asnaf, singular sinf, of craftsmen and artists established throughout the length and breadth of the Muslim world.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'all the rites and practices bound up with the chivalric orders of islam were traced without exception back to the prophets son in law ali who was thereby established as the supreme source of the virtues of futuwwa as muhammad jafar mahjub observes in his chivalry and early persian sufism s h nasr writes to similar effect that ali having received the truth and power of futuwwa from the prophet became the supreme source of futuwwa in islam for both sunnis and shiites the personality of ali at once sage and knight contemplative and protector of laborers and craftsmen has continued to dominate through the centuries over the horizon of futuwwa as it has over much of sufism nasr also draws attention to the organic link between futuwwa and the guilds the asnaf singular sinf of craftsmen and artists established throughout the length and breadth of the muslim world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'extinction and the name: the death of the saint', '13. Extinction and the Name: The Death of the Saint', 57, NULL, 'It is often said that the Naqshabandi tariqa is the one exception to this rule, tracing its line of descent from the Prophet through the first caliph, Abu Bakr, rather than through Ali. But this affiliation with Abu Bakr belongs to only one of its three principal silsilas. Abd al-Majid b. Muhammad al-Khani, himself a Naqshabandi-Khalidi shaykh, calls the first chain (السِّلْسِلَةُ الْأُولَى) the "golden chain," which begins with Ali and runs through the Shii Imams down to Ali b. Musa, then to Maruf al-Karkhi and the other masters. The second chain (السِّلْسِلَةُ الثَّانِيَةُ) likewise begins with Ali, running through Hasan al-Basri. Only the third chain, called al-silsilat al-siddiqiyya, runs from the Prophet to Abu Bakr (الصِّدِّيقُ).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 13 extinction and the name the death of the saint', 'it is often said that the naqshabandi tariqa is the one exception to this rule tracing its line of descent from the prophet through the first caliph abu bakr rather than through ali but this affiliation with abu bakr belongs to only one of its three principal silsilas abd al majid b muhammad al khani himself a naqshabandi khalidi shaykh calls the first chain السلسله الاولي the golden chain which begins with ali and runs through the shii imams down to ali b musa then to maruf al karkhi and the other masters the second chain السلسله الثانيه likewise begins with ali running through hasan al basri only the third chain called al silsilat al siddiqiyya runs from the prophet to abu bakr الصديق', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 0, NULL, 'The opening sermon of ⟪ar:نھج البلاغہ⟫ — delivered by Maulana Ali (ع) as a ⟪ar:خطبۃ⟫ — proclaims the oneness of God: a oneness that stands outside the category of numbers altogether. The sermon is built on paradox. The loftier the truth Maulana Ali means to reveal, the deeper the paradox he forms to reveal it. By negating the reach of human words and concepts, he affirms the Reality that no word and no concept can contain. That is the manner of his sermons. The eye cannot see Him, yet the mind cannot deny Him. He is farther than the farthest flight of imagination, yet nearer than the jugular vein. Nowhere is this plainer than in these opening lines.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'the opening sermon of ar نهج البلاغه delivered by maulana ali ع as a ar خطبه proclaims the oneness of god a oneness that stands outside the category of numbers altogether the sermon is built on paradox the loftier the truth maulana ali means to reveal the deeper the paradox he forms to reveal it by negating the reach of human words and concepts he affirms the reality that no word and no concept can contain that is the manner of his sermons the eye cannot see him yet the mind cannot deny him he is farther than the farthest flight of imagination yet nearer than the jugular vein nowhere is this plainer than in these opening lines', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 1, NULL, 'The sermon opens: Praise be to God, الحَمْدُ للهِ الَّذَي لاَ يَبْلُغُ مِدْحَتَهُ القَائِلُونَ — whose laudation those who speak cannot deliver. The paradox is immediate. Speech exists to carry a concept from one mind to another; here it is turned to demonstrate that God is so lofty and sublime that words can carry nothing of Him. Whose graces those who count cannot number, وَلاِ يُحْصِي نَعْمَاءَهُ العَادُّونَ — for counting belongs to things that can be enumerated, and His bounties surpass all enumeration. Whose rightful due those who strive cannot render, ولاَ يُؤَدِّي حَقَّهُ الُمجْتَهِدُونَ — for however hard they strive, the praise and gratitude He is owed remains forever beyond their reach. He cannot be reached by far-reaching aspirations, الَّذِي لاَ يُدْركُهُ بُعْدُ الهِمَمِ, nor fathomed by profound intuitions, وَلاَ يَنَالُهُ غَوْصُ الفِطَنِ.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'the sermon opens praise be to god الحمد لله الذي لا يبلغ مدحته القايلون whose laudation those who speak cannot deliver the paradox is immediate speech exists to carry a concept from one mind to another here it is turned to demonstrate that god is so lofty and sublime that words can carry nothing of him whose graces those who count cannot number ولا يحصي نعماءه العادون for counting belongs to things that can be enumerated and his bounties surpass all enumeration whose rightful due those who strive cannot render ولا يودي حقه المجتهدون for however hard they strive the praise and gratitude he is owed remains forever beyond their reach he cannot be reached by far reaching aspirations الذي لا يدركه بعد الهمم nor fathomed by profound intuitions ولا يناله غوص الفطن', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 2, NULL, 'He whose attribute admits no binding limitation, no settled description, no appointed time, no extended term — الَّذِي لَيْسَ لِصِفَتِهِ حَدٌّ مَحْدُودٌ، وَلاَ نَعْتٌ مَوْجُودٌ، وَلا وَقْتٌ مَعْدُودٌ — so that His attribute cannot be confined within a definition and yet is affirmed as real, described in the very words of revelation even though no description can capture Him. Through His power He brought all created things into being; through His mercy He sent the comforting winds abroad; and with rocky pillars He entrenched His swaying earth.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'he whose attribute admits no binding limitation no settled description no appointed time no extended term الذي ليس لصفته حد محدود ولا نعت موجود ولا وقت معدود so that his attribute cannot be confined within a definition and yet is affirmed as real described in the very words of revelation even though no description can capture him through his power he brought all created things into being through his mercy he sent the comforting winds abroad and with rocky pillars he entrenched his swaying earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 3, NULL, 'Foremost in religion is knowledge of Him. The perfection of that knowledge is belief in Him; the perfection of belief is affirming His oneness; and the perfection of that affirmation is to purify one''s devotion to Him — the perfection of sincerity, أخلاص — which means rendering both one''s devotion and one''s very conception of God entirely pure. The perfection of that purification is to divest Him of all attributes (نَفْیُ الصِّفَۃِ), because every attribute bears witness that it is other than the thing it is attributed to, and every such thing bears witness that it is other than the attribute.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'foremost in religion is knowledge of him the perfection of that knowledge is belief in him the perfection of belief is affirming his oneness and the perfection of that affirmation is to purify ones devotion to him the perfection of sincerity اخلاص which means rendering both ones devotion and ones very conception of god entirely pure the perfection of that purification is to divest him of all attributes نفي الصفه because every attribute bears witness that it is other than the thing it is attributed to and every such thing bears witness that it is other than the attribute', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 4, NULL, 'So whoever ascribes an attribute to God, glorified be He, has conjoined Him with something else. Whoever conjoins Him has made Him twofold. Whoever makes Him twofold has fragmented Him. And whoever fragments Him is ignorant of Him. Whoever points to Him confines Him. Whoever confines Him counts Him. Whoever asks "in what?" encloses Him. And whoever asks "upon what?" isolates Him.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'so whoever ascribes an attribute to god glorified be he has conjoined him with something else whoever conjoins him has made him twofold whoever makes him twofold has fragmented him and whoever fragments him is ignorant of him whoever points to him confines him whoever confines him counts him whoever asks in what encloses him and whoever asks upon what isolates him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 5, NULL, 'The very attributes by which He is named in revelation — that He is the All-Compassionate (رَحْمَٰن), the All-Merciful (رحیم), the Almighty (عزیز) — are affirmed as real and yet cannot be defined, bounded, or described. He is merciful, but not as any mercy the human mind can picture; powerful, but not as any storm or flood or force that creation has known. Reason itself "de-fines," drawing a boundary, a ⟪ar:حد⟫, around whatever it grasps. In breaking that boundary, the sermon opens an awareness beyond the reach of speculative thought: by negating the limits of human words, it affirms the Absolute that has no limit. This is the very movement of the testimony of faith — لا الہ, "no deity," which is the negation (نفی), and الا اللہ, "except God," which is the affirmation (اِثْبَات). Each attribute is negated only insofar as the limited mind conceives it, and is thereby affirmed as nothing but God Himself: La Rahmana illaLlah, there is no All-Compassionate but God; La Raheema illaLlah, there is no All-Merciful but God. Thus is God glorified above all that the mind would attribute to Him: "‏سُبْحَنَ ٱللَّهِ عَمَّا يَصِفُونَ," "Glorified is God above all that they attribute to Him!" (Surat al-Muminun, 23:91).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'the very attributes by which he is named in revelation that he is the all compassionate رحمن the all merciful رحيم the almighty عزيز are affirmed as real and yet cannot be defined bounded or described he is merciful but not as any mercy the human mind can picture powerful but not as any storm or flood or force that creation has known reason itself de fines drawing a boundary a ar حد around whatever it grasps in breaking that boundary the sermon opens an awareness beyond the reach of speculative thought by negating the limits of human words it affirms the absolute that has no limit this is the very movement of the testimony of faith لا اله no deity which is the negation نفي and الا الله except god which is the affirmation اثبات each attribute is negated only insofar as the limited mind conceives it and is thereby affirmed as nothing but god himself la rahmana illallah there is no all compassionate but god la raheema illallah there is no all merciful but god thus is god glorified above all that the mind would attribute to him سبحن الله عما يصفون glorified is god above all that they attribute to him surat al muminun 23 91', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 6, NULL, 'Being, but not by way of any becoming; existing, but not from having been non-existent; with every thing, but not through association; other than every thing, but not through separation; acting, but not through movements and instruments; seeing, even when nothing of His creation was to be seen; solitary, even when there was none whose intimacy might be sought or whose absence might be missed.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'being but not by way of any becoming existing but not from having been non existent with every thing but not through association other than every thing but not through separation acting but not through movements and instruments seeing even when nothing of his creation was to be seen solitary even when there was none whose intimacy might be sought or whose absence might be missed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 7, NULL, 'He brought forth creation, originating it from the very beginning, without pondering over any deliberation or benefiting from any previous experience, without initiating any movement or engaging in any unsettling exertion. He assigned to all things their span of time and harmonized their differences. He instilled within them their natural dispositions, impressing upon them their respective forms, knowing them before their genesis, encompassing their boundaries and their finalities, and aware of their configurations and their contours.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'he brought forth creation originating it from the very beginning without pondering over any deliberation or benefiting from any previous experience without initiating any movement or engaging in any unsettling exertion he assigned to all things their span of time and harmonized their differences he instilled within them their natural dispositions impressing upon them their respective forms knowing them before their genesis encompassing their boundaries and their finalities and aware of their configurations and their contours', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 8, NULL, 'Then He, glorified be He, created a fissure in the atmospheres, cleaving apart directions and the uppermost levels of air, and caused water to flow therein — a current of surging waves swelling and swirling in overflowing abundance. He mounted it upon a tempestuous wind, a thunderous gale, then made that wind prevent the return of the water, enabling it to dominate the violence of its flow and aligning it with the boundaries of the water. The air beneath the wind spread wide open, while the water above flowed copiously.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'then he glorified be he created a fissure in the atmospheres cleaving apart directions and the uppermost levels of air and caused water to flow therein a current of surging waves swelling and swirling in overflowing abundance he mounted it upon a tempestuous wind a thunderous gale then made that wind prevent the return of the water enabling it to dominate the violence of its flow and aligning it with the boundaries of the water the air beneath the wind spread wide open while the water above flowed copiously', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 9, NULL, 'Then He raised up another wind, making it sterile, fixing its course, intensifying its current, and distancing it from its source. He ordered it to agitate the swelling waters and to stir up oceanic waves. The wind churned up the waters as one churns milk in a milkbag, imparting to the water its own violence in the atmosphere, turning its foremost back upon its hindmost and its stillness into motion, so that its torrents surged and its swelling waves threw up foam. He then elevated that foam within a cleft air and a vast open atmosphere, and formed from it the seven heavens, making the lowest a suspended wave and the highest a protected shelter and an elevated ceiling, without any pillars to support them or any clinch to transfix them.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'then he raised up another wind making it sterile fixing its course intensifying its current and distancing it from its source he ordered it to agitate the swelling waters and to stir up oceanic waves the wind churned up the waters as one churns milk in a milkbag imparting to the water its own violence in the atmosphere turning its foremost back upon its hindmost and its stillness into motion so that its torrents surged and its swelling waves threw up foam he then elevated that foam within a cleft air and a vast open atmosphere and formed from it the seven heavens making the lowest a suspended wave and the highest a protected shelter and an elevated ceiling without any pillars to support them or any clinch to transfix them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 10, NULL, 'Then He adorned the heavens with the ornaments of the stars and the effulgence of the firmament, and made a radiant lamp — the sun — and an illuminating moon to follow an orbit in a revolving sphere, beneath a roof in motion and a firmament in flux.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'then he adorned the heavens with the ornaments of the stars and the effulgence of the firmament and made a radiant lamp the sun and an illuminating moon to follow an orbit in a revolving sphere beneath a roof in motion and a firmament in flux', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 11, NULL, 'Then He split up the highest heavens and filled them with angels of different dispositions:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'then he split up the highest heavens and filled them with angels of different dispositions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 12, NULL, 'some prostrating and not bowing; others bowing and not standing upright; some arrayed in ranks, not separating from one another; others glorifying, never wearying, not overcome by sleepiness in the eyes, distraction in the mind, fatigue of the body, or the negligence of forgetfulness.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'some prostrating and not bowing others bowing and not standing upright some arrayed in ranks not separating from one another others glorifying never wearying not overcome by sleepiness in the eyes distraction in the mind fatigue of the body or the negligence of forgetfulness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 13, NULL, 'Among them are custodians of His Revelation and conveyors of His Words to His Messengers, and those who come and go with His Decree and His Command. Among them are the guardians of His slaves and the wardens of the gates of His Gardens. And among them are those whose feet stand firmly on the lowest worlds, whose necks surpass the highest heaven, whose sides exceed all bounds, and whose shoulders are proportioned to the pillars of the Throne — their eyes cast down before it, enwrapping themselves beneath it in their wings. Between them and all others there is a barrier: veils of Glory and screens of Might. They do not imagine their Lord through formal representation, nor ascribe to Him created attributes. They do not confine Him within places, nor allude to Him through similitudes.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'among them are custodians of his revelation and conveyors of his words to his messengers and those who come and go with his decree and his command among them are the guardians of his slaves and the wardens of the gates of his gardens and among them are those whose feet stand firmly on the lowest worlds whose necks surpass the highest heaven whose sides exceed all bounds and whose shoulders are proportioned to the pillars of the throne their eyes cast down before it enwrapping themselves beneath it in their wings between them and all others there is a barrier veils of glory and screens of might they do not imagine their lord through formal representation nor ascribe to him created attributes they do not confine him within places nor allude to him through similitudes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 14, NULL, 'Then He, glorified be He, gathered up a quantity of dust — from some hard earth and some soft, some sweet and some salty — and poured water onto it until it was pure, then kneaded into it moisture until it held together. From this He fashioned a form with curves and joints, limbs and parts, compacting it until it held fast, solidifying it until it became as sounding clay, and assigning to it a measured duration and a known end. Then He breathed into it of His spirit, and it rose up as a human being, endowed with intellectual powers for reflection, thoughts by which to conduct himself, limbs to put to use, instruments at his disposal, and knowledge with which to discern between true and false, between different tastes and fragrances, and between different colors and kinds — a constitution compounded of different hues, unified forms, contrasting oppositions, and distinct admixtures of heat and cold, moisture and dryness.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'then he glorified be he gathered up a quantity of dust from some hard earth and some soft some sweet and some salty and poured water onto it until it was pure then kneaded into it moisture until it held together from this he fashioned a form with curves and joints limbs and parts compacting it until it held fast solidifying it until it became as sounding clay and assigning to it a measured duration and a known end then he breathed into it of his spirit and it rose up as a human being endowed with intellectual powers for reflection thoughts by which to conduct himself limbs to put to use instruments at his disposal and knowledge with which to discern between true and false between different tastes and fragrances and between different colors and kinds a constitution compounded of different hues unified forms contrasting oppositions and distinct admixtures of heat and cold moisture and dryness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 15, NULL, 'Then God, glorified be He, demanded of the angels the fulfillment of what He had charged them with, and their compliance with His injunction, by prostrating in submission before Adam and humbling themselves before him. So He said, "Prostrate to Adam," and they prostrated — all except Iblis. Passionate scorn deranged him and wretchedness overwhelmed him; he took pride in his constitution of fire and despised the creature made of clay. Then God granted him a respite, so that His wrath would be fully warranted, the affliction consummated, and the promise fulfilled. So He said, "You are among those given respite until a day whose time is appointed."', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'then god glorified be he demanded of the angels the fulfillment of what he had charged them with and their compliance with his injunction by prostrating in submission before adam and humbling themselves before him so he said prostrate to adam and they prostrated all except iblis passionate scorn deranged him and wretchedness overwhelmed him he took pride in his constitution of fire and despised the creature made of clay then god granted him a respite so that his wrath would be fully warranted the affliction consummated and the promise fulfilled so he said you are among those given respite until a day whose time is appointed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 16, NULL, 'Then He, glorified be He, settled Adam in an abode where He made his life comfortable and his domain secure, and warned him of Iblis and his enmity. But his enemy beguiled him, driven by envious desire for Adam''s immortal dwelling and his intimacy with the righteous. So Adam traded certainty for doubt and resolution for weakness, and replaced joy with dread and self-esteem with remorse. Then God accepted his repentance, enveloped him in a word of His mercy, and promised him a return to His Garden, before sending him down to the abode of tribulations and the begetting of progeny.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'then he glorified be he settled adam in an abode where he made his life comfortable and his domain secure and warned him of iblis and his enmity but his enemy beguiled him driven by envious desire for adams immortal dwelling and his intimacy with the righteous so adam traded certainty for doubt and resolution for weakness and replaced joy with dread and self esteem with remorse then god accepted his repentance enveloped him in a word of his mercy and promised him a return to his garden before sending him down to the abode of tribulations and the begetting of progeny', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 17, NULL, 'From Adam''s offspring God chose prophets, taking from them a pledge concerning the Revelation and entrusting them with the conveyance of His message, at a time when most of His creatures had strayed from their covenant with God — ignoring His due, setting up rivals alongside Him, while the demons distracted them from knowledge of Him and severed them from worship of Him. So He sent among them His messengers and dispatched prophets in succession, to demand of His creatures the fulfillment of their covenant, to remind them of His forgotten graces, to remonstrate with them through the communication of His Revelation, to unearth for them the buried treasures of the intellect, and to show them signs of His omnipotence: the outspread earth laid low beneath their feet, provisions that give them life, endings that mete out death, ailments hastening their decline, and a succession of events that flows over them.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'from adams offspring god chose prophets taking from them a pledge concerning the revelation and entrusting them with the conveyance of his message at a time when most of his creatures had strayed from their covenant with god ignoring his due setting up rivals alongside him while the demons distracted them from knowledge of him and severed them from worship of him so he sent among them his messengers and dispatched prophets in succession to demand of his creatures the fulfillment of their covenant to remind them of his forgotten graces to remonstrate with them through the communication of his revelation to unearth for them the buried treasures of the intellect and to show them signs of his omnipotence the outspread earth laid low beneath their feet provisions that give them life endings that mete out death ailments hastening their decline and a succession of events that flows over them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 18, NULL, 'God never left His creation without a prophet sent forth, a revealed scripture, a compelling proof, or a clear path. These messengers were not weakened by the scarcity of their numbers or by the multitude of those who denied them. Those who came earlier were told the names of those who would follow, and those who came later were informed of those who had gone before. In this way generations were born and ages elapsed, fathers passing away and sons succeeding them, until God sent forth Muhammad, Messenger of God, in fulfillment of His promise and in completion of the cycle of prophecy — he concerning whom a pledge had been taken from the prophets, known through his signs, of noble birth.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'god never left his creation without a prophet sent forth a revealed scripture a compelling proof or a clear path these messengers were not weakened by the scarcity of their numbers or by the multitude of those who denied them those who came earlier were told the names of those who would follow and those who came later were informed of those who had gone before in this way generations were born and ages elapsed fathers passing away and sons succeeding them until god sent forth muhammad messenger of god in fulfillment of his promise and in completion of the cycle of prophecy he concerning whom a pledge had been taken from the prophets known through his signs of noble birth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 19, NULL, 'At that time the people of the earth were divided into different religious communities; caprice was rampant and pathways were in disorder, among them the path of those who likened God to His creation, distorted His name, or pointed to other than Him. God guided them through His Prophet out of their error and, through his presence, delivered them from their ignorance.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'at that time the people of the earth were divided into different religious communities caprice was rampant and pathways were in disorder among them the path of those who likened god to his creation distorted his name or pointed to other than him god guided them through his prophet out of their error and through his presence delivered them from their ignorance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 20, NULL, 'Then God chose for Muhammad the meeting with Him, and desired for him what was with Himself. He removed him with dignity from the abode of this lower world and drew him away from the realm of trial, taking him to Himself in honor. The Prophet left behind among them what the prophets leave for their communities, so that they would not be abandoned to wander without a clear path or a visible beacon: the scripture of their Lord, elucidating', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'then god chose for muhammad the meeting with him and desired for him what was with himself he removed him with dignity from the abode of this lower world and drew him away from the realm of trial taking him to himself in honor the prophet left behind among them what the prophets leave for their communities so that they would not be abandoned to wander without a clear path or a visible beacon the scripture of their lord elucidating', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 21, NULL, 'what is lawful and unlawful, what is obligatory and what is recommended, the abrogating verses and the abrogated, the conditionally permissible and the unconditionally compulsory, the specific and the general, His admonitions and His analogies, the undelimited and the delimited, the unambiguous and the equivocal,', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'what is lawful and unlawful what is obligatory and what is recommended the abrogating verses and the abrogated the conditionally permissible and the unconditionally compulsory the specific and the general his admonitions and his analogies the undelimited and the delimited the unambiguous and the equivocal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 22, NULL, 'making plain what is condensed and clarifying what is obscure.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'making plain what is condensed and clarifying what is obscure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the first sermon of the nahj al-balagha', '14. The First Sermon of the Nahj al-Balagha', 23, NULL, 'In it are matters whose knowledge is binding upon God''s servants, and others whose ignorance is overlooked. There are injunctions affirmed as obligatory in the scripture yet known to have been abrogated by the Sunna, and actions made obligatory by the Sunna from which the scripture has nonetheless permitted abstention. There are duties incumbent upon a person at their prescribed time that cease to be incumbent once that time has passed. The scripture also draws a distinction between forbidden acts: the major sins, with which He has threatened punishment by His fire, and the minor ones, for which He has prepared His forgiveness. And it describes acts that are acceptable when performed to a modest degree and equally acceptable when performed to a higher degree, without either being obligatory.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 14 the first sermon of the nahj al balagha', 'in it are matters whose knowledge is binding upon gods servants and others whose ignorance is overlooked there are injunctions affirmed as obligatory in the scripture yet known to have been abrogated by the sunna and actions made obligatory by the sunna from which the scripture has nonetheless permitted abstention there are duties incumbent upon a person at their prescribed time that cease to be incumbent once that time has passed the scripture also draws a distinction between forbidden acts the major sins with which he has threatened punishment by his fire and the minor ones for which he has prepared his forgiveness and it describes acts that are acceptable when performed to a modest degree and equally acceptable when performed to a higher degree without either being obligatory', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 0, NULL, 'The Imam wrote this letter to Malik al-Ashtar when he appointed him governor of Egypt and its regions, at a time when the rule of the previous governor, Muhammad b. Abi Bakr, had grown unstable. It is the longest of his letters, and the richest of them in both beauty of form and excellence of meaning.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'the imam wrote this letter to malik al ashtar when he appointed him governor of egypt and its regions at a time when the rule of the previous governor muhammad b abi bakr had grown unstable it is the longest of his letters and the richest of them in both beauty of form and excellence of meaning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 1, NULL, 'In the Name of God, the Compassionate, the Merciful.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'in the name of god the compassionate the merciful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 2, NULL, 'This is what the servant of God, Ali (ع), Commander of the Faithful, commands Malik b. al-Harith al-Ashtar in his mandate (عہد) of appointment, upon making him governor of Egypt: to collect its revenues, to fight its enemies, to seek the welfare of its people, and to bring prosperity to its lands.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'this is what the servant of god ali ع commander of the faithful commands malik b al harith al ashtar in his mandate عهد of appointment upon making him governor of egypt to collect its revenues to fight its enemies to seek the welfare of its people and to bring prosperity to its lands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 3, NULL, 'He commands him to fear God, to place obedience to God before all else, and to hold fast to what He has commanded in His Book, both the obligatory acts and the recommended ones — for no one attains virtue except by following them, and no one becomes wretched except by denying and neglecting them. He commands him to assist God with his heart, his hand, and his tongue, for God, majestic is His name, has undertaken to grant victory to whoever assists Him and to exalt whoever glorifies Him. And he commands him to curb the passions of his soul and to hold it back when whim and caprice run high, for the soul incites to evil unless God shows mercy.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'he commands him to fear god to place obedience to god before all else and to hold fast to what he has commanded in his book both the obligatory acts and the recommended ones for no one attains virtue except by following them and no one becomes wretched except by denying and neglecting them he commands him to assist god with his heart his hand and his tongue for god majestic is his name has undertaken to grant victory to whoever assists him and to exalt whoever glorifies him and he commands him to curb the passions of his soul and to hold it back when whim and caprice run high for the soul incites to evil unless god shows mercy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 4, NULL, 'Know, Malik, that I am sending you to a land that has known governments before yours, some just and some unjust. The people will now weigh your conduct just as you once weighed the conduct of the rulers before you, and they will speak of you just as you spoke of them. The righteous are known only through what God causes to be said of them on the tongues of His servants. So let the treasure dearest to you be the treasure of good deeds. Master your desires, and hold yourself back from whatever is not lawful to you, for such restraint is the soul dealing fairly with itself, keeping it balanced between what it likes and what it dislikes.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'know malik that i am sending you to a land that has known governments before yours some just and some unjust the people will now weigh your conduct just as you once weighed the conduct of the rulers before you and they will speak of you just as you spoke of them the righteous are known only through what god causes to be said of them on the tongues of his servants so let the treasure dearest to you be the treasure of good deeds master your desires and hold yourself back from whatever is not lawful to you for such restraint is the soul dealing fairly with itself keeping it balanced between what it likes and what it dislikes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 5, NULL, 'Habituate your heart to mercy, love, and kindness toward your subjects. Do not stand over them like a ravening beast that counts them fair prey, for they are of two kinds: either your brother in religion or your equal in creation. Mistakes slip from them and faults befall them, whether by intention or by accident. So extend to them your forgiveness and your pardon, just as you would wish God to extend to you His forgiveness and pardon; for you stand above them, the one set in authority over you stands above you, and God stands above the one who appointed you. He has asked you to manage their affairs, and He is testing you through them.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'habituate your heart to mercy love and kindness toward your subjects do not stand over them like a ravening beast that counts them fair prey for they are of two kinds either your brother in religion or your equal in creation mistakes slip from them and faults befall them whether by intention or by accident so extend to them your forgiveness and your pardon just as you would wish god to extend to you his forgiveness and pardon for you stand above them the one set in authority over you stands above you and god stands above the one who appointed you he has asked you to manage their affairs and he is testing you through them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 6, NULL, 'Do not set yourself on a course of war with God, for you have no strength against His retribution and cannot do without His forgiveness and mercy. Never regret a pardon, and never rejoice in a punishment. Do not act in haste on any impulse when a way around it can still be found. Do not say, "I have been given authority, so I command and am obeyed," for that breeds corruption in the heart, weakens religion, and draws misfortune near. If the authority you hold breeds in you pride or vanity, look to the greatness of God''s dominion above you and to His power over you — a power the like of which you do not hold even over yourself. This will settle your ambition, restrain your vehemence, and restore to you the good sense that had strayed. Beware of matching yourself with God in greatness or likening yourself to Him in might, for God humbles every tyrant and disgraces every braggart.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'do not set yourself on a course of war with god for you have no strength against his retribution and cannot do without his forgiveness and mercy never regret a pardon and never rejoice in a punishment do not act in haste on any impulse when a way around it can still be found do not say i have been given authority so i command and am obeyed for that breeds corruption in the heart weakens religion and draws misfortune near if the authority you hold breeds in you pride or vanity look to the greatness of gods dominion above you and to his power over you a power the like of which you do not hold even over yourself this will settle your ambition restrain your vehemence and restore to you the good sense that had strayed beware of matching yourself with god in greatness or likening yourself to him in might for god humbles every tyrant and disgraces every braggart', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 7, NULL, 'Be just with God and be just with people, granting them their due from yourself, from your close kin, and from those of your subjects for whom you feel fondness; for if you do not, you are an oppressor. Whoever oppresses the servants of God has God for his adversary, and not merely His servants; and whomever God opposes, He refutes his plea, and that man remains at war with God until he desists and repents. Nothing so surely hastens the withdrawal of God''s grace or the coming of His retribution as persistence in oppression, for God hears the cry of the oppressed and lies in wait for the oppressors.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'be just with god and be just with people granting them their due from yourself from your close kin and from those of your subjects for whom you feel fondness for if you do not you are an oppressor whoever oppresses the servants of god has god for his adversary and not merely his servants and whomever god opposes he refutes his plea and that man remains at war with god until he desists and repents nothing so surely hastens the withdrawal of gods grace or the coming of his retribution as persistence in oppression for god hears the cry of the oppressed and lies in wait for the oppressors', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 8, NULL, 'Let the dearest of your concerns be those most balanced in truth, most complete in justice, and most inclusive of your subjects'' contentment; for the discontent of the common folk (الْعَامَّةُ) cancels the contentment of the elite (الْخَاصَّةُ), while the discontent of the elite is absorbed within the contentment of the common folk. In times of ease no one is a heavier burden to a ruler than the elite, and in hardship none less helpful; none is more averse to fair treatment, more insistent in asking for favors, less grateful when given them, slower to accept an excuse when refused, or weaker in patience under the blows of fortune. It is the common folk of the community who are the pillar of religion, the mass of the Muslims, and the defense against enemies; so let your inclination and your leaning be toward them.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'let the dearest of your concerns be those most balanced in truth most complete in justice and most inclusive of your subjects contentment for the discontent of the common folk العامه cancels the contentment of the elite الخاصه while the discontent of the elite is absorbed within the contentment of the common folk in times of ease no one is a heavier burden to a ruler than the elite and in hardship none less helpful none is more averse to fair treatment more insistent in asking for favors less grateful when given them slower to accept an excuse when refused or weaker in patience under the blows of fortune it is the common folk of the community who are the pillar of religion the mass of the muslims and the defense against enemies so let your inclination and your leaning be toward them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 9, NULL, 'Let those among your subjects who most eagerly hunt out the faults of others be the furthest from you and the most despised in your eyes, for people do have faults, and the ruler is the one most bound to conceal them. Do not expose what is hidden from you; your duty is only to correct what has become plain, and God will judge whatever remains hidden. Veil people''s failings as much as you can, and God will veil from your subjects those failings of your own that you would wish kept concealed. Loosen from the people every knot of resentment, and cut away from your own heart the cord of every enmity. Turn a blind eye to whatever is unclear to you, and do not be quick to believe a slanderer, for a slanderer is a deceiver, however sincerely he may seem to give counsel.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'let those among your subjects who most eagerly hunt out the faults of others be the furthest from you and the most despised in your eyes for people do have faults and the ruler is the one most bound to conceal them do not expose what is hidden from you your duty is only to correct what has become plain and god will judge whatever remains hidden veil peoples failings as much as you can and god will veil from your subjects those failings of your own that you would wish kept concealed loosen from the people every knot of resentment and cut away from your own heart the cord of every enmity turn a blind eye to whatever is unclear to you and do not be quick to believe a slanderer for a slanderer is a deceiver however sincerely he may seem to give counsel', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 10, NULL, 'Do not admit a miser into your counsel, for he will turn you away from generosity and frighten you with poverty; nor a coward, for he will make you feel too weak for your affairs; nor a greedy man, for he will dress up avidity as though it were justice. Miserliness, cowardice, and greed are separate traits, yet a single bad opinion of God unites them. The worst of your ministers is the one who served evil rulers before you and shared in their sins. Do not let such men into your inner circle, for they are the helpers of sinners and the brothers of tyrants. You can find good replacements for them among men of equal intelligence and capability who carry none of that burden of sin, who never helped a tyrant in his tyranny or a sinner in his sin. Such men will cost you the least, support you the best, incline most warmly toward you, and attach themselves least to anyone but you; so choose them as your intimates, in private and in public.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'do not admit a miser into your counsel for he will turn you away from generosity and frighten you with poverty nor a coward for he will make you feel too weak for your affairs nor a greedy man for he will dress up avidity as though it were justice miserliness cowardice and greed are separate traits yet a single bad opinion of god unites them the worst of your ministers is the one who served evil rulers before you and shared in their sins do not let such men into your inner circle for they are the helpers of sinners and the brothers of tyrants you can find good replacements for them among men of equal intelligence and capability who carry none of that burden of sin who never helped a tyrant in his tyranny or a sinner in his sin such men will cost you the least support you the best incline most warmly toward you and attach themselves least to anyone but you so choose them as your intimates in private and in public', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 11, NULL, 'Among these, give the highest place to the one who most readily speaks the bitter truth to you and gives you the least encouragement in whatever you do that God dislikes for His friends, however sharply that strikes at your own desires. Attach yourself to people of piety and truthfulness, and train them not to flatter you or to gladden you with praise for something you never did, for lavish praise breeds conceit and carries a person toward vanity. Never set the good and the wicked on the same footing before you, for that would make the good think little of their goodness and let the wicked settle deeper into their wickedness; hold each of them to what he has bound himself to. Know that nothing so builds a ruler''s confidence in his subjects as his kindness toward them, his easing of their burdens, and his refusal to press them beyond what they can bear. So conduct yourself in a way that earns their trust, for that trust will spare you long trouble; the one most deserving of your good opinion is the one you have treated well, and the one most deserving of your distrust is the one you have treated badly.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'among these give the highest place to the one who most readily speaks the bitter truth to you and gives you the least encouragement in whatever you do that god dislikes for his friends however sharply that strikes at your own desires attach yourself to people of piety and truthfulness and train them not to flatter you or to gladden you with praise for something you never did for lavish praise breeds conceit and carries a person toward vanity never set the good and the wicked on the same footing before you for that would make the good think little of their goodness and let the wicked settle deeper into their wickedness hold each of them to what he has bound himself to know that nothing so builds a rulers confidence in his subjects as his kindness toward them his easing of their burdens and his refusal to press them beyond what they can bear so conduct yourself in a way that earns their trust for that trust will spare you long trouble the one most deserving of your good opinion is the one you have treated well and the one most deserving of your distrust is the one you have treated badly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 12, NULL, 'Do not break any good tradition set by the leaders of this community, by which harmony was knit together and the subjects were set right; and do not bring in any new practice that harms the traditions already in place, for then the reward for the old traditions will go to the one who founded them, while the burden of breaking them will fall on you. Study much with the scholars (الَعُلَمَاءِ) and hold much discourse with the sages (الْحُكَمَاءِ), so as to strengthen what keeps your lands sound and to uphold what those before you had already set right.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'do not break any good tradition set by the leaders of this community by which harmony was knit together and the subjects were set right and do not bring in any new practice that harms the traditions already in place for then the reward for the old traditions will go to the one who founded them while the burden of breaking them will fall on you study much with the scholars العلماء and hold much discourse with the sages الحكماء so as to strengthen what keeps your lands sound and to uphold what those before you had already set right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 13, NULL, 'Know that the subjects are made up of several classes, no one of which can be sound without the others, and no one of which can do without the rest. Among them are the soldiers of God (junud Allah); the scribes (kuttab, sing. katib) who serve the common people and the elite; the judges who administer justice (قُضَاةُ الْعَدْلِ); the officials who uphold fairness and secure the right of redress (رِفْقٌ); those who pay the poll-tax (jizya, جزیۃ) and the land-tax (خَرَج) from among the protected people (أَهْلُ الذِّمَّةِ) and the Muslims; the merchants and artisans; and the lowest class, the needy and the destitute. To each of these God has assigned its share, and He has fixed its bounds and its duties in His Book or in the Sunna (سنۃ) of His Prophet, God bless him and his family, as a binding covenant (عہد) from Him, kept safe with us.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'know that the subjects are made up of several classes no one of which can be sound without the others and no one of which can do without the rest among them are the soldiers of god junud allah the scribes kuttab sing katib who serve the common people and the elite the judges who administer justice قضاه العدل the officials who uphold fairness and secure the right of redress رفق those who pay the poll tax jizya جزيه and the land tax خرج from among the protected people اهل الذمه and the muslims the merchants and artisans and the lowest class the needy and the destitute to each of these god has assigned its share and he has fixed its bounds and its duties in his book or in the sunna سنه of his prophet god bless him and his family as a binding covenant عهد from him kept safe with us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 14, NULL, 'As for the soldiers, they are, by the grace of God, the fortresses of the subjects, the adornment of the governors, the strength of religion, and the pathways to security (سُبُلُ الْأَمْنِ). The subjects cannot sustain themselves except through the soldiers, and the soldiers in their turn cannot be sustained except through the خَرَج, the revenue God brings forth for them; by it they gain the strength to wage war on their enemies, on it they depend for their own welfare, and through it they meet their needs. Neither of these two classes can be maintained without the third: the judges, the administrators, and the scribes, who uphold every contract, gather and order all interests and benefits, and are entrusted with the affairs of state, particular and general alike. None of these can function without the merchants and artisans, who gather the goods that are needed, set up the markets, and by their own labor supply what the work of others could not procure. Last comes the lowest class, the needy and the destitute, whose relief and support is an obligation owed to them. For every one of these classes there is abundance with God, and every one has upon the governor a right measured by what its welfare requires. The governor cannot fully discharge the duties God has laid upon him except through earnest striving and seeking God''s help (الِاهْتِمَامُ وَالِاسْتِعَانَةُ), training himself to hold fast to what is right, and bearing patiently whatever comes his way, be it easy or hard.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'as for the soldiers they are by the grace of god the fortresses of the subjects the adornment of the governors the strength of religion and the pathways to security سبل الامن the subjects cannot sustain themselves except through the soldiers and the soldiers in their turn cannot be sustained except through the خرج the revenue god brings forth for them by it they gain the strength to wage war on their enemies on it they depend for their own welfare and through it they meet their needs neither of these two classes can be maintained without the third the judges the administrators and the scribes who uphold every contract gather and order all interests and benefits and are entrusted with the affairs of state particular and general alike none of these can function without the merchants and artisans who gather the goods that are needed set up the markets and by their own labor supply what the work of others could not procure last comes the lowest class the needy and the destitute whose relief and support is an obligation owed to them for every one of these classes there is abundance with god and every one has upon the governor a right measured by what its welfare requires the governor cannot fully discharge the duties god has laid upon him except through earnest striving and seeking gods help الاهتمام والاستعانه training himself to hold fast to what is right and bearing patiently whatever comes his way be it easy or hard', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 15, NULL, 'Appoint as commander of your soldiers the man you feel most deeply to be the most sincere toward God, the Prophet, and your Imam, the purest of heart and the most excellent in forbearance (حِلْم): one who is slow to anger, glad to pardon, kind to the weak, and firm with the strong; neither driven by violence nor held back by weakness. Hold fast to men of noble descent, from pious families of established name and repute, and to those known for their bravery, their courage, their generosity (السَّخَاءُ), and their tolerance (السَّمَاحَةُ), for they are a group formed by nobility and a party made of honor. Then oversee their affairs as parents oversee their child. Let no act by which you strengthen them seem too great in your eyes, and do not belittle any kindness, however slight, that you have promised them, for such kindness is a summoner (دَاعِيَةٌ) calling them to give you good counsel and to place their trust in you. Do not neglect the close inspection of their affairs for the sake of matters that seem weightier, for there are small acts of kindness that benefit them greatly, and there are weightier matters that cannot be set aside.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'appoint as commander of your soldiers the man you feel most deeply to be the most sincere toward god the prophet and your imam the purest of heart and the most excellent in forbearance حلم one who is slow to anger glad to pardon kind to the weak and firm with the strong neither driven by violence nor held back by weakness hold fast to men of noble descent from pious families of established name and repute and to those known for their bravery their courage their generosity السخاء and their tolerance السماحه for they are a group formed by nobility and a party made of honor then oversee their affairs as parents oversee their child let no act by which you strengthen them seem too great in your eyes and do not belittle any kindness however slight that you have promised them for such kindness is a summoner داعيه calling them to give you good counsel and to place their trust in you do not neglect the close inspection of their affairs for the sake of matters that seem weightier for there are small acts of kindness that benefit them greatly and there are weightier matters that cannot be set aside', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 16, NULL, 'Let the most favored of your commanders be the one most generous to the people and most open-handed with his bounty, so that they and their dependants have ample means. Let their concern be gathered into a single resolve: to fight the enemy. Your kindness toward them will incline their hearts toward you.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'let the most favored of your commanders be the one most generous to the people and most open handed with his bounty so that they and their dependants have ample means let their concern be gathered into a single resolve to fight the enemy your kindness toward them will incline their hearts toward you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 17, NULL, 'The greatest source of joy for governors is the establishment of justice in the land and the flow of love from their subjects. That love will not appear unless the subjects'' hearts are secure, and their counsel will not be sound unless the governor watches over those charged with their welfare and makes the burden of his rule light and easy to bear, so that they no longer anxiously hope for it to end. Raise their hopes, praise them continually, and recount the brave deeds of those who have been brave, for abundant praise of noble acts rouses the courageous and spurs on the sluggish, if God wills. Acknowledge the courageous deed of every man; do not credit one man''s deed to another, and do not fall short in granting anyone his due. Do not let a man''s nobility lead you to reckon a small accomplishment great, nor a man''s low station lead you to reckon a great one small. Refer to God and His Messenger any matter that weighs heavily upon you or is unclear to you, for God the Exalted has said to a people whom He loved to guide: O ye who believe, obey God and obey the Messenger and those in authority among you. And if ye dispute with one another over anything, then refer it to God and the Messenger (An-Nisa: 59). To refer to God is to follow what is clear and unequivocal in His Book; to refer to the Messenger is to follow that part of his Sunna which unites rather than that which divides.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'the greatest source of joy for governors is the establishment of justice in the land and the flow of love from their subjects that love will not appear unless the subjects hearts are secure and their counsel will not be sound unless the governor watches over those charged with their welfare and makes the burden of his rule light and easy to bear so that they no longer anxiously hope for it to end raise their hopes praise them continually and recount the brave deeds of those who have been brave for abundant praise of noble acts rouses the courageous and spurs on the sluggish if god wills acknowledge the courageous deed of every man do not credit one mans deed to another and do not fall short in granting anyone his due do not let a mans nobility lead you to reckon a small accomplishment great nor a mans low station lead you to reckon a great one small refer to god and his messenger any matter that weighs heavily upon you or is unclear to you for god the exalted has said to a people whom he loved to guide o ye who believe obey god and obey the messenger and those in authority among you and if ye dispute with one another over anything then refer it to god and the messenger an nisa 59 to refer to god is to follow what is clear and unequivocal in his book to refer to the messenger is to follow that part of his sunna which unites rather than that which divides', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 18, NULL, 'For the settlement of disputes among the people, choose the one you hold to be the most excellent of your subjects: one whom complex matters do not confound and whom quarrelling litigants do not enrage; who does not persist in error, and does not shrink from returning to the truth once he perceives it; whose soul is not drawn toward greed; who is not content with a shallow understanding but probes to the depths; who is most cautious before ambiguities, most firm in holding to the proofs, least wearied by litigants returning again and again, most patient in uncovering the true state of affairs, and most resolute once the right judgment is plain; whom praise does not make vain and whom enticement does not sway. Such people are indeed rare.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'for the settlement of disputes among the people choose the one you hold to be the most excellent of your subjects one whom complex matters do not confound and whom quarrelling litigants do not enrage who does not persist in error and does not shrink from returning to the truth once he perceives it whose soul is not drawn toward greed who is not content with a shallow understanding but probes to the depths who is most cautious before ambiguities most firm in holding to the proofs least wearied by litigants returning again and again most patient in uncovering the true state of affairs and most resolute once the right judgment is plain whom praise does not make vain and whom enticement does not sway such people are indeed rare', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 19, NULL, 'Then examine carefully and often the carrying-out of the judge''s verdicts, and be generous in what you pay him, so that want is removed and his need to seek help from others is lessened. Give him a rank of nearness to yourself that none of your other close companions might hope to attain, so that he is safe in your presence and shielded from the attacks of other influential men. Scrutinize all of this with a piercing scrutiny, for this religion had been held captive in the hands of evil people, abused by them for their own caprice and exploited by them for the sake of this world.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'then examine carefully and often the carrying out of the judges verdicts and be generous in what you pay him so that want is removed and his need to seek help from others is lessened give him a rank of nearness to yourself that none of your other close companions might hope to attain so that he is safe in your presence and shielded from the attacks of other influential men scrutinize all of this with a piercing scrutiny for this religion had been held captive in the hands of evil people abused by them for their own caprice and exploited by them for the sake of this world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 20, NULL, 'Then look into the affairs of your administrators. Employ them only after testing them, and do not appoint anyone out of partiality or favouritism, for these two are a wellspring of every kind of injustice and treachery. Seek out men of proven experience and modesty, from righteous households and families of precedence in Islam, for they are the most noble in character, the most rooted in dignity, the least inclined toward greed, and the most mindful of how all things end. Then provide them with a generous livelihood, for this gives them the strength to keep themselves in good order, frees them from reaching into the funds in their charge, and stands as an argument against them should they disobey your orders or betray your trust. Examine their actions carefully by appointing over them supervisors known for their sincerity and reliability, for your quiet watching of their affairs will move them to keep faith with their trust and to be gentle with the subjects. Keep watch over your assistants as well: if any one of them stretches out his hand toward a treacherous deed, and the reports of your watchers agree upon it so that you hold it sufficient evidence, then lay corporal punishment upon him, take him to account for what his act has brought about, set him in a place of disgrace, brand him with the charge of treachery, and gird him with the shame of the accusation.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'then look into the affairs of your administrators employ them only after testing them and do not appoint anyone out of partiality or favouritism for these two are a wellspring of every kind of injustice and treachery seek out men of proven experience and modesty from righteous households and families of precedence in islam for they are the most noble in character the most rooted in dignity the least inclined toward greed and the most mindful of how all things end then provide them with a generous livelihood for this gives them the strength to keep themselves in good order frees them from reaching into the funds in their charge and stands as an argument against them should they disobey your orders or betray your trust examine their actions carefully by appointing over them supervisors known for their sincerity and reliability for your quiet watching of their affairs will move them to keep faith with their trust and to be gentle with the subjects keep watch over your assistants as well if any one of them stretches out his hand toward a treacherous deed and the reports of your watchers agree upon it so that you hold it sufficient evidence then lay corporal punishment upon him take him to account for what his act has brought about set him in a place of disgrace brand him with the charge of treachery and gird him with the shame of the accusation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 21, NULL, 'Look also into the matter of the خَرَج land-tax, in such a way that those subject to it are kept in a proper state of well-being, for it is from their welfare, and from the sound collection of the tax itself, that the good of all others is drawn. There can be no welfare of the rest except through them, since all without exception depend upon the revenues of the خَرَج and upon those who pay it. Let your concern for the cultivation of the land outweigh your concern for collecting the tax, for no tax will be gathered where there is no cultivation. Whoever exacts the tax without cultivating the land ruins the land and destroys the people, and his rule will not endure for long. So if the people complain of a heavy burden, or of some blight, or of the cutting off of irrigation, or of a lack of rain, or of a change in the condition of the soil from flooding or drought, then lighten their burden in the measure that you hope will set their situation right. Do not let any relief you grant them weigh heavily upon you, for it is an investment that will return to you in the prosperity of your land, the adornment of your rule, the finest praise you reap from them, and the pride you take in dispensing justice among them. You may then rely upon an increase in their capacity as a result of what you invested in them when you gave them respite, and you may trust them, having accustomed them to your justice and your kindness.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'look also into the matter of the خرج land tax in such a way that those subject to it are kept in a proper state of well being for it is from their welfare and from the sound collection of the tax itself that the good of all others is drawn there can be no welfare of the rest except through them since all without exception depend upon the revenues of the خرج and upon those who pay it let your concern for the cultivation of the land outweigh your concern for collecting the tax for no tax will be gathered where there is no cultivation whoever exacts the tax without cultivating the land ruins the land and destroys the people and his rule will not endure for long so if the people complain of a heavy burden or of some blight or of the cutting off of irrigation or of a lack of rain or of a change in the condition of the soil from flooding or drought then lighten their burden in the measure that you hope will set their situation right do not let any relief you grant them weigh heavily upon you for it is an investment that will return to you in the prosperity of your land the adornment of your rule the finest praise you reap from them and the pride you take in dispensing justice among them you may then rely upon an increase in their capacity as a result of what you invested in them when you gave them respite and you may trust them having accustomed them to your justice and your kindness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 22, NULL, 'It is possible that a situation might arise in which you depend upon them, and they would then bear this responsibility gladly, for a prosperous land can sustain whatever burden you place upon it. The devastation of the land comes about only through the destitution of its inhabitants, and the destitution of its inhabitants comes about only when the desire to amass wealth rules the souls of the governors, when they have doubts about what endures, and when they profit little from exemplary teachings.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'it is possible that a situation might arise in which you depend upon them and they would then bear this responsibility gladly for a prosperous land can sustain whatever burden you place upon it the devastation of the land comes about only through the destitution of its inhabitants and the destitution of its inhabitants comes about only when the desire to amass wealth rules the souls of the governors when they have doubts about what endures and when they profit little from exemplary teachings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 23, NULL, 'Now consider with care the situation of your scribes. Appoint the best of them to manage your affairs. Assign those letters containing the most sensitive strategies and secrets to the scribe in whom you find the most comprehensive moral qualities: one who will not be emboldened by his elevated status to contradict you in public; one who is not negligent in delivering to you the correspondence of your officials and properly despatching your replies; one who takes and gives on your behalf with care. He must not weaken any agreement contracted for you, nor be incapable of repudiating what has been contracted to your detriment. He must not be ignorant of the value of his own capabilities, for one who is unaware of his own worth will be even more ignorant of the worth of others. Do not make your selection solely on the basis of your own instinct, confidence, and trust, for men know how to present themselves to rulers through affectation and good service that conceals neither sincerity nor fidelity. Rather, test them by what they did in the service of good people who came before you, and appoint the one whose virtue left the deepest impression upon the common people and whose reputation for integrity is most widely known. This will be proof of your sincerity toward God and toward the one on whose behalf you have been appointed to this office, for you will be putting the right man in the right place, and in so doing enacting justice.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'now consider with care the situation of your scribes appoint the best of them to manage your affairs assign those letters containing the most sensitive strategies and secrets to the scribe in whom you find the most comprehensive moral qualities one who will not be emboldened by his elevated status to contradict you in public one who is not negligent in delivering to you the correspondence of your officials and properly despatching your replies one who takes and gives on your behalf with care he must not weaken any agreement contracted for you nor be incapable of repudiating what has been contracted to your detriment he must not be ignorant of the value of his own capabilities for one who is unaware of his own worth will be even more ignorant of the worth of others do not make your selection solely on the basis of your own instinct confidence and trust for men know how to present themselves to rulers through affectation and good service that conceals neither sincerity nor fidelity rather test them by what they did in the service of good people who came before you and appoint the one whose virtue left the deepest impression upon the common people and whose reputation for integrity is most widely known this will be proof of your sincerity toward god and toward the one on whose behalf you have been appointed to this office for you will be putting the right man in the right place and in so doing enacting justice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 24, NULL, 'Appoint for each of your affairs a head officer among your officials, one who will not be daunted by the magnitude of affairs nor scattered by their multiplicity. Any fault of your scribes which you have overlooked will be ascribed to you.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'appoint for each of your affairs a head officer among your officials one who will not be daunted by the magnitude of affairs nor scattered by their multiplicity any fault of your scribes which you have overlooked will be ascribed to you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 25, NULL, 'Then attend to the merchants and artisans, treating them well and urging the same on others, those of fixed abode, those who travel with their goods, and those who earn their livelihood with their hands. They are sources of benefit and the means by which conveniences are obtained. Through them, goods are procured from distant and remote places, brought by land and sea, from plains and mountains, and from places where men neither settle nor even dare to venture. They live in a state of reconciliation (سِلْمٌ), so no calamity need be feared from them, and in a state of peace (صُلْحٌ), so no disturbance need be expected. Examine their affairs attentively, both those close to you and those in every corner of your land. Yet be aware that, despite what has been said, many of them harbor a despicable stinginess, a repugnant greed, a propensity to hoard goods, and a tendency to fix prices arbitrarily. All of this brings loss to the people and is a source of shame for governors. So prohibit hoarding, for the Messenger of God ﷺ prohibited it. Let trading be carried out with propriety and fairness, at prices that harm neither party, buyer nor seller. If any one of them succumbs to the temptation to hoard after you have prohibited it, inflict upon him an exemplary but not excessive punishment.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'then attend to the merchants and artisans treating them well and urging the same on others those of fixed abode those who travel with their goods and those who earn their livelihood with their hands they are sources of benefit and the means by which conveniences are obtained through them goods are procured from distant and remote places brought by land and sea from plains and mountains and from places where men neither settle nor even dare to venture they live in a state of reconciliation سلم so no calamity need be feared from them and in a state of peace صلح so no disturbance need be expected examine their affairs attentively both those close to you and those in every corner of your land yet be aware that despite what has been said many of them harbor a despicable stinginess a repugnant greed a propensity to hoard goods and a tendency to fix prices arbitrarily all of this brings loss to the people and is a source of shame for governors so prohibit hoarding for the messenger of god ﷺ prohibited it let trading be carried out with propriety and fairness at prices that harm neither party buyer nor seller if any one of them succumbs to the temptation to hoard after you have prohibited it inflict upon him an exemplary but not excessive punishment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 26, NULL, 'Then, O God, O God, pay particular attention to the lowest class: those who have no wherewithal, the destitute, the needy, the afflicted, the disabled. Within this class are those who beg and those whose wretchedness calls out to be alleviated but who do not beg. Be mindful of God in regard to their rights, for He has entrusted those rights to your care. Assign to them a portion from your public treasury (بَيْتُ الْمَالِ) and a portion of the produce of what is taken as booty by the Muslims in every region, for those who are furthest away have the same rights as those nearest. Upholding the right of each of them is incumbent upon you. Do not let any haughtiness on your part cause you to neglect them, for you will not be pardoned even the slightest shortcoming toward them on account of attending to some seemingly more important matter. Do not turn your concern away from them or assume a contemptuous attitude toward them. Keep a watchful eye over the affairs of those who cannot gain access to you and who are disdained by men of high standing. Appoint from among those you trust a God-fearing and humble person to bring their affairs to your attention. Treat these people in a manner such that God may excuse you on the day you meet Him, for they are more in need of justice from you than any others among your subjects. Offer your excuse to God in respect of fulfilling each one''s right. Assume responsibility for the orphans and the elderly who have no resources and yet cannot bring themselves to beg. This is onerous for governors, and the fulfillment of all rights is onerous, but God makes it light for those who aspire to the Hereafter, who restrain their souls in patience, and trust in the truth of what God has promised them.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'then o god o god pay particular attention to the lowest class those who have no wherewithal the destitute the needy the afflicted the disabled within this class are those who beg and those whose wretchedness calls out to be alleviated but who do not beg be mindful of god in regard to their rights for he has entrusted those rights to your care assign to them a portion from your public treasury بيت المال and a portion of the produce of what is taken as booty by the muslims in every region for those who are furthest away have the same rights as those nearest upholding the right of each of them is incumbent upon you do not let any haughtiness on your part cause you to neglect them for you will not be pardoned even the slightest shortcoming toward them on account of attending to some seemingly more important matter do not turn your concern away from them or assume a contemptuous attitude toward them keep a watchful eye over the affairs of those who cannot gain access to you and who are disdained by men of high standing appoint from among those you trust a god fearing and humble person to bring their affairs to your attention treat these people in a manner such that god may excuse you on the day you meet him for they are more in need of justice from you than any others among your subjects offer your excuse to god in respect of fulfilling each ones right assume responsibility for the orphans and the elderly who have no resources and yet cannot bring themselves to beg this is onerous for governors and the fulfillment of all rights is onerous but god makes it light for those who aspire to the hereafter who restrain their souls in patience and trust in the truth of what god has promised them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 27, NULL, 'Apportion a part of your time to those who have special needs, making yourself free to attend to them personally, sitting with them in a public assembly in all due humility before God, your Creator. Keep your soldiers, guards, and officers away from them so that they may speak to you without inhibition, for I heard the Messenger of God ﷺ say, on more than one occasion: A nation in which the rights of the weak are not wrested in an uninhibited manner from the strong will never be blessed. Bear patiently any coarseness or inarticulate expression they might show; do not display irritation or disdain toward them, and God will thereby extend His compassion to you in its fullest measure and make the reward for your obedience to Him binding. Give whatever you give with beneficence, and withhold, if this be unavoidable, with grace and apology.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'apportion a part of your time to those who have special needs making yourself free to attend to them personally sitting with them in a public assembly in all due humility before god your creator keep your soldiers guards and officers away from them so that they may speak to you without inhibition for i heard the messenger of god ﷺ say on more than one occasion a nation in which the rights of the weak are not wrested in an uninhibited manner from the strong will never be blessed bear patiently any coarseness or inarticulate expression they might show do not display irritation or disdain toward them and god will thereby extend his compassion to you in its fullest measure and make the reward for your obedience to him binding give whatever you give with beneficence and withhold if this be unavoidable with grace and apology', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 28, NULL, 'There are certain affairs which you must handle personally, among them replying to your officers when your scribes are incapable of doing so, and issuing responses to the requests of people when they are brought to you in person because your aides find themselves at a loss on their account.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'there are certain affairs which you must handle personally among them replying to your officers when your scribes are incapable of doing so and issuing responses to the requests of people when they are brought to you in person because your aides find themselves at a loss on their account', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 29, NULL, 'Perform each day the task proper to it, for to each day belongs a particular task. Set apart the finest portion of your available time, and the greatest share thereof, for your soul and for what is between you and God, even though all times and all actions within them are for God, provided the intention underlying them is good and your subjects derive security as a consequence. Let your observance of those duties (faraid, sing. farida) relating exclusively to God be the special means by which you purify your religion for Him. Give unto God of your vital energy in your nights and your days, and perform fully that by which you draw near to God, doing so perfectly, without becoming dull or deficient, taking your body to its limits.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'perform each day the task proper to it for to each day belongs a particular task set apart the finest portion of your available time and the greatest share thereof for your soul and for what is between you and god even though all times and all actions within them are for god provided the intention underlying them is good and your subjects derive security as a consequence let your observance of those duties faraid sing farida relating exclusively to god be the special means by which you purify your religion for him give unto god of your vital energy in your nights and your days and perform fully that by which you draw near to god doing so perfectly without becoming dull or deficient taking your body to its limits', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 30, NULL, 'When you lead the people in prayer, do so without repelling them or squandering it, for among them are people with infirmities or special needs. Indeed, I asked the Messenger of God ﷺ, when he sent me as his representative to Yemen, How should I lead them in prayer? He replied: Lead them according to the prayer performed by the weakest among them, and be merciful to the believers.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'when you lead the people in prayer do so without repelling them or squandering it for among them are people with infirmities or special needs indeed i asked the messenger of god ﷺ when he sent me as his representative to yemen how should i lead them in prayer he replied lead them according to the prayer performed by the weakest among them and be merciful to the believers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 31, NULL, 'In addition to all of this, do not prolong any period of absence from your subjects, for the isolation of governors from those they govern creates a kind of constriction and breeds deficiency in awareness of their affairs. Such isolation cuts rulers off from acquiring knowledge of things hidden from them, so that what is great comes to appear small and what is small, great; the beautiful appears ugly and the ugly, beautiful; the true becomes mixed with the false. The governor is but a human being: he cannot know what people conceal from him, and truth bears no visible mark by which sincere expressions may be distinguished from false ones.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'in addition to all of this do not prolong any period of absence from your subjects for the isolation of governors from those they govern creates a kind of constriction and breeds deficiency in awareness of their affairs such isolation cuts rulers off from acquiring knowledge of things hidden from them so that what is great comes to appear small and what is small great the beautiful appears ugly and the ugly beautiful the true becomes mixed with the false the governor is but a human being he cannot know what people conceal from him and truth bears no visible mark by which sincere expressions may be distinguished from false ones', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 32, NULL, 'You can only be one of two kinds of men: either a man who gives himself generously for the sake of the truth, in which case, why seclude yourself, thereby preventing yourself from bestowing a necessary right or performing an honorable deed? Or else you are a man afflicted with an unwillingness to give of himself, in which case, how quickly people will refrain from making requests of you, despairing of your generosity! And this, despite the fact that fulfilling most of the needs people bring to you is not burdensome, whether they be complaints against injustice or demands for fairness in transactions.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'you can only be one of two kinds of men either a man who gives himself generously for the sake of the truth in which case why seclude yourself thereby preventing yourself from bestowing a necessary right or performing an honorable deed or else you are a man afflicted with an unwillingness to give of himself in which case how quickly people will refrain from making requests of you despairing of your generosity and this despite the fact that fulfilling most of the needs people bring to you is not burdensome whether they be complaints against injustice or demands for fairness in transactions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 33, NULL, 'The governor has favorites and intimate companions, and among them some are prone to presumptuousness, arrogance, and unfairness in their dealings. Cut this out at the root by eliminating the causes of these vices, and by granting no landed estates to anyone in your entourage or circle of friends. Give them no reason to hope for such a grant; should they receive one, it would harm those living nearby in their access to water and in any shared undertaking, the burden of which would inevitably fall on the neighbors while the profit went to those holding the estate, not to you. What would fall to you is only the blame (عَيْبٌ) for it, in this world and the next. Impose what is right upon all to whom it applies, whether they are close to you or distant. Be steadfast and vigilant in this, regardless of how it weighs upon your intimates and favorites. Always seek the end that this principle leads to, however heavily the path may lie upon you, for its outcome is praiseworthy.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'the governor has favorites and intimate companions and among them some are prone to presumptuousness arrogance and unfairness in their dealings cut this out at the root by eliminating the causes of these vices and by granting no landed estates to anyone in your entourage or circle of friends give them no reason to hope for such a grant should they receive one it would harm those living nearby in their access to water and in any shared undertaking the burden of which would inevitably fall on the neighbors while the profit went to those holding the estate not to you what would fall to you is only the blame عيب for it in this world and the next impose what is right upon all to whom it applies whether they are close to you or distant be steadfast and vigilant in this regardless of how it weighs upon your intimates and favorites always seek the end that this principle leads to however heavily the path may lie upon you for its outcome is praiseworthy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 34, NULL, 'If any of your subjects suspect you of an injustice, present your case openly so that the suspicion is cleared away from you by plain explanation. Such conduct is a discipline for yourself, a kindness to your subjects, and a means of pleading your cause that will help you keep them upright in adherence to the truth.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'if any of your subjects suspect you of an injustice present your case openly so that the suspicion is cleared away from you by plain explanation such conduct is a discipline for yourself a kindness to your subjects and a means of pleading your cause that will help you keep them upright in adherence to the truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 35, NULL, 'Never turn away from a call to peace with your enemy when God''s pleasure lies in it, for in peace there is rest for your soldiers, relief from your cares, and security for your lands. Yet once you have made peace, remain fully on your guard against your enemy, for he may have drawn close only in order to catch you off guard; so take every precaution, and hold even your own favorable opinion of him under suspicion. Yet if you and your enemy enter into a solemn agreement, or he receives from you a covenant of protection (ذِمَّةٌ), then keep your agreement faithfully and honor your obligation of protection with complete trustworthiness. Make your very life a shield for what you have promised, for among all the obligations God has laid down there is none on which people stand more firmly united, despite all the differences of their inclinations and the variety of their opinions, than the honoring of pledges. Even the polytheists observed it among themselves, quite apart from their dealings with the Muslims, so greatly did they fear the consequences of treachery. Do not betray your covenant of protection, do not break your promise, and do not deal treacherously with your enemy, for none dares defy God but the ignorant and wretched (جَاهِلٌ شَقِيٌّ). God has made His pledge and His protection a sanctuary of security, which by His mercy He has spread over His servants, a refuge in whose inviolable strength they find rest, and toward whose sheltering power they hasten. Let there be no corruption within it, no treachery, and no deception. Do not enter into any agreement that leaves room for evasion, and do not resort to twisting words once an agreement has been confirmed and made binding. Do not let any hardship that befalls you drive you to break, without right, an agreement God has made binding upon you; for patience under a difficulty whose relief and good outcome you await is far better than a treachery whose consequence you dread, that a reckoning from God (tilba) should close in upon you from which you will find no release in this world or the next.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'never turn away from a call to peace with your enemy when gods pleasure lies in it for in peace there is rest for your soldiers relief from your cares and security for your lands yet once you have made peace remain fully on your guard against your enemy for he may have drawn close only in order to catch you off guard so take every precaution and hold even your own favorable opinion of him under suspicion yet if you and your enemy enter into a solemn agreement or he receives from you a covenant of protection ذمه then keep your agreement faithfully and honor your obligation of protection with complete trustworthiness make your very life a shield for what you have promised for among all the obligations god has laid down there is none on which people stand more firmly united despite all the differences of their inclinations and the variety of their opinions than the honoring of pledges even the polytheists observed it among themselves quite apart from their dealings with the muslims so greatly did they fear the consequences of treachery do not betray your covenant of protection do not break your promise and do not deal treacherously with your enemy for none dares defy god but the ignorant and wretched جاهل شقي god has made his pledge and his protection a sanctuary of security which by his mercy he has spread over his servants a refuge in whose inviolable strength they find rest and toward whose sheltering power they hasten let there be no corruption within it no treachery and no deception do not enter into any agreement that leaves room for evasion and do not resort to twisting words once an agreement has been confirmed and made binding do not let any hardship that befalls you drive you to break without right an agreement god has made binding upon you for patience under a difficulty whose relief and good outcome you await is far better than a treachery whose consequence you dread that a reckoning from god tilba should close in upon you from which you will find no release in this world or the next', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 36, NULL, 'Beware of shedding blood unlawfully, for nothing so swiftly invites retribution, weighs more heavily in its consequence, or is more apt to end a blessing and cut short a span of life, than bloodshed without right. On the Day of Resurrection, God, glorified be He, will begin His judgment among His servants with the blood they have shed. Do not seek to strengthen your authority through unlawful bloodshed, for that in truth weakens and undermines it; indeed, it brings it down and takes it away entirely.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'beware of shedding blood unlawfully for nothing so swiftly invites retribution weighs more heavily in its consequence or is more apt to end a blessing and cut short a span of life than bloodshed without right on the day of resurrection god glorified be he will begin his judgment among his servants with the blood they have shed do not seek to strengthen your authority through unlawful bloodshed for that in truth weakens and undermines it indeed it brings it down and takes it away entirely', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 37, NULL, 'You have no excuse before God, nor before me, if you kill anyone deliberately, for that demands capital punishment. And if you are overtaken by an error, and your whip, your sword, or your hand goes too far in inflicting a penalty, for even a single blow, and whatever exceeds it, can bring about death, do not let the pride of your authority hold you back from paying the relatives of the slain what is rightfully theirs.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'you have no excuse before god nor before me if you kill anyone deliberately for that demands capital punishment and if you are overtaken by an error and your whip your sword or your hand goes too far in inflicting a penalty for even a single blow and whatever exceeds it can bring about death do not let the pride of your authority hold you back from paying the relatives of the slain what is rightfully theirs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 38, NULL, 'Beware of self-admiration, of leaning on whatever pleases you in yourself, and of loving to be flattered, for these are among the surest openings Satan finds to efface the good works (احسان) of the virtuous (المُحسنین). Beware of making your subjects feel indebted to you for the good you do them, of inflating your own deeds, and of promising what you then fail to fulfill; for laying people under obligation destroys the good itself, self-praise extinguishes the light of truth, and breaking a promise earns you the hatred of God and of men. God the Exalted has said:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'beware of self admiration of leaning on whatever pleases you in yourself and of loving to be flattered for these are among the surest openings satan finds to efface the good works احسان of the virtuous المحسنين beware of making your subjects feel indebted to you for the good you do them of inflating your own deeds and of promising what you then fail to fulfill for laying people under obligation destroys the good itself self praise extinguishes the light of truth and breaking a promise earns you the hatred of god and of men god the exalted has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 39, NULL, 'As-Saff: 3كَبُرَ مَقْتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفْعَلُونَIt is indeed hateful to God that you say that which you do not do (As-Saff: 3).', '', NULL, 'As-Saff: 3', NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'as saff 3كبر مقتا عند الله ان تقولوا ما لا تفعلونit is indeed hateful to god that you say that which you do not do as saff 3', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 40, NULL, 'Beware of rushing into matters before their time has come, and of letting them slip when the moment to act has arrived; of stubbornness when they grow tangled, and of slackness once they have become clear. Put every matter in its proper place, and attend to every task at its proper time. Beware of taking for yourself what belongs equally to all, and of feigning blindness to what is urgent and plain to every eye, for it will be taken from you for the benefit of others. Before long the coverings will be lifted from all affairs, and justice will be sought from you on behalf of the wronged. So master the heat of your pride, the sharpness of your temper, the force of your hand, and the edge of your tongue; guard against all of this by holding back sudden impulse and delaying the blow until your anger has subsided and you have regained your self-command. You will never achieve this mastery over yourself, however, unless you increase your remembrance of your return to your Lord.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'beware of rushing into matters before their time has come and of letting them slip when the moment to act has arrived of stubbornness when they grow tangled and of slackness once they have become clear put every matter in its proper place and attend to every task at its proper time beware of taking for yourself what belongs equally to all and of feigning blindness to what is urgent and plain to every eye for it will be taken from you for the benefit of others before long the coverings will be lifted from all affairs and justice will be sought from you on behalf of the wronged so master the heat of your pride the sharpness of your temper the force of your hand and the edge of your tongue guard against all of this by holding back sudden impulse and delaying the blow until your anger has subsided and you have regained your self command you will never achieve this mastery over yourself however unless you increase your remembrance of your return to your lord', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 41, NULL, 'It is incumbent upon you to remember the just governance and the noble custom that have come before you, the practice of the Prophet, and the obligations set forth in the Book of God. Follow faithfully what you have seen us do in these matters, and strive with all your soul to act upon what has been enjoined upon you in this mandate, by which the plea has been made complete against you, so that you will have no excuse when your soul races toward its caprice.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'it is incumbent upon you to remember the just governance and the noble custom that have come before you the practice of the prophet and the obligations set forth in the book of god follow faithfully what you have seen us do in these matters and strive with all your soul to act upon what has been enjoined upon you in this mandate by which the plea has been made complete against you so that you will have no excuse when your soul races toward its caprice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 42, NULL, 'I ask God, by the vastness of His mercy and the greatness of His power to grant every desire, that He bestow upon me and upon you the success that wins His pleasure, that we may present a clear justification before Him and before His creatures, earn the fairest praise among His servants, and leave behind the most beautiful traces in the land, with blessing made complete and honor ever increased; and that He seal my life and yours with felicity (اَلسَّعَادَةُ) and martyrdom (اَلشَّهَادَةُ). Truly:', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'i ask god by the vastness of his mercy and the greatness of his power to grant every desire that he bestow upon me and upon you the success that wins his pleasure that we may present a clear justification before him and before his creatures earn the fairest praise among his servants and leave behind the most beautiful traces in the land with blessing made complete and honor ever increased and that he seal my life and yours with felicity السعاده and martyrdom الشهاده truly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'verse', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 43, NULL, 'Al-Baqarah: 156ٱلَّذِينَ إِذَآ أَصَبَتْهُم مُّصِيبَةٌۭ قَالُوٓا۟ إِنَّا لِلَّهِ وَإِنَّآ إِلَيْهِ رَجِعُونَ', '', 'ٱلَّذِينَ إِذَآ أَصَبَتْهُم مُّصِيبَةٌۭ قَالُوٓا۟ إِنَّا لِلَّهِ وَإِنَّآ إِلَيْهِ رَجِعُونَ', 'Al-Baqarah: 156', 2, 156, 'spiritual ethos 15 the letter to malik al ashtar', 'al baqarah 156الذين اذا اصبتهم مصيبه قالوا انا لله وانا اليه رجعون', 'الذين اذا اصبتهم مصيبه قالوا انا لله وانا اليه رجعون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 44, NULL, 'Those who, when a misfortune befalls them, say: Truly unto God we belong, and unto Him we are returning (Al-Baqarah: 156).', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'those who when a misfortune befalls them say truly unto god we belong and unto him we are returning al baqarah 156', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 45, NULL, 'And peace be upon the Messenger of God and upon his good and pure progeny.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'and peace be upon the messenger of god and upon his good and pure progeny', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'chapter', 'the letter to malik al-ashtar', '15. The Letter to Malik al-Ashtar', 46, NULL, 'Editorial note (tradition-grounded). When the letter tells Malik to hold himself back from "whatever is not lawful to you," the word behind lawful is halal, whose root (h-l-l) means to untie or loosen a knot: the permitted is what has been unknotted — loosed from prohibition. The wider tradition preserves this sense, and it throws light on the letter''s own image a few lines later, where the governor is told to "loosen from the people every knot of resentment" and cut the cord of enmity from his own heart. A just ruler, on this reading, works as the law itself works — not by binding tighter but by untying: releasing what may be released, unknotting grievance where grievance can be unknotted, and leaving bound only what must remain forbidden.', '', NULL, NULL, NULL, NULL, 'spiritual ethos 15 the letter to malik al ashtar', 'editorial note tradition grounded when the letter tells malik to hold himself back from whatever is not lawful to you the word behind lawful is halal whose root h l l means to untie or loosen a knot the permitted is what has been unknotted loosed from prohibition the wider tradition preserves this sense and it throws light on the letters own image a few lines later where the governor is told to loosen from the people every knot of resentment and cut the cord of enmity from his own heart a just ruler on this reading works as the law itself works not by binding tighter but by untying releasing what may be released unknotting grievance where grievance can be unknotted and leaving bound only what must remain forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'episode', NULL, 'Ali and the Prophet', 0, 1, 'Ali and the Prophet The tradition calls merely gazing at this man an act of worship. We meet Ali (as) as the Prophet''s own soul and the gate to the city of knowledge, walk his early life from the Ka''ba to Khaybar, and hear the sayings that make his walaya a universal spirituality rather than a sectarian badge.', '', NULL, NULL, NULL, NULL, 'spiritual ethos ali and the prophet', 'ali and the prophet the tradition calls merely gazing at this man an act of worship we meet ali as as the prophets own soul and the gate to the city of knowledge walk his early life from the kaba to khaybar and hear the sayings that make his walaya a universal spirituality rather than a sectarian badge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'episode', NULL, 'Why Intellect, Not Reason', 0, 2, 'Why Intellect, Not Reason The word we reach for, reason, may be exactly the wrong word for how Ali (as) knew what he knew. We recover the older meaning of intellect as contemplative vision, hear the Imam refuse a merely numerical oneness on the edge of a battlefield, and learn why revelation and the intellect are not rivals but partners.', '', NULL, NULL, NULL, NULL, 'spiritual ethos why intellect not reason', 'why intellect not reason the word we reach for reason may be exactly the wrong word for how ali as knew what he knew we recover the older meaning of intellect as contemplative vision hear the imam refuse a merely numerical oneness on the edge of a battlefield and learn why revelation and the intellect are not rivals but partners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'episode', NULL, 'The Discourse to Kumayl', 0, 3, 'The Discourse to Kumayl On a night outside Kufa, Ali ibn Abi Talib (peace be upon him) led one disciple by the hand to a graveyard, drew a deep breath, and confided a counsel that later generations treated as one of the most esoteric in the whole tradition. This episode recites that discourse to Kumayl whole — the three types of people, knowledge weighed above wealth, the abundant knowledge in his own breast, and the rare guardians of the proof through whom knowledge penetrates the reality of insight — and then follows the commentary into what it teaches. Knowledge, it argues, must storm past the surface of words into the heart, past the zahir into the batin; the warlike verb hajama makes the passage vivid. That penetration cannot happen unless the whole soul is won for the intellect, which is the greatest struggle, the battle for the nafs against hawa and the subtle idolatry of the ego. Its aim is integration, tawhid, and its ground is ikhlas — sincerity made purely for God, sustained by worship, closing on the command to worship until certainty comes.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'episode', NULL, 'Joy, Virtue, and the Hereafter', 0, 4, 'Joy, Virtue, and the Hereafter In this ethos knowledge is not cold or dry but the single most joyful thing a human being can do, and the Imam calls sleeping with certainty better than praying with doubt. We close the chapter with joy, beauty as the soul made lovely, detachment that frees, and a Hereafter already tasted in every good act, salvation here and now.', '', NULL, NULL, NULL, NULL, 'spiritual ethos joy virtue and the hereafter', 'joy virtue and the hereafter in this ethos knowledge is not cold or dry but the single most joyful thing a human being can do and the imam calls sleeping with certainty better than praying with doubt we close the chapter with joy beauty as the soul made lovely detachment that frees and a hereafter already tasted in every good act salvation here and now', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'episode', NULL, 'The Sacred Conception of Justice', 0, 5, 'The Sacred Conception of Justice We reduce justice to fairness and fair play — but in Ali (ع)''s letter to Malik al-Ashtar it is nothing less than the nature of God Himself. We hear MacIntyre''s charge that ethics has lost its anchor in the Good, meet the hadith of Gabriel and virtue as worshipping God as if you could see Him, and learn why to be just is to become like God while remaining His slave.', '', NULL, NULL, NULL, NULL, 'spiritual ethos the sacred conception of justice', 'the sacred conception of justice we reduce justice to fairness and fair play but in ali ع s letter to malik al ashtar it is nothing less than the nature of god himself we hear macintyres charge that ethics has lost its anchor in the good meet the hadith of gabriel and virtue as worshipping god as if you could see him and learn why to be just is to become like god while remaining his slave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'episode', NULL, 'Pride and Conscience', 0, 6, 'Pride and Conscience How can a feeling of superiority be called war with God, and where is that war actually fought? We trace pride as the theft of an attribute belonging to God alone, meet Iblis as the archetype of arrogance and the hidden idolatry lurking in vanity, then follow the same war inward to the conscience every tyrant must silence, the self-reform and self-lowering that alone reverse it, and a compassion that turns out to be not softness but justice being faithful to the merciful nature of the Real.', '', NULL, NULL, NULL, NULL, 'spiritual ethos pride and conscience', 'pride and conscience how can a feeling of superiority be called war with god and where is that war actually fought we trace pride as the theft of an attribute belonging to god alone meet iblis as the archetype of arrogance and the hidden idolatry lurking in vanity then follow the same war inward to the conscience every tyrant must silence the self reform and self lowering that alone reverse it and a compassion that turns out to be not softness but justice being faithful to the merciful nature of the real', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'episode', NULL, 'Classes of Society and the Poor', 0, 7, 'Classes of Society and the Poor A governor is the hub of society''s wheel — and useless without an axle he cannot see. We walk the letter''s anatomy of a just state, from the army and the judges to the tillers of the soil, hear why greed is spiritual short-sightedness, and arrive at the sharpest test of all: the destitute, whose claim can be honoured only by a soul that acts from gratitude and pure intention rather than calculation.', '', NULL, NULL, NULL, NULL, 'spiritual ethos classes of society and the poor', 'classes of society and the poor a governor is the hub of societys wheel and useless without an axle he cannot see we walk the letters anatomy of a just state from the army and the judges to the tillers of the soil hear why greed is spiritual short sightedness and arrive at the sharpest test of all the destitute whose claim can be honoured only by a soul that acts from gratitude and pure intention rather than calculation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'episode', NULL, 'Prayer as the Source of Justice', 0, 8, 'Prayer as the Source of Justice The whole architecture of just governance rests, in the end, on something done alone in the dead of night. We follow prayer as drawing near, the hadith in which God becomes the servant''s very hearing and sight, remembrance as the polish of the heart — and set the Imam beside Plato''s gazing on the Good to see how he supplies the devotional method the philosopher only pointed to.', '', NULL, NULL, NULL, NULL, 'spiritual ethos prayer as the source of justice', 'prayer as the source of justice the whole architecture of just governance rests in the end on something done alone in the dead of night we follow prayer as drawing near the hadith in which god becomes the servants very hearing and sight remembrance as the polish of the heart and set the imam beside platos gazing on the good to see how he supplies the devotional method the philosopher only pointed to', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'episode', NULL, 'Dhikr, the Polish for Hearts', 0, 9, 'Dhikr, the Polish for Hearts Why is the simplest act of worship — the bare turning of the heart toward God — called the greatest? We follow Ali (ع) at the head of the whole mystical tradition of Islam, the meaning of dhikr as rendering the divine present, the Imam''s image of remembrance as a polish for the clouded heart, and the strange vision by which the polished heart sees God with a sight that is finally God''s own.', '', NULL, NULL, NULL, NULL, 'spiritual ethos dhikr the polish for hearts', 'dhikr the polish for hearts why is the simplest act of worship the bare turning of the heart toward god called the greatest we follow ali ع at the head of the whole mystical tradition of islam the meaning of dhikr as rendering the divine present the imams image of remembrance as a polish for the clouded heart and the strange vision by which the polished heart sees god with a sight that is finally gods own', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'episode', NULL, 'The Veils That Do Not Veil', 0, 10, 'The Veils That Do Not Veil If God is closer than the vein in your own neck, what is left for the world to be but a veil? We follow the Imam''s four startling words — the veils do not veil Him — into the logic by which creation both hides and discloses God, the balance of nearness and incomparability that guards the vision from idolatry, and the abundant invocation of the Name that grounds the whole discipline.', '', NULL, NULL, NULL, NULL, 'spiritual ethos the veils that do not veil', 'the veils that do not veil if god is closer than the vein in your own neck what is left for the world to be but a veil we follow the imams four startling words the veils do not veil him into the logic by which creation both hides and discloses god the balance of nearness and incomparability that guards the vision from idolatry and the abundant invocation of the name that grounds the whole discipline', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'episode', NULL, 'Forgetting the Self, Becoming the Name', 0, 11, 'Forgetting the Self, Becoming the Name Why would the highest form of remembering God turn out to be a kind of forgetting — and what exactly is the Name a person invokes? This closing episode of the remembrance arc follows the Imam from perfect remembrance to the reality of remembrance, through the extinction the tradition calls fana and the Imam''s own fainting in the orchard, to the reversal by which God, not man, is the true invoker. From there it takes up the boldest of the Sufi maxims — the Name is the Named — alongside the Imams'' apparent denial of it, and follows the resolution to its end, where the friends of God, effaced in Him, become themselves the most beautiful Names, sealed at the last in the death of Ali (ع), with the invocation still moving on his tongue.', '', NULL, NULL, NULL, NULL, 'spiritual ethos forgetting the self becoming the name', 'forgetting the self becoming the name why would the highest form of remembering god turn out to be a kind of forgetting and what exactly is the name a person invokes this closing episode of the remembrance arc follows the imam from perfect remembrance to the reality of remembrance through the extinction the tradition calls fana and the imams own fainting in the orchard to the reversal by which god not man is the true invoker from there it takes up the boldest of the sufi maxims the name is the named alongside the imams apparent denial of it and follows the resolution to its end where the friends of god effaced in him become themselves the most beautiful names sealed at the last in the death of ali ع with the invocation still moving on his tongue', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'episode', NULL, 'The First Sermon of Nahj al-Balagha', 0, 12, 'The First Sermon of Nahj al-Balagha Why does the greatest collection of Ali (ع)''s words open not on law but on the negation of every attribute of God? We hear the first sermon of Nahj al-Balagha whole — the apophatic ladder from the knowledge of God to the divesting of all attributes, the churning of the primordial sea into the seven heavens, the ranks of tireless angels, the fashioning of Adam and the breath of the spirit, the pride of Iblis, and the succession of prophets that ends in Muhammad and the Book — and follow the single arc by which a doctrine of oneness becomes a cosmos and a history.', '', NULL, NULL, NULL, NULL, 'spiritual ethos the first sermon of nahj al balagha', 'the first sermon of nahj al balagha why does the greatest collection of ali ع s words open not on law but on the negation of every attribute of god we hear the first sermon of nahj al balagha whole the apophatic ladder from the knowledge of god to the divesting of all attributes the churning of the primordial sea into the seven heavens the ranks of tireless angels the fashioning of adam and the breath of the spirit the pride of iblis and the succession of prophets that ends in muhammad and the book and follow the single arc by which a doctrine of oneness becomes a cosmos and a history', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('spiritual-ethos', 'episode', NULL, 'The Letter of Ali (ع) to Malik al-Ashtar', 0, 13, 'The Letter of Ali (ع) to Malik al-Ashtar What is the first thing you would hand a man to whom you were about to give a province? Ali (ع) hands Malik al-Ashtar neither an army nor a treasury but a warning about his own soul. We hear his longest letter whole, from first line to last — the ladder of authority that ends above every appointment, the common folk chosen over the flattering elite, the gentle commander and the incorruptible judge, the reversal that puts the cultivation of the land above the tax drawn from it, the cry — "O God, O God" — over the destitute, the unguarded assembly stripped of guards, and the pledges and the blood on which a ruler''s whole account with God is finally settled.', '', NULL, NULL, NULL, NULL, 'spiritual ethos the letter of ali ع to malik al ashtar', 'the letter of ali ع to malik al ashtar what is the first thing you would hand a man to whom you were about to give a province ali ع hands malik al ashtar neither an army nor a treasury but a warning about his own soul we hear his longest letter whole from first line to last the ladder of authority that ends above every appointment the common folk chosen over the flattering elite the gentle commander and the incorruptible judge the reversal that puts the cultivation of the land above the tax drawn from it the cry o god o god over the destitute the unguarded assembly stripped of guards and the pledges and the blood on which a rulers whole account with god is finally settled', '');
